ard: FC<CardProps> = ({ children, className = \'\' }) => (\n  <div className={`bg-white border border-slate-200/80 rounded-xl shadow-sm ${className}`}>\n    {children}\n  </div>\n);\n\ninterface CardHeaderProps {\n    icon: React.ElementType;\n    title: string;\n    children?: ReactNode;\n}\n\nconst CardHeader: FC<CardHeaderProps> = ({ icon: Icon, title, children }) => (\n    <div className="p-4 sm:p-6 border-b border-slate-200/80 flex justify-between items-center">\n        <div className="flex items-center gap-3">\n            <Icon className="w-5 h-5 text-slate-500" />\n            <h3 className="font-semibold text-slate-800 text-lg">{title}</h3>\n        </div>\n        <div>{children}</div>\n    </div>\n);\n\nconst CustomCheckbox = ({ id, label, checked, onChange }: { id: string, label: string, checked: boolean, onChange: (checked: boolean) => void }) => (\n  <label htmlFor={id} className="flex items-center gap-3 cursor-pointer text-slate-600 hover:text-slate-900 transition-colors">\n    <div className="w-5 h-5 border-2 border-slate-300 rounded-md flex items-center justify-center transition-all duration-200 relative">\n      {checked && <Check className="w-4 h-4 text-white absolute" />}\n      <div className={`w-full h-full rounded-[3px] transition-all duration-200 ${checked ? \'bg-blue-600 scale-100\' : \'bg-transparent scale-0\'}`} />\n    </div>\n    <input id={id} type="checkbox" checked={checked} onChange={(e) => onChange(e.target.checked)} className="hidden" />\n    <span>{label}</span>\n  </label>\n);\n\n// --- MAIN PAGE COMPONENT ---\nconst StockReportPage: NextPage = () => {\n  const [reportOptions, setReportOptions] = useState<ReportOptions>({ overview: true, financials: true, valuation: false, metrics: false });\n\n  const handleReportOptionChange = (option: keyof ReportOptions) => {\n    setReportOptions(prev => ({ ...prev, [option]: !prev[option] }));\n  };\n\n  return (\n    <div className="min-h-screen bg-slate-50 text-slate-800">\n      <main className="p-4 sm:p-6 md:p-8 max-w-7xl mx-auto">\n        {/* Header */}\n        <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8">\n          <div>\n            <h1 className="text-3xl font-bold text-slate-900">Stock Report Generator</h1>\n            <p className="text-slate-500 mt-1">Comprehensive analysis for Apple Inc. (AAPL)</p>\n          </div>\n          <div className="flex items-center gap-2 mt-4 sm:mt-0">\n            <button className="px-4 py-2 text-sm font-semibold text-slate-700 bg-white border border-slate-300 rounded-lg shadow-sm hover:bg-slate-100 transition-colors flex items-center gap-2">\n              Apple Inc.\n              <ChevronDown className="w-4 h-4" />\n            </button>\n            <button className="px-4 py-2 text-sm font-semibold text-white bg-slate-800 rounded-lg shadow-sm hover:bg-slate-900 transition-colors flex items-center gap-2">\n              <Download className="w-4 h-4" />\n              Download\n            </button>\n          </div>\n        </header>\n\n        {/* Main Grid */}\n        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">\n          {/* Stock Information */}\n          <Card className="lg:col-span-3 p-6">\n            <div className="grid grid-cols-2 md:grid-cols-4 gap-6 text-center md:text-left">\n              <div className="flex flex-col items-center md:items-start">\n                <span className="text-sm text-slate-500 mb-1">Current Price</span>\n                <span className="text-3xl font-bold text-slate-900">${stockInfo.price.toFixed(2)}</span>\n                <span className={`text-sm font-semibold ${stockInfo.change > 0 ? \'text-green-600\' : \'text-red-600\'}`}>\n                  {stockInfo.change > 0 ? \'+\' : \'\'}{stockInfo.change.toFixed(2)} ({stockInfo.changePercent.toFixed(2)}%)\n                </span>\n              </div>\n              <div className="flex flex-col items-center md:items-start">\n                <span className="text-sm text-slate-500 mb-1">Volume</span>\n                <span className="text-2xl font-semibold text-slate-800">{stockInfo.volume}</span>\n              </div>\n              <div className="flex flex-col items-center md:items-start">\n                <span className="text-sm text-slate-500 mb-1">Market Cap</span>\n                <span className="text-2xl font-semibold text-slate-800">{stockInfo.marketCap}</span>\n              </div>\n               <div className="col-span-2 md:col-span-1 flex flex-col items-center md:items-start">\n                 <span className="text-sm text-slate-500 mb-2">Performance Snapshot</span>\n                 <div className="w-full h-16">\n                    <ResponsiveContainer width="100%" height="100%">\n                        <LineChart data={stockPerformance} margin={{ top: 5, right: 5, left: -30, bottom: 5 }}>\n                            <Line type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={2} dot={false} />\n                            <YAxis hide={true} domain={[\'dataMin - 5\', \'dataMax + 5\']} />\n                             <Tooltip \n                                contentStyle={{ backgroundColor: \'#1e293b\', border: \'none\', borderRadius: \'8px\', fontSize: \'12px\' }} \n                                labelStyle={{ color: \'#cbd5e1\' }}\n                                itemStyle={{ color: \'#94a3b8\' }}\n                            />\n                        </LineChart>\n                    </ResponsiveContainer>\n                 </div>\n              </div>\n            </div>\n          </Card>\n\n          {/* Historical Data */}\n          <Card className="lg:col-span-2">\n            <CardHeader icon={BarChart2} title="Historical Data" />\n            <div className="p-6 h-80">\n              <ResponsiveContainer width="100%" height="100%">\n                <ComposedChart data={historicalData} margin={{ top: 5, right: 10, left: 0, bottom: 5 }}>\n                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />\n                  <XAxis dataKey="name" tick={{ fill: \'#64748b\', fontSize: 12 }} axisLine={false} tickLine={false} />\n                  <YAxis yAxisId="left" orientation="left" stroke="#64748b" tick={{ fill: \'#64748b\', fontSize: 12 }} axisLine={false} tickLine={false} tickFormatter={(value) => `$${value}`} />\n                  <YAxis yAxisId="right" orientation="right" stroke="#64748b" tick={{ fill: \'#64748b\', fontSize: 12 }} axisLine={false} tickLine={false} tickFormatter={(value) => `${value}M`} />\n                  <Tooltip contentStyle={{ backgroundColor: \'#1e293b\', border: \'none\', borderRadius: \'8px\' }} labelStyle={{ color: \'#cbd5e1\' }} itemStyle={{ color: \'#94a3b8\' }} />\n                  <Legend iconSize={10} wrapperStyle={{ fontSize: \'14px\', paddingTop: \'20px\' }} />\n                  <Line yAxisId="left" type="monotone" dataKey="price" stroke="#1e3a8a" strokeWidth={2} name="Price" dot={{ r: 4, fill: \'#1e3a8a\' }} activeDot={{ r: 6 }} />\n                  <Bar yAxisId="right" dataKey="volume" barSize={20} fill="#93c5fd" name="Volume" />\n                </ComposedChart>\n              </ResponsiveContainer>\n            </div>\n          </Card>\n\n          {/* Financial Metrics */}\n          <Card>\n            <CardHeader icon={TrendingUp} title="Financial Metrics" />\n            <div className="p-6 space-y-4">\n              {financialMetrics.map((metric, index) => (\n                <div key={index} className="flex justify-between items-center text-sm">\n                  <span className="text-slate-500">{metric.label}</span>\n                  <span className="font-medium text-slate-800">{metric.value}</span>\n                </div>\n              ))}\n            </div>\n          </Card>\n\n          {/* Ownership Distribution */}\n          <Card>\n            <CardHeader icon={PieChartIcon} title="Ownership Distribution" />\n            <div className="p-6 h-64 flex items-center justify-center">\n              <ResponsiveContainer width="100%" height="100%">\n                <PieChart>\n                  <Pie data={ownershipDistribution} cx="50%" cy="50%" labelLine={false} outerRadius={80} fill="#8884d8" dataKey="value" nameKey="name" label={({ cx, cy, midAngle, innerRadius, outerRadius, percent }) => {\n                      const radius = innerRadius + (outerRadius - innerRadius) * 1.2;\n                      const x = cx + radius * Math.cos(-midAngle * Math.PI / 180);\n                      const y = cy + radius * Math.sin(-midAngle * Math.PI / 180);\n                      return <text x={x} y={y} fill="#334155" textAnchor={x > cx ? \'start\' : \'end\'} dominantBaseline="central" fontSize={12}>{`${(percent * 100).toFixed(1)}%`}</text>;\n                  }}>\n                    {ownershipDistribution.map((entry, index) => (\n                      <Cell key={`cell-${index}`} fill={OWNERSHIP_COLORS[index % OWNERSHIP_COLORS.length]} />\n                    ))}\n                  </Pie>\n                  <Tooltip contentStyle={{ backgroundColor: \'#1e293b\', border: \'none\', borderRadius: \'8px\' }} itemStyle={{ color: \'#94a3b8\' }}/>\n                </PieChart>\n              </ResponsiveContainer>\n            </div>\n            <div className="px-6 pb-6 flex justify-center gap-4">\n                {ownershipDistribution.map((entry, index) => (\n                    <div key={index} className="flex items-center gap-2 text-xs">\n                        <div className="w-3 h-3 rounded-full" style={{backgroundColor: OWNERSHIP_COLORS[index]}}></div>\n                        <span className="text-slate-600">{entry.name}</span>\n                    </div>\n                ))}\n            </div>\n          </Card>\n\n          {/* Top Holders */}\n          <Card className="lg:col-span-2">\n            <CardHeader icon={Building2} title="Top Holders" />\n            <div className="p-6 grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-5">\n                <div>\n                    <h4 className="font-semibold text-slate-600 mb-3 flex items-center gap-2"><Building2 className="w-4 h-4"/>Institutions</h4>\n                    <div className="space-y-3">\n                        {topHolders.filter(h => h.type === \'institution\').map(holder => (\n                            <div key={holder.name}>\n                                <div className="flex justify-between text-sm mb-1">\n                                    <span className="text-slate-700 font-medium">{holder.name}</span>\n                                    <span className="text-slate-500">{holder.percentage.toFixed(2)}%</span>\n                                </div>\n                                <div className="w-full bg-slate-200 rounded-full h-1.5">\n                                    <div className="bg-blue-600 h-1.5 rounded-full" style={{ width: `${holder.percentage * 10}%` }}></div>\n                                </div>\n                            </div>\n                        ))}\n                    </div>\n                </div>\n                 <div>\n                    <h4 className="font-semibold text-slate-600 mb-3 flex items-center gap-2"><Users className="w-4 h-4"/>Individuals</h4>\n                    <div className="space-y-3">\n                        {topHolders.filter(h => h.type === \'individual\').map(holder => (\n                            <div key={holder.name}>\n                                <div className="flex justify-between text-sm mb-1">\n                                    <span className="text-slate-700 font-medium">{holder.name}</span>\n                                    <span className="text-slate-500">{holder.percentage.toFixed(3)}%</span>\n                                </div>\n                                <div className="w-full bg-slate-200 rounded-full h-1.5">\n                                    <div className="bg-sky-500 h-1.5 rounded-full" style={{ width: `${holder.percentage * 1000}%` }}></div>\n                                </div>\n                            </div>\n                        ))}\n                    </div>\n                </div>\n            </div>\n          </Card>\n\n\n          {/* Financial Summary */}\n          <Card className="lg:col-span-3">\n            <CardHeader icon={FileText} title="Financial Summary" />\n            <div className="p-2 sm:p-4">\n                <table className="w-full text-sm text-left text-slate-600">\n                    <thead className="text-xs text-slate-500 uppercase bg-slate-100/80">\n                        <tr>\n                            <th scope="col" className="px-6 py-3 rounded-l-lg">Year</th>\n                            <th scope="col" className="px-6 py-3 text-right">Revenue (in B)</th>\n                            <th scope="col" className="px-6 py-3 text-right rounded-r-lg">Net Income (in B)</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        {financialSummary.map((item, index) => (\n                            <tr key={item.year} className="bg-white border-b last:border-b-0 border-slate-200/80">\n                                <th scope="row" className="px-6 py-4 font-medium text-slate-900 whitespace-nowrap">{item.year}</th>\n                                <td className="px-6 py-4 text-right">${item.revenue.toFixed(2)}</td>\n                                <td className="px-6 py-4 text-right">${item.netIncome.toFixed(2)}</td>\n                            </tr>\n                        ))}\n                    </tbody>\n                </table>\n            </div>\n          </Card>\n\n          {/* Report Customization */}\n          <Card className="lg:col-span-3 p-6">\n            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center">\n              <div>\n                <h4 className="font-semibold text-lg text-slate-800">Customize Your Report</h4>\n                <p className="text-slate-500 text-sm mt-1">Select the sections to include in your PDF download.</p>\n              </div>\n              <div className="flex flex-wrap items-center gap-x-6 gap-y-3 mt-4 sm:mt-0">\n                <CustomCheckbox id="overview" label="Overview" checked={reportOptions.overview} onChange={() => handleReportOptionChange(\'overview\')} />\n                <CustomCheckbox id="financials" label="Financials" checked={reportOptions.financials} onChange={() => handleReportOptionChange(\'financials\')} />\n                <CustomCheckbox id="valuation" label="Valuation" checked={reportOptions.valuation} onChange={() => handleReportOptionChange(\'valuation\')} />\n                <CustomCheckbox id="metrics" label="Metrics" checked={reportOptions.metrics} onChange={() => handleReportOptionChange(\'metrics\')} />\n              </div>\n              <div className="mt-4 sm:mt-0 sm:ml-6 w-full sm:w-auto">\n                 <button className="w-full px-6 py-2.5 text-sm font-semibold text-white bg-blue-600 rounded-lg shadow-sm hover:bg-blue-700 transition-colors flex items-center justify-center gap-2">\n                    <Download className="w-4 h-4" />\n                    Download Report\n                </button>\n              </div>\n            </div>\n          </Card>\n        </div>\n      </main>\n    </div>\n  );\n};\n\nexport default StockReportPage;\n'}

