import { useState, useEffect, type FC, type ReactNode } from 'react';
import type { AppProps } from 'next/app';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell, ComposedChart, Line } from 'recharts';
import { Search, Filter, RefreshCw, ChevronDown, Download, FileText, Calendar, Activity, TrendingUp, MapPin, BarChart2, AlertTriangle } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type TrendData = { name: string; actual: number; predicted: number; target: number };
type ViolationData = { name: string; violations: number };
type DistributionData = { name: string; value: number };

type DashboardData = {
  policyType: string;
  effectiveDate: string;
  status: string;
  complianceTrend: TrendData[];
  currentCompliance: number;
  regionalDistribution: DistributionData[];
  violationsByMonth: ViolationData[];
  incidentSeverity: DistributionData[];
};

// --- MOCK DATA GENERATION ---
const generateMockData = (): DashboardData => {
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'];
  return {
    policyType: ['Environmental', 'Privacy', 'Financial'][Math.floor(Math.random() * 3)],
    effectiveDate: `2024-0${Math.floor(Math.random() * 9) + 1}-01`,
    status: ['Active', 'Pending', 'Under Review'][Math.floor(Math.random() * 3)],
    complianceTrend: months.map(month => ({
      name: month,
      actual: Math.floor(Math.random() * 20 + 70),
      predicted: Math.floor(Math.random() * 15 + 75),
      target: 90,
    })),
    currentCompliance: Math.floor(Math.random() * 40 + 60),
    regionalDistribution: [
      { name: 'North America', value: Math.floor(Math.random() * 300 + 400) },
      { name: 'Europe', value: Math.floor(Math.random() * 200 + 300) },
      { name: 'Asia-Pacific', value: Math.floor(Math.random() * 250 + 200) },
      { name: 'LATAM', value: Math.floor(Math.random() * 100 + 100) },
    ],
    violationsByMonth: months.map(month => ({
      name: month,
      violations: Math.floor(Math.random() * 20 + 5),
    })),
    incidentSeverity: [
      { name: 'Low', value: Math.floor(Math.random() * 50 + 100) },
      { name: 'Medium', value: Math.floor(Math.random() * 30 + 40) },
      { name: 'High', value: Math.floor(Math.random() * 10 + 5) },
      { name: 'Critical', value: Math.floor(Math.random() * 5 + 1) },
    ],
  };
};

const PIE_COLORS = ['#4f46e5', '#6366f1', '#a5b4fc', '#c7d2fe'];

// --- REUSABLE UI COMPONENTS ---

interface CardProps {
  children: ReactNode;
  className?: string;
}

const Card: FC<CardProps> = ({ children, className = '' }) => (
  <div className={`bg-white rounded-2xl shadow-sm p-6 ${className}`}>
    {children}
  </div>
);

interface InfoCardProps {
  icon: ReactNode;
  title: string;
  value: string;
  color: string;
}

const InfoCard: FC<InfoCardProps> = ({ icon, title, value, color }) => (
  <Card className="flex items-center gap-4">
    <div className={`rounded-full p-3 ${color}`}>
      {icon}
    </div>
    <div>
      <p className="text-sm text-slate-500">{title}</p>
      <p className="text-lg font-semibold text-slate-800">{value}</p>
    </div>
  </Card>
);

interface ChartCardProps {
    title: string;
    icon: ReactNode;
    children: ReactNode;
}

const ChartCard: FC<ChartCardProps> = ({ title, icon, children }) => (
    <Card className="flex flex-col h-full">
        <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
                {icon}
                <h3 className="text-lg font-semibold text-slate-800">{title}</h3>
            </div>
            <button className="p-2 text-slate-500 rounded-md hover:bg-slate-100 hover:text-indigo-600 transition-colors">
                <Download size={18} />
            </button>
        </div>
        <div className="flex-grow w-full h-64">
            {children}
        </div>
    </Card>
);

// --- MAIN DASHBOARD COMPONENT ---

