const QuizMastersPage: NextPage = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedContest, setSelectedContest] = useState<Contest | null>(null);

  const filteredContests = useMemo(() => {
    return contestsData
      .filter(contest => 
        selectedCategory === 'All' || contest.category === selectedCategory
      )
      .filter(contest => 
        contest.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        contest.description.toLowerCase().includes(searchQuery.toLowerCase())
      );
  }, [searchQuery, selectedCategory]);

  const handleEnrollClick = (contest: Contest) => {
    setSelectedContest(contest);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedContest(null);
  };

  useEffect(() => {
    const handleEsc = (event: KeyboardEvent) => {
       if (event.key === 'Escape') {
        handleCloseModal();
       }
    };
    window.addEventListener('keydown', handleEsc);

    return () => {
      window.removeEventListener('keydown', handleEsc);
    };
  }, []);

  return (
    <>
      <Head>
        <title>QuizMasters - Online Trivia Platform</title>
        <meta name="description" content="Explore and enroll in exciting online trivia contests." />
        <link rel="icon" href="/favicon.ico" />
