              <a href="#" className="text-slate-600 hover:text-amber-800 font-medium transition-colors">Profile</a>
            </div>
            <div className="flex items-center space-x-4">
                <button className="flex items-center space-x-2 bg-amber-100 text-amber-900 px-4 py-2 rounded-full hover:bg-amber-200 transition-colors">
                    <User size={20} />
                    <span className="font-semibold">AAlex Johnson</span>
                </button>
            </div>
          </nav>
        </header>

        {/* Main Content */}
        <main className="container mx-auto px-6 py-12">
          <div className="text-center mb-12">
            <h1 className="text-4xl md:text-5xl font-extrabold text-amber-900 mb-2">Available Contests</h1>
            <p className="text-lg text-slate-600 max-w-2xl mx-auto">Find your next challenge and prove your knowledge.</p>
          </div>

          {/* Filters */}
          <div className="mb-10 flex flex-col md:flex-row gap-4 md:items-center md:justify-between">
            <div className="relative flex-grow md:max-w-md">
                <input 
                    type="text"
                    placeholder="Search contests..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 border-2 border-amber-200 rounded-full bg-white focus:ring-2 focus:ring-amber-700 focus:border-amber-700 outline-none transition-shadow"
                />
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            </div>
            <div className="flex flex-wrap gap-2 justify-center">
              {categories.map(category => (
                <button 
                  key={category}
                  onClick={() => setSelectedCategory(category)}
                  className={`px-4 py-2 rounded-full font-semibold text-sm transition-colors ${selectedCategory === category ? 'bg-amber-800 text-white shadow' : 'bg-white text-slate-700 hover:bg-amber-100'}`}>
                  {category}
                </button>
              ))}
            </div>
          </div>

          {/* Contest Grid */}
          {filteredContests.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {filteredContests.map(contest => (
                <ContestCard key={contest.id} contest={contest} onEnroll={handleEnrollClick} />
