            <div className="text-center py-16">
                <p className="text-xl text-slate-500">No contests found. Try adjusting your search or filters!</p>
            </div>
          )}
        </main>

        {/* Modal */}
        <QuizDetailsModal contest={selectedContest} onClose={handleCloseModal} />
      </div>
    </>
  );
};

