  player: Player;
  type: PieceType;
}
type Board = (Piece | null)[][];
type Difficulty = 'Easy' | 'Medium' | 'Hard' | 'Player vs Player';
type Theme = 'Default' | 'Blue' | 'Green' | 'Purple' | 'Wood';
interface Position {
  row: number;
  col: number;
}

