    knight: (props) => <svg {...props} viewBox="0 0 45 45"><g fill="#000" stroke="#000" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M22 10c10.5 1 16.5 8 16 29H15c-2 0-9-11.5-8-21 1-10.5 12.5-8.5 15-8.5z" stroke="#FFF"/><path d="M24.55 10.4l-.45 4.45-2.2-2.15s-1.2-1.6-2.6-1.3c-1.4.3-2.25 2.45-2.25 2.45l-.6 3.9s-2.5-.9-4.3-.9c-1.8 0-3.2.5-3.2.5s-.3-1.2.3-2.6c.6-1.4 2.1-2.8 4.2-2.8 2.1 0 3.25 1.2 3.25 1.2l.9-1.9s.6-1.2 2.1-1.2c1.5 0 2.2 1.25 2.2 1.25z" fill="#FFF" stroke="#FFF"/></g></svg>,
    bishop: (props) => <svg {...props} viewBox="0 0 45 45"><g fill="#000" stroke="#000" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M9 36h27v-2H9v2zm11.4-2.4c-2.4-2.4-2.4-6.2 0-8.6l2.1-2.1c.9-.9 2.1-.9 3 0l2.1 2.1c2.4 2.4 2.4 6.2 0 8.6C26.1 35.1 22.9 35.1 20.4 33.6z" stroke="#FFF"/><path d="M22.5 11.5L20 9h5l-2.5 2.5zM22.5 11.5V17" stroke="#FFF"/><path d="M22.5 20a9.2 9.2 0 0 0 0-9" stroke="#FFF"/><path d="M22.5 20a9.2 9.2 0 0 1 0-9" transform="matrix(-1 0 0 1 45 0)" stroke="#FFF"/></g></svg>,
    queen: (props) => <svg {...props} viewBox="0 0 45 45"><g fill="#000" stroke="#000" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M9 39h27v-3H9v3zm0-4.5h27v-3H9v3zM12 31.5l2-16 8.5 10.5L31 15.5l2 16" stroke="#FFF" strokeLinecap="butt"/><path d="M12.5 7.5l-3 4 1.5 2 2.5-3 1.5 1.5-1.5 2.5 2.5 2.5 2-5-3-3z" stroke="#FFF"/><path d="M14 15.5s2.5-1.5 5-1.5 5 1.5 5 1.5" fill="none" stroke="#FFF"/><path d="M14 15.5s2.5-1.5 5-1.5 5 1.5 5 1.5" transform="matrix(-1 0 0 1 45 0)" fill="none" stroke="#FFF"/></g></svg>,
