const ChessPiece: FC<{ piece: Piece }> = ({ piece }) => {
  const PieceComponent = pieceSvgs[piece.player][piece.type];
  return <PieceComponent className="w-full h-full cursor-grab" />;
};

// INITIAL BOARD SETUP
const initialBoard: Board = [
  ['rook', 'knight', 'bishop', 'queen', 'king', 'bishop', 'knight', 'rook'].map(type => ({ player: 'black', type: type as PieceType })),
  Array(8).fill({ player: 'black', type: 'pawn' }),
  Array(8).fill(null),
  Array(8).fill(null),
  Array(8).fill(null),
  Array(8).fill(null),
  Array(8).fill({ player: 'white', type: 'pawn' }),
  ['rook', 'knight', 'bishop', 'queen', 'king', 'bishop', 'knight', 'rook'].map(type => ({ player: 'white', type: type as PieceType })),
];

// THEME CONFIGURATION
const themes: Record<Theme, { light: string; dark: string }> = {
  Default: { light: 'bg-stone-200', dark: 'bg-stone-500' },
  Blue: { light: 'bg-blue-200', dark: 'bg-blue-600' },
  Green: { light: 'bg-green-200', dark: 'bg-green-600' },
  Purple: { light: 'bg-purple-200', dark: 'bg-purple-600' },
  Wood: { light: 'bg-yellow-200', dark: 'bg-amber-600' },
};

// MAIN COMPONENT
const ChessMasterOnlinePage: NextPage = () => {
  const [board, setBoard] = useState<Board>(initialBoard);
  const [history, setHistory] = useState<Board[]>([initialBoard]);
  const [selectedPiece, setSelectedPiece] = useState<Position | null>(null);
  const [possibleMoves, setPossibleMoves] = useState<Position[]>([]);
  const [showMoves, setShowMoves] = useState(true);
  const [currentPlayer, setCurrentPlayer] = useState<Player>('white');
  const [moveHistory, setMoveHistory] = useState<string[]>([]);
  const [capturedPieces, setCapturedPieces] = useState<{ white: Piece[], black: Piece[] }>({ white: [], black: [] });
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [boardTheme, setBoardTheme] = useState<Theme>('Default');

  const score = useMemo(() => {
    const pieceValues: Record<PieceType, number> = { pawn: 1, knight: 3, bishop: 3, rook: 5, queen: 9, king: 0 };
    const calculateScore = (pieces: Piece[]) => pieces.reduce((acc, p) => acc + pieceValues[p.type], 0);
    return {
      white: calculateScore(capturedPieces.black),
      black: calculateScore(capturedPieces.white),
    };
  }, [capturedPieces]);

  const handleNewGame = useCallback(() => {
    setBoard(initialBoard);
    setHistory([initialBoard]);
    setSelectedPiece(null);
    setPossibleMoves([]);
    setCurrentPlayer('white');
    setMoveHistory([]);
    setCapturedPieces({ white: [], black: [] });
  }, []);

  const handleUndo = useCallback(() => {
    if (history.length <= 1) return;
    const newHistory = [...history];
    newHistory.pop(); // remove current state
    const lastBoard = newHistory[newHistory.length - 1];
    setBoard(lastBoard);
    setHistory(newHistory);
    setCurrentPlayer(prev => prev === 'white' ? 'black' : 'white');
    setMoveHistory(prev => prev.slice(0, -1));
    // Note: Undoing captured pieces is complex and omitted for simplicity
  }, [history]);

  const handleResign = () => {
    alert(`${currentPlayer === 'white' ? 'White' : 'Black'} resigns. ${currentPlayer === 'white' ? 'Black' : 'White'} wins!`);
    handleNewGame();
  };

  // Simplified move calculation for demonstration
  const calculatePossibleMoves = (piece: Piece, pos: Position): Position[] => {
    const moves: Position[] = [];
    if (piece.type === 'pawn') {
        const dir = piece.player === 'white' ? -1 : 1;
        // Simple one-step forward
        if (board[pos.row + dir] && board[pos.row + dir][pos.col] === null) {
            moves.push({ row: pos.row + dir, col: pos.col });
        }
    }
    // Add a few random-ish moves for other pieces to show the feature
    if (piece.type === 'knight') {
        const knightMoves = [[-2, -1], [-2, 1], [-1, -2], [-1, 2], [1, -2], [1, 2], [2, -1], [2, 1]];
        knightMoves.forEach(([dr, dc]) => {
            const newRow = pos.row + dr;
            const newCol = pos.col + dc;
            if (newRow >= 0 && newRow < 8 && newCol >= 0 && newCol < 8) {
                moves.push({ row: newRow, col: newCol });
            }
        });
    }
    return moves.filter(m => !board[m.row][m.col] || board[m.row][m.col]?.player !== piece.player);
  };

  const handleSquareClick = (row: number, col: number) => {
    if (selectedPiece) {
      const isPossibleMove = possibleMoves.some(p => p.row === row && p.col === col);
      if (isPossibleMove) {
        const newBoard = board.map(r => [...r]);
        const pieceToMove = newBoard[selectedPiece.row][selectedPiece.col];
        const captured = newBoard[row][col];

        if (captured) {
            setCapturedPieces(prev => ({
                ...prev,
                [captured.player]: [...prev[captured.player], captured]
            }));
        }

        newBoard[row][col] = pieceToMove;
        newBoard[selectedPiece.row][selectedPiece.col] = null;

        setBoard(newBoard);
        setHistory(prev => [...prev, newBoard]);
        const moveNotation = `${String.fromCharCode(97 + selectedPiece.col)}${8 - selectedPiece.row} -> ${String.fromCharCode(97 + col)}${8 - row}`;
        setMoveHistory(prev => [...prev, moveNotation]);
        setCurrentPlayer(prev => prev === 'white' ? 'black' : 'white');
      }
      setSelectedPiece(null);
      setPossibleMoves([]);
    } else {
      const piece = board[row][col];
      if (piece && piece.player === currentPlayer) {
        setSelectedPiece({ row, col });
        if (showMoves) {
            setPossibleMoves(calculatePossibleMoves(piece, { row, col }));
        }
      }
    }
  };

  return (
    <>
      <Head>
        <title>ChessMaster Online</title>
        <meta name="description" content="A sleek and interactive online chess platform." />
        <link rel="icon" href="/favicon.ico" />
      </Head>
      <main className="min-h-screen bg-gradient-to-br from-blue-50 to-blue-100 text-slate-800 p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto flex flex-col gap-6">
          <header className="text-center">
            <h1 className="text-4xl font-bold text-slate-700 tracking-tight">ChessMaster Online</h1>
            <p className="text-slate-500 mt-1">Your move, champion.</p>
          </header>

          {/* Controls Section */}
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
            <button onClick={handleNewGame} className="control-card"><RefreshCcw className="w-5 h-5 mr-2" />New Game</button>
            <button onClick={handleUndo} className="control-card"><Undo className="w-5 h-5 mr-2" />Undo</button>
            <button onClick={handleResign} className="control-card"><Flag className="w-5 h-5 mr-2" />Resign</button>
            <button onClick={() => setShowMoves(!showMoves)} className={`control-card ${showMoves ? 'bg-slate-600 text-white' : ''}`}><Eye className="w-5 h-5 mr-2" />Show Moves</button>
            <div className="control-card-select"><Palette className="w-5 h-5 mr-2" /><select value={boardTheme} onChange={(e) => setBoardTheme(e.target.value as Theme)} className="bg-transparent w-full focus:outline-none"><option>Default</option><option>Blue</option><option>Green</option><option>Purple</option><option>Wood</option></select></div>
            <div className="control-card-select"><Crown className="w-5 h-5 mr-2" /><select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-transparent w-full focus:outline-none"><option>Easy</option><option>Medium</option><option>Hard</option><option>Player vs Player</option></select></div>
          </div>

          <div className="flex flex-col lg:flex-row gap-6 items-start">
            {/* Chess Board */}
            <div className="w-full lg:w-2/3 aspect-square shadow-2xl rounded-lg overflow-hidden border-4 border-slate-200">
              <div className="grid grid-cols-8 w-full h-full">
                {board.map((rowItems, rowIndex) =>
                  rowItems.map((piece, colIndex) => {
                    const isLight = (rowIndex + colIndex) % 2 !== 0;
                    const theme = themes[boardTheme];
                    const isSelected = selectedPiece?.row === rowIndex && selectedPiece?.col === colIndex;
                    const isPossible = possibleMoves.some(p => p.row === rowIndex && p.col === colIndex);

                    return (
                      <div
                        key={`${rowIndex}-${colIndex}`}
                        onClick={() => handleSquareClick(rowIndex, colIndex)}
                        className={`relative flex items-center justify-center ${isLight ? theme.light : theme.dark}`}
                      >
                        {piece && <ChessPiece piece={piece} />}
                        {isSelected && <div className="absolute inset-0 bg-yellow-400/50"></div>}
                        {isPossible && <div className="absolute inset-0 flex items-center justify-center"><div className="w-1/3 h-1/3 rounded-full bg-slate-900/40"></div></div>}
                      </div>
                    );
                  })
                )}
              </div>
            </div>

            {/* Side Panels */}
            <div className="w-full lg:w-1/3 flex flex-col gap-6">
              {/* Score Card */}
              <div className="info-card">
                <h3 className="card-title"><Swords className="w-5 h-5 mr-2" />Score</h3>
                <div className="grid grid-cols-2 gap-4 mt-2">
                    <div>
                        <p className="font-semibold">White: {score.white}</p>
                        <div className="flex flex-wrap gap-1 mt-2 h-16">{capturedPieces.black.map((p, i) => <div key={i} className="w-6 h-6"><ChessPiece piece={p} /></div>)}</div>
                    </div>
                    <div>
                        <p className="font-semibold">Black: {score.black}</p>
                        <div className="flex flex-wrap gap-1 mt-2 h-16">{capturedPieces.white.map((p, i) => <div key={i} className="w-6 h-6"><ChessPiece piece={p} /></div>)}</div>
                    </div>
                </div>
              </div>

              {/* Move History Card */}
              <div className="info-card">
                <h3 className="card-title">Move History</h3>
                <div className="h-64 overflow-y-auto bg-slate-50 rounded-md p-2 mt-2 font-mono text-sm space-y-1">
                  {moveHistory.length === 0 ? (
                    <p className="text-slate-400">No moves yet.</p>
                  ) : (
                    moveHistory.map((move, index) => (
                      <div key={index} className={`px-2 py-1 rounded ${index % 2 === 0 ? 'bg-slate-100' : ''}`}>
                        <span className="font-semibold mr-2">{Math.floor(index / 2) + 1}.</span>
                        <span>{move}</span>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>
      <style jsx global>{`
        .control-card {
          @apply flex items-center justify-center p-3 bg-white rounded-lg shadow-md border border-slate-200 text-slate-600 font-semibold transition-all duration-200 hover:bg-slate-600 hover:text-white hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-500;
        }
        .control-card-select {
           @apply relative flex items-center p-3 bg-white rounded-lg shadow-md border border-slate-200 text-slate-600 font-semibold transition-all duration-200 hover:shadow-lg;
        }
        .info-card {
            @apply bg-white/80 backdrop-blur-sm p-4 rounded-lg shadow-lg border border-slate-200;
        }
        .card-title {
            @apply flex items-center text-lg font-bold text-slate-700 border-b border-slate-200 pb-2;
        }
      `}</style>
    </>
  );
};

export default ChessMasterOnlinePage;


