// --- MAIN PAGE COMPONENT --- //

const FortuneWheelPage: NextPage = () => {
  const [rotation, setRotation] = useState(0);
  const [isSpinning, setIsSpinning] = useState(false);
  const [winningRecords, setWinningRecords] = useState<WinningRecord[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleSpin = () => {
    if (isSpinning) return;

    setIsSpinning(true);
    const randomPrizeIndex = Math.floor(Math.random() * prizes.length);
    const prize = prizes[randomPrizeIndex];

    // Calculate rotation
    // 5 full spins + random landing spot within the prize segment
    const fullSpins = 5 * 360;
    const targetAngle = randomPrizeIndex * segmentAngle;
    // Subtract half segment angle to center the pointer in the middle of the segment
    const finalAngle = fullSpins + 360 - targetAngle - (segmentAngle / 2);

    setRotation(prev => prev + finalAngle);

    // After animation ends
    setTimeout(() => {
      const newRecord: WinningRecord = {
        prizeName: prize.name,
        date: new Date().toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }),
      };
      setWinningRecords(prev => [newRecord, ...prev]);
      setIsSpinning(false);
    }, 6000); // Match this with the transition duration
  };

  const conicGradient = `conic-gradient(from 0deg, ${prizes
    .map((p, i) => `${p.color} ${i * segmentAngle}deg, ${p.color} ${(i + 1) * segmentAngle}deg`)
    .join(', ')})`;

  return (
    <>
      <main className="bg-slate-100 min-h-screen w-full flex items-center justify-center p-4 sm:p-6 lg:p-8">
        <div className="w-full max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-16 items-center">

          {/* Left Column: Wheel */}
          <div className="flex flex-col items-center gap-8">
            <div className="relative w-80 h-80 sm:w-96 sm:h-96 flex items-center justify-center">
              {/* Pointer */}
              <div className="absolute -top-2 left-1/2 -translate-x-1/2 z-20" style={{ filter: 'drop-shadow(0 4px 3px rgb(0 0 0 / 0.2))' }}>
                  <div className="w-0 h-0 border-l-8 border-r-8 border-t-16 border-l-transparent border-r-transparent border-t-red-800" style={{ transform: 'rotate(180deg)' }}></div>
              </div>

              {/* Wheel */}
              <div 
                className="relative w-full h-full rounded-full border-8 border-white shadow-2xl transition-transform duration-[6000ms] ease-out"
                style={{ 
                  transform: `rotate(${rotation}deg)`,
                  background: conicGradient
                }}
              >
                {prizes.map((prize, index) => {
                  const angle = index * segmentAngle + segmentAngle / 2;
                  return (
                    <div
                      key={prize.id}
                      className="absolute w-full h-full flex justify-center"
                      style={{ transform: `rotate(${angle}deg)` }}
                    >
                      <prize.icon className="absolute top-4 w-8 h-8 text-slate-800/80" />
                    </div>
                  );
                })}
              </div>

              {/* Wheel Center */}
              <div className="absolute w-20 h-20 bg-white rounded-full border-4 border-red-800 shadow-inner" />
            </div>

            <button
              onClick={handleSpin}
              disabled={isSpinning}
              className="w-full max-w-xs px-8 py-4 bg-red-700 text-white font-bold text-xl rounded-full shadow-lg hover:bg-red-800 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed transform hover:scale-105 active:scale-100"
            >
              {isSpinning ? 'Spinning...' : 'SPIN THE WHEEL'}
            </button>
          </div>

          {/* Right Column: Prizes & Records */}
          <div className="w-full max-w-md mx-auto flex flex-col gap-6">
            <div className="bg-red-800 p-6 rounded-2xl shadow-lg">
              <h2 className="text-2xl font-bold text-white text-center mb-4">Prize List</h2>
              <div className="space-y-3">
                {prizes.map(prize => (
                  <PrizeCard key={prize.id} prize={prize} />
                ))}
              </div>
            </div>
            <button
              onClick={() => setIsModalOpen(true)}
              className="w-full px-8 py-4 bg-white text-red-800 font-bold text-lg rounded-full shadow-md border-2 border-red-800 hover:bg-red-50 transition-all duration-300 transform hover:scale-105 active:scale-100"
            >
              VIEW MY WINNING RECORDS
            </button>
          </div>
        </div>
      </main>

      <RecordsModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        records={winningRecords} 
      />
    </>
  );
};

export default FortuneWheelPage;


