// --- TYPESCRIPT INTERFACES ---
type Player = {
  id: number;
  name: string;
  position: string;
  battingAverage: number;
  homeRuns: number;
  rbis: number;
};

type InningScore = {
  inning: number;
  home: number | null;
  away: number | null;
};

type GameResult = {
  homeTeam: string;
  awayTeam:string;
  homeScore: number;
  awayScore: number;
  innings: InningScore[];
  summary: string;
};

type Tab = 'Player Statistics' | 'Team Management' | 'Simulate Game' | 'Game Results';

// --- INITIAL DATA ---
const initialPlayers: Player[] = [
  { id: 1, name: 'Ace Ventura', position: 'Pitcher', battingAverage: 0.150, homeRuns: 1, rbis: 5 },
  { id: 2, name: 'Bobby Bonilla', position: 'Right Fielder', battingAverage: 0.278, homeRuns: 28, rbis: 80 },
  { id: 3, name: 'Ken Griffey Jr.', position: 'Center Fielder', battingAverage: 0.312, homeRuns: 45, rbis: 120 },
  { id: 4, name: 'Mike Piazza', position: 'Catcher', battingAverage: 0.308, homeRuns: 35, rbis: 112 },
  { id: 5, name: 'Derek Jeter', position: 'Shortstop', battingAverage: 0.310, homeRuns: 18, rbis: 75 },
  { id: 6, name: 'Cal Ripken Jr.', position: 'Third Baseman', battingAverage: 0.276, homeRuns: 21, rbis: 93 },
];

const teams = ['Dragons', 'Titans', 'Vipers', 'Lions', 'Sharks', 'Jets'];

// --- HELPER COMPONENTS ---
