const BaseballTeamManagerPage: NextPage = () => {
  const [activeTab, setActiveTab] = useState<Tab>('Player Statistics');
  const [players, setPlayers] = useState<Player[]>(initialPlayers);
  const [newPlayerName, setNewPlayerName] = useState('');
  const [newPlayerPosition, setNewPlayerPosition] = useState('');

  const [homeTeam, setHomeTeam] = useState(teams[0]);
  const [awayTeam, setAwayTeam] = useState(teams[1]);

  const [isSimulating, setIsSimulating] = useState(false);
  const [gameResult, setGameResult] = useState<GameResult | null>(null);

  const handleAddPlayer = () => {
    if (newPlayerName.trim() && newPlayerPosition.trim()) {
      const newPlayer: Player = {
        id: Date.now(),
        name: newPlayerName.trim(),
        position: newPlayerPosition.trim(),
        battingAverage: 0.000,
        homeRuns: 0,
        rbis: 0,
      };
      setPlayers([...players, newPlayer]);
      setNewPlayerName('');
      setNewPlayerPosition('');
    }
  };

  const handleSimulateGame = useCallback(() => {
    if (homeTeam === awayTeam) {
        alert('Home and Away teams cannot be the same.');
        return;
    }
    setIsSimulating(true);
    setGameResult(null);

    setTimeout(() => {
      let homeScore = 0;
      let awayScore = 0;
      const innings: InningScore[] = [];

      for (let i = 1; i <= 9; i++) {
        const homeRuns = Math.floor(Math.random() * 3);
        const awayRuns = Math.floor(Math.random() * 3);
        homeScore += homeRuns;
        awayScore += awayRuns;
        innings.push({ inning: i, home: homeRuns, away: awayRuns });
      }

      // Extra innings if tied
      let inningCount = 9;
      while (homeScore === awayScore) {
        inningCount++;
        const homeRuns = Math.floor(Math.random() * 2);
        const awayRuns = Math.floor(Math.random() * 2);
        if (homeRuns !== awayRuns) {
          homeScore += homeRuns;
          awayScore += awayRuns;
        }
         innings.push({ inning: inningCount, home: homeRuns, away: awayRuns });
      }

      const result: GameResult = {
        homeTeam,
        awayTeam,
        homeScore,
        awayScore,
        innings,
        summary: `${homeScore > awayScore ? homeTeam : awayTeam} won the game!`
      };

      setGameResult(result);
      setIsSimulating(false);
      setActiveTab('Game Results');
    }, 2000);
  }, [homeTeam, awayTeam]);

  const TeamDropdown: FC<{ selectedTeam: string; onSelect: (team: string) => void; otherTeam: string; label: string }> = ({ selectedTeam, onSelect, otherTeam, label }) => (
    <div className="relative w-full">
      <label className="block text-sm font-medium text-yellow-900 mb-1">{label}</label>
      <select 
        value={selectedTeam}
        onChange={(e) => onSelect(e.target.value)}
        className="w-full p-3 bg-white border border-yellow-300 rounded-lg appearance-none focus:outline-none focus:ring-2 focus:ring-yellow-600 text-yellow-900"
      >
        {teams.map(team => (
          <option key={team} value={team}>{team}</option>
        ))}
      </select>
      <ChevronDown className="absolute right-3 top-10 h-5 w-5 text-yellow-700 pointer-events-none" />
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'Player Statistics':
        return (
          <div className="space-y-8">
            <Card>
              <h2 className="text-2xl font-bold text-yellow-900 mb-4">Player Statistics</h2>
              <div className="overflow-x-auto">
                <table className="w-full text-left table-auto">
                  <thead>
                    <tr className="border-b-2 border-yellow-200">
                      <th className="p-3 text-sm font-bold text-yellow-800">Name</th>
                      <th className="p-3 text-sm font-bold text-yellow-800">Position</th>
                      <th className="p-3 text-sm font-bold text-yellow-800">Batting Avg.</th>
                      <th className="p-3 text-sm font-bold text-yellow-800">Home Runs</th>
                      <th className="p-3 text-sm font-bold text-yellow-800">RBIs</th>
                    </tr>
                  </thead>
                  <tbody>
                    {players.map((player, index) => (
                      <tr key={player.id} className={`border-b border-yellow-100 ${index % 2 === 0 ? 'bg-amber-50' : 'bg-white'}`}>
                        <td className="p-3 font-medium text-gray-700">{player.name}</td>
                        <td className="p-3 text-gray-600">{player.position}</td>
                        <td className="p-3 text-gray-600">{player.battingAverage.toFixed(3)}</td>
                        <td className="p-3 text-gray-600">{player.homeRuns}</td>
                        <td className="p-3 text-gray-600">{player.rbis}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </Card>
            <Card>
              <h3 className="text-xl font-bold text-yellow-900 mb-4">Add New Player</h3>
              <div className="flex flex-col md:flex-row gap-4 items-end">
                <div className="w-full">
                  <label className="block text-sm font-medium text-yellow-900 mb-1">Player Name</label>
                  <input type="text" value={newPlayerName} onChange={e => setNewPlayerName(e.target.value)} placeholder="e.g., Babe Ruth" className="w-full p-3 bg-white border border-yellow-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-yellow-600" />
                </div>
                <div className="w-full">
                  <label className="block text-sm font-medium text-yellow-900 mb-1">Position</label>
                  <input type="text" value={newPlayerPosition} onChange={e => setNewPlayerPosition(e.target.value)} placeholder="e.g., Outfielder" className="w-full p-3 bg-white border border-yellow-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-yellow-600" />
                </div>
                <PrimaryButton onClick={handleAddPlayer} className="w-full md:w-auto"><Plus size={18} /> Add Player</PrimaryButton>
              </div>
            </Card>
          </div>
        );
      case 'Team Management':
        return (
            <Card>
                <h2 className="text-2xl font-bold text-yellow-900 mb-6">Team Management</h2>
                <div className="grid md:grid-cols-2 gap-6">
                    <div>
                        <h3 className="text-xl font-semibold text-yellow-800 mb-3">Roster Overview</h3>
