  Good: { scoreRange: '670-799', potential: '+10-50 Points', bgColor: 'bg-blue-100', textColor: 'text-blue-800' },
  Fair: { scoreRange: '600-669', potential: '+50-100 Points', bgColor: 'bg-yellow-100', textColor: 'text-yellow-800' },
  Poor: { scoreRange: 'Below 600', potential: '+100-150 Points', bgColor: 'bg-orange-100', textColor: 'text-orange-800' },
