const CreditStatusCard: FC<{ status: NonNullable<CreditStatus>; selected: boolean; onSelect: () => void }> = ({ status, selected, onSelect }) => {
  const data = creditStatusData[status];
  return (
    <div 
      onClick={onSelect}
      className={`p-6 rounded-xl border-2 cursor-pointer transition-all duration-300 ${selected ? 'border-blue-500 bg-blue-50 scale-105 shadow-md' : 'border-slate-200 bg-white hover:border-blue-300 hover:bg-slate-50'}`}>
      <div className="flex justify-between items-center">
        <h4 className="font-bold text-lg text-slate-800">{status} Credit</h4>
        {selected && <ShieldCheck className="w-6 h-6 text-blue-500" />}
