 <NavLink href="#benefits">Benefits</NavLink>\n            </nav>\n            <PrimaryButton onClick={() => scrollTo(\'get-started\')}>Get Started</PrimaryButton>\n          </div>\n        </header>\n\n        <main className="container mx-auto px-6 py-12 md:py-20">\n          {/* Hero Section */}\n          <section className="text-center py-16 md:py-24">\n            <h1 className="text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 tracking-tight">Revitalize Your Credit, <br/>Unlock Your Future.</h1>\n            <p className="max-w-2xl mx-auto text-lg text-slate-600 mb-8">Take control of your financial health with our expert credit repair services. A better credit score is closer than you think.</p>\n            <PrimaryButton className="px-8 py-4 text-lg" onClick={() => scrollTo(\'get-started\')}>Get Started Today <ChevronRight className="inline w-5 h-5 ml-1" /></PrimaryButton>\n          </section>\n\n          {/* Services Section */}\n          <section id="services" className="py-16 md:py-24">\n            <div className="text-center mb-12">\n              <h2 className="text-3xl md:text-4xl font-bold text-slate-800">Our Comprehensive Credit Repair Services</h2>\n              <p className="max-w-xl mx-auto text-slate-600 mt-4">We offer a suite of services designed to address every aspect of your credit health.</p>\n            </div>\n            <div className="grid md:grid-cols-1 lg:grid-cols-3 gap-8">\n              {/* Credit Report Analysis Card */}\n              <ServiceCard \n                icon={<FileText />} \n                title="Credit Report Analysis" \n                description="We dive deep into your credit reports from all three bureaus to find inaccuracies and opportunities for improvement."\n                items={["Identification of disputable items", "Personalized improvement plan"]}\n              />\n              {/* Dispute Management Card */}\n              <ServiceCard \n                icon={<GanttChartSquare />} \n                title="Dispute Management" \n                description="Our experts handle the entire dispute process, from drafting letters to communicating with creditors and bureaus."\n                items={["Expertly crafted dispute letters", "Tracking and follow-up", "Escalation when necessary"]}\n              />\n              {/* Credit Education Card */}\n              <ServiceCard \n                icon={<BookOpen />} \n                title="Credit Education"\n                description="Knowledge is power. We empower you with the financial literacy to maintain a healthy credit score for life."\n                items={["Credit score fundamentals", "Budgeting and financial planning", "Credit-building strategies"]}\n              />\n            </div>\n          </section>\n\n          {/* Lead Gen Form Section */}\n          <section id="get-started" className="py-16 md:py-24 bg-white rounded-3xl shadow-xl border border-slate-100">\n            <div className="grid lg:grid-cols-2 gap-12 items-center px-6 md:px-12">\n              {/* Left Column: Form */}\n              <div id="check-your-credit-status-card">\n                <h2 className="text-3xl md:text-4xl font-bold text-slate-800 mb-2">Get My Free Credit Analysis</h2>\n                <p className="text-slate-600 mb-8">Fill out the form below to get a no-obligation analysis and see how we can help you.</p>\n                {submitted ? (\n                    <div className="text-center p-8 bg-green-100 text-green-800 rounded-lg">\n                        <CheckCircle2 className="w-12 h-12 mx-auto mb-4"/>\n                        <h3 className="text-2xl font-bold">Thank You!</h3>\n                        <p>Your request has been submitted. One of our credit experts will contact you shortly.</p>\n                    </div>\n                ) : (\n                    <form onSubmit={handleFormSubmit} className="space-y-6">\n                    <div className="relative">\n                        <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />\n                        <input type="text" name="name" placeholder="Full Name" value={formData.name} onChange={handleInputChange} required className="w-full pl-12 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />\n                    </div>\n                    <div className="relative">\n                        <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />\n                        <input type="email" name="email" placeholder="Email Address" value={formData.email} onChange={handleInputChange} required className="w-full pl-12 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />\n                    </div>\n                    <div className="relative">\n                        <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />\n                        <input type="tel" name="phone" placeholder="Phone Number" value={formData.phone} onChange={handleInputChange} required className="w-full pl-12 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none" />\n                    </div>\n                    <div>\n                        <p className="font-medium text-slate-700 mb-3">Select your current credit status:</p>\n                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">\n                        {(Object.keys(creditStatusData) as Array<NonNullable<CreditStatus>>).map(status => (\n                            <CreditStatusCard key={status} status={status} selected={selectedStatus === status} onSelect={() => setSelectedStatus(status)} />\n                        ))}\n                        </div>\n                    </div>\n                    <PrimaryButton className="w-full py-4 text-lg">Get My Free Credit Analysis</PrimaryButton>\n                    </form>\n                )}\n              </div>\n              {/* Right Column: Potential */}\n              <div id="estimated-credit-repair-potential" className="bg-slate-50 p-8 rounded-2xl border border-slate-200">\n                <h3 className="text-2xl font-bold text-slate-800 mb-6">Estimated Credit Repair Potential</h3>\n                <div className="space-y-4">\n                    <div className="flex justify-between items-center text-slate-600">\n                        <span>Current Status:</span>\n                        <span className={`font-bold ${selectedStatus ? creditStatusData[selectedStatus].textColor : \'text-slate-800\'}`}>{selectedStatus || \'Not Selected\'}</span>\n                    </div>\n                    <div className="flex justify-between items-center text-slate-600">\n                        <span>Score Range:</span>\n                        <span className={`font-bold ${selectedStatus ? creditStatusData[selectedStatus].textColor : \'text-slate-800\'}`}>{selectedStatus ? creditStatusData[selectedStatus].scoreRange : \'N/A\'}</span>\n                    </div>\n                    <hr className="my-4 border-slate-200" />\n                    <div className="text-center py-4">\n                        <p className="text-slate-600 mb-2">Potential Score Improvement</p>\n                        <div className="flex justify-center items-baseline text-blue-600">\n                            <TrendingUp className="w-10 h-10 mr-2"/>\n                            <p className="text-5xl font-bold">{selectedStatus ? creditStatusData[selectedStatus].potential : \'... \'}</p>\n                        </div>\n                    </div>\n                </div>\n                <p className="text-xs text-slate-500 mt-6 text-center">*This is an estimate based on average results for clients with similar credit profiles. Actual results may vary.</p>\n              </div>\n            </div>\n          </section>\n\n          {/* Testimonials Section */}\n          <section id="benefits" className="py-16 md:py-24">\n            <div className="text-center mb-12">\n              <h2 className="text-3xl md:text-4xl font-bold text-slate-800">Trusted by Clients Nationwide</h2>\n              <p className="max-w-xl mx-auto text-slate-600 mt-4">See what our satisfied clients have to say about their journey with CreditRevive.</p>\n            </div>\n            <div className="grid md:grid-cols-1 lg:grid-cols-2 gap-8">\n                <TestimonialCard \n                    quote="CreditRevive completely changed my financial outlook. They removed multiple negative items from my report and my score jumped over 120 points!"\n                    name="Sarah J."\n                    title="Homeowner in Texas"\n                />\n                <TestimonialCard \n                    quote="The process was so easy and transparent. I loved the educational part, I feel so much more in control of my finances now. Highly recommended."\n                    name="Michael B."\n                    title="Small Business Owner"\n                />\n            </div>\n          </section>\n\n          {/* Final CTA Section */}\n          <section id="get-started-today-card" className="text-center bg-blue-600 text-white rounded-3xl p-12 md:p-16 my-16 shadow-2xl bg-gradient-to-r from-blue-600 to-teal-500">\n             <h2 className="text-3xl md:text-4xl font-bold mb-4">Ready to Rebuild Your Credit?</h2>\n             <p className="max-w-2xl mx-auto text-lg text-blue-100 mb-8">Your journey to a better financial future starts with a single step. Let our experts guide you.</p>\n             <button onClick={() => scrollTo(\'get-started\')} className="px-8 py-4 text-lg font-semibold bg-white text-blue-600 rounded-lg shadow-md hover:bg-slate-100 transition-colors duration-300">\n                Start My Journey Now\n             </button>\n          </section>\n\n        </main>\n\n        {/* Footer */}\n        <footer id="footer-card" className="bg-slate-800 text-slate-300">\n          <div className="container mx-auto px-6 py-12">\n            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-8">\n                <div className="col-span-2 lg:col-span-2">\n                    <h4 className="text-xl font-bold text-white mb-4">CreditRevive</h4>\n                    <p className="text-slate-400 max-w-xs">Your trusted partner in credit repair and financial education.</p>\n                </div>\n                <div id="crcredit-revive-services-card">\n                    <h5 className="font-semibold text-white mb-4">Services</h5>\n                    <ul className="space-y-2">\n                        <li><a href="#services" className="hover:text-white transition-colors">Credit Analysis</a></li>\n                        <li><a href="#services" className="hover:text-white transition-colors">Dispute Management</a></li>\n                        <li><a href="#services" className="hover:text-white transition-colors">Credit Education</a></li>\n                    </ul>\n                </div>\n                <div>\n                    <h5 className="font-semibold text-white mb-4">Company</h5>\n                    <ul className="space-y-2">\n                        <li><a href="#" className="hover:text-white transition-colors">About Us</a></li>\n                        <li><a href="#how-it-works" className="hover:text-white transition-colors">How It Works</a></li>\n                        <li><a href="#benefits" className="hover:text-white transition-colors">Testimonials</a></li>\n                    </ul>\n                </div>\n                <div>\n                    <h5 className="font-semibold text-white mb-4">Legal</h5>\n                    <ul className="space-y-2">\n                        <li><a href="#" className="hover:text-white transition-colors">Privacy Policy</a></li>\n                        <li><a href="#" className="hover:text-white transition-colors">Terms of Service</a></li>\n                    </ul>\n                </div>\n            </div>\n            <div className="mt-12 border-t border-slate-700 pt-8 text-center text-slate-400 text-sm">\n                <p>&copy; {new Date().getFullYear()} CreditRevive. All Rights Reserved.</p>\n            </div>\n          </div>\n        </footer>\n      </div>\n    </>\n  );\n};\n\nexport default CreditRevivePage;\n'}

