          <a href="#contact" className="hidden md:inline-block bg-teal-500 text-white font-bold py-2 px-5 rounded-full hover:bg-teal-600 transition-colors">
            Book Now
          </a>
        </nav>
      </header>

      <main>
        {/* Hero Section */}
        <Section id="home" className="!pt-24 md:!pt-32" ref={(el) => (sectionRefs.current['home'] = el)}>
          <div className="text-center">
            <h1 className="text-4xl md:text-6xl font-extrabold text-teal-800 leading-tight">Your Partner in Lifelong Wellness</h1>
            <p className="mt-4 text-lg md:text-xl text-slate-600 max-w-3xl mx-auto">Experience compassionate, patient-centered healthcare at Harmony Health Clinic. We\'re dedicated to your well-being.</p>
