              <div className="max-w-4xl mx-auto text-center flex flex-col items-center gap-6">
                 <Building className="w-16 h-16 text-stone-800" />
                <p className="text-lg leading-relaxed">SolarTech is dedicated to accelerating the world's transition to sustainable energy. We design, manufacture, and install the world's most advanced solar technology solutions. Our mission is to provide affordable and clean energy to residential, commercial, and utility-scale customers worldwide, driven by our core values of innovation, quality, and customer satisfaction.</p>
              </div>
            </div>
          </section>

          {/* Products Section */}
          <section id="products" className="py-20 md:py-28">
            <div className="container mx-auto px-6">
              <SectionTitle>Our Products</SectionTitle>
              <div className="grid md:grid-cols-3 gap-8">
                <ProductCard 
                  icon={<Sun size={48} strokeWidth={1.5} />} 
                  title="Solar Panels" 
                  description="High-efficiency monocrystalline and polycrystalline panels designed for maximum power output and long-term reliability."
                />
                <ProductCard 
                  icon={<BatteryCharging size={48} strokeWidth={1.5} />} 
                  title="Energy Storage" 
                  description="Advanced lithium-ion battery systems to store excess solar energy for use at night or during power outages."
                />
                <ProductCard 
                  icon={<Wrench size={48} strokeWidth={1.5} />} 
                  title="Mounting Systems" 
                  description="Durable and versatile racking and mounting solutions for all roof types and ground-mount installations."
                />
              </div>
            </div>
          </section>

          {/* News Section */}
          <section id="news" className="py-20 md:py-28 bg-white/30">
            <div className="container mx-auto px-6">
              <SectionTitle>Latest News</SectionTitle>
              <div className="max-w-2xl mx-auto bg-white/50 rounded-2xl p-6 shadow-lg border border-stone-200/50">
                <div className="divide-y divide-amber-200">
                  <NewsItem icon={<Newspaper size={24} />} title="New solar panel technology launched" date="October 26, 2023" />
                  <NewsItem icon={<Award size={24} />} title="SolarTech wins industry award for innovation" date="September 15, 2023" />
                   <NewsItem icon={<Newspaper size={24} />} title="Partnership with local communities announced" date="August 02, 2023" />
                </div>
              </div>
            </div>
          </section>

          {/* Contact Section */}
          <section id="contact" className="py-20 md:py-28">
            <div className="container mx-auto px-6">
              <SectionTitle>Contact Us</SectionTitle>
              <div className="max-w-xl mx-auto bg-white/50 p-8 rounded-2xl shadow-lg border border-stone-200/50">
                <form onSubmit={handleSubmit} className="space-y-6">
                  <div>
                    <label htmlFor="name" className="block text-sm font-medium text-stone-700 mb-1">Name</label>
                    <input type="text" name="name" id="name" required value={formData.name} onChange={handleInputChange} className="w-full px-4 py-2 border border-stone-300 rounded-md shadow-sm focus:ring-stone-600 focus:border-stone-600 transition" />
                  </div>
                  <div>
                    <label htmlFor="email" className="block text-sm font-medium text-stone-700 mb-1">Email</label>
                    <input type="email" name="email" id="email" required value={formData.email} onChange={handleInputChange} className="w-full px-4 py-2 border border-stone-300 rounded-md shadow-sm focus:ring-stone-600 focus:border-stone-600 transition" />
                  </div>
                  <div>
                    <label htmlFor="message" className="block text-sm font-medium text-stone-700 mb-1">Message</label>
                    <textarea name="message" id="message" rows={4} required value={formData.message} onChange={handleInputChange} className="w-full px-4 py-2 border border-stone-300 rounded-md shadow-sm focus:ring-stone-600 focus:border-stone-600 transition"></textarea>
                  </div>
                  <div>
                    <button type="submit" disabled={formStatus === 'submitting'} className="w-full flex justify-center items-center gap-2 px-6 py-3 border border-transparent text-base font-medium rounded-md text-amber-50 bg-stone-800 hover:bg-stone-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-stone-600 transition disabled:bg-stone-400">
                      <Send size={20} />
                      {formStatus === 'submitting' ? 'Sending...' : 'Send Message'}
                    </button>
                  </div>
                  {formStatus === 'success' && <p className="text-green-600 text-center">Message sent successfully!</p>}
                  {formStatus === 'error' && <p className="text-red-600 text-center">Please fill out all fields.</p>}
                </form>
              </div>
            </div>
          </section>
        </main>

        {/* Footer */}
        <footer className="bg-stone-800 text-amber-100/70 py-6">
          <div className="container mx-auto px-6 text-center">
            <p>&copy; {new Date().getFullYear()} SolarTech Inc. All rights reserved.</p>
          </div>
        </footer>
      </div>
    </>
  );
}

