k={() => setActiveEventType(\'Workshop\')} className="flex items-center gap-2 bg-orange-200 text-rose-800 px-4 py-2 rounded-full hover:bg-rose-200 transition-colors font-semibold"> <Ticket className="w-5 h-5" /> Cocktail Workshops</button>\n                        <button onClick={() => setActiveEventType(\'Poker\')} className="flex items-center gap-2 bg-orange-200 text-rose-800 px-4 py-2 rounded-full hover:bg-rose-200 transition-colors font-semibold"> <Crown className="w-5 h-5" /> Poker Nights</button>\n                        <button onClick={() => setActiveEventType(\'Pairing\')} className="flex items-center gap-2 bg-orange-200 text-rose-800 px-4 py-2 rounded-full hover:bg-rose-200 transition-colors font-semibold"> <Utensils className="w-5 h-5" /> Food Pairings</button>\n                     </div>\n                     <div className="grid md:grid-cols-2 gap-8">\n                        {filteredEvents.map(event => (\n                            <Card key={event.id} className="flex items-center gap-6">\n                                <div className="text-center flex-shrink-0">\n                                    <p className="text-rose-800 font-bold text-lg">{event.date.split(\' \')[0]}</p>\n                                    <p className="text-3xl font-bold text-gray-900">{event.date.split(\' \')[1]}</p>\n                                </div>\n                                <div className="flex-grow">\n                                    <h3 className="text-xl font-bold text-rose-800">{event.name}</h3>\n                                    <p className="text-gray-600 mt-1 mb-4">{event.description}</p>\n                                    <button className="bg-transparent border-2 border-rose-700 text-rose-700 px-4 py-1 rounded-full hover:bg-rose-700 hover:text-white transition-colors font-semibold">Book Now</button>\n                                </div>\n                            </Card>\n                        ))}\n                     </div>\n                </section>\n                \n                {/* Testimonials & Contact Section */}\n                <section id="testimonials" className="grid lg:grid-cols-3 gap-8 items-start">\n                    <div className="lg:col-span-2 space-y-8">\n                        <h2 className="text-4xl font-bold text-rose-800">What Our Patrons Say</h2>\n                        {testimonials.map((testimonial, i) => (\n                             <Card key={i}>\n                                <p className="text-gray-600 italic mb-4">"{testimonial.quote}"</p>\n                                <p className="font-bold text-rose-800 text-right">- {testimonial.name}</p>\n                             </Card>\n                        ))}\n                    </div>\n                    <div id="contact" className="lg:col-span-1">\n                         <h2 className="text-4xl font-bold text-rose-800 mb-4">Contact & Hours</h2>\n                         <Card>\n                            <ul className="space-y-4">\n                                <li className="flex items-center gap-4">\n                                    <MapPin className="w-6 h-6 text-rose-700 flex-shrink-0" />\n                                    <span className="text-gray-700">123 Bourbon St, Whiskeyville, KY 40004</span>\n                                </li>\n                                <li className="flex items-center gap-4">\n                                    <Phone className="w-6 h-6 text-rose-700 flex-shrink-0" />\n                                    <span className="text-gray-700">(555) 123-4567</span>\n                                </li>\n                                <li className="flex items-center gap-4">\n                                    <Mail className="w-6 h-6 text-rose-700 flex-shrink-0" />\n                                    <span className="text-gray-700">contact@bourbonhub.com</span>\n                                </li>\n                            </ul>\n                            <div className="border-t border-orange-200 mt-6 pt-4">\n                                <p className="font-bold text-rose-800">Hours:</p>\n                                <p className="text-gray-700">Mon-Thurs: 4pm - 12am</p>\n                                <p className="text-gray-700">Fri-Sun: 2pm - 2am</p>\n                            </div>\n                         </Card>\n                    </div>\n                </section>\n            </main>\n\n            <footer className="bg-orange-200/50 mt-24">\n                <div className="container mx-auto px-6 py-6 text-center text-rose-800/80">\n                    <p>&copy; {new Date().getFullYear()} Bourbon Bar Hub. All Rights Reserved.</p>\n                </div>\n            </footer>\n        </div>\n    );\n};\n\nexport default BourbonBarHubPage;\n'}

import { useState, useEffect, useMemo, type FC, type ReactNode } from 'react';
import type { NextPage } from 'next';
import { Search, UserPlus, Phone, Clock, CheckCircle, MoreHorizontal, FileText, Bell, Settings, LogOut, Download, AlertTriangle, X } from 'lucide-react';
import { clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

// Helper to merge Tailwind classes
function cn(...inputs: any[]) {
  return twMerge(clsx(inputs));
}

// --- TYPE DEFINITIONS ---
type CallStatus = 'To-Do' | 'Pending' | 'Completed';

interface Client {
  id: number;
  name: string;
  company: string;
  phone: string;
  avatar: string;
}

interface Call {
  id: number;
  clientId: number;
  reason: string;
  dueDate: string;
  status: CallStatus;
  details: string;
}

// --- MOCK DATA ---
const initialClients: Client[] = [
  { id: 1, name: 'John Doe', company: 'Innovate Inc.', phone: '555-0101', avatar: 'JD' },
  { id: 2, name: 'Jane Smith', company: 'Solutions Co.', phone: '555-0102', avatar: 'JS' },
  { id: 3, name: 'Peter Jones', company: 'Tech Gadgets', phone: '555-0103', avatar: 'PJ' },
  { id: 4, name: 'Mary Johnson', company: 'Global Exports', phone: '555-0104', avatar: 'MJ' },
];

const initialCalls: Call[] = [
  { id: 101, clientId: 1, reason: 'Billing Inquiry', dueDate: '2024-07-25', status: 'To-Do', details: 'Client has a question about their recent invoice #INV-12345.' },
  { id: 102, clientId: 2, reason: 'Technical Support', dueDate: '2024-07-26', status: 'Pending', details: 'Escalated to Tier 2 support. Waiting for feedback from the engineering team.' },
  { id: 103, clientId: 1, reason: 'Follow-up on Service', dueDate: '2024-07-22', status: 'Completed', details: 'Called to confirm service was completed to satisfaction. Client confirmed all is well.' },
  { id: 104, clientId: 3, reason: 'New Feature Request', dueDate: '2024-07-28', status: 'To-Do', details: 'Client requested a new feature for the dashboard to export data in CSV format.' },
  { id: 105, clientId: 4, reason: 'Contract Renewal', dueDate: '2024-08-01', status: 'Pending', details: 'Sent renewal documents. Awaiting client signature.' },
  { id: 106, clientId: 2, reason: 'Login Issue', dueDate: '2024-07-23', status: 'Completed', details: 'Password reset link sent. Client was able to log in successfully.' },
];

// --- UI HELPER COMPONENTS ---

const Card: FC<{ children: ReactNode; className?: string }> = ({ children, className }) => (
  <div className={cn('bg-white rounded-xl shadow-sm p-6', className)}>{children}</div>
);

const StatusPill: FC<{ status: CallStatus }> = ({ status }) => {
  const statusStyles = {
    'To-Do': 'bg-blue-100 text-blue-800',
    'Pending': 'bg-yellow-100 text-yellow-800',
    'Completed': 'bg-green-100 text-green-800',
  };
  return <span className={cn('px-2 py-1 text-xs font-medium rounded-full', statusStyles[status])}>{status}</span>;
};

const Avatar: FC<{ initial: string }> = ({ initial }) => (
  <div className="w-10 h-10 rounded-full bg-violet-100 text-violet-600 flex items-center justify-center font-bold text-sm">
    {initial}
  </div>
);

const IconButton: FC<{ icon: ReactNode; onClick?: () => void; className?: string }> = ({ icon, onClick, className }) => (
    <button onClick={onClick} className={cn('p-2 rounded-full hover:bg-violet-100 text-slate-500 hover:text-violet-600 transition-colors', className)}>
        {icon}
    </button>
);

// --- MAIN PAGE COMPONENT ---

const CustomerServiceManagerPage: NextPage = () => {
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [calls, setCalls] = useState<Call[]>(initialCalls);
  const [filteredClientId, setFilteredClientId] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCallStatusTab, setActiveCallStatusTab] = useState<CallStatus>('To-Do');
  const [lastUpdated, setLastUpdated] = useState(new Date());
  const [isAdmin, setIsAdmin] = useState(true);
  const [showAddClientModal, setShowAddClientModal] = useState(false);
  const [showCallDetailsModal, setShowCallDetailsModal] = useState<Call | null>(null);
  const [showReportModal, setShowReportModal] = useState(false);

  useEffect(() => {
    const timer = setInterval(() => setLastUpdated(new Date()), 60000); // Update every minute
    return () => clearInterval(timer);
  }, []);

  const filteredClients = useMemo(() =>
    clients.filter(client =>
      client.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      client.company.toLowerCase().includes(searchTerm.toLowerCase())
    ), [clients, searchTerm]);

  const filteredCalls = useMemo(() =>
    calls
      .filter(call => call.status === activeCallStatusTab)
      .filter(call => filteredClientId === null || call.clientId === filteredClientId)
  , [calls, activeCallStatusTab, filteredClientId]);

  const getClientById = (id: number) => clients.find(c => c.id === id);

  const handleShowCalls = (clientId: number) => {
    setFilteredClientId(current => (current === clientId ? null : clientId));
  };

  const handleGenerateReport = () => {
    if (isAdmin) {
      setShowReportModal(true);
    } else {
      alert('You do not have permission to generate reports.');
    }
  };

  return (
    <div className="min-h-screen bg-pink-50 text-slate-800 font-sans">
      {/* Header */}
      <header className="bg-white/80 backdrop-blur-lg sticky top-0 z-20 border-b border-slate-200">
        <div className="max-w-screen-2xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-4">
             <div className="w-8 h-8 bg-violet-600 rounded-lg flex items-center justify-center">
                <Phone className="w-4 h-4 text-white"/>
             </div>
            <h1 className="text-xl font-bold text-slate-800">CallManager</h1>
          </div>
          <div className="flex items-center gap-4">
            <IconButton icon={<Bell size={20} />} />
            <IconButton icon={<Settings size={20} />} />
            <div className="w-10 h-10 rounded-full bg-slate-200 border-2 border-dashed" />
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-screen-2xl mx-auto p-6 grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

        {/* Left & Middle Column */}
        <div className="lg:col-span-8 flex flex-col gap-8">

          {/* Client Directory Section */}
          <Card className="w-full">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4">
              <h2 className="text-2xl font-bold mb-2 sm:mb-0">Client Directory</h2>
              <button 
                onClick={() => setShowAddClientModal(true)}
                className="flex items-center gap-2 bg-violet-600 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-violet-700 transition-colors disabled:bg-violet-300"
                disabled={!isAdmin}
              >
                <UserPlus size={16} />
                Add New Client
              </button>
            </div>
            <div className="relative mb-4">
              <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input 
                type="text"
                placeholder="Search clients..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-violet-300 focus:border-violet-500 outline-none transition"
              />
            </div>
            <div className="space-y-3 max-h-60 overflow-y-auto pr-2">
              {filteredClients.map(client => (
                <div key={client.id} className="flex items-center justify-between bg-slate-50 p-3 rounded-lg">
                  <div className="flex items-center gap-4">
                    <Avatar initial={client.avatar} />
                    <div>
                      <p className="font-semibold">{client.name}</p>
                      <p className="text-sm text-slate-500">{client.phone}</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => handleShowCalls(client.id)}
                    className={cn(
                        'px-3 py-1.5 text-sm font-semibold rounded-md transition-colors',
                        filteredClientId === client.id ? 'bg-violet-600 text-white' : 'bg-slate-200 text-slate-700 hover:bg-slate-300'
                    )}
                  >
                    Show Calls
                  </button>
                </div>
              ))}
            </div>
          </Card>

          {/* Call Management Section */}
          <Card className="w-full">
            <h2 className="text-2xl font-bold mb-4">Call Management</h2>
            {filteredClientId && (
                <div className="flex justify-between items-center bg-violet-50 text-violet-700 p-3 rounded-lg mb-4">
                    <p>Showing calls for <span className="font-bold">{getClientById(filteredClientId)?.name}</span></p>
                    <button onClick={() => setFilteredClientId(null)} className="font-semibold text-sm hover:underline">Show All</button>
                </div>
            )}
            <div className="border-b border-slate-200 mb-4">
              <nav className="-mb-px flex gap-6" aria-label="Tabs">
                {(['To-Do', 'Pending', 'Completed'] as CallStatus[]).map(tab => (
                  <button
                    key={tab}
                    onClick={() => setActiveCallStatusTab(tab)}
                    className={cn(
                      'whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm',
                      activeCallStatusTab === tab
                        ? 'border-violet-500 text-violet-600'
                        : 'border-transparent text-slate-500 hover:text-slate-700 hover:border-slate-300'
                    )}
                  >
                    {tab}
                  </button>
                ))}
              </nav>
            </div>
            <div className="space-y-4">
              {filteredCalls.length > 0 ? filteredCalls.map(call => {
                const client = getClientById(call.clientId);
                return (
                  // Logged Call Card (Example for John Doe)
                  <div key={call.id} className="border border-slate-200 p-4 rounded-lg flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                    <div className="flex items-center gap-4">
                       <div className="hidden sm:block">
                          <Avatar initial={client?.avatar || '??'} />
                       </div>
                      <div>
                        <p className="font-semibold">{call.reason}</p>
                        <p className="text-sm text-slate-500">For: <span className="font-medium text-slate-600">{client?.name}</span></p>
                        <p className="text-sm text-slate-500">Due: {call.dueDate}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4 w-full sm:w-auto justify-between">
                      <StatusPill status={call.status} />
                      <button 
                        onClick={() => setShowCallDetailsModal(call)}
                        className="text-sm font-semibold text-violet-600 hover:underline"
                      >
                        View Details
                      </button>
                    </div>
                  </div>
                );
              }) : (
                <p className="text-center text-slate-500 py-8">No calls in this category.</p>
              )}
            </div>
          </Card>
        </div>

        {/* Right Column */}
        <div className="lg:col-span-4 flex flex-col gap-8">
          {/* Update Information Card & Last Updated Card */}
          <Card>
            <h3 className="font-bold text-lg mb-4">Update Information</h3>
            <div className="text-sm text-slate-500 mb-4">
              Last updated: <span className="font-medium text-slate-700">{lastUpdated.toLocaleTimeString()}</span>
            </div>
            <button 
              onClick={handleGenerateReport}
              className="w-full flex items-center justify-center gap-2 bg-violet-600 text-white px-4 py-2.5 rounded-lg text-sm font-semibold hover:bg-violet-700 transition-colors disabled:bg-violet-400 disabled:cursor-not-allowed"
              disabled={!isAdmin}
            >
              <FileText size={16} />
              Generate Report
            </button>
            {!isAdmin && <p className="text-xs text-red-500 mt-2 text-center">Admin permission required.</p>}
          </Card>

          {/* Client Complaint Card */}
          <Card>
            <div className="flex items-center justify-between mb-3">
                <h3 className="font-bold text-lg">Client Complaint</h3>
                <div className="w-8 h-8 rounded-full bg-red-100 flex items-center justify-center">
                    <AlertTriangle className="w-4 h-4 text-red-600"/>
                </div>
            </div>
            <p className="text-sm font-semibold text-slate-700">Login Issue - Jane Smith</p>
            <p className="text-sm text-slate-500 mt-1 line-clamp-2">Client reported being unable to access her account. Issue was resolved via password reset.</p>
             <a href="#" className="text-sm font-semibold text-violet-600 hover:underline mt-3 block">View Full Complaint</a>
          </Card>

          {/* Notes Card */}
          <Card>
            <h3 className="font-bold text-lg mb-3">Notes</h3>
            <textarea 
              placeholder="Add notes for a selected client or a general reminder..."
              className="w-full h-32 p-3 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-violet-300 focus:border-violet-500 outline-none transition"
            />
            <button className="mt-3 w-full bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-slate-900 transition-colors">Save Note</button>
          </Card>
        </div>
      </main>

      {/* Modals */}
      {showReportModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <Card className="w-full max-w-md">
            <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-lg">Call Log Report</h3>
                <IconButton icon={<X size={20} />} onClick={() => setShowReportModal(false)} className="-mr-2 -mt-2"/>
            </div>
            <p className="text-sm text-slate-600 mb-6">Your comprehensive call log report is ready for download. Click the button below to save it as a CSV file.</p>
            <button className="w-full flex items-center justify-center gap-2 bg-green-600 text-white px-4 py-2.5 rounded-lg text-sm font-semibold hover:bg-green-700 transition-colors">
              <Download size={16} />
              Download Report (.csv)
            </button>
          </Card>
        </div>
      )}
      {showCallDetailsModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <Card className="w-full max-w-lg">
            <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-lg">Call Details</h3>
                <IconButton icon={<X size={20} />} onClick={() => setShowCallDetailsModal(null)} className="-mr-2 -mt-2"/>
            </div>
            <div className="space-y-4 text-sm">
                <div className="grid grid-cols-3 gap-2"><span className="text-slate-500">Client:</span> <span className="col-span-2 font-semibold">{getClientById(showCallDetailsModal.clientId)?.name}</span></div>
                <div className="grid grid-cols-3 gap-2"><span className="text-slate-500">Reason:</span> <span className="col-span-2 font-semibold">{showCallDetailsModal.reason}</span></div>
                <div className="grid grid-cols-3 gap-2"><span className="text-slate-500">Due Date:</span> <span className="col-span-2 font-semibold">{showCallDetailsModal.dueDate}</span></div>
                <div className="grid grid-cols-3 gap-2 items-center"><span className="text-slate-500">Status:</span> <span className="col-span-2"><StatusPill status={showCallDetailsModal.status} /></span></div>
                <div className="grid grid-cols-3 gap-2"><span className="text-slate-500">Details:</span> <p className="col-span-2 text-slate-700 bg-slate-50 p-2 rounded-md">{showCallDetailsModal.details}</p></div>
            </div>
          </Card>
        </div>
      )}

    </div>
  );
};

export default CustomerServiceManagerPage;


