import { useState, useEffect, useMemo, type FC, type ReactNode } from 'react';
import type { NextPage } from 'next';
import { Mail, Calendar, Phone, BarChart2, Plus, Search, ChevronDown, Filter, FileDown, Flame, Sun, Snowflake, Briefcase, User, MessageSquare, Send, X } from 'lucide-react';

// TYPESCRIPT INTERFACES
type LeadStatus = 'New' | 'Contacted' | 'Qualified' | 'Proposal Sent' | 'Closed-Won' | 'Closed-Lost';
type LeadTemperature = 'Hot' | 'Warm' | 'Cold';
type LeadCategory = 'Enterprise' | 'SMB' | 'Startup' | 'Partner';

interface Message {
  id: number;
  text: string;
  timestamp: string;
  sender: 'user' | 'lead';
}

interface Lead {
  id: number;
  name: string;
  email: string;
  avatar: string;
  category: LeadCategory;
  status: LeadStatus;
  temperature: LeadTemperature;
  dateAdded: string;
  messages: Message[];
}

