  { id: 2, name: 'Bob Williams', email: 'bob.w@example.com', avatar: 'B', category: 'SMB', status: 'Closed-Won', temperature: 'Warm', dateAdded: '2023-10-25', messages: [] },
  { id: 3, name: 'Charlie Brown', email: 'charlie.b@example.com', avatar: 'C', category: 'Startup', status: 'Contacted', temperature: 'Cold', dateAdded: '2023-10-22', messages: [] },
