  { id: 5, name: 'Ethan Hunt', email: 'ethan.h@example.com', avatar: 'E', category: 'Partner', status: 'Closed-Lost', temperature: 'Warm', dateAdded: '2023-10-18', messages: [] },
  { id: 6, name: 'Fiona Glenanne', email: 'fiona.g@example.com', avatar: 'F', category: 'SMB', status: 'Qualified', temperature: 'Hot', dateAdded: '2023-10-15', messages: [] },
];

