// HELPER COMPONENTS
const Card: FC<{ children: ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-white rounded-xl shadow-sm border border-slate-200 ${className}`}>
    {children}
  </div>
);

const StatusBadge: FC<{ status: LeadStatus }> = ({ status }) => {
  const statusColors: Record<LeadStatus, string> = {
    'New': 'bg-blue-100 text-blue-800',
    'Contacted': 'bg-cyan-100 text-cyan-800',
    'Qualified': 'bg-purple-100 text-purple-800',
    'Proposal Sent': 'bg-yellow-100 text-yellow-800',
    'Closed-Won': 'bg-green-100 text-green-800',
    'Closed-Lost': 'bg-red-100 text-red-800',
  };
  return <span className={`px-2 py-1 text-xs font-medium rounded-full ${statusColors[status]}`}>{status}</span>;
};

const TemperatureIcon: FC<{ temp: LeadTemperature }> = ({ temp }) => {
  if (temp === 'Hot') return <Flame className="w-5 h-5 text-red-500" />;
  if (temp === 'Warm') return <Sun className="w-5 h-5 text-orange-500" />;
  return <Snowflake className="w-5 h-5 text-blue-500" />;
};

const LeadMasterCRMPage: NextPage = () => {
  const [leads, setLeads] = useState<Lead[]>(initialLeads);
  const [selectedLead, setSelectedLead] = useState<Lead | null>(leads[0]);
  const [activeTab, setActiveTab] = useState<'Leads' | 'Reports'>('Leads');
  const [searchTerm, setSearchTerm] = useState('');
