  const [statusFilter, setStatusFilter] = useState('All');
  const [detailTab, setDetailTab] = useState<'Details' | 'Messages'>('Details');
  const [showSuccess, setShowSuccess] = useState(false);
  const [newMessage, setNewMessage] = useState('');

  // Add Lead Form State
  const [newLeadName, setNewLeadName] = useState('');
  const [newLeadEmail, setNewLeadEmail] = useState('');

  const filteredLeads = useMemo(() => {
    return leads
      .filter(lead => lead.name.toLowerCase().includes(searchTerm.toLowerCase()))
      .filter(lead => categoryFilter === 'All' || lead.category === categoryFilter)
      .filter(lead => statusFilter === 'All' || lead.status === statusFilter);
  }, [leads, searchTerm, categoryFilter, statusFilter]);

  const handleAddLead = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newLeadName || !newLeadEmail) return;
    const newLead: Lead = {
      id: Date.now(),
      name: newLeadName,
      email: newLeadEmail,
      avatar: newLeadName.charAt(0).toUpperCase(),
      category: 'Startup',
      status: 'New',
      temperature: 'Warm',
      dateAdded: new Date().toISOString().split('T')[0],
      messages: [],
    };
    setLeads([newLead, ...leads]);
    setNewLeadName('');
    setNewLeadEmail('');
    setSelectedLead(newLead);
  };

  const handleSendMessage = () => {
    if (!newMessage.trim() || !selectedLead) return;

    const message: Message = {
      id: Date.now(),
      text: newMessage,
      timestamp: new Date().toLocaleString(),
      sender: 'user',
    };

    const updatedLeads = leads.map(lead =>
      lead.id === selectedLead.id
        ? { ...lead, messages: [...lead.messages, message] }
        : lead
    );
    setLeads(updatedLeads);
    setSelectedLead(prev => prev ? { ...prev, messages: [...prev.messages, message] } : null);
    setNewMessage('');
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 3000);
  };

  return (
    <div className="min-h-screen bg-amber-50 font-sans text-slate-800">
