import { useState, useEffect, useRef, FC, ReactNode } from 'react';
import type { NextPage } from 'next';
import { MessageSquare, Send, X, Ship, Package, Undo2, Phone, Bot } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type MessageType = 'user' | 'bot' | 'options' | 'shipping' | 'tracking' | 'returns' | 'contact' | 'placeholder';

type Message = {
  id: number;
  type: MessageType;
  content?: string;
  timestamp: string;
};

// --- MOCK DATA & HELPERS ---
const initialMessages: Message[] = [
  {
    id: 1,
    type: 'bot',
    content: "Hello! I'm the Chatly assistant. How can I help you today?",
    timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
  },
  {
    id: 2,
    type: 'options',
    timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
  },
];

const options = [
  { label: 'What are your shipping options?', type: 'shipping' as MessageType },
  { label: 'How can I track my order?', type: 'tracking' as MessageType },
  { label: 'What is your return policy?', type: 'returns' as MessageType },
  { label: 'How do I contact support?', type: 'contact' as MessageType },
];

// --- UI COMPONENTS ---

const Card = ({ children, className }: { children: ReactNode; className?: string }) => (
  <div className={`bg-white border border-slate-200 rounded-xl p-4 shadow-sm ${className}`}>
    {children}
  </div>
);

const BotMessage = ({ message }: { message: Message }) => (
  <div className="flex items-start gap-3">
    <div className="flex-shrink-0 bg-slate-200 text-slate-600 rounded-full w-8 h-8 flex items-center justify-center">
      <Bot size={18} />
    </div>
    <div className="bg-slate-100 text-slate-800 rounded-xl rounded-tl-none p-3 max-w-xs md:max-w-md">
      <p className="text-sm">{message.content}</p>
      <p className="text-xs text-slate-400 mt-2 text-right">{message.timestamp}</p>
    </div>
  </div>
);

const UserMessage = ({ message }: { message: Message }) => (
  <div className="flex justify-end">
    <div className="bg-blue-500 text-white rounded-xl rounded-tr-none p-3 max-w-xs md:max-w-md">
      <p className="text-sm">{message.content}</p>
      <p className="text-xs text-blue-200 mt-2 text-right">{message.timestamp}</p>
    </div>
  </div>
);

const OptionsCard = ({ onOptionClick }: { onOptionClick: (option: typeof options[0]) => void }) => (
  <div className="flex items-start gap-3">
    <div className="flex-shrink-0 bg-slate-200 text-slate-600 rounded-full w-8 h-8 flex items-center justify-center">
      <Bot size={18} />
    </div>
    <Card className="max-w-xs md:max-w-md">
      <p className="font-semibold text-slate-800 mb-3">Choose an option:</p>
      <div className="flex flex-col gap-2">
        {options.map((opt, index) => (
          <button
            key={index}
            onClick={() => onOptionClick(opt)}
            className="w-full text-left text-sm text-blue-600 hover:bg-blue-50 rounded-lg p-2 transition-colors duration-200 border border-slate-200 hover:border-blue-300"
          >
            {opt.label}
          </button>
        ))}
      </div>
    </Card>
  </div>
);

const InfoCard = ({ icon, title, children, timestamp }: { icon: ReactNode, title: string, children: ReactNode, timestamp: string }) => (
    <div className="flex items-start gap-3">
        <div className="flex-shrink-0 bg-slate-200 text-slate-600 rounded-full w-8 h-8 flex items-center justify-center">
            <Bot size={18} />
        </div>
        <Card className="max-w-xs md:max-w-md">
            <div className="flex items-center gap-3 mb-2">
                <div className="text-blue-500">{icon}</div>
                <h3 className="font-bold text-slate-800">{title}</h3>
            </div>
            <div className="text-sm text-slate-600 space-y-2">{children}</div>
            <p className="text-xs text-slate-400 mt-3 text-right">{timestamp}</p>
        </Card>
    </div>
);

const ShippingOptionsCard: FC<{ timestamp: string }> = ({ timestamp }) => (
  <InfoCard icon={<Ship size={20} />} title="Shipping Options" timestamp={timestamp}>
    <p><strong>Standard:</strong> 5-7 business days - $4.99</p>
    <p><strong>Express:</strong> 2-3 business days - $12.99</p>
    <p><strong>Overnight:</strong> Next business day - $24.99</p>
    <p className='text-xs pt-2'>Free standard shipping on orders over $50.</p>
  </InfoCard>
);

const TrackOrderCard: FC<{ timestamp: string }> = ({ timestamp }) => (
  <InfoCard icon={<Package size={20} />} title="Track Your Order" timestamp={timestamp}>
    <p>You can track your order status by entering your order number on our tracking page. A link was also sent to your email.</p>
    <button className='text-sm mt-2 w-full bg-blue-500 text-white py-2 px-4 rounded-lg hover:bg-blue-600 transition-colors'>Go to Tracking Page</button>
  </InfoCard>
);

const ReturnPolicyCard: FC<{ timestamp: string }> = ({ timestamp }) => (
  <InfoCard icon={<Undo2 size={20} />} title="Return Policy" timestamp={timestamp}>
    <p>We accept returns within 30 days of purchase. The item must be unused and in its original packaging. Please visit our returns portal to start a return.</p>
  </InfoCard>
);

const ContactSupportCard: FC<{ timestamp: string }> = ({ timestamp }) => (
  <InfoCard icon={<Phone size={20} />} title="Contact Support" timestamp={timestamp}>
    <p>You can reach our support team via:</p>
    <p><strong>Email:</strong> support@chatly.com</p>
    <p><strong>Phone:</strong> 1-800-555-CHAT</p>
    <p className='text-xs pt-2'>Available Mon-Fri, 9am-5pm EST.</p>
  </InfoCard>
);

const PlaceholderCard: FC = () => (
    <div className="flex items-start gap-3">
        <div className="flex-shrink-0 bg-slate-200 text-slate-600 rounded-full w-8 h-8 flex items-center justify-center">
            <Bot size={18} />
        </div>
        <div className="bg-slate-100 rounded-xl rounded-tl-none p-3">
            <div className="flex items-center gap-1">
                <span className="w-2 h-2 bg-slate-300 rounded-full animate-pulse"></span>
                <span className="w-2 h-2 bg-slate-300 rounded-full animate-pulse delay-150"></span>
                <span className="w-2 h-2 bg-slate-300 rounded-full animate-pulse delay-300"></span>
            </div>
        </div>
    </div>
);

// --- MAIN PAGE COMPONENT ---
const ChatlySupportHubPage: NextPage = () => {
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>(initialMessages);
  const [inputValue, setInputValue] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const addMessage = (type: MessageType, content?: string) => {
    const newMessage: Message = {
      id: Date.now(),
      type,
      content,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    };
    setMessages(prev => [...prev, newMessage]);
    return newMessage;
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim()) return;
    addMessage('user', inputValue);
    setInputValue('');
    // Simple bot response for typed messages
    setTimeout(() => {
        const placeholder = addMessage('placeholder');
        setTimeout(() => {
            setMessages(prev => prev.filter(msg => msg.id !== placeholder.id));
            addMessage('bot', "I can best help with the options below. Please select one.");
            addMessage('options');
        }, 1500);
    }, 500);
  };

  const handleOptionClick = (option: typeof options[0]) => {
    addMessage('user', option.label);

    setTimeout(() => {
        const placeholder = addMessage('placeholder');
        setTimeout(() => {
            setMessages(prev => prev.filter(msg => msg.id !== placeholder.id));
            addMessage(option.type);
            // Follow up with options again
            setTimeout(() => {
                addMessage('bot', 'Is there anything else I can help with?');
                addMessage('options');
            }, 1000);
        }, 1500);
    }, 500);
  };

  return (
    <div className="bg-white font-sans w-full min-h-screen relative">
      {/* This is the main page content area. It's intentionally sparse. */}
      <div className="p-8">
        <h1 className="text-4xl font-bold text-slate-800">Chatly Support Hub</h1>
        <p className="text-slate-500 mt-2">Welcome! Click the button in the corner to start a chat.</p>
      </div>

      {/* Chat Bubble Button */}
      {!isChatOpen && (
        <button
          onClick={() => setIsChatOpen(true)}
          className="fixed bottom-8 right-8 bg-gradient-to-br from-blue-500 to-cyan-400 text-white w-16 h-16 rounded-full shadow-lg hover:shadow-xl transform hover:scale-110 transition-all duration-300 flex items-center justify-center"
          aria-label="Open Chat"
        >
          <MessageSquare size={28} />
        </button>
      )}

      {/* Chat Window */}
      {isChatOpen && (
        <div className="fixed bottom-8 right-8 w-[calc(100%-4rem)] max-w-sm h-[70vh] max-h-[600px] flex flex-col bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden animate-fade-in-up">
          {/* Header */}
          <header className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center flex-shrink-0">
            <h2 className="font-bold text-lg text-slate-800">Chatly Support</h2>
            <button
              onClick={() => setIsChatOpen(false)}
              className="text-slate-500 hover:text-slate-800 transition-colors"
              aria-label="Close chat"
            >
              <X size={20} />
            </button>
          </header>

          {/* Messages Area */}
          <div className="flex-1 p-4 overflow-y-auto bg-slate-50/50">
            <div className="space-y-6">
              {messages.map((msg) => {
                switch (msg.type) {
                  case 'bot': return <BotMessage key={msg.id} message={msg} />;
                  case 'user': return <UserMessage key={msg.id} message={msg} />;
                  case 'options': return <OptionsCard key={msg.id} onOptionClick={handleOptionClick} />;
                  case 'shipping': return <ShippingOptionsCard key={msg.id} timestamp={msg.timestamp} />;
                  case 'tracking': return <TrackOrderCard key={msg.id} timestamp={msg.timestamp} />;
                  case 'returns': return <ReturnPolicyCard key={msg.id} timestamp={msg.timestamp} />;
                  case 'contact': return <ContactSupportCard key={msg.id} timestamp={msg.timestamp} />;
                  case 'placeholder': return <PlaceholderCard key={msg.id} />;
                  default: return null;
                }
              })}
              <div ref={chatEndRef} />
            </div>
          </div>

          {/* Input Area */}
          <footer className="p-4 bg-white border-t border-slate-200 flex-shrink-0">
            <form onSubmit={handleSendMessage} className="flex items-center gap-2">
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Type a message..."
                className="flex-1 w-full px-4 py-2 bg-slate-100 border border-slate-200 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-400 transition-shadow"
              />
              <button
                type="submit"
                className="w-10 h-10 flex-shrink-0 bg-blue-500 text-white rounded-full flex items-center justify-center hover:bg-blue-600 disabled:bg-slate-300 transition-colors"
                aria-label="Send Message"
                disabled={!inputValue.trim()}
              >
                <Send size={20} />
              </button>
            </form>
          </footer>
        </div>
      )}

      <style jsx global>{`
        @keyframes fade-in-up {
          from { opacity: 0; transform: translateY(1rem); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
          animation: fade-in-up 0.3s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default ChatlySupportHubPage;


