// --- TYPESCRIPT INTERFACES ---
type CustomerStatus = 'Active' | 'Inactive' | 'Pending' | 'Blocked';
type Gender = 'Male' | 'Female' | 'Other';

type Customer = {
  id: string;
  name: string;
  email: string;
  phone: string;
  gender: Gender;
  dob: string; // YYYY-MM-DD
  status: CustomerStatus;
};

type SortConfig = {
  key: keyof Customer | null;
  direction: 'ascending' | 'descending';
};

