const CustomDropdown: FC<{ label: string; options: string[]; value: string; onChange: (value: string) => void; placeholder: string;}> = ({ label, options, value, onChange, placeholder }) => {
    const [isOpen, setIsOpen] = useState(false);

    return (
        <div className="relative w-full md:w-48">
            <label className="text-sm font-medium text-slate-600">{label}</label>
            <button onClick={() => setIsOpen(!isOpen)} className="mt-1 flex items-center justify-between w-full bg-white border border-slate-300 rounded-md shadow-sm px-3 py-2 text-left text-slate-700 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">
                <span className={value ? '' : 'text-slate-400'}>{value || placeholder}</span>
                <ChevronDown className={`h-5 w-5 text-slate-400 transform transition-transform ${isOpen ? 'rotate-180' : ''}`} />
            </button>
            {isOpen && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-lg border border-slate-200 rounded-md py-1">
                    <a onClick={() => { onChange(''); setIsOpen(false); }} className="cursor-pointer block px-4 py-2 text-sm text-slate-700 hover:bg-slate-100">All</a>
                    {options.map(option => (
                        <a key={option} onClick={() => { onChange(option); setIsOpen(false); }} className="cursor-pointer block px-4 py-2 text-sm text-slate-700 hover:bg-slate-100">
                            {option}
                        </a>
                    ))}
                </div>
            )}
        </div>
    );
};

const AddCustomerModal: FC<{ isOpen: boolean; onClose: () => void; onAddCustomer: (customer: Omit<Customer, 'id'>) => void;}> = ({ isOpen, onClose, onAddCustomer }) => {
  const [newCustomer, setNewCustomer] = useState({ name: '', email: '', phone: '', gender: 'Male' as Gender, dob: '', status: 'Pending' as CustomerStatus });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCustomer.name && newCustomer.email && newCustomer.dob) {
      onAddCustomer(newCustomer);
      setNewCustomer({ name: '', email: '', phone: '', gender: 'Male', dob: '', status: 'Pending' });
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-40 flex justify-center items-center p-4">
      {/* Add New Customer Card */}
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg animate-fade-in-up">
        <div className="p-6 border-b border-slate-200">
          <h3 className="text-xl font-semibold text-slate-800">Add New Customer</h3>
          <p className="text-sm text-slate-500 mt-1">Enter the details for the new customer.</p>
        </div>
        <form onSubmit={handleSubmit}>
          <div className="p-6 space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Name Input */}
              <div>
                <label className="text-sm font-medium text-slate-600">Full Name</label>
                <input type="text" value={newCustomer.name} onChange={e => setNewCustomer({...newCustomer, name: e.target.value})} placeholder="e.g. John Doe" required className="mt-1 w-full border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600"/>
              </div>
              {/* Email Input */}
              <div>
                <label className="text-sm font-medium text-slate-600">Email Address</label>
                <input type="email" value={newCustomer.email} onChange={e => setNewCustomer({...newCustomer, email: e.target.value})} placeholder="e.g. john.doe@example.com" required className="mt-1 w-full border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600"/>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium text-slate-600">Phone Number</label>
                <input type="tel" value={newCustomer.phone} onChange={e => setNewCustomer({...newCustomer, phone: e.target.value})} placeholder="e.g. 555-0101" className="mt-1 w-full border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600"/>
              </div>
              {/* Date of Birth Input */}
              <div>
                <label className="text-sm font-medium text-slate-600">Date of Birth</label>
                <input type="date" value={newCustomer.dob} onChange={e => setNewCustomer({...newCustomer, dob: e.target.value})} required className="mt-1 w-full border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600 text-slate-700"/>
              </div>
            </div>
            <div>
              <label className="text-sm font-medium text-slate-600">Gender</label>
              <select value={newCustomer.gender} onChange={e => setNewCustomer({...newCustomer, gender: e.target.value as Gender})} className="mt-1 w-full bg-white border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600">
                <option>Male</option>
                <option>Female</option>
                <option>Other</option>
              </select>
            </div>
          </div>
          <div className="bg-slate-50 p-4 flex justify-end items-center gap-3 rounded-b-xl">
            {/* Cancel Card (Implicitly, the button is the card content) */}
            <button type="button" onClick={onClose} className="px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">
              Cancel
            </button>
            {/* Add Customer Card (Implicitly, the button is the card content) */}
            <button type="submit" className="px-4 py-2 bg-cyan-700 text-white rounded-md text-sm font-medium hover:bg-cyan-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">
              Add Customer
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

// --- MAIN PAGE COMPONENT ---
const InsuranceProPage: NextPage = () => {
  const [customers, setCustomers] = useState<Customer[]>(initialCustomers);
  const [activeView, setActiveView] = useState('Customers');
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isAddModalOpen, setAddModalOpen] = useState(false);
  const [isExportMenuOpen, setExportMenuOpen] = useState(false);

  // Filters State
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [genderFilter, setGenderFilter] = useState('');
  const [dobFilter, setDobFilter] = useState('');

  // Sorting and Pagination State
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'ascending' });
  const [currentPage, setCurrentPage] = useState(1);

  const filteredAndSortedCustomers = useMemo(() => {
    let filtered = [...customers];

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(c =>
        c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
        c.id.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Dropdown filters
    if (statusFilter) filtered = filtered.filter(c => c.status === statusFilter);
    if (genderFilter) filtered = filtered.filter(c => c.gender === genderFilter);
    if (dobFilter) filtered = filtered.filter(c => c.dob === dobFilter);

    // Sorting
    if (sortConfig.key) {
      filtered.sort((a, b) => {
        if (a[sortConfig.key!] < b[sortConfig.key!]) return sortConfig.direction === 'ascending' ? -1 : 1;
        if (a[sortConfig.key!] > b[sortConfig.key!]) return sortConfig.direction === 'ascending' ? 1 : -1;
        return 0;
      });
    }

    return filtered;
  }, [customers, searchTerm, statusFilter, genderFilter, dobFilter, sortConfig]);

  const totalPages = Math.ceil(filteredAndSortedCustomers.length / ITEMS_PER_PAGE);
  const paginatedCustomers = filteredAndSortedCustomers.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, statusFilter, genderFilter, dobFilter]);

  const handleSort = (key: keyof Customer) => {
    let direction: 'ascending' | 'descending' = 'ascending';
    if (sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const handleAddCustomer = (newCustomerData: Omit<Customer, 'id'>) => {
    const newId = `CUST${(customers.length + 1).toString().padStart(3, '0')}`;
    setCustomers(prev => [{ id: newId, ...newCustomerData }, ...prev]);
    setAddModalOpen(false);
  };

  const handleDeleteCustomer = (id: string) => {
    if (window.confirm('Are you sure you want to delete this customer?')) {
        setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const statusColors: Record<CustomerStatus, string> = {
    Active: 'bg-green-100 text-green-800',
    Inactive: 'bg-slate-100 text-slate-800',
    Pending: 'bg-yellow-100 text-yellow-800',
    Blocked: 'bg-red-100 text-red-800',
  };

  return (
    <div className="bg-slate-50 min-h-screen flex text-slate-800">
      <Sidebar isOpen={isSidebarOpen} activeView={activeView} setActiveView={setActiveView} />
      <main className="flex-1 flex flex-col transition-all duration-300">
