          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="lg:hidden p-2 -ml-2 text-slate-600 hover:bg-slate-200 rounded-full">
            {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          <div className="relative w-full max-w-xs hidden md:block">
            <input type="text" placeholder="Search customers..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-100 border border-transparent rounded-full pl-10 pr-4 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600" />
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" />
          </div>
          <div className="flex items-center space-x-4">
             <div className="w-10 h-10 bg-slate-200 border-2 border-dashed rounded-full" />
          </div>
        </header>

        <div className="flex-1 p-4 md:p-8 space-y-8">
          {/* Customers Management Card */}
          <div className="bg-white border border-slate-200 rounded-xl shadow-sm">
            <div className="p-6 border-b border-slate-200">
              <h2 className="text-2xl font-bold text-slate-800">Customer Management</h2>
              <p className="text-slate-500 mt-1">View, add, edit, and manage all customer records.</p>
            </div>
            <div className="p-6 flex flex-wrap items-center gap-4">
                {/* Gender Dropdown */}
                <CustomDropdown label="Gender" options={['Male', 'Female', 'Other']} value={genderFilter} onChange={setGenderFilter} placeholder="All Genders" />
                {/* Status Dropdown */}
                <CustomDropdown label="Status" options={['Active', 'Inactive', 'Pending', 'Blocked']} value={statusFilter} onChange={setStatusFilter} placeholder="All Statuses" />
                {/* Date of Birth Input (as a filter) */}
                <div className="w-full md:w-48">
                    <label className="text-sm font-medium text-slate-600">Date of Birth</label>
                    <div className="relative mt-1">
                        <input type="date" value={dobFilter} onChange={e => setDobFilter(e.target.value)} className="w-full bg-white border border-slate-300 rounded-md px-3 py-2 text-slate-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600"/>
                    </div>
                </div>
                <div className="flex-grow" />
                <div className="flex items-center gap-2">
                    <div className="relative">
                        {/* Export Button */}
                        <button onClick={() => setExportMenuOpen(!isExportMenuOpen)} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">
                            <Download size={16} /> Export
                        </button>
                        {/* Export Card */}
                        {isExportMenuOpen && (
                            <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg border border-slate-200 z-10">
                                <a href="#" className="block px-4 py-2 text-sm text-slate-700 hover:bg-slate-100">Export as CSV</a>
                                <a href="#" className="block px-4 py-2 text-sm text-slate-700 hover:bg-slate-100">Export as PDF</a>
                            </div>
                        )}
                    </div>
                    {/* Add Customer Button (triggers modal) */}
                    <button onClick={() => setAddModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-cyan-700 text-white rounded-md text-sm font-medium hover:bg-cyan-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">
                        <PlusCircle size={16} /> Add Customer
                    </button>
                </div>
            </div>
          </div>

          {/* Customer List Table Card */}
          <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left text-slate-500">
                <thead className="text-xs text-slate-700 uppercase bg-slate-100 border-b border-slate-200">
                  <tr>
                    {['ID', 'Name', 'Email', 'Phone', 'Gender', 'Status'].map(header => (
                      <th key={header} scope="col" className="px-6 py-4 font-medium">
                        <div className="flex items-center gap-2 cursor-pointer" onClick={() => handleSort(header.toLowerCase() as keyof Customer)}>
                          {header}
                          <ArrowUpDown size={14} className="text-slate-400" />
                        </div>
                      </th>
                    ))}
                    <th scope="col" className="px-6 py-4 font-medium text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedCustomers.map((customer) => (
                    <tr key={customer.id} className="bg-white border-b border-slate-200 hover:bg-slate-50">
                      <td className="px-6 py-4 font-mono text-xs text-cyan-700 font-semibold">{customer.id}</td>
                      <td className="px-6 py-4 font-medium text-slate-900 whitespace-nowrap">{customer.name}</td>
                      <td className="px-6 py-4">{customer.email}</td>
                      <td className="px-6 py-4">{customer.phone}</td>
                      <td className="px-6 py-4">{customer.gender}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${statusColors[customer.status]}`}>{customer.status}</span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                          <button className="p-2 text-slate-500 hover:bg-slate-200 rounded-md"><FilePenLine size={16} /></button>
                          <button onClick={() => handleDeleteCustomer(customer.id)} className="p-2 text-red-500 hover:bg-red-100 rounded-md"><Trash2 size={16} /></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {/* Pagination Controls */}
            <div className="p-4 flex flex-col md:flex-row justify-between items-center gap-4 bg-white border-t border-slate-200">
              <span className="text-sm text-slate-600">Showing {Math.min(filteredAndSortedCustomers.length, (currentPage - 1) * ITEMS_PER_PAGE + 1)}-{Math.min(currentPage * ITEMS_PER_PAGE, filteredAndSortedCustomers.length)} of {filteredAndSortedCustomers.length} results</span>
              <div className="flex items-center gap-2">
                 {/* Previous Card (Button) */}
                <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed">
                  <ChevronLeft size={16} /> Previous
                </button>
                {/* Next Card (Button) */}
                <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed">
                  Next <ChevronRight size={16} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </main>
      <AddCustomerModal isOpen={isAddModalOpen} onClose={() => setAddModalOpen(false)} onAddCustomer={handleAddCustomer} />
    </div>
  );
};

export default InsuranceProPage;


