d className="mt-1 w-full border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600"/>\n              </div>\n            </div>\n            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">\n              <div>\n                <label className="text-sm font-medium text-slate-600">Phone Number</label>\n                <input type="tel" value={newCustomer.phone} onChange={e => setNewCustomer({...newCustomer, phone: e.target.value})} placeholder="e.g. 555-0101" className="mt-1 w-full border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600"/>\n              </div>\n              {/* Date of Birth Input */}\n              <div>\n                <label className="text-sm font-medium text-slate-600">Date of Birth</label>\n                <input type="date" value={newCustomer.dob} onChange={e => setNewCustomer({...newCustomer, dob: e.target.value})} required className="mt-1 w-full border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600 text-slate-700"/>\n              </div>\n            </div>\n            <div>\n              <label className="text-sm font-medium text-slate-600">Gender</label>\n              <select value={newCustomer.gender} onChange={e => setNewCustomer({...newCustomer, gender: e.target.value as Gender})} className="mt-1 w-full bg-white border border-slate-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600">\n                <option>Male</option>\n                <option>Female</option>\n                <option>Other</option>\n              </select>\n            </div>\n          </div>\n          <div className="bg-slate-50 p-4 flex justify-end items-center gap-3 rounded-b-xl">\n            {/* Cancel Card (Implicitly, the button is the card content) */}\n            <button type="button" onClick={onClose} className="px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">\n              Cancel\n            </button>\n            {/* Add Customer Card (Implicitly, the button is the card content) */}\n            <button type="submit" className="px-4 py-2 bg-cyan-700 text-white rounded-md text-sm font-medium hover:bg-cyan-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">\n              Add Customer\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  );\n}\n\n// --- MAIN PAGE COMPONENT ---\nconst InsuranceProPage: NextPage = () => {\n  const [customers, setCustomers] = useState<Customer[]>(initialCustomers);\n  const [activeView, setActiveView] = useState(\'Customers\');\n  const [isSidebarOpen, setSidebarOpen] = useState(false);\n  const [isAddModalOpen, setAddModalOpen] = useState(false);\n  const [isExportMenuOpen, setExportMenuOpen] = useState(false);\n\n  // Filters State\n  const [searchTerm, setSearchTerm] = useState(\'\');\n  const [statusFilter, setStatusFilter] = useState(\'\');\n  const [genderFilter, setGenderFilter] = useState(\'\');\n  const [dobFilter, setDobFilter] = useState(\'\');\n\n  // Sorting and Pagination State\n  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: \'name\', direction: \'ascending\' });\n  const [currentPage, setCurrentPage] = useState(1);\n\n  const filteredAndSortedCustomers = useMemo(() => {\n    let filtered = [...customers];\n\n    // Search filter\n    if (searchTerm) {\n      filtered = filtered.filter(c =>\n        c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||\n        c.email.toLowerCase().includes(searchTerm.toLowerCase()) ||\n        c.id.toLowerCase().includes(searchTerm.toLowerCase())\n      );\n    }\n\n    // Dropdown filters\n    if (statusFilter) filtered = filtered.filter(c => c.status === statusFilter);\n    if (genderFilter) filtered = filtered.filter(c => c.gender === genderFilter);\n    if (dobFilter) filtered = filtered.filter(c => c.dob === dobFilter);\n\n    // Sorting\n    if (sortConfig.key) {\n      filtered.sort((a, b) => {\n        if (a[sortConfig.key!] < b[sortConfig.key!]) return sortConfig.direction === \'ascending\' ? -1 : 1;\n        if (a[sortConfig.key!] > b[sortConfig.key!]) return sortConfig.direction === \'ascending\' ? 1 : -1;\n        return 0;\n      });\n    }\n\n    return filtered;\n  }, [customers, searchTerm, statusFilter, genderFilter, dobFilter, sortConfig]);\n\n  const totalPages = Math.ceil(filteredAndSortedCustomers.length / ITEMS_PER_PAGE);\n  const paginatedCustomers = filteredAndSortedCustomers.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);\n\n  useEffect(() => {\n    setCurrentPage(1);\n  }, [searchTerm, statusFilter, genderFilter, dobFilter]);\n\n  const handleSort = (key: keyof Customer) => {\n    let direction: \'ascending\' | \'descending\' = \'ascending\';\n    if (sortConfig.key === key && sortConfig.direction === \'ascending\') {\n      direction = \'descending\';\n    }\n    setSortConfig({ key, direction });\n  };\n\n  const handleAddCustomer = (newCustomerData: Omit<Customer, \'id\'>) => {\n    const newId = `CUST${(customers.length + 1).toString().padStart(3, \'0\')}`;\n    setCustomers(prev => [{ id: newId, ...newCustomerData }, ...prev]);\n    setAddModalOpen(false);\n  };\n\n  const handleDeleteCustomer = (id: string) => {\n    if (window.confirm(\'Are you sure you want to delete this customer?\')) {\n        setCustomers(prev => prev.filter(c => c.id !== id));\n    }\n  };\n\n  const statusColors: Record<CustomerStatus, string> = {\n    Active: \'bg-green-100 text-green-800\',\n    Inactive: \'bg-slate-100 text-slate-800\',\n    Pending: \'bg-yellow-100 text-yellow-800\',\n    Blocked: \'bg-red-100 text-red-800\',\n  };\n\n  return (\n    <div className="bg-slate-50 min-h-screen flex text-slate-800">\n      <Sidebar isOpen={isSidebarOpen} activeView={activeView} setActiveView={setActiveView} />\n      <main className="flex-1 flex flex-col transition-all duration-300">\n        <header className="flex items-center justify-between h-20 bg-white/80 backdrop-blur-sm border-b border-slate-200 px-4 md:px-8 sticky top-0 z-10">\n          {/* Menu Toggle */}\n          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="lg:hidden p-2 -ml-2 text-slate-600 hover:bg-slate-200 rounded-full">\n            {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}\n          </button>\n          <div className="relative w-full max-w-xs hidden md:block">\n            <input type="text" placeholder="Search customers..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-100 border border-transparent rounded-full pl-10 pr-4 py-2 focus:outline-none focus:ring-2 focus:ring-cyan-600" />\n            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" />\n          </div>\n          <div className="flex items-center space-x-4">\n             <div className="w-10 h-10 bg-slate-200 border-2 border-dashed rounded-full" />\n          </div>\n        </header>\n\n        <div className="flex-1 p-4 md:p-8 space-y-8">\n          {/* Customers Management Card */}\n          <div className="bg-white border border-slate-200 rounded-xl shadow-sm">\n            <div className="p-6 border-b border-slate-200">\n              <h2 className="text-2xl font-bold text-slate-800">Customer Management</h2>\n              <p className="text-slate-500 mt-1">View, add, edit, and manage all customer records.</p>\n            </div>\n            <div className="p-6 flex flex-wrap items-center gap-4">\n                {/* Gender Dropdown */}\n                <CustomDropdown label="Gender" options={[\'Male\', \'Female\', \'Other\']} value={genderFilter} onChange={setGenderFilter} placeholder="All Genders" />\n                {/* Status Dropdown */}\n                <CustomDropdown label="Status" options={[\'Active\', \'Inactive\', \'Pending\', \'Blocked\']} value={statusFilter} onChange={setStatusFilter} placeholder="All Statuses" />\n                {/* Date of Birth Input (as a filter) */}\n                <div className="w-full md:w-48">\n                    <label className="text-sm font-medium text-slate-600">Date of Birth</label>\n                    <div className="relative mt-1">\n                        <input type="date" value={dobFilter} onChange={e => setDobFilter(e.target.value)} className="w-full bg-white border border-slate-300 rounded-md px-3 py-2 text-slate-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600"/>\n                    </div>\n                </div>\n                <div className="flex-grow" />\n                <div className="flex items-center gap-2">\n                    <div className="relative">\n                        {/* Export Button */}\n                        <button onClick={() => setExportMenuOpen(!isExportMenuOpen)} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">\n                            <Download size={16} /> Export\n                        </button>\n                        {/* Export Card */}\n                        {isExportMenuOpen && (\n                            <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-lg border border-slate-200 z-10">\n                                <a href="#" className="block px-4 py-2 text-sm text-slate-700 hover:bg-slate-100">Export as CSV</a>\n                                <a href="#" className="block px-4 py-2 text-sm text-slate-700 hover:bg-slate-100">Export as PDF</a>\n                            </div>\n                        )}\n                    </div>\n                    {/* Add Customer Button (triggers modal) */}\n                    <button onClick={() => setAddModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-cyan-700 text-white rounded-md text-sm font-medium hover:bg-cyan-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-cyan-600">\n                        <PlusCircle size={16} /> Add Customer\n                    </button>\n                </div>\n            </div>\n          </div>\n\n          {/* Customer List Table Card */}\n          <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">\n            <div className="overflow-x-auto">\n              <table className="w-full text-sm text-left text-slate-500">\n                <thead className="text-xs text-slate-700 uppercase bg-slate-100 border-b border-slate-200">\n                  <tr>\n                    {[\'ID\', \'Name\', \'Email\', \'Phone\', \'Gender\', \'Status\'].map(header => (\n                      <th key={header} scope="col" className="px-6 py-4 font-medium">\n                        <div className="flex items-center gap-2 cursor-pointer" onClick={() => handleSort(header.toLowerCase() as keyof Customer)}>\n                          {header}\n                          <ArrowUpDown size={14} className="text-slate-400" />\n                        </div>\n                      </th>\n                    ))}\n                    <th scope="col" className="px-6 py-4 font-medium text-right">Actions</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  {paginatedCustomers.map((customer) => (\n                    <tr key={customer.id} className="bg-white border-b border-slate-200 hover:bg-slate-50">\n                      <td className="px-6 py-4 font-mono text-xs text-cyan-700 font-semibold">{customer.id}</td>\n                      <td className="px-6 py-4 font-medium text-slate-900 whitespace-nowrap">{customer.name}</td>\n                      <td className="px-6 py-4">{customer.email}</td>\n                      <td className="px-6 py-4">{customer.phone}</td>\n                      <td className="px-6 py-4">{customer.gender}</td>\n                      <td className="px-6 py-4">\n                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${statusColors[customer.status]}`}>{customer.status}</span>\n                      </td>\n                      <td className="px-6 py-4 text-right">\n                        <div className="flex items-center justify-end gap-2">\n                          <button className="p-2 text-slate-500 hover:bg-slate-200 rounded-md"><FilePenLine size={16} /></button>\n                          <button onClick={() => handleDeleteCustomer(customer.id)} className="p-2 text-red-500 hover:bg-red-100 rounded-md"><Trash2 size={16} /></button>\n                        </div>\n                      </td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n            {/* Pagination Controls */}\n            <div className="p-4 flex flex-col md:flex-row justify-between items-center gap-4 bg-white border-t border-slate-200">\n              <span className="text-sm text-slate-600">Showing {Math.min(filteredAndSortedCustomers.length, (currentPage - 1) * ITEMS_PER_PAGE + 1)}-{Math.min(currentPage * ITEMS_PER_PAGE, filteredAndSortedCustomers.length)} of {filteredAndSortedCustomers.length} results</span>\n              <div className="flex items-center gap-2">\n                 {/* Previous Card (Button) */}\n                <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed">\n                  <ChevronLeft size={16} /> Previous\n                </button>\n                {/* Next Card (Button) */}\n                <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-md text-sm font-medium text-slate-700 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed">\n                  Next <ChevronRight size={16} />\n                </button>\n              </div>\n            </div>\n          </div>\n        </div>\n      </main>\n      <AddCustomerModal isOpen={isAddModalOpen} onClose={() => setAddModalOpen(false)} onAddCustomer={handleAddCustomer} />\n    </div>\n  );\n};\n\nexport default InsuranceProPage;\n'}

import { useState, useMemo, FC, useEffect } from 'react';
import type { NextPage } from 'next';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { motion, AnimatePresence } from 'framer-motion';
import { Vote, Users, TrendingUp, BarChart3, CheckCircle, XCircle } from 'lucide-react';

// TypeScript Interfaces
interface VoteOption {
  id: string;
  name: string;
  votes: number;
  color: string;
}

// --- Reusable UI Components ---

const Card: FC<{ children: React.ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-gray-800/50 backdrop-blur-sm border border-gray-700 rounded-2xl shadow-lg ${className}`}>
    {children}
  </div>
);

const CardHeader: FC<{ icon: React.ElementType; title: string }> = ({ icon: Icon, title }) => (
  <div className="flex items-center gap-3 border-b border-gray-700 p-4">
    <Icon className="h-6 w-6 text-purple-400" />
    <h2 className="text-lg font-semibold text-gray-100">{title}</h2>
  </div>
);

const PrimaryButton: FC<{ onClick: () => void; disabled?: boolean; children: React.ReactNode }> = ({ onClick, disabled, children }) => (
  <button
    onClick={onClick}
    disabled={disabled}
    className="w-full flex items-center justify-center gap-2 rounded-lg bg-purple-600 px-4 py-3 text-base font-bold text-white transition-all hover:bg-purple-700 disabled:cursor-not-allowed disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-2 focus:ring-offset-gray-900"
  >
    {children}
  </button>
);

const SecondaryButton: FC<{ onClick: () => void; disabled?: boolean; children: React.ReactNode }> = ({ onClick, disabled, children }) => (
    <button
        onClick={onClick}
        disabled={disabled}
        className="w-full flex items-center justify-center gap-2 rounded-lg bg-gray-600/50 px-4 py-3 text-base font-bold text-gray-300 transition-all hover:bg-gray-600 disabled:cursor-not-allowed disabled:opacity-50 focus:outline-none focus:ring-2 focus:ring-gray-500 focus:ring-offset-2 focus:ring-offset-gray-900"
    >
        {children}
    </button>
);

// --- Main Voting Portal Component ---

const VotingPortalHub: NextPage = () => {
  const [options, setOptions] = useState<VoteOption[]>([
    { id: 'A', name: 'Option A', votes: 120, color: '#8B5CF6' },
    { id: 'B', name: 'Option B', votes: 85, color: '#EC4899' },
    { id: 'C', name: 'Option C', votes: 50, color: '#10B981' },
    { id: 'D', name: 'Option D', votes: 95, color: '#F59E0B' },
  ]);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [hasVoted, setHasVoted] = useState(false);

  const totalVotes = useMemo(() => options.reduce((sum, option) => sum + option.votes, 0), [options]);

  const { leadingOption, voteDifference } = useMemo(() => {
    if (options.length < 2) return { leadingOption: options[0], voteDifference: options[0]?.votes || 0 };
    const sortedOptions = [...options].sort((a, b) => b.votes - a.votes);
    const leading = sortedOptions[0];
    const runnerUp = sortedOptions[1];
    const difference = leading.votes - runnerUp.votes;
    return { leadingOption: leading, voteDifference: difference };
  }, [options]);

  const handleSelectOption = (optionId: string) => {
    if (hasVoted) return;
    setSelectedOption(optionId);
  };

  const handleCastVote = () => {
    if (!selectedOption) return;

    setOptions(prevOptions =>
      prevOptions.map(option =>
        option.id === selectedOption ? { ...option, votes: option.votes + 1 } : option
      )
    );
    setHasVoted(true);

    setTimeout(() => {
        setSelectedOption(null);
        setHasVoted(false);
    }, 2000); // Allow voting again after 2 seconds
  };

  const handleReset = () => {
    setSelectedOption(null);
  };

  return (
    <div className="min-h-screen w-full bg-gradient-to-br from-gray-900 via-gray-900 to-black p-4 sm:p-6 lg:p-8 font-sans text-gray-200">
      <main className="mx-auto max-w-7xl">
        <div className="text-center mb-12">
            <h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-pink-500">Voting Portal Hub</h1>
            <p className="mt-2 text-lg text-gray-400">Engage, vote, and see results unfold in real-time.</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
          {/* Left Side: Voting Panel */}
          <div className="lg:col-span-2">
            <Card className="h-full">
              <CardHeader icon={Vote} title="Vote Now" />
              <div className="p-6 space-y-4">
                {options.map(option => {
                  const percentage = totalVotes > 0 ? (option.votes / totalVotes) * 100 : 0;
                  const isSelected = selectedOption === option.id;

                  return (
                    <motion.div 
                        key={option.id} 
                        initial={{ opacity: 0, y: 20 }} 
                        animate={{ opacity: 1, y: 0 }} 
                        transition={{ duration: 0.5, delay: options.indexOf(option) * 0.1 }}
                        className={`border-2 rounded-xl p-4 transition-all duration-300 ${isSelected ? 'border-purple-500 bg-purple-900/20' : 'border-gray-700 hover:border-purple-600'}`}>
                      <div className="flex justify-between items-center mb-2">
                        <span className="font-bold text-gray-100">{option.name}</span>
                        <span className="text-sm font-mono text-gray-400">{option.votes.toLocaleString()} votes</span>
                      </div>
                      <div className="relative w-full bg-gray-700 rounded-full h-2.5 mb-3">
                        <motion.div
                          className="h-2.5 rounded-full"
                          style={{ background: option.color }}
                          initial={{ width: 0 }}
                          animate={{ width: `${percentage}%` }}
                          transition={{ duration: 0.8, ease: "easeInOut" }}
                        />
                      </div>
                      <div className="flex justify-between items-center">
                        <button onClick={() => handleSelectOption(option.id)} disabled={hasVoted} className={`text-sm font-semibold transition-colors ${isSelected ? 'text-purple-400' : 'text-gray-400 hover:text-white'}`}>
                          Select {option.id}
                        </button>
                        <span className="text-sm font-mono font-bold text-gray-300">{percentage.toFixed(1)}%</span>
                      </div>
                    </motion.div>
                  );
                })}
              </div>
              <div className="p-6 pt-2 space-y-3 border-t border-gray-700">
                <AnimatePresence mode="wait">
                {hasVoted ? (
                    <motion.div
                        key="voted"
                        initial={{ opacity: 0, y: -10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 10 }}
                        className="flex items-center justify-center gap-2 rounded-lg bg-green-600/20 text-green-400 px-4 py-3 text-base font-bold"
                    >
                        <CheckCircle className="h-5 w-5" />
                        Vote Cast Successfully!
                    </motion.div>
                ) : (
                    <motion.div key="voting" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                        <PrimaryButton onClick={handleCastVote} disabled={!selectedOption || hasVoted}>
                            <Vote className="h-5 w-5" />
                            Cast Vote
                        </PrimaryButton>
                    </motion.div>
                )}
                </AnimatePresence>
                <SecondaryButton onClick={handleReset} disabled={!selectedOption || hasVoted}>
                    <XCircle className="h-5 w-5" />
                    Reset Selection
                </SecondaryButton>
              </div>
            </Card>
          </div>

          {/* Right Side: Results Visualization */}
          <div className="lg:col-span-3 space-y-8">
            {/* Bar Chart Card */}
            <Card>
              <CardHeader icon={BarChart3} title="Vote Results" />
              <div className="p-4 h-80">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={options} margin={{ top: 20, right: 20, left: -10, bottom: 5 }}>
                    <defs>
                      {options.map((option, index) => (
                        <linearGradient key={`gradient-${index}`} id={`color${option.id}`} x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor={option.color} stopOpacity={0.8}/>
                          <stop offset="95%" stopColor={option.color} stopOpacity={0.2}/>
                        </linearGradient>
                      ))}
                    </defs>
                    <XAxis dataKey="name" stroke="#9CA3AF" fontSize={12} tickLine={false} axisLine={false} />
                    <YAxis stroke="#9CA3AF" fontSize={12} tickLine={false} axisLine={false} />
                    <Tooltip 
                        cursor={{fill: 'rgba(139, 92, 246, 0.1)'}}
                        contentStyle={{ 
                            background: 'rgba(31, 41, 55, 0.8)', 
                            borderColor: '#4B5563',
                            borderRadius: '0.75rem',
                            backdropFilter: 'blur(4px)'
                        }} 
                        labelStyle={{ color: '#F3F4F6' }} 
                    />
                    <Bar dataKey="votes" radius={[4, 4, 0, 0]}>
                      {options.map((entry) => (
                        <Cell key={`cell-${entry.id}`} fill={`url(#color${entry.id})`} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </Card>

            {/* Live Results Summary Card */}
            <Card>
              <CardHeader icon={TrendingUp} title="Live Results Summary" />
              <div className="grid grid-cols-1 sm:grid-cols-3 divide-y sm:divide-y-0 sm:divide-x divide-gray-700">
                <div className="p-6 flex flex-col items-center justify-center text-center">
                    <Users className="h-8 w-8 text-purple-400 mb-2"/>
                    <p className="text-sm text-gray-400">Total Votes</p>
                    <p className="text-3xl font-bold text-white">{totalVotes.toLocaleString()}</p>
                </div>
                <div className="p-6 flex flex-col items-center justify-center text-center">
                    <div style={{color: leadingOption?.color}} className="h-8 w-8 mb-2 font-extrabold text-2xl flex items-center justify-center rounded-full bg-gray-700">{leadingOption?.id}</div>
                    <p className="text-sm text-gray-400">Leading Option</p>
                    <p className="text-3xl font-bold text-white">{leadingOption?.name || 'N/A'}</p>
                </div>
                <div className="p-6 flex flex-col items-center justify-center text-center">
                    <BarChart3 className="h-8 w-8 text-purple-400 mb-2"/>
                    <p className="text-sm text-gray-400">Lead Difference</p>
                    <p className="text-3xl font-bold text-white">+{voteDifference.toLocaleString()}</p>
                </div>
              </div>
            </Card>
          </div>
        </div>
      </main>
    </div>
  );
};

export default VotingPortalHub;


