interface ReplyCardProps {
    reply: Reply;
}

const ReplyCard: FC<ReplyCardProps> = ({ reply }) => (
    <div className="pl-8 pt-3 mt-3 border-l-2 border-green-200">
        <div className="flex items-center space-x-2 text-sm">
            <div className="w-6 h-6 bg-slate-200 border-2 border-dashed rounded-full" />
            <span className="font-semibold text-slate-700">{reply.author}</span>
            <span className="text-slate-400">•</span>
            <span className="text-slate-400">{timeSince(reply.timestamp)}</span>
        </div>
        <p className="text-slate-600 mt-1 ml-8">{reply.text}</p>
    </div>
);

interface PostCardProps {
  post: Post;
  onAddReply: (postId: string, text: string) => void;
}

const PostCard: FC<PostCardProps> = ({ post, onAddReply }) => {
  const [showReplies, setShowReplies] = useState(false);
  const [replyText, setReplyText] = useState('');

  const handleReplySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (replyText.trim()) {
        onAddReply(post.id, replyText.trim());
        setReplyText('');
    }
  }

  return (
    <article className="bg-white p-5 rounded-xl border border-green-200/50 shadow-sm hover:shadow-md transition-shadow duration-300">
      <div className="flex items-start space-x-4">
        <div className="bg-slate-200 border-2 border-dashed rounded-xl w-12 h-12 flex-shrink-0" />
        <div className="flex-grow">
          <div className="flex justify-between items-start">
            <div>
              <h2 className="text-lg font-bold text-green-900">{post.title}</h2>
              <div className="flex items-center space-x-2 text-sm text-slate-500 mt-1">
                <span>{post.author}</span>
                <span>•</span>
                <span>{timeSince(post.timestamp)} ago</span>
              </div>
            </div>
            <div className="text-xs font-medium bg-green-100 text-green-800 px-2 py-1 rounded-full">{post.category}</div>
          </div>
          <p className="text-slate-700 mt-3">{post.content}</p>
          <div className="flex flex-wrap gap-2 mt-4">
            {post.tags.map(tag => (
                <span key={tag} className="bg-gray-100 text-gray-600 px-2 py-1 text-xs rounded-full font-medium">{tag}</span>
            ))}
          </div>
          <div className="flex items-center justify-between mt-4 text-slate-600">
            <button onClick={() => setShowReplies(!showReplies)} className="flex items-center space-x-2 p-2 -ml-2 rounded-lg hover:bg-green-100 hover:text-green-900 transition-colors">
              <MessageSquare className="h-5 w-5" />
              <span className="font-medium text-sm">{post.replies.length} Replies</span>
              {post.replies.length > 0 && <ChevronDown className={cn('h-4 w-4 transition-transform', { 'rotate-180': showReplies })} />}
            </button>
          </div>

          {showReplies && (
            <div className="mt-4">
                {post.replies.length > 0 ? (
                    <div className="space-y-3">
                        {post.replies.map(reply => <ReplyCard key={reply.id} reply={reply} />)}
                    </div>
                ) : (
                    <p className="text-sm text-slate-400 pl-8 pt-3 mt-3 border-l-2 border-green-200">No replies yet.</p>
                )}
                <form onSubmit={handleReplySubmit} className="mt-4 pl-8 border-l-2 border-green-200">
                    <div className="flex space-x-2">
                        <input 
                            type="text"
                            value={replyText}
                            onChange={(e) => setReplyText(e.target.value)}
                            placeholder="Add a reply..."
                            className="w-full bg-slate-100 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-green-500"
                        />
                        <button type="submit" className="px-4 py-2 text-sm font-semibold text-white bg-green-900 rounded-lg hover:bg-green-800 transition-colors">Reply</button>
                    </div>
                </form>
            </div>
          )}
        </div>
      </div>
    </article>
  );
};

interface NewPostModalProps {
  onClose: () => void;
  onPostSubmit: (post: Omit<Post, 'id' | 'author' | 'timestamp' | 'replies'>) => void;
}

const NewPostModal: FC<NewPostModalProps> = ({ onClose, onPostSubmit }) => {
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [category, setCategory] = useState<'Academics' | 'Campus Life' | 'Events'>('Academics');
    const [tags, setTags] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if(title.trim() && content.trim()) {
            onPostSubmit({ 
                title, 
                content, 
                category, 
                tags: tags.split(',').map(t => t.trim().startsWith('#') ? t.trim() : `#${t.trim()}`).filter(t => t.length > 1)
            });
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl relative animate-in fade-in-90 slide-in-from-bottom-10 duration-300">
                <div className="p-6 border-b border-green-200/50 flex justify-between items-center">
                    <h2 className="text-xl font-bold text-green-900">Create a New Post</h2>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-100"><X className="h-5 w-5 text-slate-500" /></button>
                </div>
                <form onSubmit={handleSubmit}>
                    <div className="p-6 space-y-4">
                        <input type="text" placeholder="Title" value={title} onChange={e => setTitle(e.target.value)} className="w-full border border-slate-300 rounded-lg p-3 text-lg focus:outline-none focus:ring-2 focus:ring-green-500" required />
                        <textarea placeholder="What's on your mind?" value={content} onChange={e => setContent(e.target.value)} className="w-full border border-slate-300 rounded-lg p-3 h-40 resize-none focus:outline-none focus:ring-2 focus:ring-green-500" required />
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as any)} className="w-full border border-slate-300 rounded-lg p-3 bg-white focus:outline-none focus:ring-2 focus:ring-green-500">
                                    {CATEGORIES.map(cat => <option key={cat.name} value={cat.name}>{cat.name}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">Tags</label>
                                <input type="text" placeholder="e.g. #Housing, #Exams" value={tags} onChange={e => setTags(e.target.value)} className="w-full border border-slate-300 rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-green-500" />
                            </div>
                        </div>
                    </div>
                    <div className="p-6 bg-slate-50 rounded-b-xl border-t border-green-200/50 flex justify-end space-x-3">
                        <button type="button" onClick={onClose} className="px-6 py-2 font-semibold text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-100 transition-colors">Cancel</button>
                        <button type="submit" className="px-6 py-2 font-semibold text-white bg-green-900 rounded-lg hover:bg-green-800 transition-colors">Post</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

// MAIN PAGE COMPONENT
const CampusConnectPage: NextPage = () => {
  const [posts, setPosts] = useState<Post[]>(initialPosts);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [activeTag, setActiveTag] = useState<string | null>(null);
  const [showNewPostModal, setShowNewPostModal] = useState(false);

  const filteredPosts = useMemo(() => {
    return posts
      .filter(post => 
        activeCategory ? post.category === activeCategory : true
      )
      .filter(post =>
        activeTag ? post.tags.includes(activeTag) : true
      )
      .filter(post => 
        post.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        post.content.toLowerCase().includes(searchTerm.toLowerCase())
      )
      .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
  }, [posts, searchTerm, activeCategory, activeTag]);

  const handlePostSubmit = (newPostData: Omit<Post, 'id' | 'author' | 'timestamp' | 'replies'>) => {
    const newPost: Post = {
        ...newPostData,
        id: `post-${Date.now()}`,
        author: `user${Math.floor(Math.random() * 900) + 100}`,
        timestamp: new Date(),
        replies: [],
    };
    setPosts(prevPosts => [newPost, ...prevPosts]);
    setShowNewPostModal(false);
  };

  const handleAddReply = (postId: string, text: string) => {
    const newReply: Reply = {
        id: `reply-${Date.now()}`,
        author: `user${Math.floor(Math.random() * 900) + 100}`,
        text,
        timestamp: new Date(),
    };
    setPosts(posts.map(p => p.id === postId ? { ...p, replies: [...p.replies, newReply] } : p));
  };

  return (
    <div className="min-h-screen bg-green-50 font-sans text-slate-800">
      <Header />
      <main className="container mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex flex-col lg:flex-row gap-8">
          <Sidebar 
            activeCategory={activeCategory} 
            setActiveCategory={setActiveCategory}
            activeTag={activeTag}
            setActiveTag={setActiveTag}
          />
          <div className="flex-1 min-w-0">
            <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
              <div className="relative w-full sm:max-w-xs">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" />
                <input 
                  type="text"
                  placeholder="Search discussions..."
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-green-200/80 rounded-lg bg-white focus:outline-none focus:ring-2 focus:ring-green-500"
                />
              </div>
              <button 
                onClick={() => setShowNewPostModal(true)} 
                className="w-full sm:w-auto flex items-center justify-center gap-2 px-4 py-2 font-semibold text-white bg-green-900 rounded-lg hover:bg-green-800 transition-colors shadow-sm hover:shadow-md">
                <PlusCircle className="h-5 w-5" />
                New Post
              </button>
            </div>
            <div className="space-y-4">
              {filteredPosts.length > 0 ? (
                filteredPosts.map(post => <PostCard key={post.id} post={post} onAddReply={handleAddReply} />)
              ) : (
                <div className="text-center py-16 bg-white rounded-xl border border-dashed border-green-300">
                    <h3 className="text-lg font-medium text-slate-600">No posts found</h3>
                    <p className="text-slate-500 mt-1">Try adjusting your search or filters.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
      {showNewPostModal && <NewPostModal onClose={() => setShowNewPostModal(false)} onPostSubmit={handlePostSubmit} />}
    </div>
  );
};

export default CampusConnectPage;


