const CryptoEscrowPage = () => {
  const [activeView, setActiveView] = useState<ActiveView>('products');
  const [transactions, setTransactions] = useState<Transaction[]>(initialTransactions);
  const [error, setError] = useState<string | null>(null);

  const handlePurchase = (product: Product) => {
    // Simulate a client-side exception for demonstration
    if (product.id === 'prod_001') { // Fail purchase for BTC Mining Rig
      setError('Purchase failed: Insufficient crypto balance for this high-value item. Please try a different payment method.');
      return;
    }

    // Simulate a successful purchase
    const newTransaction: Transaction = {
      id: `txn_${Math.random().toString(36).substr(2, 6)}`,
      productTitle: product.title,
      date: new Date().toISOString().split('T')[0],
      amount: product.price,
      status: 'In Escrow',
    };
    setTransactions(prev => [newTransaction, ...prev]);
    setActiveView('transactions');
  };

  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(null), 5000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  return (
    <div className="bg-gray-100 min-h-screen font-sans">
      {error && <ErrorMessage message={error} onClose={() => setError(null)} />}
      <div className="flex h-screen">
        <Sidebar activeView={activeView} setActiveView={setActiveView} />
        <div className="flex-1 flex flex-col overflow-hidden">
          <Header />
          <main className="flex-1 overflow-y-auto p-8">
            {activeView === 'products' && <ProductsView onPurchase={handlePurchase} />}
            {activeView === 'transactions' && <TransactionsView transactions={transactions} />}
          </main>
        </div>
      </div>
    </div>
  );
};

export default CryptoEscrowPage;


