import { useState, useEffect, FC, FormEvent } from 'react';
import type { NextPage } from 'next';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { ArrowDownLeft, ArrowUpRight, BarChart2, Briefcase, Clock, DollarSign, LogIn, LogOut, Paperclip, TrendingUp, User } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type Trade = {
  id: string;
  type: 'buy' | 'sell';
  amount: number;
  price: number;
  timestamp: string;
};

type ChartData = {
  time: string;
  price: number;
};

// --- MOCK DATA ---
const generateChartData = (): ChartData[] => {
  const data: ChartData[] = [];
  let price = 150.00;
  for (let i = 60; i >= 0; i--) {
    const date = new Date(Date.now() - i * 60000);
    price += (Math.random() - 0.5) * 3;
    if (price < 140) price = 140;
    if (price > 160) price = 160;
    data.push({
      time: date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      price: parseFloat(price.toFixed(2)),
    });
  }
  return data;
};

const initialTradeHistory: Trade[] = [
  {
    id: 't2',
    type: 'buy',
    amount: 0.5,
    price: 148.55,
    timestamp: new Date(Date.now() - 3600000).toLocaleString(),
  },
  {
    id: 't1',
    type: 'sell',
    amount: 1.2,
    price: 151.20,
    timestamp: new Date(Date.now() - 7200000).toLocaleString(),
  },
];

// --- UI HELPER COMPONENTS (within the same file) ---

interface CardProps {
  children: React.ReactNode;
  className?: string;
}

const Card: FC<CardProps> = ({ children, className = '' }) => (
  <div className={`bg-white rounded-xl shadow-md p-4 sm:p-6 ${className}`}>
    {children}
  </div>
);

interface CardTitleProps {
  icon: React.ElementType;
