  const [tradeHistory, setTradeHistory] = useState<Trade[]>(initialTradeHistory);
  const [chartData, setChartData] = useState<ChartData[]>(generateChartData());
  const [currentPrice, setCurrentPrice] = useState<number>(chartData[chartData.length - 1].price);

  useEffect(() => {
