const ComposeView: FC<{ onSend: (email: Omit<Email, 'id' | 'timestamp' | 'read'>) => void; onDiscard: () => void }> = ({ onSend, onDiscard }) => {
    const [to, setTo] = useState('');
    const [subject, setSubject] = useState('');
    const [body, setBody] = useState('');

    const handleSend = () => {
        if (!to || !subject || !body) return;
        onSend({ sender: 'you@example.com', recipient: to, subject, body, hasAttachment: false });
    };

    return (
        // Compose Section
        <div className="bg-white border border-slate-200 rounded-xl shadow-sm">
            <div className="p-4 border-b border-slate-200">
                <h2 className="text-lg font-semibold text-slate-800">New Message</h2>
            </div>
            <div className="p-6 space-y-4">
                {/* Recipients Field */}
                <input type="email" placeholder="Recipients" value={to} onChange={e => setTo(e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-amber-400 transition" />
                {/* Subject Field */}
                <input type="text" placeholder="Subject" value={subject} onChange={e => setSubject(e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-amber-400 transition" />
                {/* Body Field */}
                <textarea placeholder="Compose your email..." value={body} onChange={e => setBody(e.target.value)} className="w-full h-64 px-3 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-amber-400 transition resize-none" />
            </div>
            <div className="flex justify-between items-center p-4 bg-slate-50 rounded-b-xl border-t border-slate-200">
                <div className="flex items-center gap-2">
                    {/* Add File Card / Button */}
                    <button className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-600 rounded-md hover:bg-slate-200 transition-colors">
                        <Paperclip className="w-4 h-4" />
                        Add File
