const EmailManagementHubPage: NextPage = () => {
  const [activeView, setActiveView] = useState<ActiveView>('inbox');
  const [emails, setEmails] = useState<Email[]>(initialEmails);
  const [contacts, setContacts] = useState<Contact[]>(initialContacts);
  const [searchTerm, setSearchTerm] = useState('');

  const handleDeleteEmail = (id: string) => {
    setEmails(prevEmails => prevEmails.filter(email => email.id !== id));
  };

  const handleSendEmail = (newEmailData: Omit<Email, 'id' | 'timestamp' | 'read'>) => {
    const newEmail: Email = {
        ...newEmailData,
        id: `email-${Date.now()}`,
        timestamp: 'Just now',
        read: true, // Sent emails are considered 'read' by the sender
    };
    setEmails(prevEmails => [newEmail, ...prevEmails]);
    setActiveView('inbox');
  };

  const handleRefresh = () => {
    // Simple refresh simulation by re-setting state
    setEmails([...initialEmails].sort(() => Math.random() - 0.5)); // Shuffle for visual feedback
  };

  const renderActiveView = () => {
    switch (activeView) {
      case 'inbox':
        return <InboxView emails={emails} searchTerm={searchTerm} onDelete={handleDeleteEmail} />;
      case 'compose':
        return <ComposeView onSend={handleSendEmail} onDiscard={() => setActiveView('inbox')} />;
      case 'templates':
        return <TemplatesView />;
      case 'contacts':
        return <ContactsView contacts={contacts} setContacts={setContacts} />;
      default:
        return <InboxView emails={emails} searchTerm={searchTerm} onDelete={handleDeleteEmail} />;
    }
  };

  return (
    <div className="flex h-screen font-sans bg-orange-50 text-slate-900">
      <Sidebar activeView={activeView} setActiveView={setActiveView} />
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Top Bar */}
        <header className="flex-shrink-0 bg-orange-50/80 backdrop-blur-sm border-b border-amber-200/50 p-4">
            <div className="flex items-center justify-between">
                {/* Search Box */}
                <div className="relative w-full max-w-md">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input
                        type="text"
                        placeholder="Search mail..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 bg-white border border-slate-300 rounded-full focus:outline-none focus:ring-2 focus:ring-amber-400 transition"
                    />
                </div>
                <div className="flex items-center gap-4">
                    {/* Refresh Button */}
                    <button onClick={handleRefresh} className="p-2 text-slate-500 rounded-full hover:bg-amber-100 hover:text-amber-800 transition-colors">
                        <RefreshCw className="w-5 h-5" />
                    </button>
                    {/* Compose Button */}
                    <button onClick={() => setActiveView('compose')} className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-amber-700 rounded-full hover:bg-amber-800 transition-colors shadow-sm">
                        <Edit className="w-4 h-4" />
                        Compose
                    </button>
                </div>
            </div>
        </header>
        <div className="flex-1 overflow-y-auto p-6">
          {renderActiveView()}
        </div>
      </main>
    </div>
  );
};

export default EmailManagementHubPage;


