type NavItemKey = 'sendMessage' | 'users' | 'policies' | 'monitoring';

type Message = {
  id: number;
  sender: string;
  content: string;
  timestamp: string;
};

// --- MOCK DATA ---
const initialUsers = [
  { id: '1', name: 'Alice Johnson', phone: '+1234567890' },
  { id: '2', name: 'Bob Williams', phone: '+1987654321' },
  { id: '3', name: 'Charlie Brown', phone: '+1122334455' },
];

const initialMessages: Message[] = [
  {
    id: 1,
    sender: 'Marketing Dept',
    content: 'Flash Sale! 50% off on all items this weekend. Dont miss out!',
    timestamp: '2024-07-21 10:30 AM',
  },
  {
    id: 2,
    sender: 'Support Team',
    content: 'Your support ticket #12345 has been resolved. Please rate your experience.',
    timestamp: '2024-07-21 09:15 AM',
  },
  {
    id: 3,
    sender: 'System Alert',
    content: 'Scheduled maintenance will occur tonight from 11 PM to 1 AM.',
    timestamp: '2024-07-20 05:00 PM',
  },
];

// --- HELPER COMPONENTS ---

const IconWrapper: FC<{ icon: React.ElementType<SVGProps<SVGSVGElement>>; className?: string }> = ({ icon: Icon, className }) => (
  <Icon className={className || 'w-5 h-5'} />
);

interface CardProps {
  children: ReactNode;
  className?: string;
}

const Card: FC<CardProps> = ({ children, className = '' }) => (
  <div className={`bg-slate-800/50 backdrop-blur-sm border border-slate-700 rounded-xl shadow-lg ${className}`}>
    {children}
  </div>
);

interface NavItemProps {
  icon: React.ElementType<SVGProps<SVGSVGElement>>;
  label: string;
  isActive: boolean;
  onClick: () => void;
}

const NavItem: FC<NavItemProps> = ({ icon, label, isActive, onClick }) => (
  <button
    onClick={onClick}
    className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-all duration-200 ${isActive
        ? 'bg-sky-500 text-white shadow-md'
        : 'text-slate-300 hover:bg-slate-700/50 hover:text-white'
      }`}
  >
    <IconWrapper icon={icon} className="w-5 h-5 mr-4" />
    <span>{label}</span>
  </button>
);

// --- MAIN SECTIONS ---

const SendMessageSection: FC<{ onSendMessage: (msg: Omit<Message, 'id'>) => void }> = ({ onSendMessage }) => {
  const [recipient, setRecipient] = useState(initialUsers[0].id);
  const [customRecipient, setCustomRecipient] = useState('');
  const [message, setMessage] = useState('');

  const handleSend = () => {
    if (!message.trim()) return;
    const selectedUser = initialUsers.find(u => u.id === recipient);
    const finalRecipient = customRecipient.trim() || selectedUser?.phone || 'Unknown';

    onSendMessage({
      sender: 'You',
      content: message,
      timestamp: new Date().toLocaleString(),
    });

    setMessage('');
    setCustomRecipient('');
  };

  return (
    <Card className="p-6">
      <h2 className="text-xl font-bold text-white mb-6">Compose & Send Message</h2>
      <div className="space-y-6">
        <div>
          <label htmlFor="recipient" className="block text-sm font-medium text-slate-300 mb-2">Recipient</label>
          {/* Recipient Dropdown */}
          <select
            id="recipient"
            value={recipient}
            onChange={(e) => setRecipient(e.target.value)}
            className="w-full bg-slate-700 border border-slate-600 text-white rounded-lg p-3 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 transition"
          >
            {initialUsers.map(user => <option key={user.id} value={user.id}>{user.name} ({user.phone})</option>)}
          </select>
        </div>
        <div>
          <label htmlFor="custom-recipient" className="block text-sm font-medium text-slate-300 mb-2">Or Enter Custom Recipient</label>
          {/* Custom Recipient Input */}
          <input
            type="text"
            id="custom-recipient"
            value={customRecipient}
            onChange={(e) => setCustomRecipient(e.target.value)}
            placeholder="+15551234567"
            className="w-full bg-slate-700 border border-slate-600 text-white rounded-lg p-3 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 transition"
          />
        </div>
        <div>
          <label htmlFor="message" className="block text-sm font-medium text-slate-300 mb-2">Message</label>
          {/* Message Textarea */}
          <textarea
            id="message"
            rows={5}
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="Type your message here..."
            className="w-full bg-slate-700 border border-slate-600 text-white rounded-lg p-3 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 transition"
          />
        </div>
        {/* Send Message Button */}
        <button
          onClick={handleSend}
          className="w-full flex items-center justify-center gap-2 bg-sky-500 text-white font-bold py-3 px-4 rounded-lg hover:bg-sky-600 transition-all duration-200 disabled:bg-slate-600 disabled:cursor-not-allowed"
          disabled={!message.trim() || (!recipient && !customRecipient.trim())}
        >
          <IconWrapper icon={Send} className="w-5 h-5" />
          Send Message
        </button>
      </div>
    </Card>
  );
};

const MessageHistorySection: FC<{ messages: Message[] }> = ({ messages }) => (
  /* Message History Card */
  <Card className="p-6">
    <h2 className="text-xl font-bold text-white mb-4">Message History</h2>
    <div className="space-y-4 max-h-[40rem] overflow-y-auto pr-2">
      {messages.map((msg) => (
        <div key={msg.id} className="bg-slate-900/70 p-4 rounded-lg border border-slate-700 hover:border-sky-500 transition-colors duration-200 cursor-pointer">
          <div className="flex justify-between items-start">
            <p className="font-semibold text-sky-400 flex items-center gap-2"><IconWrapper icon={MessageCircle} className="w-4 h-4"/>{msg.sender}</p>
            <p className="text-xs text-slate-400 flex items-center gap-1.5"><IconWrapper icon={Clock} className="w-3 h-3"/>{msg.timestamp}</p>
          </div>
          <p className="text-slate-300 mt-2 text-sm">{msg.content}</p>
        </div>
      ))}
    </div>
  </Card>
);

const UserManagementSection: FC = () => (
  /* User Management Card */
  <Card className="p-6">
    <h2 className="text-xl font-bold text-white mb-6">User Management</h2>
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
      {/* User Details Card */}
      <Card className="p-4 bg-slate-900/50">
        <div className="flex items-center gap-4">
            <div className="bg-gray-200 border-2 border-dashed rounded-full w-16 h-16 flex-shrink-0" />
            <div>
                <h3 className="font-bold text-white">John Doe</h3>
                <p className="text-sm text-slate-400">Admin</p>
            </div>
        </div>
        <div className="mt-4 space-y-2 text-sm">
            <p className="text-slate-300">Email: john.doe@example.com</p>
            <p className="text-slate-300">Phone: +1123456789</p>
            <p className="text-slate-300">Status: <span className="text-green-400">Active</span></p>
        </div>
      </Card>
      <Card className="p-4 bg-slate-900/50 flex items-center justify-center">
        <p className="text-slate-400">More user cards...</p>
      </Card>
    </div>
  </Card>
);

const PoliciesSection: FC = () => (
  <Card className="p-6">
    <h2 className="text-xl font-bold text-white mb-4">Policy Configuration</h2>
    <p className="text-slate-300">Policy management interface will be displayed here. Configure sending limits, content filters, and compliance rules.</p>
  </Card>
);

const MonitoringSection: FC = () => (
  <Card className="p-6">
    <h2 className="text-xl font-bold text-white mb-4">System Monitoring</h2>
    <p className="text-slate-300">Real-time monitoring dashboards for SMS delivery rates, system health, and API usage will be available here.</p>
  </Card>
);


const SMSHubPage: NextPage = () => {
  const [activeView, setActiveView] = useState<NavItemKey>('sendMessage');
  const [messages, setMessages] = useState<Message[]>(initialMessages);

  const handleSendMessage = (newMessage: Omit<Message, 'id'>) => {
    setMessages(prev => [{ ...newMessage, id: Date.now() }, ...prev]);
  };

  const renderContent = () => {
    switch (activeView) {
      case 'sendMessage':
        return (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <SendMessageSection onSendMessage={handleSendMessage} />
            <MessageHistorySection messages={messages} />
          </div>
        );
      case 'users':
        return <UserManagementSection />;
      case 'policies':
        return <PoliciesSection />;
      case 'monitoring':
        return <MonitoringSection />;
      default:
        return null;
    }
  };

  return (
    <>
      <Head>
        <title>SMS Management Hub</title>
        <meta name="description" content="Manage and send SMS messages with ease" />
        <link rel="icon" href="/favicon.ico" />
      </Head>

      <div className="min-h-screen bg-gradient-to-br from-slate-900 to-slate-800 text-slate-100 font-sans">
        <div className="grid grid-cols-1 md:grid-cols-[280px_1fr]">
          {/* Sidebar */}
          <aside className="bg-slate-900/80 backdrop-blur-sm p-6 border-r border-slate-800 h-screen sticky top-0">
            {/* Sidebar Menu Card */}
            <div className="flex flex-col h-full">
              {/* SMS Platform Card */}
              <div className="flex items-center gap-3 mb-10">
                 <div className="bg-sky-500 p-2 rounded-lg">
                    <IconWrapper icon={MessageSquare} className="w-6 h-6 text-white" />
                 </div>
                 <h1 className="text-xl font-bold text-white">SMS Platform</h1>
              </div>

              <nav className="flex flex-col gap-y-4">
                {/* Send Message Menu Item & Button */}
                <NavItem icon={MessageSquare} label="Send Message" isActive={activeView === 'sendMessage'} onClick={() => setActiveView('sendMessage')} />

                {/* Users Menu Item, Button & Card */}
                <NavItem icon={Users} label="Users" isActive={activeView === 'users'} onClick={() => setActiveView('users')} />

                {/* Policies Menu Item, Button & Card */}
                <NavItem icon={Shield} label="Policies" isActive={activeView === 'policies'} onClick={() => setActiveView('policies')} />

                {/* Monitoring Menu Item, Button & Card */}
                <NavItem icon={BarChart4} label="Monitoring" isActive={activeView === 'monitoring'} onClick={() => setActiveView('monitoring')} />
              </nav>

              <div className="mt-auto">
                 <Card className="p-4 text-center bg-slate-800">
                    <h4 className="font-bold text-white">Upgrade to Pro</h4>
                    <p className="text-sm text-slate-300 mt-1 mb-4">Unlock advanced features and get unlimited SMS.</p>
                    <button className="w-full bg-sky-500 text-white font-bold py-2 px-4 rounded-lg hover:bg-sky-600 transition-all">Upgrade</button>
                 </Card>
              </div>
            </div>
          </aside>

          {/* Main Content */}
          <main className="p-8">
            {/* Header */}
            <header className="flex justify-between items-center mb-8">
              <div className="relative w-full max-w-md">
                {/* Search Input */}
                <input
                  type="text"
                  placeholder="Search platform..."
                  className="w-full bg-slate-800 border border-slate-700 text-white rounded-lg py-2 pl-10 pr-4 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 transition"
                />
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <IconWrapper icon={Search} className="w-5 h-5 text-slate-400" />
                </div>
              </div>
              <div className="flex items-center gap-6">
                {/* Notification Icon */}
                <button className="text-slate-400 hover:text-white transition-colors">
                  <IconWrapper icon={Bell} />
                </button>
                {/* User Profile Icon */}
                <button className="text-slate-400 hover:text-white transition-colors">
                  <IconWrapper icon={UserCircle} />
                </button>
              </div>
            </header>

            {/* Dynamic Content Area */}
            {renderContent()}
          </main>
        </div>
      </div>
    </>
  );
};

export default SMSHubPage;


