import { useState, type FC, useMemo } from 'react';
import type { NextPage } from 'next';
import { Box, Package, MapPin, Search, BarChart, FileCheck, RefreshCcw, Factory, Ship } from 'lucide-react';

// --- TYPES --- //
type ProductStatus = 'Registered' | 'In Transit' | 'Delivered';
type Product = {
  id: string;
  name: string;
  origin: string;
  status: ProductStatus;
};
type TabId = 'register' | 'track' | 'inquiry' | 'verify' | 'statistics';

// --- MOCK DATA --- //
const initialProducts: Product[] = [
  { id: 'PROD-001', name: 'Organic Avocados', origin: 'Mexico', status: 'Delivered' },
  { id: 'PROD-002', name: 'Robusta Coffee Beans', origin: 'Vietnam', status: 'In Transit' },
  { id: 'PROD-003', name: 'Basmati Rice', origin: 'India', status: 'Registered' },
  { id: 'PROD-004', name: 'Extra Virgin Olive Oil', origin: 'Spain', status: 'Registered' },
];

// --- HELPER COMPONENTS --- //

const StatusBadge: FC<{ status: ProductStatus }> = ({ status }) => {
  const baseClasses = 'px-3 py-1 text-xs font-medium rounded-full inline-flex items-center gap-1';
  const styles = {
    Registered: 'bg-blue-100 text-blue-800',
    'In Transit': 'bg-amber-100 text-amber-800',
    Delivered: 'bg-green-100 text-green-800',
  };
  return <span className={`${baseClasses} ${styles[status]}`}>{status}</span>;
};

const PlaceholderContent: FC<{ title: string; icon: React.ReactNode }> = ({ title, icon }) => (
  <div className="text-center py-20 px-6 bg-rose-50 rounded-lg">
    <div className="inline-flex items-center justify-center p-4 bg-rose-100 rounded-full mb-4">
      {icon}
    </div>
    <h3 className="text-xl font-semibold text-rose-900 mb-2">{title}</h3>
    <p className="text-rose-700">This feature is currently under development. Please check back later!</p>
  </div>
);

// --- MAIN PAGE COMPONENT --- //

const SupplyChainPortalPage: NextPage = () => {
  const [activeTab, setActiveTab] = useState<TabId>('register');
  const [products, setProducts] = useState<Product[]>(initialProducts);
  const [productId, setProductId] = useState('');
  const [productName, setProductName] = useState('');
  const [origin, setOrigin] = useState('');
  const [error, setError] = useState('');

  const tabs = useMemo(() => [
    { id: 'register', label: 'Register', icon: <Package size={18} /> },
    { id: 'track', label: 'Track', icon: <MapPin size={18} /> },
    { id: 'inquiry', label: 'Inquiry', icon: <Search size={18} /> },
    { id: 'verify', label: 'Verify', icon: <FileCheck size={18} /> },
    { id: 'statistics', label: 'Statistics', icon: <BarChart size={18} /> },
  ], []);

  const handleRegisterProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!productId || !productName || !origin) {
      setError('All fields are required.');
      return;
    }
    if (products.some(p => p.id.toLowerCase() === productId.toLowerCase())) {
      setError('A product with this ID already exists.');
      return;
    }

    const newProduct: Product = {
      id: productId.toUpperCase(),
      name: productName,
      origin: origin,
      status: 'Registered',
    };

    setProducts([newProduct, ...products]);
    setProductId('');
    setProductName('');
    setOrigin('');
    setError('');
  };

  const handleReset = () => {
    setProducts(initialProducts);
    setProductId('');
    setProductName('');
    setOrigin('');
    setError('');
    setActiveTab('register');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'register':
        return (
          <div className="space-y-8">
            {/* Register New Product Section */}
            <section>
              <h2 className="text-xl font-semibold text-slate-800 mb-4">Register New Product</h2>
              <form onSubmit={handleRegisterProduct} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                <div className="md:col-span-1">
                  <label htmlFor="productId" className="block text-sm font-medium text-slate-600 mb-1">Product ID</label>
                  <input id="productId" type="text" value={productId} onChange={(e) => setProductId(e.target.value)} placeholder="e.g., PROD-005" className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-rose-600 focus:border-transparent transition" />
                </div>
                <div className="md:col-span-1">
                  <label htmlFor="productName" className="block text-sm font-medium text-slate-600 mb-1">Product Name</label>
                  <input id="productName" type="text" value={productName} onChange={(e) => setProductName(e.target.value)} placeholder="e.g., Blueberries" className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-rose-600 focus:border-transparent transition" />
                </div>
                <div className="md:col-span-1">
                  <label htmlFor="origin" className="block text-sm font-medium text-slate-600 mb-1">Origin</label>
                  <input id="origin" type="text" value={origin} onChange={(e) => setOrigin(e.target.value)} placeholder="e.g., Chile" className="w-full px-3 py-2 border border-slate-300 rounded-md focus:ring-2 focus:ring-rose-600 focus:border-transparent transition" />
                </div>
                <div className="md:col-span-1">
                  <button type="submit" className="w-full bg-rose-800 text-white font-semibold py-2 px-4 rounded-md hover:bg-rose-900 transition-colors flex items-center justify-center gap-2"> <Package size={16} /> Register Product</button>
                </div>
              </form>
              {error && <p className="text-red-600 text-sm mt-2">{error}</p>}
            </section>

            <div className="border-b border-slate-200"></div>

            {/* Registered Products Table */}
            <section>
              <h2 className="text-xl font-semibold text-slate-800 mb-4">Registered Products</h2>
              <div className="overflow-x-auto bg-white rounded-lg border border-slate-200">
                <table className="w-full text-sm text-left text-slate-600">
                  <thead className="bg-slate-50 text-xs text-slate-700 uppercase">
                    <tr>
                      <th scope="col" className="px-6 py-3">Product ID</th>
                      <th scope="col" className="px-6 py-3">Name</th>
                      <th scope="col" className="px-6 py-3">Origin</th>
                      <th scope="col" className="px-6 py-3">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {products.map((product) => (
                      <tr key={product.id} className="bg-white border-b border-slate-200 hover:bg-rose-50 transition-colors">
                        <th scope="row" className="px-6 py-4 font-medium text-slate-900 whitespace-nowrap">{product.id}</th>
                        <td className="px-6 py-4">{product.name}</td>
                        <td className="px-6 py-4">{product.origin}</td>
                        <td className="px-6 py-4"><StatusBadge status={product.status} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {products.length === 0 && <div className="text-center py-10 text-slate-500">No products registered yet.</div>}
              </div>
            </section>
          </div>
        );
      case 'track':
        return <PlaceholderContent title="Track Product" icon={<MapPin size={32} className="text-rose-800" />} />;
      case 'inquiry':
        return <PlaceholderContent title="Product Inquiry" icon={<Search size={32} className="text-rose-800" />} />;
      case 'verify':
        return <PlaceholderContent title="Verify Authenticity" icon={<FileCheck size={32} className="text-rose-800" />} />;
      case 'statistics':
        return <PlaceholderContent title="Data Statistics & Analysis" icon={<BarChart size={32} className="text-rose-800" />} />;
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-rose-50 font-sans text-slate-800">
      <div className="container mx-auto p-4 md:p-8">

        {/* Header */}
        <header className="flex flex-col md:flex-row justify-between items-center mb-8">
          <div className="flex items-center gap-3 mb-4 md:mb-0">
            <div className="p-2 bg-rose-800 text-white rounded-lg">
                <Ship size={28}/>
            </div>
            <h1 className="text-2xl md:text-3xl font-bold text-rose-900">Supply Chain Traceability</h1>
          </div>
          <button onClick={handleReset} className="flex items-center gap-2 text-sm text-rose-700 hover:text-rose-900 font-medium transition-colors">
            <RefreshCcw size={16} />
            Reset Application
          </button>
        </header>

        {/* Main Card */}
        <main className="bg-white rounded-2xl shadow-lg p-6 md:p-8">
          {/* Supply Chain Tracker Card Navigation */}
          <nav className="flex flex-wrap border-b border-slate-200 mb-8">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-2 px-4 py-3 text-sm font-semibold transition-colors -mb-px border-b-2
                  ${activeTab === tab.id
                    ? 'border-rose-800 text-rose-800'
                    : 'border-transparent text-slate-500 hover:border-rose-300 hover:text-rose-700'}
                `}
              >
                {tab.icon}
                {tab.label}
              </button>
            ))}
          </nav>

          {/* Content Area */}
          <div>{renderContent()}</div>
        </main>

        {/* Footer */}
        <footer className="text-center mt-8">
          <p className="text-sm text-rose-600">&copy; {new Date().getFullYear()} Supply Chain Solutions. All Rights Reserved.</p>
        </footer>
      </div>
    </div>
  );
};

export default SupplyChainPortalPage;


