      <div className="flex items-center gap-3 mb-4 md:mb-0">\n            <div className="p-2 bg-rose-800 text-white rounded-lg">\n                <Ship size={28}/>\n            </div>\n            <h1 className="text-2xl md:text-3xl font-bold text-rose-900">Supply Chain Traceability</h1>\n          </div>\n          <button onClick={handleReset} className="flex items-center gap-2 text-sm text-rose-700 hover:text-rose-900 font-medium transition-colors">\n            <RefreshCcw size={16} />\n            Reset Application\n          </button>\n        </header>\n\n        {/* Main Card */}\n        <main className="bg-white rounded-2xl shadow-lg p-6 md:p-8">\n          {/* Supply Chain Tracker Card Navigation */}\n          <nav className="flex flex-wrap border-b border-slate-200 mb-8">\n            {tabs.map((tab) => (\n              <button\n                key={tab.id}\n                onClick={() => setActiveTab(tab.id)}\n                className={`flex items-center gap-2 px-4 py-3 text-sm font-semibold transition-colors -mb-px border-b-2\n                  ${activeTab === tab.id\n                    ? \'border-rose-800 text-rose-800\'\n                    : \'border-transparent text-slate-500 hover:border-rose-300 hover:text-rose-700\'}\n                `}\n              >\n                {tab.icon}\n                {tab.label}\n              </button>\n            ))}\n          </nav>\n          \n          {/* Content Area */}\n          <div>{renderContent()}</div>\n        </main>\n\n        {/* Footer */}\n        <footer className="text-center mt-8">\n          <p className="text-sm text-rose-600">&copy; {new Date().getFullYear()} Supply Chain Solutions. All Rights Reserved.</p>\n        </footer>\n      </div>\n    </div>\n  );\n};\n\nexport default SupplyChainPortalPage;\n'}

import { useState, useEffect, FC, ReactNode } from 'react';
import type { NextPage } from 'next';
import { 
    LayoutDashboard, Boxes, Factory, ShoppingCart, BarChart3, Users, Settings, 
    ChevronLeft, ChevronRight, PlusCircle, Package, PackageCheck, DollarSign, Users2, 
    FileDown, Sheet, FileText 
} from 'lucide-react';

// --- TYPE DEFINITIONS ---
type NavItem = 'Dashboard' | 'Inventory' | 'Production' | 'Sales' | 'Reports' | 'Customers' | 'Settings';

type ProductionRecord = {
  id: string;
  product: string;
  quantity: number;
  date: string;
  shift: 'Day' | 'Night';
};

type SaleRecord = {
  id: string;
  customer: string;
  product: string;
  quantity: number;
  total: number;
  date: string;
};

type InventoryItem = {
  id: string;
  material: string;
  quantity: number;
  unit: string;
  threshold: number;
};

