  { id: 'INV-001', material: 'Paper Roll (250gsm)', quantity: 50, unit: 'rolls', threshold: 20 },
  { id: 'INV-002', material: 'Paper Roll (300gsm)', quantity: 15, unit: 'rolls', threshold: 20 },
