const salesSummaryData = {
    '8oz Single Wall': 1500,
    '12oz Double Wall': 1250,
    '4oz Espresso': 800,
    '16oz Cold Cup': 600,
};

// --- HELPER COMPONENTS ---

const Card: FC<{ children: ReactNode; className?: string }> = ({ children, className }) => (
  <div className={`bg-white rounded-xl shadow-md p-6 ${className}`}>{children}</div>
);

const StatCard: FC<{ title: string; value: string; icon: ReactNode; a_id: string; }> = ({ title, value, icon, a_id }) => (
  <Card className="flex flex-col" data-testid={a_id}>
    <div className="flex items-center justify-between">
      <p className="text-sm font-medium text-gray-500">{title}</p>
      <div className="text-[#6b8e23]">{icon}</div>
    </div>
    <p className="text-3xl font-bold text-gray-800 mt-2">{value}</p>
  </Card>
);

const PaperCupManagerPage: NextPage = () => {
  const [activeView, setActiveView] = useState<NavItem>('Dashboard');
  const [currentDate, setCurrentDate] = useState('');
  const [productionPage, setProductionPage] = useState(1);

  useEffect(() => {
    setCurrentDate(new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }));
  }, []);

  const navItems: { name: NavItem; icon: ReactNode }[] = [
    { name: 'Dashboard', icon: <LayoutDashboard size={20} /> },
    { name: 'Inventory', icon: <Boxes size={20} /> },
    { name: 'Production', icon: <Factory size={20} /> },
    { name: 'Sales', icon: <ShoppingCart size={20} /> },
    { name: 'Reports', icon: <BarChart3 size={20} /> },
    { name: 'Customers', icon: <Users size={20} /> },
    { name: 'Settings', icon: <Settings size={20} /> },
  ];

  const productionsPerPage = 3;
  const paginatedProductions = mockProductions.slice((productionPage - 1) * productionsPerPage, productionPage * productionsPerPage);
  const totalProductionPages = Math.ceil(mockProductions.length / productionsPerPage);

  const renderContent = () => {
    switch (activeView) {
      case 'Dashboard':
        return (
            <div className="space-y-8">
                <div data-testid="Paper Cup Manufacturing System">
                    <h1 className="text-3xl font-bold text-[#6b8e23]">Paper Cup Manufacturing System</h1>
                    <p className="text-gray-500">{currentDate}</p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                    <StatCard a_id="Raw Materials" title="Raw Materials" value="5 Types" icon={<Package size={24} />} />
                    <StatCard a_id="Finished Products" title="Finished Products" value="4 Types" icon={<PackageCheck size={24} />} />
                    <StatCard a_id="Customers" title="Customers" value="87" icon={<Users2 size={24} />} />
                    <StatCard a_id="Inventory Value" title="Inventory Value" value="$12,450" icon={<DollarSign size={24} />} />
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <Card className="lg:col-span-2" data-testid="Recent Productions">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-xl font-bold text-gray-800">Recent Productions</h2>
                            <button data-testid="Record Production" className="flex items-center gap-2 bg-[#6b8e23] text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-opacity-90 transition-colors">
                                <PlusCircle size={16} />
                                Record Production
                            </button>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-left text-sm">
                                <thead className="text-xs text-gray-500 uppercase bg-gray-50">
                                    <tr>
                                        <th className="px-4 py-3">Product</th>
                                        <th className="px-4 py-3">Quantity</th>
                                        <th className="px-4 py-3">Date</th>
                                        <th className="px-4 py-3">Shift</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {paginatedProductions.map(p => (
                                        <tr key={p.id} className="border-b hover:bg-gray-50">
                                            <td className="px-4 py-3 font-medium text-gray-900">{p.product}</td>
                                            <td className="px-4 py-3">{p.quantity.toLocaleString()}</td>
                                            <td className="px-4 py-3">{p.date}</td>
                                            <td className="px-4 py-3"><span className={`px-2 py-1 rounded-full text-xs font-medium ${p.shift === 'Day' ? 'bg-amber-100 text-amber-800' : 'bg-blue-100 text-blue-800'}`}>{p.shift}</span></td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="flex justify-between items-center mt-4 text-sm">
                            <p className="text-gray-500">Page {productionPage} of {totalProductionPages}</p>
                            <div className="flex gap-2">
