                                <thead className="text-xs text-gray-500 uppercase bg-gray-50">
                                    <tr>
                                        <th className="px-4 py-3">Material</th>
                                        <th className="px-4 py-3">Quantity</th>
                                        <th className="px-4 py-3">Threshold</th>
                                        <th className="px-4 py-3">Status</th>
