                                </div>
                            ))}
                        </div>
                        <div className="border-t mt-4 pt-4 flex justify-between items-center">
                             <span className="font-bold text-gray-800">Total Sales</span>
                             <span className="font-bold text-xl text-[#6b8e23]">$5,150</span>
                        </div>
                    </Card>
                </div>
            </div>
        );
      default:
        return (
            <Card data-testid={`${activeView} Card`}>
                <h1 className="text-2xl font-bold text-[#6b8e23]">{activeView}</h1>
                <p className="text-gray-600 mt-2">This is the {activeView} section. Functionality and detailed components for this view would be built out here.</p>
