                    <p className="text-gray-500">Content for {activeView}</p>
                </div>
            </Card>
        );
    }
  };

  return (
    <div className="flex h-screen bg-[#faf0e6] font-sans">
      <aside className="w-64 bg-white flex flex-col border-r shadow-sm">
        <div className="p-6 flex items-center gap-3">
            <div className="p-2 bg-[#6b8e23] rounded-lg">
                <Factory className="text-white" size={24} />
            </div>
            <h1 className="text-lg font-bold text-gray-800">PaperCup Co.</h1>
        </div>
        <nav className="flex-1 px-4 py-2 space-y-2">
          {navItems.map(item => (
            <button
              key={item.name}
              data-testid={item.name}
              onClick={() => setActiveView(item.name)}
              className={`flex items-center w-full gap-3 px-4 py-2.5 rounded-lg text-sm font-medium text-left transition-colors ${
                activeView === item.name
                  ? 'bg-[#6b8e23] text-white'
                  : 'text-gray-600 hover:bg-gray-100'
              }`}>
              {item.icon}
              {item.name}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t">
            <p className="text-xs text-center text-gray-400">© 2023 PaperCup Manufacturing</p>
        </div>
      </aside>
      <main className="flex-1 p-8 overflow-y-auto">
        {renderContent()}
      </main>
    </div>
  );
};

export default PaperCupManagerPage;


