import { useState, type FC, type ReactNode } from 'react';
import type { NextPage } from 'next';
import { 
    LayoutDashboard, 
    Banknote, 
    BarChart3, 
    FlaskConical, 
    FileText, 
    HandCoins, 
    Stethoscope, 
    Warehouse, 
    Users, 
    Pill, 
    Activity 
} from 'lucide-react';

// --- TYPE DEFINITIONS ---
type View = 'Home' | 'Finances' | 'Reports' | 'Pharmacy' | 'Patient Files' | 'Claim Formulation' | 'Laboratory' | 'Theatre';

type NavItem = {
  name: View;
  icon: FC<any>;
};

type OverviewCardProps = {
  title: string;
  icon: ReactNode;
  data: { label: string; value: string | number }[];
};

// --- MOCK DATA ---
const navItems: NavItem[] = [
  { name: 'Home', icon: LayoutDashboard },
  { name: 'Finances', icon: Banknote },
  { name: 'Reports', icon: BarChart3 },
  { name: 'Pharmacy', icon: Pill },
  { name: 'Patient Files', icon: FileText },
  { name: 'Claim Formulation', icon: HandCoins },
  { name: 'Laboratory', icon: FlaskConical },
  { name: 'Theatre', icon: Stethoscope },
];

// --- UI COMPONENTS ---

const OverviewCard: FC<OverviewCardProps> = ({ title, icon, data }) => (
  <div className="bg-white rounded-2xl shadow-lg p-6 transition-transform transform hover:-translate-y-1">
    <div className="flex items-center justify-between mb-4">
      <h3 className="text-xl font-bold text-gray-700">{title}</h3>
      <div className="bg-rose-100 text-rose-700 p-3 rounded-full">{icon}</div>
    </div>
    <div className="space-y-3">
      {data.map((item) => (
        <div key={item.label} className="flex justify-between items-baseline">
          <p className="text-gray-500">{item.label}</p>
          <p className="text-2xl font-semibold text-gray-800">{item.value}</p>
        </div>
      ))}
    </div>
  </div>
);

const Dashboard: FC = () => (
  <div>
    <h1 className="text-4xl font-bold text-gray-800 mb-8">Dashboard</h1>
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
      <OverviewCard
        title="Patient Overview"
        icon={<Users size={24} />}
        data={[
          { label: 'Total Patients', value: 125 },
          { label: 'Admitted Today', value: 8 },
          { label: 'Discharged Today', value: 5 },
        ]}
      />
      <OverviewCard
        title="Financial Overview"
        icon={<Banknote size={24} />}
        data={[
          { label: 'Today\'s Income', value: '$15,230' },
          { label: 'Today\'s Expenses', value: '$4,120' },
          { label: 'Net Profit', value: '$11,110' },
        ]}
      />
      <OverviewCard
        title="Inventory Overview"
        icon={<Warehouse size={24} />}
        data={[
          { label: 'Medicine Stock', value: '85%' },
          { label: 'Equipment Status', value: '98%' },
          { label: 'Supplies Low', value: 3 },
        ]}
      />
    </div>
     <div className="mt-12 bg-white rounded-2xl shadow-lg p-6">
        <h3 className="text-xl font-bold text-gray-700 mb-4">Daily Activity Report</h3>
        <p className="text-gray-500 mb-4">Submit your daily activity log here.</p>
        <textarea 
            className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-rose-500 focus:border-transparent transition duration-200" 
            rows={4} 
            placeholder="Enter details of your activities today..."
        ></textarea>
        <button className="mt-4 px-6 py-2 bg-rose-700 text-white font-semibold rounded-lg hover:bg-rose-800 transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-rose-500">
            Submit Report
        </button>
    </div>
  </div>
);

const PlaceholderView: FC<{ title: string }> = ({ title }) => (
    <div className="flex flex-col items-center justify-center h-full bg-white/50 rounded-2xl p-8">
        <div className="bg-rose-100 text-rose-700 p-4 rounded-full mb-4">
            <Activity size={40} />
        </div>
        <h1 className="text-3xl font-bold text-gray-700">{title}</h1>
        <p className="text-gray-500 mt-2">This section is under construction.</p>
    </div>
);

const Sidebar: FC<{ activeView: View; setActiveView: (view: View) => void }> = ({ activeView, setActiveView }) => (
  <aside className="w-64 bg-rose-700 text-white flex flex-col p-4 space-y-2">
    <div className="flex items-center gap-3 p-4 mb-4">
        <div className="bg-white p-2 rounded-lg">
            <Stethoscope className="text-rose-700" size={24} />
        </div>
        <h1 className="text-2xl font-bold">HMS</h1>
    </div>
    <nav className="flex flex-col space-y-2">
      {navItems.map((item) => (
        <button
          key={item.name}
          onClick={() => setActiveView(item.name)}
          className={`flex items-center gap-3 px-4 py-3 rounded-lg text-left text-base font-medium transition-colors duration-200 ${ 
            activeView === item.name 
            ? 'bg-rose-800 shadow-inner'
            : 'hover:bg-rose-600/70'
          }`}
        >
          <item.icon size={20} />
          <span>{item.name}</span>
        </button>
      ))}
    </nav>
  </aside>
);

const MainContent: FC<{ activeView: View }> = ({ activeView }) => {
    const renderView = () => {
        switch (activeView) {
            case 'Home':
                return <Dashboard />;
            case 'Finances':
            case 'Reports':
            case 'Pharmacy':
            case 'Patient Files':
            case 'Claim Formulation':
            case 'Laboratory':
            case 'Theatre':
                return <PlaceholderView title={activeView} />;
            default:
                return <Dashboard />;
        }
    };

    return (
        <main className="flex-1 p-8 lg:p-12 bg-orange-100 overflow-y-auto">
            {renderView()}
        </main>
    );
};

const HospitalManagementSystemPage: NextPage = () => {
  const [activeView, setActiveView] = useState<View>('Home');

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <Sidebar activeView={activeView} setActiveView={setActiveView} />
      <MainContent activeView={activeView} />
    </div>
  );
};

export default HospitalManagementSystemPage;


