import { useState, type FC, type ReactNode } from 'react';
import type { NextPage } from 'next';
import { Home, LayoutGrid, FileText, CheckSquare, HelpCircle, BarChart2, Search, Bell, User, Power, Calendar, FileUp, Briefcase, X, ArrowRight } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type NavItem = {
  name: string;
  icon: ReactNode;
};

type StatCardProps = {
  title: string;
  count: number;
  icon: ReactNode;
};

type QuickActionProps = {
  title: string;
  icon: ReactNode;
  onClick?: () => void;
};

// --- UI COMPONENTS ---

const Sidebar: FC<{ activeItem: string; setActiveItem: (item: string) => void }> = ({ activeItem, setActiveItem }) => {
  const navItems: NavItem[] = [
    { name: 'Home', icon: <Home size={20} /> },
    { name: 'Modules', icon: <LayoutGrid size={20} /> },
    { name: 'Applications', icon: <FileText size={20} /> },
    { name: 'Approvals', icon: <CheckSquare size={20} /> },
    { name: 'Queries', icon: <HelpCircle size={20} /> },
    { name: 'Reports', icon: <BarChart2 size={20} /> },
  ];

  return (
    <aside className="w-64 flex-shrink-0 bg-white p-4 border-r border-slate-200">
      <div className="flex items-center gap-2 p-4 mb-4">
        <div className="w-8 h-8 bg-rose-600 rounded-full"></div>
        <span className="font-bold text-lg text-slate-800">E-Gov Office</span>
      </div>
      <nav className="flex flex-col gap-2">
        {navItems.map((item) => (
          <button
            key={item.name}
            onClick={() => setActiveItem(item.name)}
            className={`flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-semibold transition-colors ${
              activeItem === item.name
                ? 'bg-rose-50 text-rose-700'
                : 'text-slate-600 hover:bg-slate-100'
            }`}>
            {item.icon}
            <span>{item.name}</span>
          </button>
        ))}
      </nav>
    </aside>
  );
};

const Header: FC = () => {
  return (
    <header className="flex items-center justify-between pb-6">
      <div className="relative w-full max-w-sm">
        <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
        <input
          type="text"
          placeholder="Search for information..."
          className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-rose-500"
        />
      </div>
      <div className="flex items-center gap-4">
        <button className="p-2 rounded-full hover:bg-slate-100">
          <Bell size={20} className="text-slate-600" />
        </button>
        <div className="flex items-center gap-3">
           <div className="w-10 h-10 rounded-full bg-slate-200 flex items-center justify-center">
              <User size={20} className="text-slate-500" />
            </div>
          <div className="text-right">
            <p className="font-semibold text-slate-800 text-sm">Alex Johnson</p>
            <p className="text-xs text-slate-500">Administrator</p>
          </div>
        </div>
      </div>
    </header>
  );
};

const StatCard: FC<StatCardProps> = ({ title, count, icon }) => (
  <div className="bg-white p-4 rounded-xl border border-slate-200 flex items-center gap-4">
    <div className="p-3 bg-rose-50 rounded-lg text-rose-600">{icon}</div>
    <div>
      <p className="text-slate-500 text-sm">{title}</p>
      <p className="font-bold text-2xl text-slate-800">{count}</p>
    </div>
  </div>
);

const LeaveRequestModal: FC<{ isOpen: boolean; onClose: () => void; onSubmit: (name: string, reason: string) => void }> = ({ isOpen, onClose, onSubmit }) => {
  const [name, setName] = useState('Alex Johnson');
  const [reason, setReason] = useState('');

  if (!isOpen) return null;

  const handleSubmit = () => {
    onSubmit(name, reason);
    setName('Alex Johnson');
    setReason('');
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl p-8 shadow-2xl w-full max-w-md relative animate-in fade-in-90 zoom-in-95">
        <button onClick={onClose} className="absolute top-4 right-4 p-2 rounded-full hover:bg-slate-100">
          <X size={20} className="text-slate-500" />
        </button>
        <h2 className="text-xl font-bold text-slate-800 mb-2">Submit Leave Application</h2>
        <p className="text-slate-500 mb-6">Please fill out the details for your leave request.</p>
        <div className="space-y-4">
          <div>
            <label htmlFor="name" className="block text-sm font-medium text-slate-700 mb-1">Name</label>
            <input
              type="text"
              id="name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-rose-500"
            />
          </div>
          <div>
            <label htmlFor="reason" className="block text-sm font-medium text-slate-700 mb-1">Reason</label>
            <textarea
              id="reason"
              rows={4}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="e.g., Family emergency, personal matter..."
              className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-rose-500"
            />
          </div>
        </div>
        <button
          onClick={handleSubmit}
          className="w-full mt-6 bg-rose-600 text-white font-semibold py-3 rounded-lg hover:bg-rose-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-rose-500 transition-colors flex items-center justify-center gap-2"
        >
          Submit Application <ArrowRight size={16} />
        </button>
      </div>
    </div>
  );
};

const EGovernmentDashboard: NextPage = () => {
  const [activeItem, setActiveItem] = useState('Home');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const quickActions: QuickActionProps[] = [
    { title: 'Submit Leave Request', icon: <FileUp size={24} />, onClick: () => setIsModalOpen(true) },
    { title: 'Cadre Leaving Request', icon: <Briefcase size={24} /> },
    { title: 'Submit Attendance', icon: <Calendar size={24} /> },
    { title: 'Submit Power Request', icon: <Power size={24} /> },
  ];

  const statistics: StatCardProps[] = [
    { title: 'Leave Requests', count: 0, icon: <FileUp size={22} /> },
    { title: 'Cadre Leaving Requests', count: 0, icon: <Briefcase size={22} /> },
    { title: 'Attendance Records', count: 0, icon: <Calendar size={22} /> },
    { title: 'Power Requests', count: 0, icon: <Power size={22} /> },
  ];

  const handleLeaveSubmit = (name: string, reason: string) => {
    console.log('Leave Request Submitted:', { name, reason });
    // Here you would typically send data to an API
    setIsModalOpen(false);
  };

  return (
    <div className="flex min-h-screen bg-pink-50 text-slate-800">
      <Sidebar activeItem={activeItem} setActiveItem={setActiveItem} />
      <main className="flex-grow p-8">
        <Header />
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-8">
            {/* Quick Actions */}
            <section>
              <h2 className="text-xl font-bold mb-4">Quick Actions</h2>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {quickActions.map((action) => (
                  <button
                    key={action.title}
                    onClick={action.onClick}
                    className="bg-white p-4 rounded-xl border border-slate-200 text-center hover:shadow-lg hover:-translate-y-1 transition-all duration-300 group"
                  >
                    <div className="mx-auto w-fit p-3 bg-rose-50 text-rose-600 rounded-full group-hover:bg-rose-600 group-hover:text-white transition-colors">
                      {action.icon}
                    </div>
                    <p className="mt-3 text-sm font-semibold text-slate-700">{action.title}</p>
                  </button>
                ))}
              </div>
            </section>

            {/* Recent Activity */}
            <section>
                <h2 className="text-xl font-bold mb-4">Recent Activity</h2>
                <div className="bg-white p-6 rounded-xl border border-slate-200 space-y-4">
                     {/* Required Card: "3 Alex Johnson" */}
                    <div className="flex items-center justify-between p-3 rounded-lg hover:bg-slate-50">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-slate-200 border-2 border-dashed rounded-xl flex items-center justify-center font-bold text-slate-500">3</div>
                            <div>
                                <p className="font-semibold text-slate-800">Alex Johnson</p>
                                <p className="text-sm text-slate-500">Updated profile information</p>
                            </div>
                        </div>
                        <p className="text-sm text-slate-400">2h ago</p>
                    </div>
                    <div className="text-center py-10">
                        <p className="text-slate-500">No other recent activity.</p>
                    </div>
                </div>
            </section>
          </div>

          {/* Statistics */}
          <aside className="lg:col-span-1 space-y-8">
             <section>
              <h2 className="text-xl font-bold mb-4">Statistics</h2>
              <div className="space-y-4">
                {statistics.map((stat) => (
                  <StatCard key={stat.title} {...stat} />
                ))}
              </div>
            </section>
          </aside>
        </div>
      </main>
      <LeaveRequestModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSubmit={handleLeaveSubmit} />
    </div>
  );
};

export default EGovernmentDashboard;


