import { useState, FC, SVGProps, useEffect, useRef } from 'react';
import type { NextPage } from 'next';
import Head from 'next/head';
import { Search, Bell, User, Settings, LogIn, LogOut, ChevronDown, Building, Briefcase, BarChart2, CheckCircle, XCircle, Clock } from 'lucide-react';

// Type definition for SVG icons
type Icon = (props: SVGProps<SVGSVGElement>) => JSX.Element;

// --- Reusable UI Components --- //

interface SidebarItemProps {
  IconComponent: Icon;
  text: string;
  active?: boolean;
}

const SidebarItem: FC<SidebarItemProps> = ({ IconComponent, text, active }) => (
  <a
    href="#"
    className={`flex items-center p-3 rounded-lg transition-colors text-gray-700 ${ 
      active 
        ? 'bg-orange-100 text-orange-600 font-semibold'
        : 'hover:bg-orange-100/50'
    }`}
  >
    <IconComponent className="w-5 h-5 mr-3" />
    <span>{text}</span>
  </a>
);

interface StatCardProps {
    IconComponent: Icon;
    title: string;
    value: string;
    color: string;
}

const StatCard: FC<StatCardProps> = ({ IconComponent, title, value, color }) => (
    <div className="bg-white p-6 rounded-xl border border-gray-200/80 shadow-sm flex items-center gap-4">
        <div className={`p-3 rounded-full ${color}`}>
            <IconComponent className="w-6 h-6 text-white" />
        </div>
        <div>
            <p className="text-sm text-gray-500">{title}</p>
            <p className="text-2xl font-bold text-gray-800">{value}</p>
        </div>
    </div>
);

// --- Main Page Component --- //

const AttendanceTrackerPage: NextPage = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const profileMenuRef = useRef<HTMLDivElement>(null);

  const handleLoginToggle = () => {
    setIsLoggedIn(!isLoggedIn);
    setIsProfileOpen(false);
  };

  // Close profile dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);


  return (
    <>
      <Head>
        <title>Attendance Tracker</title>
        <meta name="description" content="Attendance Tracker System Dashboard" />
        <link rel="icon" href="/favicon.ico" />
      </Head>

      <div className="bg-orange-50 min-h-screen flex text-gray-800">
        {/* --- Sidebar --- */}
        <aside className="w-64 bg-white border-r border-gray-200/80 p-6 flex-col hidden md:flex">
          <div className="flex items-center gap-3 mb-10">
            <Building className="h-8 w-8 text-orange-500" />
            <h1 className="text-xl font-bold text-gray-800">Attendance Inc.</h1>
          </div>

          <div className="flex flex-col items-center mb-10 text-center">
            <div className="w-24 h-24 rounded-full bg-gray-200 border-4 border-white shadow-md mb-3 flex items-center justify-center">
                <User className="w-12 h-12 text-gray-400" />
            </div>
            <h2 className="font-bold text-lg">{isLoggedIn ? 'Emily Carter' : 'Guest'}</h2>
            <p className="text-sm text-gray-500">{isLoggedIn ? 'Frontend Developer' : 'No role'}</p>
          </div>

          <nav className="flex-grow flex flex-col gap-2">
            <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider px-3 mb-2">Menu</p>
            <SidebarItem IconComponent={Briefcase} text="My Profile" />
            <SidebarItem IconComponent={Settings} text="Settings" />
          </nav>

          <div className="mt-auto">
             <button
                onClick={handleLoginToggle}
                className="w-full flex items-center justify-center gap-2 bg-orange-500 text-white font-bold py-3 px-4 rounded-lg hover:bg-orange-600 transition-all duration-300 shadow-lg shadow-orange-500/20 focus:outline-none focus:ring-4 focus:ring-orange-300"
              >
                {isLoggedIn ? <LogOut size={18} /> : <LogIn size={18} />}
                <span>{isLoggedIn ? 'Logout' : 'Login'}</span>
              </button>
          </div>
        </aside>

        {/* --- Main Content --- */}
        <div className="flex-1 flex flex-col">
          {/* --- Header --- */}
          <header className="bg-white/80 backdrop-blur-sm border-b border-gray-200/80 p-4 flex items-center justify-between sticky top-0 z-10">
            <div className="flex items-center gap-4">
                <div className="relative w-full max-w-xs">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <input 
                        type="text"
                        placeholder="Search..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="bg-gray-100/70 border border-transparent focus:bg-white focus:border-orange-300 focus:ring-2 focus:ring-orange-200 w-full pl-10 pr-4 py-2 rounded-lg text-sm outline-none transition-all"
                    />
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button className="p-2 rounded-full hover:bg-orange-100/50 text-gray-500 hover:text-orange-500 transition-colors">
                    <Bell className="h-6 w-6" />
                </button>

                <div className="relative" ref={profileMenuRef}>
                    <button onClick={() => setIsProfileOpen(!isProfileOpen)} className="flex items-center gap-2">
                        <div className="w-10 h-10 rounded-full bg-gray-200 border-2 border-dashed flex items-center justify-center">
                             <User className="w-5 h-5 text-gray-400" />
                        </div>
                        <ChevronDown className={`h-4 w-4 text-gray-500 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
                    </button>
                    {isProfileOpen && (
                        <div className="absolute right-0 mt-2 w-48 bg-white rounded-xl shadow-lg border border-gray-200/80 py-2 z-20 animate-fade-in-down">
                            <a href="#" className="block px-4 py-2 text-sm text-gray-700 hover:bg-orange-100/50">My Profile</a>
                            <a href="#" className="block px-4 py-2 text-sm text-gray-700 hover:bg-orange-100/50">Settings</a>
                            <div className="my-2 h-px bg-gray-200/80"></div>
                            <button onClick={handleLoginToggle} className="w-full text-left px-4 py-2 text-sm text-red-500 hover:bg-red-50 flex items-center gap-2">
                                {isLoggedIn ? <LogOut size={16} /> : <LogIn size={16} />}
                                {isLoggedIn ? 'Logout' : 'Login'}
                            </button>
                        </div>
                    )}
                </div>
            </div>
          </header>

          <main className="flex-1 p-6 lg:p-8">
            {isLoggedIn ? (
                // --- Logged-In View --- //
                <div className="space-y-8">
                    <div>
                        <h1 className="text-3xl font-bold text-gray-800">Welcome back, Emily!</h1>
                        <p className="text-gray-500 mt-1">Here is your attendance summary for this month.</p>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                        <StatCard IconComponent={CheckCircle} title="Days Present" value="21" color="bg-green-500" />
                        <StatCard IconComponent={XCircle} title="Days Absent" value="1" color="bg-red-500" />
                        <StatCard IconComponent={Clock} title="Late Arrivals" value="3" color="bg-yellow-500" />
                    </div>

                    <div className="bg-white p-6 rounded-xl border border-gray-200/80 shadow-sm">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold">Recent Activity</h3>
                            <a href="#" className="text-sm font-semibold text-orange-500 hover:underline">View All</a>
                        </div>
                        {/* Placeholder for recent activity list */}
                        <div className="space-y-4">
                           <div className="flex items-center p-3 bg-green-50 rounded-lg"><CheckCircle className="w-5 h-5 text-green-500 mr-3"/><div><p className="font-medium">Clocked In</p><p className="text-sm text-gray-500">Today at 8:58 AM</p></div></div>
                           <div className="flex items-center p-3 bg-red-50 rounded-lg"><LogOut className="w-5 h-5 text-red-500 mr-3"/><div><p className="font-medium">Clocked Out</p><p className="text-sm text-gray-500">Yesterday at 5:31 PM</p></div></div>
                        </div>
                    </div>
                </div>
            ) : (
                // --- Guest View (Login Prompt) --- //
                <div className="h-full flex items-center justify-center">
                    <div className="text-center bg-white p-12 rounded-2xl shadow-sm border border-gray-200/80 max-w-md mx-auto">
                        <BarChart2 className="mx-auto h-16 w-16 text-orange-400 mb-6" />
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">Welcome to the Attendance Tracker</h2>
                        <p className="text-gray-500 mb-8">Please log in to access your dashboard and manage your attendance records.</p>
                        <button
                            onClick={handleLoginToggle}
                            className="w-full sm:w-auto flex items-center justify-center gap-2 bg-orange-500 text-white font-bold py-3 px-8 rounded-lg hover:bg-orange-600 transition-all duration-300 shadow-lg shadow-orange-500/20 focus:outline-none focus:ring-4 focus:ring-orange-300"
                        >
                            <LogIn size={18} />
                            <span>Login to Continue</span>
                        </button>
                    </div>
                </div>
            )}
          </main>

          {/* --- Footer --- */}
          <footer className="p-4 text-center text-sm text-gray-500">
            <p>&copy; {new Date().getFullYear()} Attendance Inc. All rights reserved.</p>
          </footer>
        </div>
      </div>
      <style jsx global>{`
        @keyframes fade-in-down {
          0% {
            opacity: 0;
            transform: translateY(-10px);
          }
          100% {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .animate-fade-in-down {
          animation: fade-in-down 0.2s ease-out;
        }
      `}</style>
    </>
  );
};

export default AttendanceTrackerPage;


