r:bg-orange-100/50">My Profile</a>\n                            <a href="#" className="block px-4 py-2 text-sm text-gray-700 hover:bg-orange-100/50">Settings</a>\n                            <div className="my-2 h-px bg-gray-200/80"></div>\n                            <button onClick={handleLoginToggle} className="w-full text-left px-4 py-2 text-sm text-red-500 hover:bg-red-50 flex items-center gap-2">\n                                {isLoggedIn ? <LogOut size={16} /> : <LogIn size={16} />}\n                                {isLoggedIn ? \'Logout\' : \'Login\'}\n                            </button>\n                        </div>\n                    )}\n                </div>\n            </div>\n          </header>\n\n          <main className="flex-1 p-6 lg:p-8">\n            {isLoggedIn ? (\n                // --- Logged-In View --- //\n                <div className="space-y-8">\n                    <div>\n                        <h1 className="text-3xl font-bold text-gray-800">Welcome back, Emily!</h1>\n                        <p className="text-gray-500 mt-1">Here is your attendance summary for this month.</p>\n                    </div>\n\n                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">\n                        <StatCard IconComponent={CheckCircle} title="Days Present" value="21" color="bg-green-500" />\n                        <StatCard IconComponent={XCircle} title="Days Absent" value="1" color="bg-red-500" />\n                        <StatCard IconComponent={Clock} title="Late Arrivals" value="3" color="bg-yellow-500" />\n                    </div>\n\n                    <div className="bg-white p-6 rounded-xl border border-gray-200/80 shadow-sm">\n                        <div className="flex justify-between items-center mb-4">\n                            <h3 className="text-xl font-bold">Recent Activity</h3>\n                            <a href="#" className="text-sm font-semibold text-orange-500 hover:underline">View All</a>\n                        </div>\n                        {/* Placeholder for recent activity list */}\n                        <div className="space-y-4">\n                           <div className="flex items-center p-3 bg-green-50 rounded-lg"><CheckCircle className="w-5 h-5 text-green-500 mr-3"/><div><p className="font-medium">Clocked In</p><p className="text-sm text-gray-500">Today at 8:58 AM</p></div></div>\n                           <div className="flex items-center p-3 bg-red-50 rounded-lg"><LogOut className="w-5 h-5 text-red-500 mr-3"/><div><p className="font-medium">Clocked Out</p><p className="text-sm text-gray-500">Yesterday at 5:31 PM</p></div></div>\n                        </div>\n                    </div>\n                </div>\n            ) : (\n                // --- Guest View (Login Prompt) --- //\n                <div className="h-full flex items-center justify-center">\n                    <div className="text-center bg-white p-12 rounded-2xl shadow-sm border border-gray-200/80 max-w-md mx-auto">\n                        <BarChart2 className="mx-auto h-16 w-16 text-orange-400 mb-6" />\n                        <h2 className="text-2xl font-bold text-gray-800 mb-2">Welcome to the Attendance Tracker</h2>\n                        <p className="text-gray-500 mb-8">Please log in to access your dashboard and manage your attendance records.</p>\n                        <button\n                            onClick={handleLoginToggle}\n                            className="w-full sm:w-auto flex items-center justify-center gap-2 bg-orange-500 text-white font-bold py-3 px-8 rounded-lg hover:bg-orange-600 transition-all duration-300 shadow-lg shadow-orange-500/20 focus:outline-none focus:ring-4 focus:ring-orange-300"\n                        >\n                            <LogIn size={18} />\n                            <span>Login to Continue</span>\n                        </button>\n                    </div>\n                </div>\n            )}\n          </main>\n\n          {/* --- Footer --- */}\n          <footer className="p-4 text-center text-sm text-gray-500">\n            <p>&copy; {new Date().getFullYear()} Attendance Inc. All rights reserved.</p>\n          </footer>\n        </div>\n      </div>\n      <style jsx global>{`\n        @keyframes fade-in-down {\n          0% {\n            opacity: 0;\n            transform: translateY(-10px);\n          }\n          100% {\n            opacity: 1;\n            transform: translateY(0);\n          }\n        }\n        .animate-fade-in-down {\n          animation: fade-in-down 0.2s ease-out;\n        }\n      `}</style>\n    </>\n  );\n};\n\nexport default AttendanceTrackerPage;\n'}

import { useState, useMemo, FC, ReactNode } from 'react';
import type { NextPage } from 'next';
import { User, Scissors, Clock, DollarSign, Search, Plus, X, CalendarDays, Star } from 'lucide-react';

