// --- SNOWFALL BACKGROUND COMPONENT ---
const Snowfall: FC = () => {
  const snowflakes = useMemo(() => Array.from({ length: 50 }).map((_, i) => ({
    id: i,
    left: `${Math.random() * 100}%`,
    animationDuration: `${Math.random() * 10 + 5}s`, // 5 to 15 seconds
    animationDelay: `${Math.random() * 5}s`,
    opacity: Math.random() * 0.5 + 0.3, // 0.3 to 0.8
    fontSize: `${Math.random() * 8 + 6}px`, // 6px to 14px
  })), []);

  return (
    <>
      <style>
        {`
          @keyframes fall {
            0% { transform: translateY(-10vh); }
            100% { transform: translateY(110vh); }
          }
          .snowflake {
            position: fixed;
            top: 0;
            color: #cbd5e1;
            border-radius: 50%;
            pointer-events: none;
            animation-name: fall;
            animation-timing-function: linear;
            animation-iteration-count: infinite;
          }
        `}
      </style>
      <div className="fixed top-0 left-0 w-full h-full -z-10 overflow-hidden">
        {snowflakes.map(flake => (
          <div
            key={flake.id}
            className="snowflake"
            style={{
              left: flake.left,
              animationDuration: flake.animationDuration,
              animationDelay: flake.animationDelay,
              opacity: flake.opacity,
              fontSize: flake.fontSize,
            }}
          >
            ❄︎
          </div>
        ))}
      </div>
    </>
  );
};

// --- MODAL COMPONENT ---
const Modal: FC<{ isOpen: boolean; onClose: () => void; title: string; children: ReactNode }> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 relative" onClick={e => e.stopPropagation()}>
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-2xl font-bold text-slate-800 font-serif">{title}</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X size={24} />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
};

// --- MAIN PAGE COMPONENT ---
const BarberShopManagerPage: NextPage = () => {
  const [barbers, setBarbers] = useState<Barber[]>(initialBarbers);
  const [services, setServices] = useState<Service[]>(initialServices);

  const [barberSearch, setBarberSearch] = useState('');
  const [serviceSearch, setServiceSearch] = useState('');

  const [isAddBarberModalOpen, setAddBarberModalOpen] = useState(false);
  const [isAddServiceModalOpen, setAddServiceModalOpen] = useState(false);

  const [newBarberName, setNewBarberName] = useState('');
  const [newBarberSpecialty, setNewBarberSpecialty] = useState('');

  const [newServiceName, setNewServiceName] = useState('');
  const [newServiceDuration, setNewServiceDuration] = useState('');
  const [newServicePrice, setNewServicePrice] = useState('');

  const filteredBarbers = barbers.filter(b => 
    b.name.toLowerCase().includes(barberSearch.toLowerCase()) || 
    b.specialty.toLowerCase().includes(barberSearch.toLowerCase())
  );

  const filteredServices = services.filter(s => 
    s.name.toLowerCase().includes(serviceSearch.toLowerCase())
  );

  const handleAddBarber = (e: React.FormEvent) => {
    e.preventDefault();
    if (newBarberName && newBarberSpecialty) {
      const newBarber: Barber = {
        id: Date.now(),
        name: newBarberName,
        specialty: newBarberSpecialty,
        rating: 4.5, // Default rating
        availableSlots: ['10:00 AM', '11:00 AM', '1:00 PM', '2:00 PM'], // Default slots
        avatar: <div className="bg-gray-200 border-2 border-dashed rounded-full w-16 h-16" />
      };
      setBarbers([...barbers, newBarber]);
      setNewBarberName('');
      setNewBarberSpecialty('');
      setAddBarberModalOpen(false);
    }
  };

  const handleAddService = (e: React.FormEvent) => {
    e.preventDefault();
    if (newServiceName && newServiceDuration && newServicePrice) {
      const newService: Service = {
        id: Date.now(),
        name: newServiceName,
        duration: parseInt(newServiceDuration, 10),
        price: parseFloat(newServicePrice),
      };
      setServices([...services, newService]);
      setNewServiceName('');
      setNewServiceDuration('');
      setNewServicePrice('');
      setAddServiceModalOpen(false);
    }
  };

  return (
    <>
      <Snowfall />
      <main className="min-h-screen bg-beige-100/50 font-sans text-slate-800 p-4 sm:p-6 lg:p-8">
        <div className="max-w-screen-xl mx-auto">
          <header className="mb-8 text-center">
            <h1 className="text-4xl md:text-5xl font-bold font-serif text-slate-900">BarberShop Manager Pro</h1>
            <p className="text-slate-600 mt-2">Efficiently manage your barbers, services, and appointments.</p>
          </header>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* --- Barbers & Services Column --- */}
            <div className="lg:col-span-2 space-y-8">
              {/* Our Barbers Section */}
              <section>
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-4">
                  <h2 className="text-3xl font-bold font-serif text-slate-800">Our Barbers</h2>
                  <div className="flex items-center gap-2 w-full sm:w-auto">
                    <div className="relative w-full sm:w-48">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input type="text" placeholder="Search barbers..." value={barberSearch} onChange={e => setBarberSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-slate-400 focus:outline-none" />
                    </div>
                    <button onClick={() => setAddBarberModalOpen(true)} className="flex-shrink-0 bg-slate-800 text-white px-4 py-2 rounded-lg hover:bg-slate-700 transition-colors flex items-center gap-2">
                      <Plus size={18} />
                      <span className='hidden sm:inline'>Add Barber</span>
                    </button>
                  </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {filteredBarbers.map(barber => (
                    <div key={barber.id} className="bg-white rounded-2xl shadow-md p-5 border border-slate-100 hover:shadow-lg transition-shadow">
                      <div className="flex items-center gap-4 mb-4">
                        {barber.avatar}
                        <div>
                          <h3 className="font-bold text-lg text-slate-900">{barber.name}</h3>
                          <p className="text-sm text-slate-500 flex items-center gap-1.5"><User size={14} /> {barber.specialty}</p>
                          <div className="flex items-center gap-1 text-amber-500 mt-1">
                             <Star size={16} className="fill-current"/> <span className="font-bold text-slate-700 text-sm">{barber.rating}</span>
                          </div>
                        </div>
                      </div>
                      <div className="mb-4">
                        <h4 className="text-xs font-semibold text-slate-400 uppercase mb-2">Available Times</h4>
                        <div className="flex flex-wrap gap-2">
                          {barber.availableSlots.map(slot => (
                            <span key={slot} className="text-xs bg-slate-100 text-slate-700 font-medium px-2.5 py-1 rounded-full">{slot}</span>
                          ))}
                        </div>
                      </div>
                      <button className="w-full bg-slate-800 text-white font-semibold py-2.5 rounded-lg hover:bg-slate-700 transition-colors">Book Appointment</button>
                    </div>
                  ))}
                </div>
              </section>

              {/* Our Services Section */}
              <section>
                 <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-4">
                  <h2 className="text-3xl font-bold font-serif text-slate-800">Our Services</h2>
                  <div className="flex items-center gap-2 w-full sm:w-auto">
                    <div className="relative w-full sm:w-48">
                      <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input type="text" placeholder="Search services..." value={serviceSearch} onChange={e => setServiceSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg focus:ring-2 focus:ring-slate-400 focus:outline-none" />
                    </div>
                    <button onClick={() => setAddServiceModalOpen(true)} className="flex-shrink-0 bg-slate-800 text-white px-4 py-2 rounded-lg hover:bg-slate-700 transition-colors flex items-center gap-2">
                      <Plus size={18} />
                      <span className='hidden sm:inline'>Add Service</span>
                    </button>
                  </div>
                </div>
                <div className="bg-white rounded-2xl shadow-md border border-slate-100 divide-y divide-slate-200">
                  {filteredServices.map(service => (
                    <div key={service.id} className="p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 hover:bg-slate-50/50 transition-colors">
                      <div>
                        <h3 className="font-bold text-slate-900">{service.name}</h3>
                        <div className="flex items-center gap-4 text-sm text-slate-500 mt-1">
                          <span className="flex items-center gap-1.5"><Clock size={14} /> {service.duration} min</span>
                          <span className="flex items-center gap-1.5"><DollarSign size={14} /> {service.price.toFixed(2)}</span>
                        </div>
                      </div>
                      <button className="w-full sm:w-auto flex-shrink-0 bg-slate-200 text-slate-800 font-semibold px-4 py-2 rounded-lg hover:bg-slate-300 transition-colors">Book Service</button>
                    </div>
                  ))}
                </div>
              </section>
            </div>

            {/* --- Appointments Column --- */}
            <div className="lg:col-span-1">
              <section className="sticky top-8">
                <h2 className="text-3xl font-bold font-serif text-slate-800 mb-4">Appointments</h2>
                <div className="bg-white rounded-2xl shadow-md p-6 border border-slate-100 text-center">
                  <CalendarDays className="mx-auto text-slate-300" size={48} />
                  <h3 className="font-bold text-lg mt-4 text-slate-800">No appointments scheduled</h3>
                  <p className="text-slate-500 text-sm mt-1">Your upcoming appointments will appear here.</p>
                </div>
              </section>
            </div>
          </div>
        </div>

        {/* --- Modals --- */}
        <Modal isOpen={isAddBarberModalOpen} onClose={() => setAddBarberModalOpen(false)} title="Add New Barber">
          <form onSubmit={handleAddBarber} className="space-y-4">
            <div>
              <label htmlFor="barberName" className="block text-sm font-medium text-slate-700 mb-1">Barber Name</label>
              <input type="text" id="barberName" value={newBarberName} onChange={e => setNewBarberName(e.target.value)} placeholder="e.g., John Doe" required className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-400 focus:outline-none" />
            </div>
            <div>
              <label htmlFor="barberSpecialty" className="block text-sm font-medium text-slate-700 mb-1">Barber Specialty</label>
              <input type="text" id="barberSpecialty" value={newBarberSpecialty} onChange={e => setNewBarberSpecialty(e.target.value)} placeholder="e.g., Master of Fades" required className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-400 focus:outline-none" />
            </div>
            <div className="flex justify-end gap-3 pt-4">
              <button type="button" onClick={() => setAddBarberModalOpen(false)} className="px-4 py-2 bg-slate-200 text-slate-800 font-semibold rounded-lg hover:bg-slate-300">Cancel</button>
              <button type="submit" className="px-4 py-2 bg-slate-800 text-white font-semibold rounded-lg hover:bg-slate-700">Add Barber</button>
            </div>
          </form>
        </Modal>

        <Modal isOpen={isAddServiceModalOpen} onClose={() => setAddServiceModalOpen(false)} title="Add New Service">
          <form onSubmit={handleAddService} className="space-y-4">
            <div>
              <label htmlFor="serviceName" className="block text-sm font-medium text-slate-700 mb-1">Service Name</label>
              <input type="text" id="serviceName" value={newServiceName} onChange={e => setNewServiceName(e.target.value)} placeholder="e.g., Buzz Cut" required className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-400 focus:outline-none" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="serviceDuration" className="block text-sm font-medium text-slate-700 mb-1">Duration (min)</label>
                <input type="number" id="serviceDuration" value={newServiceDuration} onChange={e => setNewServiceDuration(e.target.value)} placeholder="e.g., 30" required className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-400 focus:outline-none" />
              </div>
              <div>
                <label htmlFor="servicePrice" className="block text-sm font-medium text-slate-700 mb-1">Price ($)</label>
                <input type="number" id="servicePrice" value={newServicePrice} onChange={e => setNewServicePrice(e.target.value)} placeholder="e.g., 25.00" step="0.01" required className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-400 focus:outline-none" />
              </div>
            </div>
            <div className="flex justify-end gap-3 pt-4">
              <button type="button" onClick={() => setAddServiceModalOpen(false)} className="px-4 py-2 bg-slate-200 text-slate-800 font-semibold rounded-lg hover:bg-slate-300">Cancel</button>
              <button type="submit" className="px-4 py-2 bg-slate-800 text-white font-semibold rounded-lg hover:bg-slate-700">Add Service</button>
            </div>
          </form>
        </Modal>
      </main>
    </>
  );
};

