import { useState, useEffect, FC, ReactNode } from 'react';
import type { NextPage } from 'next';
import Head from 'next/head';
import { Search, MapPin, Briefcase, ChevronDown, Phone, Building, Star, Filter, Calendar, DollarSign } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type WorkerProfile = {
  id: number;
  name: string;
  trade: string;
  category: string;
  jobType: 'Full-time' | 'Part-time' | 'Contract';
  location: string;
  experience: number; // years
  pay: number; // per hour
  joinedDate: string;
  avatar: string;
};

// --- MOCK DATA ---
const initialWorkers: WorkerProfile[] = [
  { id: 1, name: 'John Doe', trade: 'Electrician', category: 'Construction', jobType: 'Full-time', location: 'New York, NY', experience: 10, pay: 55, joinedDate: '2024-07-15', avatar: '' },
  { id: 2, name: 'Jane Smith', trade: 'Plumber', category: 'Maintenance', jobType: 'Contract', location: 'Los Angeles, CA', experience: 8, pay: 60, joinedDate: '2024-07-10', avatar: '' },
  { id: 3, name: 'Mike Johnson', trade: 'Carpenter', category: 'Construction', jobType: 'Part-time', location: 'Chicago, IL', experience: 15, pay: 50, joinedDate: '2024-06-28', avatar: '' },
  { id: 4, name: 'Emily Davis', trade: 'Welder', category: 'Manufacturing', jobType: 'Full-time', location: 'Houston, TX', experience: 5, pay: 45, joinedDate: '2024-07-20', avatar: '' },
  { id: 5, name: 'Chris Lee', trade: 'HVAC Technician', category: 'Maintenance', jobType: 'Full-time', location: 'Phoenix, AZ', experience: 7, pay: 52, joinedDate: '2024-05-12', avatar: '' },
  { id: 6, name: 'Patricia Garcia', trade: 'Mechanic', category: 'Automotive', jobType: 'Contract', location: 'Philadelphia, PA', experience: 12, pay: 48, joinedDate: '2024-07-01', avatar: '' },
  { id: 7, name: 'David Martinez', trade: 'Roofer', category: 'Construction', jobType: 'Part-time', location: 'San Antonio, TX', experience: 6, pay: 40, joinedDate: '2024-07-18', avatar: '' },
];

const jobCategories = ['All Categories', 'Construction', 'Maintenance', 'Manufacturing', 'Automotive', 'Logistics'];
const jobTypes = ['All Job Types', 'Full-time', 'Part-time', 'Contract'];

// --- UI HELPER COMPONENTS ---
const Card: FC<{ children: ReactNode; className?: string }> = ({ children, className }) => (
  <div className={`bg-white border border-stone-200 rounded-xl shadow-sm ${className}`}>
    {children}
  </div>
);

const BlueCollarConnectPage: NextPage = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [category, setCategory] = useState('All Categories');
  const [jobType, setJobType] = useState('All Job Types');
  const [sort, setSort] = useState<'Newest' | 'Highest Pay'>('Newest');
  const [filteredWorkers, setFilteredWorkers] = useState<WorkerProfile[]>(initialWorkers);

  useEffect(() => {
    let workers = [...initialWorkers];

    // Filter
    workers = workers.filter(worker => {
      const matchesQuery = worker.name.toLowerCase().includes(searchQuery.toLowerCase()) || worker.trade.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesCategory = category === 'All Categories' || worker.category === category;
      const matchesJobType = jobType === 'All Job Types' || worker.jobType === jobType;
      return matchesQuery && matchesCategory && matchesJobType;
    });

    // Sort
    if (sort === 'Newest') {
      workers.sort((a, b) => new Date(b.joinedDate).getTime() - new Date(a.joinedDate).getTime());
    } else if (sort === 'Highest Pay') {
      workers.sort((a, b) => b.pay - a.pay);
    }

    setFilteredWorkers(workers);
  }, [searchQuery, category, jobType, sort]);

  const renderWorkerCard = (worker: WorkerProfile) => (
    <Card key={worker.id} className="p-6 hover:shadow-lg transition-shadow duration-300">
      <div className="flex items-start space-x-4">
        <div className="bg-stone-200 border-2 border-dashed rounded-xl w-16 h-16 flex-shrink-0" />
        <div className="flex-grow">
          <div className="flex justify-between items-start">
            <div>
              <h3 className="text-lg font-bold text-stone-800">{worker.name}</h3>
              <p className="text-emerald-700 font-semibold">{worker.trade}</p>
            </div>
            <span className="text-xl font-bold text-emerald-700">${worker.pay}/hr</span>
          </div>
          <div className="flex items-center text-stone-500 text-sm mt-2 space-x-4">
            <div className="flex items-center"><MapPin className="w-4 h-4 mr-1.5" /> {worker.location}</div>
            <div className="flex items-center"><Briefcase className="w-4 h-4 mr-1.5" /> {worker.experience} years exp.</div>
            <div className="flex items-center"><Building className="w-4 h-4 mr-1.5" /> {worker.jobType}</div>
          </div>
        </div>
      </div>
    </Card>
  );

  const CustomSelect: FC<{ value: string; onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void; options: string[]; icon: ReactNode }> = ({ value, onChange, options, icon }) => (
    <div className="relative w-full">
      <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-stone-400">
        {icon}
      </div>
      <select
        value={value}
        onChange={onChange}
        className="w-full pl-10 pr-10 py-2.5 border border-stone-300 rounded-lg bg-white appearance-none focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition"
      >
        {options.map(opt => <option key={opt}>{opt}</option>)}
      </select>
      <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none text-stone-400">
        <ChevronDown className="w-5 h-5" />
      </div>
    </div>
  );

  return (
    <>
      <Head>
        <title>Blue-Collar Connect</title>
        <meta name="description" content="Connect with skilled blue-collar workers and find job opportunities." />
        <link rel="icon" href="/favicon.ico" />
      </Head>

      <div className="min-h-screen bg-stone-50 font-sans text-stone-800">
        {/* Header */}
        <header className="bg-white/80 backdrop-blur-sm sticky top-0 z-40 border-b border-stone-200">
          <nav className="container mx-auto px-6 py-4 flex justify-between items-center">
            <h1 className="text-2xl font-bold text-emerald-700">BLUE-COLLAR CONNECT</h1>
            <div className="hidden md:flex items-center space-x-8 font-medium text-stone-600">
              <a href="#" className="hover:text-emerald-700 transition-colors">Jobs</a>
              <a href="#" className="hover:text-emerald-700 transition-colors">Post a Job</a>
              <a href="#" className="hover:text-emerald-700 transition-colors">About Us</a>
            </div>
            <div className="flex items-center space-x-4">
                <button className="bg-emerald-700 text-white font-semibold px-5 py-2.5 rounded-lg hover:bg-emerald-800 transition-colors shadow-sm">Create Profile</button>
            </div>
          </nav>
        </header>

        <main className="container mx-auto px-6 py-12">
          {/* Hero Section */}
          <div className="text-center mb-12">
            <h2 className="text-4xl md:text-5xl font-extrabold text-stone-800 mb-4">Find Your Next Skilled Worker</h2>
            <p className="text-lg text-stone-600 max-w-2xl mx-auto mb-8">The premier hub for connecting employers with top-tier blue-collar professionals.</p>
            <div className="flex justify-center space-x-4">
                <button className="bg-emerald-700 text-white font-semibold px-6 py-3 rounded-lg hover:bg-emerald-800 transition-colors text-base">Find Workers</button>
                <button className="bg-white text-emerald-700 border-2 border-emerald-700 font-semibold px-6 py-3 rounded-lg hover:bg-emerald-50 transition-colors text-base">Post a Job</button>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            {/* Sidebar */}
            <aside className="lg:col-span-1 space-y-8">
              {/* Categories Card */}
              <Card className="p-6">
                <h3 className="text-lg font-bold mb-4">Categories</h3>
                <ul className="space-y-2 text-stone-600">
                    {jobCategories.slice(1).map(cat => <li key={cat} className="hover:text-emerald-700 cursor-pointer">{cat}</li>)}
                </ul>
              </Card>

              {/* Job Types Card */}
              <Card className="p-6">
                <h3 className="text-lg font-bold mb-4">Job Types</h3>
                <ul className="space-y-2 text-stone-600">
                    {jobTypes.slice(1).map(type => <li key={type} className="hover:text-emerald-700 cursor-pointer">{type}</li>)}
                </ul>
              </Card>

              {/* BLUE-COLLAR CONNECT Card */}
              <Card className="p-6 bg-emerald-700 text-white">
                <Building className="w-10 h-10 mb-3 opacity-50"/>
                <h3 className="text-lg font-bold mb-2">BLUE-COLLAR CONNECT</h3>
                <p className="text-sm text-emerald-100">Your trusted partner in skilled labor recruitment. We vet, you hire.</p>
              </Card>
            </aside>

            {/* Main Content */}
            <div className="lg:col-span-3 space-y-8">
              {/* Filters Card */}
              <Card className="p-6">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 items-center">
                  <div className="relative md:col-span-2 lg:col-span-4">
                    <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-stone-400">
                      <Search className="w-5 h-5" />
                    </div>
                    <input 
                      type="text" 
                      placeholder="Search by name or trade (e.g., 'John Doe', 'Plumber')" 
                      className="w-full pl-10 pr-4 py-3 border border-stone-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                    />
                  </div>
                  <CustomSelect value={category} onChange={(e) => setCategory(e.target.value)} options={jobCategories} icon={<Filter className="w-5 h-5" />} />
                  <CustomSelect value={jobType} onChange={(e) => setJobType(e.target.value)} options={jobTypes} icon={<Briefcase className="w-5 h-5" />} />
                  <div className="flex space-x-2 col-span-2">
                    <button onClick={() => setSort('Newest')} className={`w-full text-sm py-2.5 rounded-md transition-colors ${sort === 'Newest' ? 'bg-emerald-700 text-white' : 'bg-stone-100 hover:bg-stone-200'}`}><div className="flex items-center justify-center"><Calendar className="w-4 h-4 mr-2"/>Newest</div></button>
                    <button onClick={() => setSort('Highest Pay')} className={`w-full text-sm py-2.5 rounded-md transition-colors ${sort === 'Highest Pay' ? 'bg-emerald-700 text-white' : 'bg-stone-100 hover:bg-stone-200'}`}><div className="flex items-center justify-center"><DollarSign className="w-4 h-4 mr-2"/>Highest Pay</div></button>
                  </div>
                </div>
              </Card>

              {/* Worker List */}
              <div className="space-y-6">
                {filteredWorkers.length > 0 ? (
                  filteredWorkers.map(renderWorkerCard)
                ) : (
                  <Card className="p-12 text-center text-stone-500">
                    <p className="font-semibold">No workers match your search criteria.</p>
                  </Card>
                )}
              </div>
            </div>
          </div>

          {/* Create Profile Section */}
          <div className="mt-20">
              <Card className="p-8 md:p-12">
                  <h2 className="text-3xl font-bold text-center mb-2">Ready to Get Started?</h2>
                  <p className="text-center text-stone-600 mb-8">Create your profile to showcase your skills to thousands of employers.</p>
                  <div className="max-w-2xl mx-auto space-y-6">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                          <div>
                              <label htmlFor="fullName" className="block text-sm font-medium text-stone-700 mb-1">Full Name</label>
                              <input type="text" id="fullName" placeholder="John Doe" className="w-full p-3 border border-stone-300 rounded-lg focus:ring-2 focus:ring-emerald-500" />
                          </div>
                          <div>
                              <label htmlFor="phone" className="block text-sm font-medium text-stone-700 mb-1">Phone Number</label>
                              <div className="relative">
                                  <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none text-stone-400"><Phone className="w-5 h-5" /></div>
                                  <input type="tel" id="phone" placeholder="(555) 123-4567" className="w-full p-3 pl-10 border border-stone-300 rounded-lg focus:ring-2 focus:ring-emerald-500" />
                              </div>
                          </div>
                      </div>
                      <div>
                          <label htmlFor="workExperience" className="block text-sm font-medium text-stone-700 mb-1">Work Experience</label>
                          <textarea id="workExperience" rows={5} placeholder="Describe your skills, past projects, and certifications..." className="w-full p-3 border border-stone-300 rounded-lg focus:ring-2 focus:ring-emerald-500"></textarea>
                      </div>
                      <button className="w-full bg-emerald-700 text-white font-semibold py-3.5 rounded-lg hover:bg-emerald-800 transition-colors text-lg">Create My Profile</button>
                  </div>
              </Card>
          </div>

        </main>

        {/* Footer */}
        <footer className="bg-white border-t border-stone-200 mt-20">
          <div className="container mx-auto px-6 py-12">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
              <div className="col-span-2 md:col-span-1">
                  <h2 className="text-xl font-bold text-emerald-700">BLUE-COLLAR CONNECT</h2>
                  <p className="text-stone-500 mt-2 text-sm">The future of skilled work.</p>
              </div>
              <div>
                  <h3 className="font-semibold text-stone-800">Quick Links</h3>
                  <ul className="mt-4 space-y-3 text-stone-600">
                      <li><a href="#" className="hover:text-emerald-700">Find Workers</a></li>
                      <li><a href="#" className="hover:text-emerald-700">Find Jobs</a></li>
                      <li><a href="#" className="hover:text-emerald-700">Post a Job</a></li>
                  </ul>
              </div>
              <div>
                  <h3 className="font-semibold text-stone-800">Resources</h3>
                  <ul className="mt-4 space-y-3 text-stone-600">
                      <li><a href="#" className="hover:text-emerald-700">FAQ</a></li>
                      <li><a href="#" className="hover:text-emerald-700">Terms of Service</a></li>
                      <li><a href="#" className="hover:text-emerald-700">Privacy Policy</a></li>
                  </ul>
              </div>
              <div>
                  <h3 className="font-semibold text-stone-800">Contact Us</h3>
                  <ul className="mt-4 space-y-3 text-stone-600">
                      <li><a href="#" className="hover:text-emerald-700">Contact Form</a></li>
                      <li><a href="#" className="hover:text-emerald-700">About Us</a></li>
                  </ul>
              </div>
            </div>
            <div className="mt-12 border-t border-stone-200 pt-6 text-center text-sm text-stone-500">
