const CybersecurityEducationHubPage: FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilter, setActiveFilter] = useState<Category>('All');
  const [filteredCourses, setFilteredCourses] = useState<Course[]>(allCourses);
  const [enrollmentMessage, setEnrollmentMessage] = useState<string | null>(null);

  useEffect(() => {
    let courses = allCourses;

    if (activeFilter !== 'All') {
      courses = courses.filter(course => course.category === activeFilter);
    }

    if (searchTerm) {
      courses = courses.filter(course =>
        course.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        course.description.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredCourses(courses);
  }, [searchTerm, activeFilter]);

  const handleEnroll = (courseTitle: string) => {
    setEnrollmentMessage(`Successfully enrolled in ${courseTitle}!`);
    setTimeout(() => setEnrollmentMessage(null), 3000);
  };

  return (
    <div className="bg-violet-50 min-h-screen font-sans text-slate-800">
      <Header />
      <main>
        <Hero />
        <section id="courses" className="py-16 md:py-24">
            <div className="container mx-auto px-4 sm:px-6 lg:px-8">
                <div className="text-center mb-12">
                    <h2 className="text-3xl md:text-4xl font-bold tracking-tight">Our Courses</h2>
                    <p className="mt-4 max-w-2xl mx-auto text-lg text-slate-600">Find the perfect course to launch or advance your cybersecurity career.</p>
                </div>

                {/* Search and Filter UI */}
                <div className="mb-10 space-y-6">
                    <div className="relative max-w-lg mx-auto">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                            <SearchIcon />
                        </div>
                        <input
                            type="text"
                            placeholder="Search for courses..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            id="search-input"
                            className="w-full pl-11 pr-4 py-3 border border-slate-300 rounded-full shadow-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                        />
                    </div>
                    <div className="flex flex-wrap justify-center gap-2 md:gap-3">
                        {categories.map(category => (
                            <button
                                key={category}
                                onClick={() => setActiveFilter(category)}
                                className={`px-4 py-2 text-sm font-semibold rounded-full transition-colors ${activeFilter === category ? 'bg-indigo-600 text-white shadow' : 'bg-white text-slate-700 hover:bg-slate-100'}`}
                            >
                                {category === 'Software Security' ? 'Software Security' : category === 'Cloud Security' ? 'Cloud Security' : category === 'Data Science' ? 'Data Science' : category === 'Cybersecurity' ? 'Cybersecurity' : category}
                            </button>
                        ))}
                    </div>
                </div>

                {/* Enrollment Success Message */}
                {enrollmentMessage && (
                    <div className="fixed top-20 left-1/2 -translate-x-1/2 bg-green-500 text-white px-6 py-3 rounded-lg shadow-lg z-50 animate-fade-in-down">
                        {enrollmentMessage}
                    </div>
                )}

                {/* Course Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {filteredCourses.length > 0 ? (
                        filteredCourses.map(course => <CourseCard key={course.id} course={course} onEnroll={handleEnroll} />)
                    ) : (
                        <p className="text-center text-slate-500 md:col-span-2 lg:col-span-3">No courses found. Try adjusting your search or filters.</p>
                    )}
                </div>
            </div>
        </section>
        <AboutUs />
        <ContactForm />
      </main>
      <Footer />
      <ChatWidget />
    </div>
  );
};

export default CybersecurityEducationHubPage;


