const EduConnectPage = () => {
  const [activeNav, setActiveNav] = useState<NavItem>('Dashboard');
  const [profile, setProfile] = useState<ProfileData>(initialProfile);
  const [programs, setPrograms] = useState<Program[]>(initialPrograms);

  const handleApply = (id: number) => {
    setPrograms(programs.map(p => p.id === id ? { ...p, status: 'Applied' } : p));
  };

  const handleProfileChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setProfile(prev => ({ ...prev, [name]: value }));
  };

  const renderContent = () => {
    switch (activeNav) {
      case 'Dashboard':
        return <DashboardContent programs={programs} onApply={handleApply} />;
      case 'Profile':
        return <ProfileContent profile={profile} onProfileChange={handleProfileChange} />;
      case 'Find Programs':
        return <PlaceholderContent title="Find Programs" icon={Search} />;
      case 'Applications':
        return <PlaceholderContent title="My Applications" icon={FileText} />;
      case 'Inbox':
        return <PlaceholderContent title="Inbox" icon={Inbox} />;
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#003554] to-[#00A6FB] text-slate-100 font-sans">
      <div className="flex">
        <aside className="w-64 p-6 bg-slate-900/30 backdrop-blur-lg border-r border-slate-700/50 min-h-screen flex flex-col">
          <div className="flex items-center gap-3 mb-12">
            <GraduationCap className="w-8 h-8 text-[#00A6FB]" />
            <h1 className="text-2xl font-bold tracking-tight">EduConnect</h1>
          </div>
          <nav className="flex flex-col gap-3">
            <NavItem icon={LayoutDashboard} label="Dashboard" active={activeNav === 'Dashboard'} onClick={() => setActiveNav('Dashboard')} />
            <NavItem icon={User} label="Profile" active={activeNav === 'Profile'} onClick={() => setActiveNav('Profile')} />
            <NavItem icon={Search} label="Find Programs" active={activeNav === 'Find Programs'} onClick={() => setActiveNav('Find Programs')} />
            <NavItem icon={FileText} label="Applications" active={activeNav === 'Applications'} onClick={() => setActiveNav('Applications')} />
            <NavItem icon={Inbox} label="Inbox" active={activeNav === 'Inbox'} onClick={() => setActiveNav('Inbox')} />
          </nav>
          <div className="mt-auto">
            <div className="bg-blue-500/10 border border-blue-400/30 rounded-lg p-4 text-center">
              <h3 className="font-bold text-white">Upgrade to Pro</h3>
              <p className="text-xs text-slate-300 mt-1 mb-3">Get unlimited access to all features.</p>
              <button className="w-full bg-[#00A6FB] hover:bg-blue-400 text-white font-semibold py-2 px-4 rounded-lg text-sm transition-colors">Upgrade</button>
            </div>
          </div>
        </aside>

        <main className="flex-1 p-8">
          <header className="flex justify-between items-center mb-8">
            <h2 className="text-3xl font-bold text-white">{activeNav}</h2>
            <div className="flex items-center gap-4">
              <button className="relative text-slate-300 hover:text-white transition-colors">
                <Bell className="w-6 h-6" />
                <span className="absolute -top-1 -right-1 w-3 h-3 bg-red-500 rounded-full border-2 border-slate-800"></span>
              </button>
              <div className="flex items-center gap-3">
                 <div className="bg-gray-200 border-2 border-dashed rounded-full w-10 h-10" />
                <div>
                  <p className="font-semibold text-white">{profile.name}</p>
                  <p className="text-xs text-slate-400">Student</p>
                </div>
              </div>
            </div>
          </header>
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

const NavItem: FC<{ icon: React.ComponentType<{ className?: string }>, label: string, active: boolean, onClick: () => void }> = ({ icon: Icon, label, active, onClick }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${active ? 'bg-[#00A6FB] text-white' : 'text-slate-300 hover:bg-slate-700/50 hover:text-white'}`}>
    <Icon className="w-5 h-5" />
    <span>{label}</span>
  </button>
);

const DashboardContent: FC<{ programs: Program[], onApply: (id: number) => void }> = ({ programs, onApply }) => (
  <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
    <div className="lg:col-span-2 flex flex-col gap-8">
      <Card>
        <h3 className="font-bold text-lg text-white mb-1">Your Progress</h3>
        <p className="text-sm text-slate-400 mb-4">You've completed 4/5 steps to a perfect profile!</p>
        <ProgressPrimitive.Root value={80} className="relative h-3 w-full overflow-hidden rounded-full bg-slate-700">
          <ProgressPrimitive.Indicator
            className="h-full w-full flex-1 bg-gradient-to-r from-cyan-400 to-[#00A6FB] transition-all"
            style={{ transform: `translateX(-${100 - 80}%)` }}
          />
        </ProgressPrimitive.Root>
      </Card>

      <Card>
        <h3 className="font-bold text-lg text-white mb-4">Program Matches</h3>
        <ResponsiveContainer width="100%" height={250}>
          <BarChart data={programMatchesData} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
            <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
            <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(value) => `${value}%`} />
            <RechartsTooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(100, 116, 139, 0.1)' }} />
            <Bar dataKey="match" fill="#00A6FB" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </Card>

      <div className="flex flex-col gap-4">
        <h3 className="font-bold text-lg text-white">Available Programs</h3>
        {programs.map(program => (
          <ProgramCard key={program.id} program={program} onApply={onApply} />
        ))}
      </div>
    </div>

    <div className="lg:col-span-1 flex flex-col gap-8">
      <Card>
        <h3 className="font-bold text-lg text-white mb-4">Top Matching Fields</h3>
        <ResponsiveContainer width="100%" height={250}>
          <PieChart>
            <Pie data={topFieldsData} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={80} labelLine={false}>
              {topFieldsData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={PIE_CHART_COLORS[index % PIE_CHART_COLORS.length]} />
              ))}
            </Pie>
             <RechartsTooltip cursor={{ fill: 'rgba(100, 116, 139, 0.1)' }} contentStyle={{backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '0.5rem'}}/>
          </PieChart>
        </ResponsiveContainer>
        <div className="mt-4 space-y-2">
          {topFieldsData.map((entry, index) => (
            <div key={entry.name} className="flex items-center justify-between text-sm">
              <div className="flex items-center gap-2">
                <span className="w-3 h-3 rounded-full" style={{ backgroundColor: PIE_CHART_COLORS[index] }}></span>
                <span className="text-slate-300">{entry.name}</span>
              </div>
              <span className="font-medium text-white">{((entry.value / 1200) * 100).toFixed(0)}%</span>
            </div>
          ))}
        </div>
      </Card>
    </div>
  </div>
);

const ProgramCard: FC<{ program: Program; onApply: (id: number) => void }> = ({ program, onApply }) => (
  <Card className="flex items-center justify-between !p-4 hover:bg-slate-800/60 transition-colors">
    <div className="flex items-center gap-4">
      <div className="bg-slate-700/50 p-3 rounded-lg">
        <program.icon className="w-6 h-6 text-[#00A6FB]" />
      </div>
      <div>
        <h4 className="font-semibold text-white">{program.title}</h4>
        <p className="text-sm text-slate-400">{program.provider}</p>
      </div>
    </div>
    <div className="flex items-center gap-6">
      <RadixTooltip content={`Match Score: ${program.match}%`}>
        <div className="flex items-center gap-2">
          <span className="font-bold text-lg text-white">{program.match}%</span>
          <span className="text-xs text-slate-400">Match</span>
        </div>
      </RadixTooltip>
      {program.status === 'Apply' ? (
        <button onClick={() => onApply(program.id)} className="bg-[#00A6FB] text-white font-semibold py-2 px-6 rounded-lg text-sm hover:bg-blue-400 transition-colors">Apply</button>
      ) : (
        <button disabled className="flex items-center gap-2 bg-green-500/20 text-green-400 font-semibold py-2 px-6 rounded-lg text-sm cursor-not-allowed">
          <CheckCircle className="w-4 h-4" /> Applied
        </button>
      )}
    </div>
  </Card>
);

const ProfileContent: FC<{ profile: ProfileData; onProfileChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void }> = ({ profile, onProfileChange }) => (
  <Card className="max-w-4xl mx-auto">
    <div className="flex flex-col md:flex-row items-center gap-8">
      <div className="flex flex-col items-center">
        <div className="bg-gray-200 border-2 border-dashed rounded-full w-32 h-32 mb-4" />
        <button className="bg-slate-700 hover:bg-slate-600 text-white font-semibold py-2 px-4 rounded-lg text-sm transition-colors">Change Photo</button>
      </div>
      <div className="flex-1 w-full">
        <h3 className="font-bold text-xl text-white mb-6">Your Profile Information</h3>
        <form className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <ProfileInput label="Full Name" name="name" value={profile.name} onChange={onProfileChange} icon={User} />
          <ProfileInput label="Email Address" name="email" value={profile.email} onChange={onProfileChange} icon={Inbox} isReadOnly />
          <ProfileInput label="Phone Number" name="phone" value={profile.phone} onChange={onProfileChange} icon={Phone} />
          <ProfileInput label="Location" name="location" value={profile.location} onChange={onProfileChange} icon={MapPin} />
          <div className="md:col-span-2">
            <ProfileInput label="Qualifications" name="qualifications" value={profile.qualifications} onChange={onProfileChange} icon={Award} isTextarea />
          </div>
          <div className="md:col-span-2">
            <ProfileInput label="Career Interests" name="careerInterests" value={profile.careerInterests} onChange={onProfileChange} icon={Lightbulb} isTextarea />
          </div>
          <div className="md:col-span-2 flex justify-end">
            <button type="submit" className="bg-[#00A6FB] hover:bg-blue-400 text-white font-bold py-3 px-8 rounded-lg transition-colors">Save Changes</button>
          </div>
        </form>
      </div>
    </div>
  </Card>
);

const ProfileInput: FC<{ label: string, name: string, value: string, icon: React.ComponentType<{ className?: string }>, onChange: (e: any) => void, isReadOnly?: boolean, isTextarea?: boolean }> = ({ label, name, value, icon: Icon, onChange, isReadOnly = false, isTextarea = false }) => (
  <div>
    <label className="block text-sm font-medium text-slate-300 mb-2">{label}</label>
    <div className="relative">
      <span className="absolute inset-y-0 left-0 flex items-center pl-3">
        <Icon className="w-5 h-5 text-slate-400" />
      </span>
      {isTextarea ? (
        <textarea
          name={name}
          value={value}
          onChange={onChange}
          rows={3}
          className="w-full pl-10 pr-4 py-2 bg-slate-800 border border-slate-600 rounded-lg focus:ring-2 focus:ring-[#00A6FB] focus:border-[#00A6FB] outline-none transition-colors"
        />
      ) : (
        <input
          type="text"
          name={name}
          value={value}
          onChange={onChange}
          readOnly={isReadOnly}
          className={`w-full pl-10 pr-4 py-2 bg-slate-800 border border-slate-600 rounded-lg focus:ring-2 focus:ring-[#00A6FB] focus:border-[#00A6FB] outline-none transition-colors ${isReadOnly ? 'opacity-70 cursor-not-allowed' : ''}`}
        />
      )}
    </div>
  </div>
);

const PlaceholderContent: FC<{ title: string; icon: React.ComponentType<{ className?: string }> }> = ({ title, icon: Icon }) => (
  <Card className="text-center py-20">
    <Icon className="w-16 h-16 text-slate-500 mx-auto mb-4" />
    <h3 className="text-2xl font-bold text-white">{title}</h3>
    <p className="text-slate-400 mt-2">This section is under construction. Check back soon!</p>
  </Card>
);

export default EduConnectPage;


