// --- TYPE DEFINITIONS ---
type AnswerKey = 'q1' | 'q2' | 'q3' | 'q4';

type AssessmentAnswers = {
  [key in AnswerKey]: string;
};

interface Question {
  id: AnswerKey;
  text: string;
  options: [string, string];
}

// --- DATA ---
const assessmentQuestions: Question[] = [
  {
    id: 'q1',
    text: 'When making decisions, do you prefer to rely on logic or on personal values?',
    options: ['Logic and objective principles', 'Personal values and impact on others'],
  },
  {
    id: 'q2',
    text: 'Do you tend to focus on concrete, factual information or abstract, theoretical ideas?',
    options: ['Concrete, factual information', 'Abstract, theoretical ideas'],
  },
  {
    id: 'q3',
    text: 'Are you more energized by spending time with a large group of people or alone?',
    options: ['Large groups of people', 'Quiet time alone'],
  },
  {
    id: 'q4',
    text: 'Do you prefer to have a planned, orderly way of life or a flexible, spontaneous approach?',
    options: ['Planned and orderly', 'Flexible and spontaneous'],
  },
];

const initialAnswers: AssessmentAnswers = {
  q1: '',
  q2: '',
  q3: '',
  q4: '',
};

// --- REUSABLE COMPONENTS ---
interface CustomSelectProps {
  id: string;
  label: string;
  options: string[];
  value: string;
  onChange: (e: ChangeEvent<HTMLSelectElement>) => void;
}

const CustomSelect: FC<CustomSelectProps> = ({ id, label, options, value, onChange }) => (
  <div className="w-full">
    <label htmlFor={id} className="block text-sm font-medium text-stone-600 mb-2">
      {label}
    </label>
    <div className="relative">
      <select
        id={id}
        name={id}
        value={value}
        onChange={onChange}
        className="w-full appearance-none bg-stone-50 border border-stone-300 text-stone-900 rounded-lg py-3 px-4 pr-10 focus:outline-none focus:ring-2 focus:ring-amber-700 focus:border-amber-700 transition duration-200"
      >
        <option value="" disabled>Select your preference</option>
        {options.map((option) => (
          <option key={option} value={option}>{option}</option>
        ))}
      </select>
      <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-3 text-stone-500">
        <ChevronDown className="h-5 w-5" />
      </div>
    </div>
  </div>
);

// --- MAIN PAGE COMPONENT ---
const CoachMateAssessmentPage: NextPage = () => {
  const [answers, setAnswers] = useState<AssessmentAnswers>(initialAnswers);
  const [submissionStatus, setSubmissionStatus] = useState<'idle' | 'submitting' | 'submitted'>('idle');

  const handleInputChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const { name, value } = e.target;
    setAnswers(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setSubmissionStatus('submitting');
    console.log('Submitting Assessment:', answers);

    // Simulate API call
    setTimeout(() => {
      setSubmissionStatus('submitted');
    }, 2000);
  };

  const allQuestionsAnswered = Object.values(answers).every(answer => answer !== '');

  return (
    <>
      <Head>
        <title>CoachMate - Personality Assessment</title>
        <meta name="description" content="Take the CoachMate personality assessment to find your perfect coach." />
        <link rel="icon" href="/favicon.ico" />
      </Head>
      <main className="flex flex-col items-center justify-center min-h-screen bg-stone-100 p-4 sm:p-6 md:p-8 font-sans">
        <div className="w-full max-w-2xl mx-auto">
          {submissionStatus === 'submitted' ? (
            <div className="bg-white p-8 sm:p-12 rounded-2xl shadow-lg text-center transition-all duration-500 transform scale-100">
              <CheckCircle2 className="w-16 h-16 text-green-500 mx-auto mb-6" />
              <h1 className="text-3xl font-bold text-stone-900 mb-2">Assessment Submitted!</h1>
              <p className="text-stone-600 mb-8">Thank you. We are now analyzing your results to find the perfect coach for you.</p>
              <button
                onClick={() => setSubmissionStatus('idle')}
                className="bg-amber-800 text-white font-semibold py-3 px-8 rounded-lg hover:bg-amber-900 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-700 transition-all duration-200"
              >
                Take Again
              </button>
            </div>
          ) : (
            <div className="bg-white p-8 sm:p-12 rounded-2xl shadow-lg transition-all duration-500">
              <div className="text-center mb-8">
                <UserCheck className="w-12 h-12 text-amber-800 mx-auto mb-4" />
                <h1 className="text-3xl font-bold text-stone-900">Personality Assessment</h1>
                <p className="text-stone-600 mt-2">Discover your traits to find a compatible coach.</p>
              </div>

              <form onSubmit={handleSubmit} className="space-y-8">
                {assessmentQuestions.map((q, index) => (
                  <CustomSelect
                    key={q.id}
                    id={q.id}
                    label={`${index + 1}. ${q.text}`}
                    options={q.options}
                    value={answers[q.id]}
                    onChange={handleInputChange}
                  />
                ))}

                <div className="pt-4">
                  <button
                    type="submit"
                    disabled={!allQuestionsAnswered || submissionStatus === 'submitting'}
                    className="w-full flex items-center justify-center bg-amber-800 text-white font-semibold py-4 px-6 rounded-lg hover:bg-amber-900 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-700 transition-all duration-200 disabled:bg-stone-400 disabled:cursor-not-allowed"
                  >
                    {submissionStatus === 'submitting' ? (
                      <>
                        <LoaderCircle className="animate-spin h-5 w-5 mr-3" />
                        Submitting...
                      </>
                    ) : (
                      'Submit Assessment'
                    )}
                  </button>
                </div>
              </form>
            </div>
          )}
        </div>
        <footer className="text-center mt-8">
            <p className="text-sm text-stone-500">© {new Date().getFullYear()} CoachMate. All rights reserved.</p>
        </footer>
      </main>
    </>
  );
};

export default CoachMateAssessmentPage;


