// --- HELPER FUNCTIONS ---
const generateJoinCode = () => {
  return Math.random().toString(36).substring(2, 8).toUpperCase();
};

// --- UI COMPONENTS (INTERNAL) ---

interface WelcomeCardProps {
  onLogout: () => void;
}

const WelcomeCard: FC<WelcomeCardProps> = ({ onLogout }) => (
  <header className="bg-white dark:bg-slate-800 shadow-md rounded-xl p-4 mb-8">
    <div className="flex justify-between items-center">
      <div className="flex items-center gap-4">
        <div className="bg-slate-600 p-3 rounded-lg">
            <BookOpen className="w-8 h-8 text-white" />
        </div>
        <div>
            <h1 className="text-xl font-bold text-slate-800 dark:text-white">Welcome to the Virtual Study Hub</h1>
            <p className="text-sm text-slate-500 dark:text-slate-400">Your space for collaborative learning and growth.</p>
        </div>
      </div>
      <button
        onClick={onLogout}
        className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-700 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-500 transition-all duration-200"
      >
        <LogOut className="w-4 h-4" />
        <span>Logout</span>
      </button>
    </div>
  </header>
);

interface HomeCardProps {
    activeTab: ActiveTab;
    setActiveTab: (tab: ActiveTab) => void;
}

const HomeCard: FC<HomeCardProps> = ({ activeTab, setActiveTab }) => {
    const tabs: { id: ActiveTab; label: string; icon: JSX.Element }[] = [
        { id: 'my-groups', label: 'My Study Groups', icon: <Users className="w-5 h-5" /> },
        { id: 'create', label: 'Create Study Group', icon: <PlusCircle className="w-5 h-5" /> },
        { id: 'join', label: 'Join Study Group', icon: <ArrowRight className="w-5 h-5" /> },
    ];

    return (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
            {tabs.map(tab => (
                <button 
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`p-6 text-left rounded-xl transition-all duration-300 group ${activeTab === tab.id ? 'bg-slate-700 text-white shadow-lg -translate-y-1' : 'bg-slate-600 text-white hover:bg-slate-700 hover:-translate-y-1'}`}>
                    <div className="flex items-center gap-3 mb-2">
                        {tab.icon}
                        <h3 className="font-bold text-lg">{tab.label}</h3>
                    </div>
                    <p className="text-sm text-slate-300 group-hover:text-white">
                        {tab.id === 'my-groups' && 'View and manage your groups.'}
                        {tab.id === 'create' && 'Start a new group with your peers.'}
                        {tab.id === 'join' && 'Enter a code to join a group.'}
                    </p>
                </button>
            ))}
        </div>
    );
};

interface NotificationProps {
  message: string;
  type: 'success' | 'error';
  onClose: () => void;
}

const Notification: FC<NotificationProps> = ({ message, type, onClose }) => {
  if (!message) return null;

  const isSuccess = type === 'success';
  const bgColor = isSuccess ? 'bg-green-100 dark:bg-green-900' : 'bg-red-100 dark:bg-red-900';
  const textColor = isSuccess ? 'text-green-800 dark:text-green-200' : 'text-red-800 dark:text-red-200';
  const Icon = isSuccess ? CheckCircle : XCircle;

  return (
    <div className={`flex items-center justify-between p-4 mb-6 rounded-lg ${bgColor} ${textColor}`}>
      <div className="flex items-center gap-3">
        <Icon className="w-5 h-5" />
        <span className="font-medium">{message}</span>
      </div>
      <button onClick={onClose} className="text-current opacity-70 hover:opacity-100">&times;</button>
    </div>
  );
};

// --- MAIN PAGE COMPONENT ---
const VirtualStudyHubPage: NextPage = () => {
  const [activeTab, setActiveTab] = useState<ActiveTab>('my-groups');
  const [allGroups, setAllGroups] = useState<StudyGroup[]>(initialAllGroups);
  const [userGroups, setUserGroups] = useState<StudyGroup[]>(initialUserGroups);

  const [groupName, setGroupName] = useState('');
  const [groupDescription, setGroupDescription] = useState('');
  const [joinCode, setJoinCode] = useState('');

  const [notification, setNotification] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 4000);
  };

  const handleLogout = () => {
    showNotification('You have been logged out.', 'success');
  };

  const handleCreateGroup = (e: FormEvent) => {
    e.preventDefault();
    if (!groupName.trim() || !groupDescription.trim()) {
        showNotification('Group name and description cannot be empty.', 'error');
        return;
    }
    const newGroup: StudyGroup = {
      id: new Date().toISOString(),
      name: groupName,
      description: groupDescription,
      memberCount: 1,
      joinCode: generateJoinCode(),
    };
    setAllGroups(prev => [newGroup, ...prev]);
    setUserGroups(prev => [newGroup, ...prev]);
    setGroupName('');
    setGroupDescription('');
    showNotification(`Successfully created and joined '${newGroup.name}'!`, 'success');
    setActiveTab('my-groups');
  };

  const handleJoinGroup = (e: FormEvent) => {
    e.preventDefault();
    const groupToJoin = allGroups.find(g => g.joinCode.toLowerCase() === joinCode.toLowerCase());
    if (groupToJoin) {
        if (userGroups.some(ug => ug.id === groupToJoin.id)) {
            showNotification(`You are already a member of '${groupToJoin.name}'.`, 'error');
        } else {
            setUserGroups(prev => [groupToJoin, ...prev]);
            showNotification(`Successfully joined '${groupToJoin.name}'!`, 'success');
            setActiveTab('my-groups');
        }
    } else {
        showNotification('Invalid join code. Please try again.', 'error');
    }
    setJoinCode('');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'create':
        return (
            <form onSubmit={handleCreateGroup} className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-md space-y-4">
                <h3 className="text-lg font-semibold text-slate-800 dark:text-white">Create a New Study Group</h3>
                <div>
                    <label htmlFor="groupName" className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">Group Name</label>
                    <input id="groupName" type="text" value={groupName} onChange={(e: ChangeEvent<HTMLInputElement>) => setGroupName(e.target.value)} placeholder="e.g., Advanced JavaScript" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-md focus:outline-none focus:ring-2 focus:ring-slate-500 text-slate-900 dark:text-white"/>
                </div>
                <div>
                    <label htmlFor="groupDescription" className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">Group Description</label>
                    <textarea id="groupDescription" value={groupDescription} onChange={(e: ChangeEvent<HTMLTextAreaElement>) => setGroupDescription(e.target.value)} rows={4} placeholder="What is this group about?" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-md focus:outline-none focus:ring-2 focus:ring-slate-500 text-slate-900 dark:text-white"></textarea>
                </div>
                <button type="submit" className="w-full flex items-center justify-center gap-2 px-4 py-3 font-semibold text-white bg-slate-600 rounded-lg hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-500 transition-colors">
                    <PlusCircle className="w-5 h-5" />
                    Create Group
                </button>
            </form>
        );
      case 'join':
        return (
            <form onSubmit={handleJoinGroup} className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-md space-y-4">
                <h3 className="text-lg font-semibold text-slate-800 dark:text-white">Join an Existing Group</h3>
                <div>
                    <label htmlFor="joinCode" className="block text-sm font-medium text-slate-600 dark:text-slate-300 mb-1">Join Code</label>
                    <input id="joinCode" type="text" value={joinCode} onChange={(e: ChangeEvent<HTMLInputElement>) => setJoinCode(e.target.value)} placeholder="Enter join code" className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-md focus:outline-none focus:ring-2 focus:ring-slate-500 text-slate-900 dark:text-white"/>
                </div>
                <button type="submit" className="w-full flex items-center justify-center gap-2 px-4 py-3 font-semibold text-white bg-slate-600 rounded-lg hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-500 transition-colors">
                    <ArrowRight className="w-5 h-5" />
                    Join Group
                </button>
            </form>
        );
      case 'my-groups':
      default:
        return (
            <div className="bg-white dark:bg-slate-800 p-6 rounded-xl shadow-md">
                <h3 className="text-lg font-semibold text-slate-800 dark:text-white mb-4">My Groups ({userGroups.length})</h3>
                {userGroups.length > 0 ? (
                    <div className="space-y-4">
                        {userGroups.map(group => (
                            <div key={group.id} className="p-4 border border-slate-200 dark:border-slate-700 rounded-lg">
                                <h4 className="font-bold text-slate-700 dark:text-slate-200">{group.name}</h4>
                                <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">{group.description}</p>
                                <p className="text-xs text-slate-400 dark:text-slate-500 mt-2">Join Code: <span className="font-mono bg-slate-100 dark:bg-slate-700 px-1 rounded">{group.joinCode}</span></p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="text-center py-8">
                        <p className="text-slate-500 dark:text-slate-400">You haven't joined any groups yet.</p>
                        <button onClick={() => setActiveTab('join')} className="mt-2 text-sm font-semibold text-slate-600 dark:text-slate-300 hover:underline">Join one now!</button>
                    </div>
                )}
            </div>
        );
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 dark:bg-slate-900 font-sans text-slate-900 dark:text-slate-50 p-4 sm:p-6 lg:p-8">
      <div className="max-w-4xl mx-auto">
        <WelcomeCard onLogout={handleLogout} />
        <main>
            <HomeCard activeTab={activeTab} setActiveTab={setActiveTab} />
            <div className="mt-6">
              {notification && <Notification message={notification.message} type={notification.type} onClose={() => setNotification(null)} />}
              {renderContent()}
            </div>
            <section className="mt-12">
                <h2 className="text-2xl font-bold text-slate-800 dark:text-white mb-6 flex items-center gap-3"><Search className="w-6 h-6 text-slate-500"/> Discover Study Groups</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {allGroups.length > 0 ? allGroups.map(group => (
                        <div key={group.id} className="bg-white dark:bg-slate-800 rounded-xl shadow-md p-6 flex flex-col">
                            <h4 className="text-lg font-bold text-slate-800 dark:text-white">{group.name}</h4>
                            <p className="text-sm text-slate-600 dark:text-slate-400 mt-2 flex-grow">{group.description}</p>
                            <div className="flex justify-between items-center mt-4 pt-4 border-t border-slate-200 dark:border-slate-700">
                                <div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400">
                                    <Users className="w-4 h-4" />
                                    <span>{group.memberCount} members</span>
                                </div>
                                {userGroups.some(ug => ug.id === group.id) ? (
                                    <span className="px-3 py-1 text-xs font-medium text-green-700 bg-green-100 dark:text-green-200 dark:bg-green-900 rounded-full">Joined</span>
                                ) : (
                                    <button onClick={() => { setJoinCode(group.joinCode); setActiveTab('join'); }} className="text-sm font-semibold text-slate-600 dark:text-slate-300 hover:underline">Join</button>
                                )}
                            </div>
                        </div>
                    )) : (
                        <div className="col-span-full text-center py-10 bg-white dark:bg-slate-800 rounded-xl">
                            <p className="text-slate-500 dark:text-slate-400">No study groups available at the moment.</p>
                        </div>
                    )}
                </div>
            </section>
        </main>
      </div>
    </div>
  );
};

export default VirtualStudyHubPage;


