import { useState, useMemo, type FC } from 'react';
import type { NextPage } from 'next';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend, TooltipProps } from 'recharts';
import { Flame, BookOpen, Target, Puzzle, Shuffle, FileText, Sparkles, BrainCircuit, Layers, BadgeCheck, Menu, X, User } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type NavItem = 'Dashboard' | 'Activities' | 'Blog';

type WeeklyProgressData = {
  day: string;
  progress: number;
};

type ActivityDistributionData = {
  name: string;
  value: number;
};

// --- MOCK DATA ---
const weeklyProgressData: WeeklyProgressData[] = [
  { day: 'Mon', progress: 65 },
  { day: 'Tue', progress: 78 },
  { day: 'Wed', progress: 50 },
  { day: 'Thu', progress: 85 },
  { day: 'Fri', progress: 92 },
  { day: 'Sat', progress: 45 },
  { day: 'Sun', progress: 70 },
];

const activityDistributionData: ActivityDistributionData[] = [
  { name: 'Crosswords', value: 25 },
  { name: 'Flashcards', value: 30 },
  { name: 'Quizzes', value: 20 },
  { name: 'Word Games', value: 25 },
];

const wordOfTheDay = {
  word: 'Ephemeral',
  pronunciation: '/əˈfem(ə)rəl/',
  definition: 'Lasting for a very short time.',
  example: 'The beauty of the cherry blossoms is ephemeral, lasting only a week.',
};

// --- UI HELPER COMPONENTS (within the same file) ---

const DashboardCard: FC<{ children: React.ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-white rounded-2xl shadow-sm p-6 ${className}`}>
    {children}
  </div>
);

const CustomTooltip: FC<TooltipProps<number, string>> = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-slate-800 text-white p-3 rounded-lg shadow-lg">
        <p className="font-bold">{`${label}`}</p>
        <p className="text-sm">{`Completion: ${payload[0].value}%`}</p>
      </div>
    );
  }
  return null;
};

const VocabularyMasteryHub: NextPage = () => {
  const [activeNav, setActiveNav] = useState<NavItem>('Dashboard');
  const [isMobileMenuOpen, setMobileMenuOpen] = useState(false);

  const PIE_COLORS = ['#881337', '#be123c', '#e11d48', '#f43f5e'];

  const quickActivities = [
    { name: 'Crossword', icon: Puzzle, href: '#', id: 'crossword' },
    { name: 'Unjumble Letters', icon: Shuffle, href: '#', id: 'unjumble-letters' },
    { name: 'Find Synonyms', icon: Layers, href: '#', id: 'find-synonyms' },
    { name: 'Find Antonyms', icon: Sparkles, href: '#', id: 'find-antonyms' },
    { name: 'Fill in the Blanks', icon: FileText, href: '#', id: 'fill-in-the-blanks' },
    { name: 'Flashcards', icon: BrainCircuit, href: '#', id: 'flashcards' },
