  const navItems: NavItem[] = ['Dashboard', 'Activities', 'Blog'];

  const renderNavLinks = (isMobile: boolean = false) =>
    navItems.map((item) => (
      <button
        key={item}
        onClick={() => setActiveNav(item)}
        className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors duration-200 ${activeNav === item
            ? 'bg-red-800 text-white'
            : `text-slate-700 hover:bg-red-100 ${isMobile ? 'text-left w-full' : ''}`
          }`}>
        {item}
      </button>
    ));

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-800">
      {/* --- Header --- */}
      <header className="bg-white/80 backdrop-blur-lg sticky top-0 z-20 shadow-sm">
        <div className="container mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <BookOpen className="h-7 w-7 text-red-800" />
            <h1 className="text-xl font-bold text-slate-900">Vocabulary Mastery Hub</h1>
          </div>
          <nav className="hidden md:flex items-center gap-2">
            {renderNavLinks()}
