      <main className="container mx-auto p-6">
        <div className="grid grid-cols-1 lg:grid-cols-3 xl:grid-cols-4 gap-6">

          {/* Welcome Card */}
          <DashboardCard className="lg:col-span-3 xl:col-span-4 bg-red-800 text-white">
