          {/* Learning Streak Card */}
          <DashboardCard className="flex flex-col items-center justify-center text-center">
            <Flame className="w-12 h-12 text-red-600 mb-2" />
            <h3 className="text-lg font-semibold text-slate-600">Learning Streak</h3>
            <p className="text-5xl font-bold text-slate-900 mt-2">12</p>
            <p className="text-sm text-slate-500">days in a row!</p>
          </DashboardCard>

          {/* Word of the Day Card */}
          <DashboardCard className="xl:col-span-2">
            <div className="flex items-center gap-3 mb-4">
              <BadgeCheck className="w-8 h-8 text-red-700" />
              <div>
                <h3 className="text-lg font-semibold text-slate-900">Word of the Day</h3>
                <p className="text-sm text-slate-500">Your daily dose of vocabulary</p>
              </div>
            </div>
            <div className="mt-4">
              <h4 className="text-2xl font-bold text-red-800">{wordOfTheDay.word}</h4>
              <p className="text-slate-500 italic">{wordOfTheDay.pronunciation}</p>
