              <p className="mt-2 text-sm text-slate-600 bg-slate-100 p-2 rounded-md">"{wordOfTheDay.example}"</p>
            </div>
          </DashboardCard>

          {/* Activity Distribution Card */}
          <DashboardCard className="flex flex-col">
            <h3 className="text-lg font-semibold text-slate-900 mb-4">Activity Distribution</h3>
            <div className="flex-grow h-64 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={activityDistributionData}
                    cx="50%"
                    cy="50%"
                    labelLine={false}
                    outerRadius={80}
                    fill="#8884d8"
                    dataKey="value"
                    nameKey="name"
                  >
                    {activityDistributionData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip contentStyle={{ backgroundColor: '#fff', border: '1px solid #ddd', borderRadius: '0.5rem' }} />
                  <Legend iconSize={10} layout="vertical" verticalAlign="middle" align="right" />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </DashboardCard>

          {/* Weekly Progress Card */}
          <DashboardCard className="lg:col-span-3 xl:col-span-4">
            <h3 className="text-lg font-semibold text-slate-900 mb-4">Weekly Progress</h3>
            <div className="h-72 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={weeklyProgressData} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                  <XAxis dataKey="day" tickLine={false} axisLine={false} stroke="#64748b" fontSize={12} />
                  <YAxis tickFormatter={(value) => `${value}%`} axisLine={false} tickLine={false} stroke="#64748b" fontSize={12}/>
                  <Tooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(225, 29, 72, 0.1)' }} />
                  <Bar dataKey="progress" fill="#be123c" radius={[4, 4, 0, 0]} barSize={30} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </DashboardCard>

          {/* Quick Activities Section */}
          <DashboardCard className="lg:col-span-3 xl:col-span-4">
            <h3 className="text-lg font-semibold text-slate-900 mb-4">Quick Activities</h3>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              {quickActivities.map((activity) => (
                <a
                  key={activity.id}
                  href={activity.href}
                  id={activity.id}
                  className="group flex flex-col items-center justify-center p-4 bg-slate-50 rounded-xl border-2 border-transparent hover:border-red-700 hover:bg-red-50 transition-all duration-200 text-center"
                >
                  <activity.icon className="w-10 h-10 text-red-700 mb-2 transition-transform group-hover:scale-110" />
                  <span className="font-medium text-slate-800 text-sm">{activity.name}</span>
                </a>
              ))}
            </div>
          </DashboardCard>
        </div>
      </main>
    </div>
  );
};

export default VocabularyMasteryHub;


