               <YAxis tickFormatter={(value) => `${value}%`} axisLine={false} tickLine={false} stroke="#64748b" fontSize={12}/>\n                  <Tooltip content={<CustomTooltip />} cursor={{ fill: \'rgba(225, 29, 72, 0.1)\' }} />\n                  <Bar dataKey="progress" fill="#be123c" radius={[4, 4, 0, 0]} barSize={30} />\n                </BarChart>\n              </ResponsiveContainer>\n            </div>\n          </DashboardCard>\n\n          {/* Quick Activities Section */}\n          <DashboardCard className="lg:col-span-3 xl:col-span-4">\n            <h3 className="text-lg font-semibold text-slate-900 mb-4">Quick Activities</h3>\n            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">\n              {quickActivities.map((activity) => (\n                <a\n                  key={activity.id}\n                  href={activity.href}\n                  id={activity.id}\n                  className="group flex flex-col items-center justify-center p-4 bg-slate-50 rounded-xl border-2 border-transparent hover:border-red-700 hover:bg-red-50 transition-all duration-200 text-center"\n                >\n                  <activity.icon className="w-10 h-10 text-red-700 mb-2 transition-transform group-hover:scale-110" />\n                  <span className="font-medium text-slate-800 text-sm">{activity.name}</span>\n                </a>\n              ))}\n            </div>\n          </DashboardCard>\n        </div>\n      </main>\n    </div>\n  );\n};\n\nexport default VocabularyMasteryHub;\n'}

import { useState, useEffect, type FC, type ReactNode } from 'react';
import type { NextPage } from 'next';
import { DndProvider, useDrag, useDrop } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { Recycle, Star, Trophy, Award, BarChart2, Trash2, Bot, GlassWater, Newspaper, Package } from 'lucide-react';

// --- TYPES AND MOCK DATA ---
type ItemType = 'plastic' | 'glass' | 'paper' | 'metal' | 'trash';

interface RecycleItem {
  id: number;
  name: string;
  type: ItemType;
  icon: ReactNode;
}

interface Bin {
  accepts: ItemType;
  name: string;
  color: string;
  icon: ReactNode;
}

const ITEMS_TO_SORT: RecycleItem[] = [
  { id: 1, name: 'Plastic Bottle', type: 'plastic', icon: <Bot className="w-8 h-8" /> },
  { id: 2, name: 'Glass Jar', type: 'glass', icon: <GlassWater className="w-8 h-8" /> },
  { id: 3, name: 'Newspaper', type: 'paper', icon: <Newspaper className="w-8 h-8" /> },
  { id: 4, name: 'Soda Can', type: 'metal', icon: <Trash2 className="w-8 h-8 text-slate-500" /> },
  { id: 5, name: 'Food Scraps', type: 'trash', icon: <Trash2 className="w-8 h-8" /> },
  { id: 6, name: 'Milk Carton', type: 'plastic', icon: <Package className="w-8 h-8" /> },
  { id: 7, name: 'Wine Bottle', type: 'glass', icon: <GlassWater className="w-8 h-8" /> },
  { id: 8, name: 'Cardboard Box', type: 'paper', icon: <Package className="w-8 h-8" /> },
  { id: 9, name: 'Tin Foil', type: 'metal', icon: <Trash2 className="w-8 h-8 text-slate-500" /> },
  { id: 10, name: 'Styrofoam Cup', type: 'trash', icon: <Trash2 className="w-8 h-8" /> },
];

const BINS: Bin[] = [
  { accepts: 'plastic', name: 'Plastic', color: 'bg-green-500', icon: <Bot className="w-10 h-10" /> },
  { accepts: 'glass', name: 'Glass', color: 'bg-blue-500', icon: <GlassWater className="w-10 h-10" /> },
  { accepts: 'paper', name: 'Paper', color: 'bg-yellow-500', icon: <Newspaper className="w-10 h-10" /> },
  { accepts: 'metal', name: 'Metal', color: 'bg-slate-500', icon: <Trash2 className="w-10 h-10 text-slate-200" /> },
  { accepts: 'trash', name: 'Trash', color: 'bg-gray-800', icon: <Trash2 className="w-10 h-10" /> },
];

const mockLeaderboard = [
  { name: 'EcoHero', score: 90 },
  { name: 'RecycleQueen', score: 80 },
  { name: 'PlanetSaver', score: 75 },
  { name: 'TrashMaster', score: 60 },
];

// --- REUSABLE UI COMPONENTS ---

const InfoCard: FC<{ icon: ReactNode; title: string; children: ReactNode; className?: string }> = ({ icon, title, children, className }) => (
  <div className={`bg-white/70 backdrop-blur-sm p-6 rounded-xl shadow-md border border-gray-200 ${className}`}>
    <div className="flex items-center gap-4 mb-4">
      <div className="text-teal-500">{icon}</div>
      <h3 className="text-xl font-bold text-teal-700">{title}</h3>
    </div>
    <div className="text-slate-600 space-y-2">{children}</div>
  </div>
);

// --- DRAG-AND-DROP COMPONENTS ---

const DraggableItem: FC<{ item: RecycleItem }> = ({ item }) => {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: 'ITEM',
    item: { id: item.id, type: item.type },
    collect: (monitor) => ({
      isDragging: !!monitor.isDragging(),
    }),
  }));

  return (
    <div
      ref={drag}
      className={`flex flex-col items-center justify-center gap-2 p-4 border-2 border-dashed rounded-xl bg-white cursor-grab transition-all duration-300 ${isDragging ? 'opacity-50 scale-95 shadow-inner' : 'shadow-lg'}`}
      style={{ touchAction: 'none' }} // Recommended for better mobile DnD experience
    >
      <div className="text-teal-600">{item.icon}</div>
      <p className="text-lg font-semibold text-slate-700 text-center">{item.name}</p>
    </div>
  );
};

const DropBin: FC<{ bin: Bin; onDrop: (itemType: ItemType) => void }> = ({ bin, onDrop }) => {
  const [{ isOver, canDrop }, drop] = useDrop(() => ({
    accept: 'ITEM',
    drop: (item: { type: ItemType }) => onDrop(item.type),
    collect: (monitor) => ({
      isOver: !!monitor.isOver(),
      canDrop: !!monitor.canDrop(),
    }),
  }));

  const isActive = isOver && canDrop;

  return (
    <div
      ref={drop}
      className={`flex flex-col items-center justify-center p-4 rounded-xl text-white transition-all duration-300 transform ${bin.color} ${isActive ? 'scale-110 shadow-2xl' : 'shadow-lg'} ${canDrop ? '' : 'opacity-70'}`}
    >
      <div className="mb-2 opacity-80">{bin.icon}</div>
      <p className="text-lg font-bold">{bin.name}</p>
    </div>
  );
};

// --- GAME STATE SCREENS ---

const StartScreen: FC<{ onStart: (name: string) => void }> = ({ onStart }) => {
  const [name, setName] = useState('');

  return (
    <div className="w-full max-w-2xl mx-auto bg-white p-8 rounded-2xl shadow-xl border border-gray-100 space-y-6 animate-fade-in">
      <div className="text-center">
        <Recycle className="mx-auto h-12 w-12 text-teal-500" />
        <h1 className="text-4xl font-extrabold text-teal-600 mt-2">EcoSort Master</h1>
        <p className="text-slate-500 mt-2">Learn to recycle the fun way and become a champion for our planet!</p>
      </div>

      <div className="bg-cyan-50/50 p-6 rounded-xl border border-cyan-100 space-y-4">
        <h2 className="text-2xl font-bold text-teal-700">How to Play</h2>
        <p className="text-slate-600">Drag each item to the correct recycling bin. Match the colors to know where each item goes!</p>
        <ul className="space-y-2 pt-2">
          <li className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-green-500"></div><span className="font-medium text-slate-700">Plastic Items</span></li>
          <li className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-blue-500"></div><span className="font-medium text-slate-700">Glass Items</span></li>
          <li className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-yellow-500"></div><span className="font-medium text-slate-700">Paper & Cardboard</span></li>
          <li className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-slate-500"></div><span className="font-medium text-slate-700">Metal Items</span></li>
          <li className="flex items-center gap-3"><div className="w-5 h-5 rounded-full bg-gray-800"></div><span className="font-medium text-slate-700">General Trash</span></li>
        </ul>
        <p className="text-slate-600 !mt-4"><strong className="text-teal-600">Scoring:</strong> Score points for correct answers and build your streak!</p>
      </div>

      <div className="space-y-4">
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Enter your name"
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-teal-400 focus:border-teal-400 transition"
        />
        <button
          onClick={() => onStart(name || 'EcoPlayer')}
          disabled={!name}
          className="w-full bg-teal-500 text-white font-bold py-3 px-4 rounded-lg hover:bg-teal-600 transition-colors disabled:bg-gray-300 disabled:cursor-not-allowed"
        >
          Start Game
        </button>
      </div>
      <p className="text-xs text-center text-slate-400 pt-2">By playing, you agree to our imaginary terms and privacy policy.</p>
    </div>
  );
};

const GameScreen: FC<{ items: RecycleItem[], onGameEnd: (finalScore: number, bestStreak: number) => void }> = ({ items, onGameEnd }) => {
  const [currentItemIndex, setCurrentItemIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [streak, setStreak] = useState(0);
  const [bestStreak, setBestStreak] = useState(0);
  const [feedback, setFeedback] = useState<'correct' | 'incorrect' | null>(null);

  const handleDrop = (droppedItemType: ItemType) => {
    const correctType = items[currentItemIndex].type;
    if (droppedItemType === correctType) {
      setScore(s => s + 10);
      const newStreak = streak + 1;
      setStreak(newStreak);
      if (newStreak > bestStreak) {
        setBestStreak(newStreak);
      }
      setFeedback('correct');
    } else {
      setStreak(0);
      setFeedback('incorrect');
    }

    setTimeout(() => {
      setFeedback(null);
      if (currentItemIndex < items.length - 1) {
        setCurrentItemIndex(i => i + 1);
      } else {
        onGameEnd(score + (droppedItemType === correctType ? 10 : 0), Math.max(bestStreak, streak + (droppedItemType === correctType ? 1 : 0)));
      }
    }, 1200);
  };

  const currentItem = items[currentItemIndex];

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="w-full max-w-5xl mx-auto p-4 md:p-8 space-y-6 relative">
        {feedback && (
          <div className={`absolute inset-0 z-20 flex items-center justify-center rounded-2xl animate-fade-in-out ${feedback === 'correct' ? 'bg-green-500/80' : 'bg-red-500/80'}`}>
            <p className="text-5xl font-extrabold text-white">{feedback === 'correct' ? 'Correct!' : 'Oops!'}</p>
          </div>
        )}
        <header className="flex justify-between items-center bg-white/80 backdrop-blur-sm p-4 rounded-xl shadow-md">
          <div className="text-lg font-bold text-teal-600">Score: <span className="text-2xl text-slate-800">{score}</span></div>
          <div className="text-lg font-bold text-teal-600">Streak: <span className="text-2xl text-slate-800">{streak} <Star className="inline-block w-6 h-6 text-yellow-400 mb-1" /></span></div>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
          <div className="md:col-span-1 flex justify-center">
            <DraggableItem item={currentItem} />
          </div>
          <div className="md:col-span-2 grid grid-cols-2 lg:grid-cols-3 gap-4">
            {BINS.map(bin => (
              <DropBin key={bin.name} bin={bin} onDrop={() => handleDrop(bin.accepts)} />
            ))}
          </div>
        </div>
      </div>
    </DndProvider>
  );
};

const EndScreen: FC<{ name: string; score: number; bestStreak: number; totalItems: number; onPlayAgain: () => void }> = ({ name, score, bestStreak, totalItems, onPlayAgain }) => {
  const accuracy = totalItems > 0 ? ((score / 10) / totalItems * 100).toFixed(0) : 0;
  const updatedLeaderboard = [...mockLeaderboard, { name: `${name} (You)`, score }].sort((a, b) => b.score - a.score).slice(0, 5);

  const achievements = [
    { name: 'Eco-Novice', unlocked: score >= 30, icon: <Award className="w-8 h-8" /> },
    { name: 'Streak Starter', unlocked: bestStreak >= 3, icon: <Star className="w-8 h-8" /> },
    { name: 'Perfect Game!', unlocked: accuracy === '100', icon: <Trophy className="w-8 h-8" /> },
    { name: 'Recycling Rockstar', unlocked: score >= 80, icon: <Trophy className="w-8 h-8" /> },
  ];

  return (
    <div className="w-full max-w-4xl mx-auto bg-white p-8 rounded-2xl shadow-xl border border-gray-100 space-y-8 animate-fade-in">
      <div className="text-center">
        <Trophy className="mx-auto h-12 w-12 text-yellow-500" />
        <h1 className="text-4xl font-extrabold text-teal-600 mt-2">Great Job, {name}!</h1>
        <p className="text-slate-500 mt-2">Here's how you did. Keep practicing to save the planet!</p>
      </div>

      <div className="grid md:grid-cols-3 gap-6">
        <InfoCard icon={<BarChart2 />} title="Statistics" className="md:col-span-1">
          <p><strong>Final Score:</strong> {score}</p>
          <p><strong>Best Streak:</strong> {bestStreak}</p>
          <p><strong>Accuracy:</strong> {accuracy}%</p>
        </InfoCard>

        <InfoCard icon={<Award />} title="Achievements" className="md:col-span-2">
          <div className="grid grid-cols-2 gap-4">
            {achievements.map(ach => (
              <div key={ach.name} className={`flex items-center gap-3 p-2 rounded-lg ${ach.unlocked ? 'bg-green-100 text-green-800' : 'bg-slate-100 text-slate-500'}`}>
                <div className={`${ach.unlocked ? 'text-green-600' : 'text-slate-400'}`}>{ach.icon}</div>
                <span className="font-medium">{ach.name}</span>
              </div>
            ))}
          </div>
        </InfoCard>
      </div>

      <InfoCard icon={<Trophy />} title="Leaderboard">
        <ol className="space-y-3">
          {updatedLeaderboard.map((entry, index) => (
            <li key={index} className={`flex justify-between items-center p-3 rounded-lg ${entry.name.includes('(You)') ? 'bg-teal-100 border-teal-300 border-2' : 'bg-slate-50'}`}>
              <span className="font-bold text-slate-700">{index + 1}. {entry.name}</span>
              <span className="font-semibold text-teal-600">{entry.score} pts</span>
            </li>
          ))}
        </ol>
      </InfoCard>

      <button
        onClick={onPlayAgain}
        className="w-full bg-teal-500 text-white font-bold py-3 px-4 rounded-lg hover:bg-teal-600 transition-colors"
      >
        Play Again
      </button>
    </div>
  );
};

// --- MAIN PAGE COMPONENT ---

const EcoSortMasterPage: NextPage = () => {
  const [gameState, setGameState] = useState<'start' | 'playing' | 'end'>('start');
  const [playerName, setPlayerName] = useState('');
  const [finalScore, setFinalScore] = useState(0);
  const [finalBestStreak, setFinalBestStreak] = useState(0);
  const [shuffledItems, setShuffledItems] = useState<RecycleItem[]>([]);

  useEffect(() => {
    // Shuffle items on initial load
    setShuffledItems([...ITEMS_TO_SORT].sort(() => Math.random() - 0.5));
  }, []);

  const handleStartGame = (name: string) => {
    setPlayerName(name);
    setGameState('playing');
  };

  const handleGameEnd = (score: number, bestStreak: number) => {
    setFinalScore(score);
    setFinalBestStreak(bestStreak);
    setGameState('end');
  };

  const handlePlayAgain = () => {
    // Re-shuffle for a new game
    setShuffledItems([...ITEMS_TO_SORT].sort(() => Math.random() - 0.5));
    setGameState('start');
    setFinalScore(0);
    setFinalBestStreak(0);
  };

  const renderGameState = () => {
    switch (gameState) {
      case 'playing':
        return <GameScreen items={shuffledItems} onGameEnd={handleGameEnd} />;
      case 'end':
        return <EndScreen name={playerName} score={finalScore} bestStreak={finalBestStreak} totalItems={shuffledItems.length} onPlayAgain={handlePlayAgain} />;
      case 'start':
      default:
        return <StartScreen onStart={handleStartGame} />;
    }
  };

  return (
    <main className="min-h-screen w-full bg-cyan-50 flex items-center justify-center p-4 font-sans">
      <style jsx global>{`
        @keyframes fade-in {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes fade-in-out {
          0%, 100% { opacity: 0; }
          20%, 80% { opacity: 1; }
        }
        .animate-fade-in { animation: fade-in 0.5s ease-out forwards; }
        .animate-fade-in-out { animation: fade-in-out 1.2s ease-in-out forwards; }
      `}</style>
      {renderGameState()}
    </main>
  );
};

export default EcoSortMasterPage;


