            <span className="font-medium text-amber-900">{option}</span>
          </button>
        ))}
      </div>
      <ActionButton onClick={onNext} className={!selectedAnswer ? 'opacity-50 cursor-not-allowed' : ''} >
        {isLastQuestion ? 'Submit Exam' : 'Next Question'}
      </ActionButton>
    </Card>
  );
};

const ResultsView: FC<{ 
  examQuestions: Question[];
  userAnswers: (string | null)[];
  onRestart: () => void;
  onHome: () => void;
}> = ({ examQuestions, userAnswers, onRestart, onHome }) => {
  const score = useMemo(() => 
    examQuestions.reduce((acc, question, index) => 
      acc + (question.answer === userAnswers[index] ? 1 : 0), 0)
  , [examQuestions, userAnswers]);

  return (
    <Card>
      <h2 className="text-2xl font-bold text-amber-900 text-center">Exam Complete!</h2>
      <div className="text-center my-6">
        <p className="text-amber-800">You scored</p>
        <p className="text-6xl font-bold text-amber-900 my-2">{score} / {examQuestions.length}</p>
        <p className={`font-semibold ${score / examQuestions.length >= 0.7 ? 'text-green-600' : 'text-red-600'}`}>
          {score / examQuestions.length >= 0.7 ? 'Great job! You passed.' : 'Keep practicing to improve.'}
        </p>
      </div>

      <div className="border-t border-amber-200/80 pt-6">
        <h3 className="font-bold text-lg text-amber-900 mb-4">Review Your Answers</h3>
        <div className="space-y-4">
          {examQuestions.map((q, i) => {
            const userAnswer = userAnswers[i];
            const isCorrect = q.answer === userAnswer;
            return (
              <div key={q.id} className="border border-amber-200/80 rounded-lg p-4">
                <p className="font-semibold text-amber-900 mb-2">{q.text}</p>
                <div className={`flex items-center gap-2 p-2 rounded-md ${isCorrect ? 'bg-green-100/70' : 'bg-red-100/70'}`}>
                  {isCorrect ? <CheckCircle2 className="h-5 w-5 text-green-700 flex-shrink-0" /> : <XCircle className="h-5 w-5 text-red-700 flex-shrink-0" />}
                  <p className={`text-sm font-medium ${isCorrect ? 'text-green-800' : 'text-red-800'}`}>Your answer: {userAnswer || 'Not answered'}</p>
                </div>
                {!isCorrect && (
                  <div className="flex items-center gap-2 p-2 mt-2 rounded-md bg-green-100/70">
                     <CheckCircle2 className="h-5 w-5 text-green-700 flex-shrink-0" />
                     <p className="text-sm font-medium text-green-800">Correct answer: {q.answer}</p>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-4 mt-8">
        <ActionButton onClick={onRestart} className="bg-amber-100 text-amber-900 hover:bg-amber-200">
          <RefreshCw className="h-4 w-4 mr-2" /> Try Again
        </ActionButton>
        <ActionButton onClick={onHome}>Back to Home</ActionButton>
      </div>
    </Card>
  );
};

// --- MAIN PAGE COMPONENT ---

const DriverLicensePrepPage: NextPage = () => {
  const [view, setView] = useState<'home' | 'practice' | 'exam' | 'results'>('home');
  const [examQuestions, setExamQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [userAnswers, setUserAnswers] = useState<(string | null)[]>([]);

  const handleStartPractice = () => setView('practice');

  const handleStartExam = () => {
    const shuffled = [...questionsDatabase].sort(() => 0.5 - Math.random());
    const selectedQuestions = shuffled.slice(0, 3);
    setExamQuestions(selectedQuestions);
    setUserAnswers(new Array(3).fill(null));
    setCurrentQuestionIndex(0);
    setView('exam');
  };

  const handleSelectAnswer = (answer: string) => {
    const newAnswers = [...userAnswers];
    newAnswers[currentQuestionIndex] = answer;
    setUserAnswers(newAnswers);
  };

  const handleNextQuestion = () => {
    if (userAnswers[currentQuestionIndex] === null) return; // Prevent proceeding without an answer

    if (currentQuestionIndex < examQuestions.length - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
    } else {
      setView('results');
    }
  };

  const handleGoHome = () => {
    setView('home');
    // Reset state for a clean start next time
    setExamQuestions([]);
    setCurrentQuestionIndex(0);
    setUserAnswers([]);
  };

  const renderContent = () => {
    switch (view) {
      case 'practice':
        return <PracticeView onBack={handleGoHome} />;
      case 'exam':
        return (
          <ExamView
            examQuestions={examQuestions}
            currentQuestionIndex={currentQuestionIndex}
            selectedAnswer={userAnswers[currentQuestionIndex]}
            onSelectAnswer={handleSelectAnswer}
            onNext={handleNextQuestion}
          />
        );
      case 'results':
        return (
          <ResultsView
            examQuestions={examQuestions}
            userAnswers={userAnswers}
            onRestart={handleStartExam}
            onHome={handleGoHome}
          />
        );
      case 'home':
      default:
        return <HomeView onStartPractice={handleStartPractice} onStartExam={handleStartExam} />;
    }
  };

  return (
    <main className="bg-amber-50 min-h-screen w-full text-amber-900 antialiased">
      <div className="container mx-auto px-4 py-8 sm:py-12 md:py-16">
        <header className="text-center mb-8 sm:mb-12">
          <h1 className="text-4xl sm:text-5xl font-extrabold text-amber-900 tracking-tight">Driver's License Prep Hub</h1>
          <p className="mt-3 text-lg text-amber-700/90 max-w-2xl mx-auto">Your one-stop destination to ace the DMV exam with confidence.</p>
        </header>
        <div className="max-w-4xl mx-auto">
          {renderContent()}
        </div>
      </div>
    </main>
  );
};

export default DriverLicensePrepPage;


