interface StarRatingProps {
  rating: number;
  size?: number;
  className?: string;
}

const StarRating: FC<StarRatingProps> = ({ rating, size = 4, className = '' }) => {
  const fullStars = Math.floor(rating);
  const halfStar = rating % 1 !== 0;
  const emptyStars = 5 - fullStars - (halfStar ? 1 : 0);

  return (
    <div className={`flex items-center ${className}`}>
      {[...Array(fullStars)].map((_, i) => (
        <Star key={`full-${i}`} className={`h-${size} w-${size} text-yellow-400 fill-yellow-400`} />
      ))}
      {halfStar && <Star key="half" className={`h-${size} w-${size} text-yellow-400`} fill="url(#half_grad)" />}
      {[...Array(emptyStars)].map((_, i) => (
        <Star key={`empty-${i}`} className={`h-${size} w-${size} text-stone-600`} />
      ))}
      <svg width="0" height="0">
        <defs>
          <linearGradient id="half_grad">
            <stop offset="50%" stopColor="#FBBF24" />
            <stop offset="50%" stopColor="#44403C" stopOpacity="1" />
          </linearGradient>
        </defs>
      </svg>
    </div>
  );
};

interface RatingSelectionProps {
  rating: number;
  setRating: (rating: number) => void;
}

const RatingSelection: FC<RatingSelectionProps> = ({ rating, setRating }) => {
  const [hoverRating, setHoverRating] = useState(0);

  return (
    <div className="flex items-center space-x-1">
      {[1, 2, 3, 4, 5].map((star) => (
        <button
          key={star}
          onClick={() => setRating(star)}
          onMouseEnter={() => setHoverRating(star)}
          onMouseLeave={() => setHoverRating(0)}
          className="focus:outline-none"
        >
          <Star
            className={`h-8 w-8 cursor-pointer transition-colors duration-200 ${ 
              (hoverRating || rating) >= star ? 'text-yellow-400 fill-yellow-400' : 'text-stone-500' 
            }`}
          />
        </button>
      ))}
    </div>
  );
};

