const AddObituaryModal: FC<{ isOpen: boolean; onClose: () => void; onAdd: (obituary: Omit<Obituary, 'id' | 'condolences'>) => void; }> = ({ isOpen, onClose, onAdd }) => {
  const [name, setName] = useState('');
  const [lifespan, setLifespan] = useState('');
  const [description, setDescription] = useState('');

  useEffect(() => {
    if (!isOpen) {
        setName('');
        setLifespan('');
        setDescription('');
    }
  }, [isOpen]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (name && lifespan && description) {
      onAdd({ name, lifespan, description });
      onClose();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6 sm:p-8 relative" onClick={e => e.stopPropagation()}>
        <button onClick={onClose} className="absolute top-4 right-4 text-stone-500 hover:text-stone-800 transition-colors">
          <X size={24} />
        </button>
        <h2 className="text-2xl font-bold text-stone-800 mb-6">Add a New Obituary</h2>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label htmlFor="name" className="block text-sm font-medium text-stone-600 mb-1">Name</label>
            <input id="name" type="text" value={name} onChange={e => setName(e.target.value)} placeholder="e.g., John Doe" required className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-amber-500 transition" />
          </div>
          <div>
            <label htmlFor="lifespan" className="block text-sm font-medium text-stone-600 mb-1">Lifespan</label>
            <input id="lifespan" type="text" value={lifespan} onChange={e => setLifespan(e.target.value)} placeholder="e.g., 1940 - 2024" required className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-amber-500 transition" />
          </div>
          <div>
            <label htmlFor="description" className="block text-sm font-medium text-stone-600 mb-1">Description</label>
            <textarea id="description" value={description} onChange={e => setDescription(e.target.value)} rows={4} placeholder="Share a few words about their life..." required className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-amber-500 transition"></textarea>
          </div>
          <div className="flex justify-end pt-4">
            <button type="submit" className="bg-amber-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-amber-700 transition-transform transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-500">
