          <button onClick={() => onDelete(obituary.id)} className="text-stone-400 hover:text-red-500 transition-colors p-1 rounded-full hover:bg-red-50">
            <Trash2 size={20} />
          </button>
        </div>
        <p className="text-stone-600 mt-4 text-base leading-relaxed">{obituary.description}</p>
      </div>

      <div className="p-6 bg-stone-50/70">
        <h4 className="font-semibold text-stone-700 mb-3">Multimedia Memories</h4>
        <div className="flex items-center space-x-3">
