            <ImageIcon size={16} className="text-blue-500" /><span>Image</span>
          </button>
          <button className="flex items-center space-x-2 px-3 py-1.5 bg-white border border-stone-300 rounded-full text-sm font-medium text-stone-600 hover:bg-stone-100 transition">
            <Video size={16} className="text-red-500" /><span>Video</span>
