            <Mic size={16} className="text-green-500" /><span>Audio</span>
          </button>
        </div>
      </div>

      <div className="p-6 flex-grow flex flex-col">
        <h4 className="font-semibold text-stone-700 mb-4">Condolences ({obituary.condolences.length})</h4>
