const FamilyMemoryPortalPage: NextPage = () => {
  const [obituaries, setObituaries] = useState<Obituary[]>(initialObituaries);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState('obituaries');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const filteredObituaries = useMemo(() =>
    obituaries.filter(o =>
      o.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      o.description.toLowerCase().includes(searchTerm.toLowerCase())
    ), [obituaries, searchTerm]);

  const handleAddObituary = (data: Omit<Obituary, 'id' | 'condolences'>) => {
    const newObituary: Obituary = {
      id: Date.now(),
      ...data,
      condolences: [],
    };
    setObituaries(prev => [newObituary, ...prev]);
  };

  const handleDeleteObituary = (id: number) => {
    if (window.confirm('Are you sure you want to delete this obituary?')) {
        setObituaries(prev => prev.filter(o => o.id !== id));
    }
  };

  const handleAddCondolence = (obituaryId: number, text: string) => {
    setObituaries(prev =>
      prev.map(o =>
        o.id === obituaryId
          ? { ...o, condolences: [...o.condolences, { id: Date.now(), text }] }
          : o
      )
    );
  };

  const statsData = useMemo(() => {
    return obituaries.map(o => ({ name: o.name, condolences: o.condolences.length })).sort((a,b) => b.condolences - a.condolences);
  }, [obituaries]);

  const totalCondolences = useMemo(() => obituaries.reduce((sum, o) => sum + o.condolences.length, 0), [obituaries]);

  return (
    <div className="bg-orange-50 text-stone-800 min-h-screen font-sans">
      <AddObituaryModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onAdd={handleAddObituary} />
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-12">
        <header className="text-center mb-12">
          <h1 className="text-4xl sm:text-5xl font-extrabold text-stone-900 tracking-tight">Family Memory Portal</h1>
          <p className="mt-3 max-w-2xl mx-auto text-lg text-stone-600">Remembering and celebrating our loved ones.</p>
        </header>

        <div className="mb-8 p-4 bg-white/60 backdrop-blur-sm rounded-2xl shadow-sm border border-stone-200/80 sticky top-4 z-10">
          <div className="flex flex-col sm:flex-row gap-4 justify-between items-center">
            <div className="relative w-full sm:max-w-xs">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" size={20} />
              <input type="text" placeholder="Find an obituary..." value={searchTerm} onChange={(e: ChangeEvent<HTMLInputElement>) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-amber-500 transition" />
            </div>
            <div className="flex items-center border border-stone-200 bg-stone-100 rounded-lg p-1">
              <button onClick={() => setActiveTab('obituaries')} className={`px-4 py-1.5 rounded-md text-sm font-semibold transition-colors ${activeTab === 'obituaries' ? 'bg-white shadow-sm text-amber-700' : 'text-stone-600 hover:text-stone-800'}`}>Obituaries</button>
              <button onClick={() => setActiveTab('statistics')} className={`px-4 py-1.5 rounded-md text-sm font-semibold transition-colors ${activeTab === 'statistics' ? 'bg-white shadow-sm text-amber-700' : 'text-stone-600 hover:text-stone-800'}`}>Statistics</button>
            </div>
          </div>
        </div>

        {activeTab === 'obituaries' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredObituaries.map(obituary => (
              <ObituaryCard key={obituary.id} obituary={obituary} onDelete={handleDeleteObituary} onAddCondolence={handleAddCondolence} />
            ))}
            <div onClick={() => setIsModalOpen(true)} className="bg-stone-100 border-2 border-dashed border-stone-300 rounded-2xl flex flex-col items-center justify-center text-center p-6 cursor-pointer hover:bg-stone-200 hover:border-amber-500 transition-all group">
              <div className="bg-white rounded-full p-4 border border-stone-300 group-hover:border-amber-500 transition-colors mb-4">
                <Plus size={32} className="text-amber-600" />
              </div>
              <h3 className="font-bold text-xl text-stone-800">Add Obituary</h3>
              <p className="text-stone-500 mt-1">Create a new memorial for a loved one.</p>
            </div>
          </div>
        )}

        {activeTab === 'statistics' && (
          <div className="bg-white p-6 sm:p-8 rounded-2xl shadow-lg border border-stone-200/80">
            <h2 className="text-3xl font-bold text-stone-900 mb-8">Portal Statistics</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-10">
              <div className="bg-stone-100 p-6 rounded-xl">
                <h3 className="text-sm font-medium text-stone-500">Total Obituaries</h3>
                <p className="text-4xl font-bold text-amber-700 mt-1">{obituaries.length}</p>
              </div>
              <div className="bg-stone-100 p-6 rounded-xl">
                <h3 className="text-sm font-medium text-stone-500">Total Condolences</h3>
                <p className="text-4xl font-bold text-amber-700 mt-1">{totalCondolences}</p>
              </div>
            </div>
            <h3 className="text-2xl font-bold text-stone-800 mb-6">Condolences per Person</h3>
            <div style={{ width: '100%', height: 400 }}>
              <ResponsiveContainer>
                <BarChart data={statsData} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                  <XAxis dataKey="name" stroke="#57534e" />
                  <YAxis allowDecimals={false} stroke="#57534e" />
                  <Tooltip cursor={{fill: 'rgba(212, 175, 55, 0.1)'}} contentStyle={{ backgroundColor: 'white', border: '1px solid #e5e7eb', borderRadius: '0.75rem' }} />
                  <Legend />
                  <Bar dataKey="condolences" fill="#b45309" name="Condolences" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

