border-amber-500 transition-all group">\n              <div className="bg-white rounded-full p-4 border border-stone-300 group-hover:border-amber-500 transition-colors mb-4">\n                <Plus size={32} className="text-amber-600" />\n              </div>\n              <h3 className="font-bold text-xl text-stone-800">Add Obituary</h3>\n              <p className="text-stone-500 mt-1">Create a new memorial for a loved one.</p>\n            </div>\n          </div>\n        )}\n\n        {activeTab === \'statistics\' && (\n          <div className="bg-white p-6 sm:p-8 rounded-2xl shadow-lg border border-stone-200/80">\n            <h2 className="text-3xl font-bold text-stone-900 mb-8">Portal Statistics</h2>\n            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-10">\n              <div className="bg-stone-100 p-6 rounded-xl">\n                <h3 className="text-sm font-medium text-stone-500">Total Obituaries</h3>\n                <p className="text-4xl font-bold text-amber-700 mt-1">{obituaries.length}</p>\n              </div>\n              <div className="bg-stone-100 p-6 rounded-xl">\n                <h3 className="text-sm font-medium text-stone-500">Total Condolences</h3>\n                <p className="text-4xl font-bold text-amber-700 mt-1">{totalCondolences}</p>\n              </div>\n            </div>\n            <h3 className="text-2xl font-bold text-stone-800 mb-6">Condolences per Person</h3>\n            <div style={{ width: \'100%\', height: 400 }}>\n              <ResponsiveContainer>\n                <BarChart data={statsData} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>\n                  <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />\n                  <XAxis dataKey="name" stroke="#57534e" />\n                  <YAxis allowDecimals={false} stroke="#57534e" />\n                  <Tooltip cursor={{fill: \'rgba(212, 175, 55, 0.1)\'}} contentStyle={{ backgroundColor: \'white\', border: \'1px solid #e5e7eb\', borderRadius: \'0.75rem\' }} />\n                  <Legend />\n                  <Bar dataKey="condolences" fill="#b45309" name="Condolences" radius={[4, 4, 0, 0]} />\n                </BarChart>\n              </ResponsiveContainer>\n            </div>\n          </div>\n        )}\n      </main>\n    </div>\n  );\n};\n\nexport default FamilyMemoryPortalPage;\n'}

import { useState, useEffect, FC, useMemo } from 'react';
import type { AppProps } from 'next/app';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Sun, Wind, Droplets, Thermometer, RefreshCw, AlertTriangle, Leaf, Factory, Cloud, BarChart, Check, X } from 'lucide-react';

// --- TYPESCRIPT DEFINITIONS ---
type Pollutant = 'AQI' | 'PM2.5' | 'PM10' | 'O3' | 'NO2' | 'CO' | 'SO2';

interface WeatherData {
  temperature: number;
  humidity: number;
  windSpeed: number;
  uvIndex: number;
  condition: 'Sunny' | 'Cloudy' | 'Rainy';
}

interface AirQualityData {
  aqi: number;
  level: 'Good' | 'Moderate' | 'Unhealthy for Sensitive Groups' | 'Unhealthy' | 'Very Unhealthy' | 'Hazardous';
  dominantPollutant: Pollutant;
  pollutants: Record<Exclude<Pollutant, 'AQI'>, number>;
}

interface HistoricalDataPoint {
  date: string;
  'AQI': number;
  'PM2.5': number;
  'PM10': number;
  'O3': number;
  'NO2': number;
  'CO': number;
  'SO2': number;
  temperature: number;
  humidity: number;
}

// --- MOCK DATA GENERATION ---
const generateHistoricalData = (): HistoricalDataPoint[] => {
  const data: HistoricalDataPoint[] = [];
  const today = new Date();
  for (let i = 13; i >= 0; i--) {
    const date = new Date(today);
    date.setDate(today.getDate() - i);
    data.push({
      date: date.toLocaleDateString('en-US', { month: 'numeric', day: 'numeric' }),
      'AQI': 50 + Math.floor(Math.random() * 50),
      'PM2.5': 10 + Math.floor(Math.random() * 25),
      'PM10': 20 + Math.floor(Math.random() * 30),
      'O3': 30 + Math.floor(Math.random() * 40),
      'NO2': 15 + Math.floor(Math.random() * 20),
      'CO': 1 + Math.floor(Math.random() * 5),
      'SO2': 2 + Math.floor(Math.random() * 8),
      temperature: 20 + Math.floor(Math.random() * 10),
      humidity: 50 + Math.floor(Math.random() * 30),
    });
  }
  // Required element: Tooltip for a specific date (mocking it)
  const specificDateIndex = data.findIndex(d => d.date === new Date('2025-07-24').toLocaleDateString('en-US', { month: 'numeric', day: 'numeric' }));
  if (specificDateIndex !== -1) {
    data[specificDateIndex]['AQI'] = 110;
  } else if (data.length > 5) {
    data[5].date = '7/24';
    data[5]['AQI'] = 110;
  }
  return data;
};

const generateDashboardData = () => {
  const aqi = 60 + Math.floor(Math.random() * 50);
  let level: AirQualityData['level'] = 'Good';
  if (aqi > 50) level = 'Moderate';
  if (aqi > 100) level = 'Unhealthy for Sensitive Groups';
  if (aqi > 150) level = 'Unhealthy';
  if (aqi > 200) level = 'Very Unhealthy';
  if (aqi > 300) level = 'Hazardous';

  return {
    weather: {
      temperature: 25,
      humidity: 60 + Math.floor(Math.random() * 10),
      windSpeed: 10 + Math.floor(Math.random() * 5),
      uvIndex: 5 + Math.floor(Math.random() * 2),
      condition: 'Sunny' as WeatherData['condition'],
    },
    airQuality: {
      aqi: 85, // Static for the required element
      level,
      dominantPollutant: 'PM2.5' as Pollutant,
      pollutants: {
        'PM2.5': 12, // Static for the required element
        'PM10': 30 + Math.floor(Math.random() * 10),
        'O3': 50 + Math.floor(Math.random() * 20),
        'NO2': 25 + Math.floor(Math.random() * 10),
        'CO': 3 + Math.floor(Math.random() * 2),
        'SO2': 5 + Math.floor(Math.random() * 3),
      },
    },
    historicalData: generateHistoricalData(),
  };
};

// --- HELPER COMPONENTS ---

const Card: FC<{ children: React.ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-white rounded-xl shadow-md p-6 ${className}`}>{children}</div>
);

const WeatherCard: FC<{ icon: React.ReactNode; title: string; value: string; unit: string }> = ({ icon, title, value, unit }) => (
  <div className="flex items-center space-x-4">
    <div className="bg-sky-100 text-sky-600 p-3 rounded-full">{icon}</div>
    <div>
      <p className="text-slate-500 text-sm">{title}</p>
      <p className="text-slate-800 text-xl font-bold">
        {value}<span className="text-sm font-normal">{unit}</span>
      </p>
    </div>
  </div>
);

const PollutantButton: FC<{ pollutant: Pollutant; selected: boolean; onClick: () => void; isCompareMode: boolean; isCompared: boolean }> = ({ pollutant, selected, onClick, isCompareMode, isCompared }) => (
  <button
    onClick={onClick}
    className={`px-4 py-2 text-sm font-semibold rounded-full transition-all duration-200 flex items-center space-x-2 ${selected && !isCompareMode ? 'bg-slate-800 text-white shadow-lg' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}>
    <span>{pollutant}</span>
    {isCompareMode && (isCompared ? <Check size={16} className="text-green-500" /> : <X size={16} className="text-slate-400" />)}
  </button>
);

const aqiColor = (aqi: number): string => {
  if (aqi <= 50) return 'text-green-500 border-green-500';
  if (aqi <= 100) return 'text-yellow-500 border-yellow-500';
  if (aqi <= 150) return 'text-orange-500 border-orange-500';
  if (aqi <= 200) return 'text-red-500 border-red-500';
  if (aqi <= 300) return 'text-purple-500 border-purple-500';
  return 'text-maroon-500 border-maroon-500'; // Fictional color
};

const pollutantDetails: Record<Exclude<Pollutant, 'AQI'>, { name: string; icon: React.ReactNode }> = {
    'PM2.5': { name: 'Particulate Matter <2.5μm', icon: <Factory size={16} /> },
    'PM10': { name: 'Particulate Matter <10μm', icon: <Factory size={16} /> },
    'NO2': { name: 'Nitrogen Dioxide', icon: <Cloud size={16} /> },
    'O3': { name: 'Ozone', icon: <Sun size={16} /> },
    'CO': { name: 'Carbon Monoxide', icon: <AlertTriangle size={16} /> },
    'SO2': { name: 'Sulphur Dioxide', icon: <AlertTriangle size={16} /> },
};

const pollutantChartColors: Record<Pollutant, string> = {
    'AQI': '#2F4F4F', // dark slate blue
    'PM2.5': '#ef4444', // red-500
    'PM10': '#f97316', // orange-500
    'O3': '#eab308', // yellow-500
    'NO2': '#84cc16', // lime-500
    'CO': '#3b82f6', // blue-500
    'SO2': '#8b5cf6', // violet-500
}

// --- MAIN COMPONENT ---
const EnvironmentalDashboardPage: FC = () => {
  const [data, setData] = useState(generateDashboardData());
  const [selectedPollutant, setSelectedPollutant] = useState<Pollutant>('PM2.5');
  const [isCompareMode, setCompareMode] = useState(false);
  const [comparedPollutants, setComparedPollutants] = useState<Pollutant[]>(['AQI']);

  const handleRefresh = () => {
    setData(generateDashboardData());
  };

  useEffect(() => {
    // Initial data load
  }, []);

  const handlePollutantSelect = (pollutant: Pollutant) => {
    if (isCompareMode) {
        setComparedPollutants(prev => 
            prev.includes(pollutant) 
            ? prev.filter(p => p !== pollutant)
            : [...prev, pollutant]
        );
    } else {
        setSelectedPollutant(pollutant);
        setComparedPollutants([pollutant]);
    }
  };

  const chartPollutants = useMemo(() => isCompareMode ? comparedPollutants : [selectedPollutant], [isCompareMode, comparedPollutants, selectedPollutant]);

  return (
    <main className="bg-slate-50 min-h-screen p-4 sm:p-6 lg:p-8 font-sans text-slate-800">
      <div className="max-w-7xl mx-auto">
        {/* Header Section */}
        <header className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-bold text-slate-900">Environmental Warning System</h1>
            <p className="text-slate-500">Real-time weather and air quality monitoring.</p>
          </div>
          {/* Refresh Data: Card displaying refresh data option (as a button) */}
          <button onClick={handleRefresh} className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-200 rounded-lg shadow-sm hover:bg-slate-100 transition-colors">
            <RefreshCw size={16} />
            <span className="hidden sm:inline">Refresh Data</span>
          </button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Column */}
          <div className="lg:col-span-1 space-y-6">
            {/* Current Weather Conditions Card */}
            <Card className="bg-sky-50/50 border border-sky-100">
                <h2 className="font-bold text-lg mb-4 text-slate-700">Current Weather Conditions</h2>
                <div className="space-y-4">
                    {/* Sunny 25°C: Card showing sunny weather condition */}
                    <WeatherCard icon={<Thermometer size={24} />} title="Temperature" value={data.weather.temperature.toString()} unit="°C" />
                    <WeatherCard icon={<Droplets size={24} />} title="Humidity" value={data.weather.humidity.toString()} unit="%" />
                    <WeatherCard icon={<Wind size={24} />} title="Wind Speed" value={data.weather.windSpeed.toString()} unit=" km/h" />
                    <WeatherCard icon={<Sun size={24} />} title="UV Index" value={data.weather.uvIndex.toString()} unit="" />
                </div>
            </Card>

            {/* Air Quality Index Card */}
            <Card>
              <h2 className="font-bold text-lg mb-4 text-slate-700">Air Quality Index (AQI)</h2>
              <div className="flex flex-col items-center justify-center space-y-4">
                <div className={`relative w-40 h-40 rounded-full flex items-center justify-center border-8 ${aqiColor(data.airQuality.aqi)}`}>
                    {/* 85: Card showing air quality index value */}
                    <span className="text-4xl font-bold text-slate-800">{data.airQuality.aqi}</span>
                </div>
                <div className="text-center">
                    <p className={`text-xl font-semibold ${aqiColor(data.airQuality.aqi).split(' ')[0]}`}>{data.airQuality.level}</p>
                    <p className="text-sm text-slate-500">Dominant Pollutant: {data.airQuality.dominantPollutant}</p>
                </div>
              </div>
            </Card>
          </div>

          {/* Right Column */}
          <div className="lg:col-span-2 space-y-6">
            {/* Pollutant Levels Card */}
            <Card>
                <h2 className="font-bold text-lg mb-4 text-slate-700">Pollutant Levels</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-center">
                    {/* PM2.5 12µg/m³ Card */}
                    <div className="bg-slate-100 rounded-lg p-4 flex items-center space-x-4">
                        <div className="text-slate-600 p-3 rounded-full bg-white shadow-inner">
                            {pollutantDetails[selectedPollutant as Exclude<Pollutant, 'AQI'>]?.icon || <Leaf size={24} />}
                        </div>
                        <div>
                            <p className="text-slate-800 text-2xl font-bold">{data.airQuality.pollutants[selectedPollutant as Exclude<Pollutant, 'AQI'>]}<span className="text-sm font-normal text-slate-500"> µg/m³</span></p>
                            <p className="text-sm text-slate-500">{pollutantDetails[selectedPollutant as Exclude<Pollutant, 'AQI'>]?.name}</p>
                        </div>
                    </div>
                    {/* Pollutant Selection Buttons */}
                    <div className="flex flex-wrap gap-2 justify-start md:justify-end">
                        <PollutantButton pollutant="PM2.5" selected={selectedPollutant === 'PM2.5'} onClick={() => handlePollutantSelect('PM2.5')} isCompareMode={false} isCompared={false}/>
                        <PollutantButton pollutant="PM10" selected={selectedPollutant === 'PM10'} onClick={() => handlePollutantSelect('PM10')} isCompareMode={false} isCompared={false}/>
                        <PollutantButton pollutant="NO2" selected={selectedPollutant === 'NO2'} onClick={() => handlePollutantSelect('NO2')} isCompareMode={false} isCompared={false}/>
                        <PollutantButton pollutant="O3" selected={selectedPollutant === 'O3'} onClick={() => handlePollutantSelect('O3')} isCompareMode={false} isCompared={false}/>
                        <PollutantButton pollutant="CO" selected={selectedPollutant === 'CO'} onClick={() => handlePollutantSelect('CO')} isCompareMode={false} isCompared={false}/>
                        <PollutantButton pollutant="SO2" selected={selectedPollutant === 'SO2'} onClick={() => handlePollutantSelect('SO2')} isCompareMode={false} isCompared={false}/>
                    </div>
                </div>
            </Card>

            {/* Pollutant Trend Section */}
            <Card>
                <div className="flex flex-wrap justify-between items-center mb-4 gap-2">
                    <h2 className="font-bold text-lg text-slate-700">Pollutant Trend</h2>
                    <div className="flex items-center gap-2 flex-wrap">
                        {/* Pollutant selection for chart */}
                        {(['AQI', 'PM2.5', 'PM10', 'O3', 'NO2', 'CO', 'SO2'] as Pollutant[]).map(p => (
                            <PollutantButton key={p} pollutant={p} selected={chartPollutants.includes(p)} onClick={() => handlePollutantSelect(p)} isCompareMode={isCompareMode} isCompared={comparedPollutants.includes(p)}/>
                        ))}
                        <button onClick={() => setCompareMode(!isCompareMode)} className={`px-4 py-2 text-sm font-semibold rounded-full transition-colors ${isCompareMode ? 'bg-sky-600 text-white' : 'bg-slate-200 text-slate-800'}`}>
                            Compare
                        </button>
                    </div>
                </div>
                {/* Pollutant Trend Line Chart */}
                <div className="h-72 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <LineChart data={data.historicalData} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                            <XAxis dataKey="date" tick={{ fontSize: 12 }} stroke="#64748b" />
                            <YAxis tick={{ fontSize: 12 }} stroke="#64748b" />
                            <Tooltip
                                contentStyle={{ backgroundColor: 'white', border: '1px solid #e2e8f0', borderRadius: '0.5rem' }}
                                labelStyle={{ fontWeight: 'bold', color: '#2F4F4F' }}
                                // Required: Tooltip for 7/24/2025 (mocked as 7/24)
                                formatter={(value, name, props) => [`${value}`, name]} 
                            />
                            <Legend iconType="circle" iconSize={8} />
                            {chartPollutants.map(pollutant => (
                                <Line key={pollutant} type="monotone" dataKey={pollutant} stroke={pollutantChartColors[pollutant]} strokeWidth={2} dot={false} activeDot={{ r: 6 }} />
                            ))}
                        </LineChart>
                    </ResponsiveContainer>
                </div>
            </Card>
          </div>
        </div>

        {/* Historical Air Quality Data Table */}
        <div className="mt-6">
            <Card>
                <h2 className="font-bold text-lg mb-4 text-slate-700">Historical Air Quality Data (Last 14 Days)</h2>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-slate-600">
                        <thead className="text-xs text-slate-700 uppercase bg-slate-100">
                            <tr>
                                <th scope="col" className="px-6 py-3">Date</th>
                                <th scope="col" className="px-6 py-3">AQI</th>
                                <th scope="col" className="px-6 py-3">PM2.5 (µg/m³)</th>
                                <th scope="col" className="px-6 py-3">PM10 (µg/m³)</th>
                                <th scope="col" className="px-6 py-3">Temp (°C)</th>
                                <th scope="col" className="px-6 py-3">Humidity (%)</th>
                            </tr>
                        </thead>
                        <tbody>
                            {data.historicalData.slice().reverse().map((d) => (
                                <tr key={d.date} className="bg-white border-b last:border-b-0 border-slate-200 hover:bg-slate-50">
                                    <th scope="row" className="px-6 py-4 font-medium text-slate-900 whitespace-nowrap">{d.date}</th>
                                    <td className={`px-6 py-4 font-bold ${aqiColor(d.AQI).split(' ')[0]}`}>{d.AQI}</td>
                                    <td className="px-6 py-4">{d['PM2.5']}</td>
                                    <td className="px-6 py-4">{d['PM10']}</td>
                                    <td className="px-6 py-4">{d.temperature}</td>
                                    <td className="px-6 py-4">{d.humidity}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </Card>
        </div>
      </div>
    </main>
  );
};

