import { Search, PlusCircle, Filter, MessageCircle, ArrowLeft, BookOpen, User, Calendar, X } from 'lucide-react';

// TYPE DEFINITIONS
type Comment = {
  id: number;
  author: string;
  text: string;
};

type Poem = {
  id: number;
  title: string;
  author: string;
  date: string;
  content: string;
  type: 'Sonnet' | 'Haiku' | 'Free Verse' | 'Limerick';
