// HELPER COMPONENTS
const Card: FC<{ children: ReactNode; className?: string }> = ({ children, className }) => (
  <div className={`bg-white rounded-2xl shadow-md p-6 ${className}`}>{children}</div>
);

const IconButton: FC<{ icon: ReactNode; onClick: () => void; children?: ReactNode; className?: string }> = ({ icon, onClick, children, className }) => (
  <button onClick={onClick} className={`flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors ${className}`}>
    {icon}
    {children}
