// MAIN PAGE COMPONENT
const PoeticMuseGallery: NextPage = () => {
  const [view, setView] = useState<'home' | 'add' | 'poem'>('home');
  const [poems, setPoems] = useState<Poem[]>(initialPoems);
  const [selectedPoemId, setSelectedPoemId] = useState<number | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<string>('all');

  // Form state
  const [newPoemTitle, setNewPoemTitle] = useState('');
  const [newPoemContent, setNewPoemContent] = useState('');
  const [newPoemType, setNewPoemType] = useState<Poem['type']>('Free Verse');

  // Comment state
  const [newComment, setNewComment] = useState('');

  const filteredPoems = useMemo(() => {
    return poems
      .filter(poem => poem.title.toLowerCase().includes(searchQuery.toLowerCase()) || poem.author.toLowerCase().includes(searchQuery.toLowerCase()))
      .filter(poem => filterType === 'all' || poem.type === filterType);
  }, [poems, searchQuery, filterType]);

  const selectedPoem = useMemo(() => poems.find(p => p.id === selectedPoemId), [poems, selectedPoemId]);

  const handleAddPoem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPoemTitle || !newPoemContent) return;
    const newPoem: Poem = {
      id: Date.now(),
      title: newPoemTitle,
      author: "Anonymous", // Or implement user login
      date: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }),
      content: newPoemContent,
      type: newPoemType,
      comments: [],
    };
    setPoems([newPoem, ...poems]);
    setNewPoemTitle('');
    setNewPoemContent('');
    setNewPoemType('Free Verse');
    setView('home');
  };

  const handleAddComment = () => {
    if (!newComment.trim() || !selectedPoemId) return;
    const updatedPoems = poems.map(poem => {
      if (poem.id === selectedPoemId) {
        const newCommentObj: Comment = {
          id: Date.now(),
          author: "Guest",
          text: newComment,
        };
        return { ...poem, comments: [...poem.comments, newCommentObj] };
      }
      return poem;
    });
    setPoems(updatedPoems);
    setNewComment('');
  };

  const renderHeader = () => (
    <header className="bg-slate-800 text-white p-4 shadow-lg sticky top-0 z-20">
