        <nav className="flex items-center gap-2">
          <IconButton icon={<BookOpen size={16} />} onClick={() => setView('home')} className="bg-slate-700 hover:bg-slate-600">Home</IconButton>
          <IconButton icon={<PlusCircle size={16} />} onClick={() => setView('add')} className="bg-slate-700 hover:bg-slate-600">Add Poem</IconButton>
        </nav>
      </div>
    </header>
  );

  const renderHomeView = () => (
    <div className="space-y-8">
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        <div className="relative md:col-span-3">
          <Search size={20} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Search poems by title or author..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 focus:outline-none transition"
          />
        </div>
        <div className="relative md:col-span-2">
          <Filter size={20} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <select
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
            className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 focus:outline-none appearance-none transition bg-white"
          >
            <option value="all">All Types</option>
            {POEM_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
          </select>
        </div>
      </div>

      <motion.div layout className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        <AnimatePresence>
