              animate={{ opacity: 1, y: 0, transition: { delay: index * 0.05 } }}
              exit={{ opacity: 0, scale: 0.95 }}
              onClick={() => { setView('poem'); setSelectedPoemId(poem.id); }}
              className="cursor-pointer transform hover:scale-105 transition-transform duration-300"
            >
              <Card className="h-full flex flex-col bg-yellow-50 border border-yellow-200">
                <h3 className="text-xl font-bold text-slate-800 mb-2">{poem.title}</h3>
                <p className="text-sm text-slate-500 mb-4">by {poem.author} &bull; {poem.date}</p>
                <p className="text-slate-700 italic text-base leading-relaxed flex-grow">{poem.content.substring(0, 100)}...</p>
                <div className="flex items-center gap-2 mt-4 text-slate-500 text-sm font-medium">
                  <MessageCircle size={16} />
                  <span>{poem.comments.length} comments</span>
                </div>
              </Card>
            </motion.div>
          ))}
        </AnimatePresence>
      </motion.div>
    </div>
  );

  const renderAddPoemView = () => (
    <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }}>
      <Card className="max-w-2xl mx-auto bg-yellow-50">
        <form onSubmit={handleAddPoem} className="space-y-6">
          <h2 className="text-2xl font-bold text-slate-800 mb-4">Add Your Poem</h2>
          {/* Add Poem Form Card */}
          <div className="space-y-4">
            <div>
              <label htmlFor="title" className="block text-sm font-medium text-slate-700 mb-1">Title</label>
              <input id="title" type="text" value={newPoemTitle} onChange={e => setNewPoemTitle(e.target.value)} placeholder="The Whispering Wind" className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 focus:outline-none transition" required />
            </div>
            <div>
              <label htmlFor="type" className="block text-sm font-medium text-slate-700 mb-1">Type of Poem</label>
              {/* Type Dropdown */}
              <select id="type" value={newPoemType} onChange={e => setNewPoemType(e.target.value as Poem['type'])} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 focus:outline-none transition bg-white appearance-none">
