              <button type="submit" className="px-6 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-700 transition-colors">Submit Poem</button>
            </div>
          </div>
        </form>
      </Card>
    </motion.div>
  );

  const renderPoemDetailView = () => {
    if (!selectedPoem) return null;
    return (
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
        <div className="max-w-3xl mx-auto space-y-8">
          <IconButton icon={<ArrowLeft size={16} />} onClick={() => setView('home')} className="text-slate-700 hover:bg-slate-200">Back to Home</IconButton>
          <Card className="bg-yellow-50">
            <h2 className="text-3xl font-bold text-slate-800 mb-2">{selectedPoem.title}</h2>
            <div className="flex items-center gap-4 text-slate-500 mb-6 border-b pb-4">
