              <div className="flex items-center gap-2"><Calendar size={16} /><span>{selectedPoem.date}</span></div>
              <div className="flex items-center gap-2"><span className="px-2 py-1 bg-slate-200 text-slate-700 text-xs font-semibold rounded-full">{selectedPoem.type}</span></div>
            </div>
            <p className="text-slate-700 whitespace-pre-wrap text-lg leading-loose">{selectedPoem.content}</p>
          </Card>

          <Card>
            <h3 className="text-xl font-bold text-slate-800 mb-6">Comments ({selectedPoem.comments.length})</h3>
            <div className="space-y-6">
              {selectedPoem.comments.map(comment => (
                // Comment Card
                <div key={comment.id} className="flex items-start gap-4">
                   <div className="w-10 h-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 font-bold">{comment.author.charAt(0)}</div>
                   <div className="flex-1">
                     <p className="font-semibold text-slate-800">{comment.author}</p>
                     <p className="text-slate-600">{comment.text}</p>
                   </div>
                </div>
              ))}
              {selectedPoem.comments.length === 0 && <p className="text-slate-500 italic">No comments yet. Be the first to share your thoughts!</p>}
            </div>
            <div className="mt-8 pt-6 border-t">
              <h4 className="font-semibold text-slate-800 mb-2">Leave a Comment</h4>
              <div className="flex gap-2">
                <input type="text" value={newComment} onChange={e => setNewComment(e.target.value)} placeholder="I love this!" className="flex-grow px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-slate-500 focus:outline-none transition" />
                <button onClick={handleAddComment} className="px-4 py-2 bg-slate-800 text-white rounded-lg hover:bg-slate-700 transition-colors shrink-0">Add Comment</button>
              </div>
            </div>
          </Card>
        </div>
      </motion.div>
    );
  };

  return (
    <div className="min-h-screen bg-stone-100 font-sans">
      {renderHeader()}
      <main className="container mx-auto p-4 sm:p-6 md:p-8">
        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -15 }}
            transition={{ duration: 0.25 }}
          >
            {view === 'home' && renderHomeView()}
            {view === 'add' && renderAddPoemView()}
            {view === 'poem' && renderPoemDetailView()}
          </motion.div>
        </AnimatePresence>
      </main>
    </div>
  );
};

