  onClick?: () => void;
}

const ActionButton: FC<ActionButtonProps> = ({ text, variant = 'primary', onClick }) => {
  const baseClasses = "inline-flex items-center justify-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg focus:outline-none focus:ring-2 focus:ring-offset-2 transition-all duration-200";
  const variantClasses = variant === 'primary'
    ? "bg-rose-600 text-white hover:bg-rose-700 focus:ring-rose-500"
    : "bg-rose-100 text-rose-700 hover:bg-rose-200 focus:ring-rose-500";

  return (
    <button className={`${baseClasses} ${variantClasses}`} onClick={onClick}>
      {text}
