import { useState, useEffect, FC, FormEvent } from 'react';
import type { NextPage } from 'next';
import Head from 'next/head';
import { motion, AnimatePresence } from 'framer-motion';
import { Toaster, toast } from 'sonner';
import {
  User, Link as LinkIcon, Copy, Plus, Trash2, Edit, Moon, Sun, Save, Share2, Check
} from 'lucide-react';

// --- TYPE DEFINITIONS ---
type Link = {
  id: number;
  title: string;
  url: string;
};

type Theme = 'light' | 'dark';

// --- HELPER COMPONENTS ---

interface CardProps {
  children: React.ReactNode;
  className?: string;
}

const Card: FC<CardProps> = ({ children, className = '' }) => (
  <div className={`bg-white/80 dark:bg-slate-800/80 backdrop-blur-sm border border-slate-200 dark:border-slate-700 rounded-2xl shadow-lg w-full ${className}`}>
    {children}
  </div>
);

// --- MAIN PAGE COMPONENT ---

const LinkTreeManagerPage: NextPage = () => {
  const [theme, setTheme] = useState<Theme>('light');
  const [profileName, setProfileName] = useState<string>('@username');
  const [isEditingName, setIsEditingName] = useState<boolean>(false);
  const [links, setLinks] = useState<Link[]>([]);
  const [newLinkTitle, setNewLinkTitle] = useState<string>('');
  const [newLinkUrl, setNewLinkUrl] = useState<string>('');
  const [copied, setCopied] = useState<boolean>(false);

  useEffect(() => {
    const savedTheme = localStorage.getItem('theme') as Theme | null;
    if (savedTheme) {
      setTheme(savedTheme);
    } else {
      const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
      setTheme(prefersDark ? 'dark' : 'light');
    }
  }, []);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prevTheme => (prevTheme === 'light' ? 'dark' : 'light'));
  };

  const handleAddLink = (e: FormEvent) => {
    e.preventDefault();
    if (!newLinkTitle.trim() || !newLinkUrl.trim()) {
      toast.error('Both title and URL are required.');
      return;
    }
    try {
      new URL(newLinkUrl); // Validate URL format
    } catch (_) {
      toast.error('Please enter a valid URL.');
      return;
    }

    const newLink: Link = {
      id: Date.now(),
      title: newLinkTitle,
      url: newLinkUrl,
    };
    setLinks([...links, newLink]);
    setNewLinkTitle('');
    setNewLinkUrl('');
    toast.success('Link added successfully!');
  };

  const handleDeleteLink = (id: number) => {
    setLinks(links.filter(link => link.id !== id));
    toast.info('Link removed.');
  };

  const handleCopyLink = () => {
    const shareableLink = `https://your-domain.com/${profileName.replace('@', '')}`;
    navigator.clipboard.writeText(shareableLink);
    setCopied(true);
    toast.success('Link copied to clipboard!');
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <>
      <Head>
        <title>LinkTree Manager</title>
        <meta name="description" content="Manage and share your personal link tree" />
        <link rel="icon" href="/favicon.ico" />
      </Head>
      <Toaster position="bottom-center" richColors theme={theme} />
      <main className="min-h-screen bg-orange-50 dark:bg-slate-900 text-slate-800 dark:text-slate-200 flex flex-col items-center justify-center p-4 font-sans transition-colors duration-300">
        <div className="w-full max-w-md mx-auto space-y-6">

          {/* Profile Section */}
          <div className="relative flex flex-col items-center space-y-4">
             <div className="absolute top-0 right-0">
                <button onClick={toggleTheme} className="p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                    {theme === 'light' ? <Moon className="w-5 h-5 text-orange-600" /> : <Sun className="w-5 h-5 text-orange-400" />}
                </button>
            </div>
            <div className="relative">
                <div className="w-24 h-24 rounded-full bg-slate-200 dark:bg-slate-700 border-4 border-white dark:border-slate-800 shadow-md flex items-center justify-center">
                    <User className="w-12 h-12 text-slate-400 dark:text-slate-500" />
                </div>
            </div>
            <div className="flex items-center gap-2">
              {isEditingName ? (
                <input 
                  type="text"
                  value={profileName}
                  onChange={(e) => setProfileName(e.target.value)}
                  className="text-2xl font-bold text-center bg-transparent border-b-2 border-orange-500 focus:outline-none"
                  autoFocus
                />
              ) : (
                <h1 className="text-2xl font-bold text-slate-900 dark:text-white">{profileName}</h1>
              )}
              <button 
                onClick={() => setIsEditingName(!isEditingName)}
                className="p-1.5 rounded-full text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700 hover:text-orange-600 dark:hover:text-orange-400 transition-all"
              >
                {isEditingName ? <Save className="w-4 h-4" /> : <Edit className="w-4 h-4" />}
              </button>
            </div>
          </div>

          {/* Share Link Card */}
          <Card>
            <div className="p-5 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Share2 className="w-5 h-5 text-orange-600 dark:text-orange-400"/>
                <p className="font-semibold">Share your Linktree</p>
              </div>
              <button
                onClick={handleCopyLink}
                className={`flex items-center justify-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-all duration-200 ${copied ? 'bg-green-500 text-white' : 'bg-orange-600 text-white hover:bg-orange-700'} shadow-md`}
              >
                {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                {copied ? 'Copied!' : 'Copy Link'}
              </button>
            </div>
          </Card>

          {/* Manage Links Card */}
          <Card>
            <form onSubmit={handleAddLink} className="p-5 space-y-4">
              <h2 className="font-bold text-lg text-slate-900 dark:text-white">Manage Links</h2>
              <div className="space-y-3">
                <input 
                  type="text" 
                  placeholder="Title" 
                  value={newLinkTitle}
                  onChange={(e) => setNewLinkTitle(e.target.value)}
                  className="w-full px-4 py-2 bg-slate-100 dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 transition"
                />
                <input 
                  type="url" 
                  placeholder="URL (e.g., https://example.com)" 
                  value={newLinkUrl}
                  onChange={(e) => setNewLinkUrl(e.target.value)}
                  className="w-full px-4 py-2 bg-slate-100 dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 transition"
                />
              </div>
              <button type="submit" className="w-full flex items-center justify-center gap-2 px-4 py-2.5 font-bold bg-orange-600 text-white rounded-lg hover:bg-orange-700 transition-colors shadow-md focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-orange-500 dark:ring-offset-slate-900">
                <Plus className="w-5 h-5" />
                Add Link
              </button>
            </form>
          </Card>

          {/* Links List */}
          <div className="space-y-4">
            <AnimatePresence>
              {links.length > 0 ? (
                links.map((link) => (
                  <motion.div
                    key={link.id}
                    layout
                    initial={{ opacity: 0, y: -20, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, x: -50, transition: { duration: 0.2 } }}
                    className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg shadow-sm flex items-center justify-between p-4"
                  >
                    <a href={link.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 group flex-1 min-w-0">
                      <LinkIcon className="w-5 h-5 text-slate-400 group-hover:text-orange-600 transition-colors flex-shrink-0" />
                      <span className="font-semibold truncate group-hover:text-orange-600 transition-colors">{link.title}</span>
                    </a>
                    <button 
                      onClick={() => handleDeleteLink(link.id)}
                      className="ml-4 p-2 rounded-full text-slate-500 hover:bg-red-100 dark:hover:bg-red-900/50 hover:text-red-600 dark:hover:text-red-500 transition-colors"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </motion.div>
                ))
              ) : (
                <div className="text-center py-10 px-4 border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl">
                  <p className="text-slate-500 dark:text-slate-400">You haven't added any links yet.</p>
                  <p className="text-slate-400 dark:text-slate-500 text-sm">Add your first link to get started!</p>
                </div>
              )}
            </AnimatePresence>
          </div>

          {/* Footer */}
          <footer className="text-center py-4">
            <p className="text-sm text-slate-500 dark:text-slate-400">&copy; {new Date().getFullYear()} LinkTree Manager. All Rights Reserved.</p>
          </footer>
        </div>
      </main>
    </>
  );
};

export default LinkTreeManagerPage;


