// --- MAIN PAGE COMPONENT ---
const BiographyExplorerPage: NextPage = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedPerson, setSelectedPerson] = useState<Person | null>(null);

  const filteredBiographies = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return biographies;

    return biographies.filter(
      (person) =>
        person.name.toLowerCase().includes(query) ||
        person.profession.toLowerCase().includes(query) ||
        person.keywords.some(keyword => keyword.toLowerCase().includes(query))
    );
  }, [searchQuery]);

  const handleViewDetails = (person: Person) => {
    setSelectedPerson(person);
  };

  const handleCloseModal = () => {
    setSelectedPerson(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900">
      <main className="container mx-auto px-4 py-12 md:py-20">
        <header className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-extrabold tracking-tight text-slate-900">Extraordinary Lives</h1>
          <p className="mt-3 max-w-2xl mx-auto text-lg text-slate-600">
            Explore the biographies of remarkable individuals who shaped our world.
          </p>
        </header>

        <div className="mb-12 max-w-2xl mx-auto">
          <div className="relative">
            <span className="absolute inset-y-0 left-0 flex items-center pl-4 text-slate-500">
              <Search className="h-5 w-5" />
            </span>
            <input
              type="search"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search biographies by name, profession, or keywords..."
              className="w-full rounded-full border border-slate-300 bg-white py-3 pl-12 pr-4 text-base shadow-sm transition-colors placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
            />
          </div>
        </div>

        {filteredBiographies.length > 0 ? (
          <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 lg:grid-cols-3">
            {filteredBiographies.map((person) => (
              <BiographyCard key={person.id} person={person} onViewDetails={handleViewDetails} />
            ))}
          </div>
        ) : (
            <div className="text-center py-16">
                <p className="text-lg text-slate-600">No biographies found for "{searchQuery}".</p>
                <p className="text-sm text-slate-500 mt-2">Try a different search term.</p>
            </div>
        )}
      </main>

      {selectedPerson && <DetailModal person={selectedPerson} onClose={handleCloseModal} />}
    </div>
  );
};

export default BiographyExplorerPage;


