import { useState, useEffect, useRef, FC, ReactNode } from 'react';
import type { NextPage } from 'next';
import { Search, Filter, Wrench, ChevronDown, User, LogIn, SearchX } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type Category = {
  name: string;
  id: string;
};

// --- MOCK DATA ---
const toolCategories: Category[] = [
  { name: 'All Categories', id: 'all' },
  { name: 'Analysis & Simulation', id: 'analysis' },
  { name: 'CAD & 3D Modeling', id: 'cad' },
  { name: 'Project Management', id: 'pm' },
  { name: 'Data & Analytics', id: 'data' },
  { name: 'Development & IDEs', id: 'dev' },
];

// --- HELPER COMPONENTS ---

interface IconButtonProps {
  Icon: FC<{ className?: string }>;
  children: ReactNode;
  onClick?: () => void;
  className?: string;
}

const IconButton: FC<IconButtonProps> = ({ Icon, children, onClick, className = '' }) => (
  <button
    onClick={onClick}
    className={`flex items-center justify-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-colors duration-200 ${className}`}
  >
    <Icon className="w-4 h-4" />
    <span>{children}</span>
  </button>
);

// --- MAIN COMPONENT ---

const EngineerToolkitHubPage: NextPage = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [isFiltersOpen, setIsFiltersOpen] = useState<boolean>(false);
  const [isCategoryDropdownOpen, setIsCategoryDropdownOpen] = useState<boolean>(false);
  const [selectedCategory, setSelectedCategory] = useState<Category>(toolCategories[0]);

  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsCategoryDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleCategorySelect = (category: Category) => {
    setSelectedCategory(category);
    setIsCategoryDropdownOpen(false);
  };

  return (
    <div className="min-h-screen bg-stone-50 font-sans text-slate-800">
      {/* Header */}
      <header className="border-b border-stone-200 bg-white/60 backdrop-blur-sm sticky top-0 z-20">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex h-16 items-center justify-between">
            <div className="flex items-center gap-4">
              <Wrench className="h-7 w-7 text-green-800" />
              <h1 className="text-xl font-bold text-slate-900 tracking-tight">Tool Information</h1>
            </div>
            <div className="flex items-center gap-2 sm:gap-4">
              <IconButton Icon={LogIn} className="text-green-800 hover:bg-green-50">Login</IconButton>
              <IconButton Icon={User} className="bg-green-800 text-white hover:bg-green-900">Register</IconButton>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-12">
        <div className="max-w-3xl mx-auto">
          {/* Search and Filter Controls */}
          <div className="mb-8 space-y-4">
            <div className="flex flex-col sm:flex-row gap-4">
                {/* Search Bar */}
                <div className="relative flex-grow">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
                    <input
                        type="text"
                        placeholder="Search tools..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2.5 border border-stone-300 rounded-lg focus:ring-2 focus:ring-green-700 focus:border-green-700 outline-none transition-shadow duration-200 bg-white"
                    />
                </div>
                {/* Filters Button */}
                <button
                    onClick={() => setIsFiltersOpen(!isFiltersOpen)}
                    className={`flex items-center justify-center gap-2 px-4 py-2.5 font-semibold rounded-lg transition-colors duration-200 border ${isFiltersOpen ? 'bg-green-100 text-green-900 border-green-700' : 'bg-white text-slate-700 border-stone-300 hover:bg-stone-100'}`}
                >
                    <Filter className="w-4 h-4" />
                    <span>Filters</span>
                </button>
            </div>

            {/* Filters Section (Category Dropdown) */}
            {isFiltersOpen && (
              <div className="bg-white p-4 rounded-lg border border-stone-200 shadow-sm">
                <label htmlFor="category-select" className="block text-sm font-medium text-slate-600 mb-2">Tool Category</label>
                <div className="relative" ref={dropdownRef}>
                  {/* Category Dropdown Button */}
                  <button
                    id="category-select"
                    onClick={() => setIsCategoryDropdownOpen(!isCategoryDropdownOpen)}
                    className="w-full flex items-center justify-between text-left px-4 py-2 bg-stone-50 border border-stone-300 rounded-lg hover:bg-stone-100 focus:ring-2 focus:ring-green-700 focus:border-green-700 outline-none transition-all duration-200"
                  >
                    <span>{selectedCategory.name}</span>
                    <ChevronDown className={`w-5 h-5 text-stone-500 transition-transform duration-200 ${isCategoryDropdownOpen ? 'rotate-180' : ''}`} />
                  </button>
                  {/* Category Dropdown Menu */}
                  {isCategoryDropdownOpen && (
                    <div className="absolute mt-1 w-full bg-white border border-stone-200 rounded-lg shadow-lg z-10 max-h-60 overflow-y-auto">
                      {toolCategories.map((category) => (
                        <a
                          key={category.id}
                          href="#"
                          onClick={(e) => { e.preventDefault(); handleCategorySelect(category); }}
                          className="block px-4 py-2 text-sm text-slate-700 hover:bg-green-50 hover:text-green-900"
                        >
                          {category.name}
                        </a>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Selected Category Card */}
          {selectedCategory.id !== 'all' && (
            <div className="mb-6">
              <div className="inline-flex items-center gap-2 bg-green-100 text-green-900 text-sm font-medium px-3 py-1 rounded-full">
                <span>{selectedCategory.name}</span>
                <button onClick={() => handleCategorySelect(toolCategories[0])} className="text-green-700 hover:text-green-900">&#x2715;</button>
              </div>
            </div>
          )}

          {/* No Tools Found Message Card */}
          <div className="text-center border-2 border-dashed border-stone-300 rounded-xl p-8 sm:p-12 bg-white">
            <div className="flex flex-col items-center gap-4">
              <div className="w-16 h-16 rounded-full bg-stone-100 flex items-center justify-center">
                <SearchX className="w-8 h-8 text-stone-400" />
              </div>
              <h3 className="text-lg font-semibold text-slate-800">No Tools Found</h3>
              <p className="max-w-sm text-sm text-slate-500">
                No tools found matching your criteria. Try adjusting your search or filter options.
              </p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default EngineerToolkitHubPage;


