import { useState, type FC, MouseEvent } from 'react';
import type { NextPage } from 'next';
import Head from 'next/head';
import { Calculator, ChevronDown, History, Delete, X } from 'lucide-react';
import * as DropdownMenu from '@radix-ui/react-dropdown-menu';
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

// Helper for combining Tailwind classes
function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Type for calculation history entries
type HistoryEntry = {
  expression: string;
  result: string;
};

const MathGenCalculatorPage: NextPage = () => {
  const [input, setInput] = useState<string>('');
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [error, setError] = useState<string>('');

  const handleButtonClick = (value: string) => {
    setError('');
    if (input === 'Error') {
      setInput(value);
      return;
    }
    setInput(prev => prev + value);
  };

  const handleClear = () => {
    setInput('');
    setError('');
  };

  const handleDelete = () => {
    if (input === 'Error') {
      setInput('');
    } else {
      setInput(prev => prev.slice(0, -1));
    }
    setError('');
  };

  const handleEquals = () => {
    if (!input || input === 'Error') return;

    try {
      // Replace display operators with evaluatable operators
      let evalExpression = input.replace(/×/g, '*').replace(/÷/g, '/');

      // Basic validation to prevent unsafe eval calls
      if (/[^0-9+\-*/().\s]/.test(evalExpression)) {
        throw new Error('Invalid characters in expression');
      }

      // WARNING: eval() is used for simplicity. In a production environment,
      // it's safer to use a dedicated math expression parser library.
      const result = eval(evalExpression);

      if (typeof result !== 'number' || !isFinite(result)) {
          throw new Error('Invalid calculation');
      }

      const resultString = String(Number(result.toFixed(10)));

      setHistory(prev => [{ expression: input, result: resultString }, ...prev].slice(0, 10)); // Keep last 10
      setInput(resultString);
      setError('');
    } catch (e) {
      setError('Error');
      setInput('Error');
    }
  };

  const buttonLayout = [
    { label: 'C', handler: handleClear, type: 'special' },
    { label: 'DEL', handler: handleDelete, type: 'special' },
    { label: '÷', handler: () => handleButtonClick('÷'), type: 'operator' },
    { label: '×', handler: () => handleButtonClick('×'), type: 'operator' },
    { label: '7', handler: () => handleButtonClick('7'), type: 'number' },
    { label: '8', handler: () => handleButtonClick('8'), type: 'number' },
    { label: '9', handler: () => handleButtonClick('9'), type: 'number' },
    { label: '-', handler: () => handleButtonClick('-'), type: 'operator' },
    { label: '4', handler: () => handleButtonClick('4'), type: 'number' },
    { label: '5', handler: () => handleButtonClick('5'), type: 'number' },
    { label: '6', handler: () => handleButtonClick('6'), type: 'number' },
    { label: '+', handler: () => handleButtonClick('+'), type: 'operator' },
    { label: '1', handler: () => handleButtonClick('1'), type: 'number' },
    { label: '2', handler: () => handleButtonClick('2'), type: 'number' },
    { label: '3', handler: () => handleButtonClick('3'), type: 'number' },
    { label: '=', handler: handleEquals, type: 'equals', className: 'row-span-2' },
    { label: '0', handler: () => handleButtonClick('0'), type: 'number', className: 'col-span-2' },
    { label: '.', handler: () => handleButtonClick('.'), type: 'number' },
  ];

  return (
    <>
      <Head>
        <title>MathGen Calculator</title>
        <meta name="description" content="A sleek, user-friendly online calculator for basic arithmetic." />
        <link rel="icon" href="/favicon.ico" />
      </Head>
      <main className="bg-slate-50 min-h-screen w-full flex flex-col items-center justify-center p-4 font-sans text-slate-800">
        <div className="w-full max-w-md mx-auto">

          <header className="flex items-center justify-center gap-3 mb-4">
            <Calculator className="text-teal-500" size={32} />
            <h1 className="text-4xl font-bold text-slate-700">MathGen</h1>
          </header>

          <div className="mb-6 p-3 bg-white rounded-lg shadow-sm border border-slate-200 flex items-center justify-between">
            <span className="text-sm font-medium text-slate-500">Calculation Type:</span>
            <span className="bg-teal-100 text-teal-700 text-sm font-semibold px-3 py-1 rounded-full">Basic Arithmetic</span>
          </div>

          {/* Math Gen Card */}
          <div className="bg-white rounded-2xl shadow-lg overflow-hidden border border-slate-200">
            {/* Display */}
            <div className="p-6 bg-slate-100 text-right">
              <div className="text-slate-500 text-lg break-all h-8">{error ? '' : history[0]?.expression || ''}</div>
              <div className={cn("text-5xl font-light tracking-tight h-[60px] break-all", error && 'text-red-500')}>{input || '0'}</div>
            </div>

            {/* Buttons */}
            <div className="p-4 bg-slate-50/50">
              <div className="grid grid-cols-4 grid-rows-5 gap-2">
                {buttonLayout.map(({ label, handler, type, className }) => (
                  <button
                    key={label}
                    onClick={handler as (e: MouseEvent<HTMLButtonElement>) => void}
                    className={cn(
                      'flex items-center justify-center h-16 rounded-xl text-2xl font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500',
                      {
                        'bg-slate-200 hover:bg-slate-300 text-slate-800': type === 'number',
                        'bg-teal-500 hover:bg-teal-600 text-white': type === 'operator',
                        'bg-slate-400 hover:bg-slate-500 text-white': type === 'special',
                        'bg-teal-600 hover:bg-teal-700 text-white': type === 'equals',
                      },
                      className
                    )}
                  >
                    {label === 'DEL' ? <Delete size={24} /> : label}
                  </button>
                ))}
              </div>

              {/* Operators Dropdown */}
              <DropdownMenu.Root>
                <DropdownMenu.Trigger asChild>
                  <button className="mt-2 w-full flex items-center justify-center gap-2 h-12 rounded-xl bg-white border border-slate-300 text-slate-600 hover:bg-slate-100 transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500">
                    More Operators <ChevronDown size={16} />
                  </button>
                </DropdownMenu.Trigger>
                <DropdownMenu.Portal>
                  <DropdownMenu.Content 
                    sideOffset={5}
                    className="w-56 bg-white rounded-md shadow-lg p-1 border border-slate-200 z-50 animate-in fade-in-0 zoom-in-95"
                  >
                    {['(', ')', '%'].map(op => (
                      <DropdownMenu.Item key={op} onSelect={() => handleButtonClick(op)} className="flex items-center px-3 py-2 text-sm text-slate-700 rounded-md hover:bg-teal-50 hover:text-teal-600 focus:bg-teal-50 focus:outline-none cursor-pointer">
                        {op}
                      </DropdownMenu.Item>
                    ))}
                  </DropdownMenu.Content>
                </DropdownMenu.Portal>
              </DropdownMenu.Root>
            </div>
          </div>

          {/* History Section */}
          <div className="mt-8">
            <h2 className="flex items-center gap-2 text-lg font-semibold text-slate-600 mb-4">
              <History size={20} />
              Calculation History
            </h2>
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-4 space-y-3 h-48 overflow-y-auto">
              {history.length > 0 ? (
                history.map((entry, index) => (
                  <div key={index} className="text-slate-600 text-sm flex justify-between items-center border-b border-slate-100 pb-2 last:border-b-0 last:pb-0">
                    <span className="text-slate-500 truncate pr-2">{entry.expression} =</span>
                    <span className="font-semibold text-slate-700">{entry.result}</span>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-400">
                  <div className="bg-gray-200 border-2 border-dashed rounded-xl w-16 h-16 mb-2" />
                  <p>No history yet.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    </>
  );
};

export default MathGenCalculatorPage;


