} from 'lucide-react';

// --- TYPES AND DATA --- //

type NodeType = 'process' | 'decision' | 'input' | 'database' | 'terminator' | 'document' | 'external';

interface Node {
  id: string;
  type: NodeType;
  label: string;
  x: number;
  y: number;
}

const NODE_PALETTE: { type: NodeType; label: string; icon: ReactNode }[] = [
  { type: 'process', label: 'Process', icon: <RectangleHorizontal className="w-5 h-5" /> },
  { type: 'decision', label: 'Decision', icon: <Diamond className="w-5 h-5" /> },
  { type: 'input', label: 'Input', icon: <MoveRight className="w-5 h-5 -rotate-45" /> },
  { type: 'database', label: 'Database', icon: <Database className="w-5 h-5" /> },
  { type: 'terminator', label: 'Terminator', icon: <CircleDot className="w-5 h-5" /> },
  { type: 'document', label: 'Document', icon: <FileText className="w-5 h-5" /> },
  { type: 'external', label: 'External', icon: <ExternalLink className="w-5 h-5" /> },
];

const DIAGRAM_TYPES = ['Flowchart', 'Org Chart', 'Mind Map', 'Sequence Diagram'];
const LAYOUT_STYLES = ['Hierarchical', 'Orthogonal', 'Circular', 'Force-Directed'];

// --- HELPER COMPONENTS --- //

interface IconButtonProps {
  icon: ReactNode;
  label: string;
  onClick?: () => void;
  className?: string;
}

const IconButton: FC<IconButtonProps> = ({ icon, label, onClick, className }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-md transition-colors text-slate-700 hover:bg-slate-200 hover:text-slate-900 ${className}`}
  >
    {icon}
    {label}
  </button>
);

interface PanelProps {
  title: string;
  icon: ReactNode;
  children: ReactNode;
}

const Panel: FC<PanelProps> = ({ title, icon, children }) => (
  <div className="bg-white border border-slate-200 rounded-lg">
    <div className="flex items-center gap-2 p-3 border-b border-slate-200">
      {icon}
      <h3 className="font-semibold text-slate-800 text-sm">{title}</h3>
    </div>
    <div className="p-3">{children}</div>
  </div>
);

interface NodePaletteItemProps {
  nodeInfo: { type: NodeType; label: string; icon: ReactNode };
}

const NodePaletteItem: FC<NodePaletteItemProps> = ({ nodeInfo }) => {
  const onDragStart = (event: DragEvent<HTMLDivElement>, nodeType: NodeType) => {
    event.dataTransfer.setData('application/diagram-craft', nodeType);
    event.dataTransfer.effectAllowed = 'move';
  };

  return (
    <div
      draggable
      onDragStart={(e) => onDragStart(e, nodeInfo.type)}
      className="flex items-center gap-3 p-2 rounded-md cursor-grab active:cursor-grabbing hover:bg-slate-100 transition-colors"
    >
      <div className="flex items-center justify-center w-8 h-8 bg-slate-100 border border-slate-200 rounded-md text-slate-600">
        {nodeInfo.icon}
      </div>
      <span className="text-sm font-medium text-slate-700">{nodeInfo.label}</span>
    </div>
  );
};

interface DiagramNodeProps {
  node: Node;
  isSelected: boolean;
  onClick: (id: string) => void;
}

const DiagramNode: FC<DiagramNodeProps> = ({ node, isSelected, onClick }) => {
  const nodeStyles: { [key in NodeType]: string } = {
    process: 'bg-blue-100 border-blue-400 text-blue-800',
    decision: 'bg-amber-100 border-amber-400 text-amber-800 -rotate-45 transform',
    input: 'bg-green-100 border-green-400 text-green-800',
    database: 'bg-purple-100 border-purple-400 text-purple-800',
    terminator: 'bg-gray-100 border-gray-400 text-gray-800 rounded-full',
    document: 'bg-rose-100 border-rose-400 text-rose-800',
    external: 'bg-cyan-100 border-cyan-400 text-cyan-800',
  };

  const shapeWrapperClass = node.type === 'decision' ? 'w-[100px] h-[100px] flex items-center justify-center' : '';
  const shapeInnerClass = node.type === 'decision' ? 'rotate-45' : '';

  return (
    <div
      style={{ left: node.x, top: node.y }}
      className={`absolute cursor-pointer transition-all duration-150 ${shapeWrapperClass}`}
      onClick={() => onClick(node.id)}
    >
      <div
        className={`flex items-center justify-center p-4 border-2 rounded-lg shadow-sm ${nodeStyles[node.type]} ${isSelected ? 'ring-2 ring-offset-2 ring-blue-500' : ''} ${shapeInnerClass}`}
      >
        <span className="text-sm font-medium select-none truncate">{node.label}</span>
      </div>
    </div>
  );
};

// --- MAIN PAGE COMPONENT --- //

const DiagramCraftStudio: NextPage = () => {
  const [diagramName, setDiagramName] = useState('Untitled Diagram');
  const [diagramType, setDiagramType] = useState(DIAGRAM_TYPES[0]);
  const [layoutStyle, setLayoutStyle] = useState(LAYOUT_STYLES[0]);
  const [nodes, setNodes] = useState<Node[]>([]);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const canvasRef = useRef<HTMLDivElement>(null);

  const handleNewDiagram = () => {
    setNodes([]);
    setDiagramName('Untitled Diagram');
    setSelectedNodeId(null);
  };

  const onDrop = useCallback((event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    const nodeType = event.dataTransfer.getData('application/diagram-craft') as NodeType;
    if (!nodeType || !canvasRef.current) return;

    const canvasBounds = canvasRef.current.getBoundingClientRect();
    const x = event.clientX - canvasBounds.left - 50; // Adjust for node width/2
    const y = event.clientY - canvasBounds.top - 25;  // Adjust for node height/2

    const newNode: Node = {
      id: `node_${Date.now()}`,
      type: nodeType,
      label: nodeType.charAt(0).toUpperCase() + nodeType.slice(1),
      x: Math.max(0, x),
      y: Math.max(0, y),
    };
    setNodes((currentNodes) => [...currentNodes, newNode]);
  }, []);

  const onDragOver = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  };

  const handleCanvasClick = (e: MouseEvent<HTMLDivElement>) => {
    if (e.target === canvasRef.current) {
        setSelectedNodeId(null);
    }
  }

  return (
    <>
      <Head>
        <title>DiagramCraft Studio</title>
        <meta name="description" content="A modern diagram-making platform." />
        <link rel="icon" href="/favicon.ico" />
      </Head>

      <div className="flex flex-col h-screen font-sans bg-slate-50 text-slate-900">
        {/* Header */}
        <header className="flex items-center justify-between px-4 py-2 bg-white border-b border-slate-200 shadow-sm z-10">
          <div className="flex items-center gap-2">
            <GitBranch className="w-7 h-7 text-slate-800" />
            <h1 className="text-lg font-bold text-slate-800">DiagramCraft Studio</h1>
          </div>
          <div className="flex items-center gap-2">
            <IconButton icon={<FilePlus2 size={16} />} label="New Diagram" onClick={handleNewDiagram} />
            <IconButton icon={<Save size={16} />} label="Save" onClick={() => alert('Diagram Saved!')} />
            <div className="relative group">
                <IconButton icon={<Save size={16} />} label="Save As" />
            </div>
            <IconButton icon={<Trash2 size={16} />} label="Discard" onClick={handleNewDiagram} className="hover:bg-red-100 hover:text-red-700" />
            <div className="w-px h-6 bg-slate-200 mx-2"></div>
            <IconButton icon={<Upload size={16} />} label="Import" />
            <IconButton icon={<Download size={16} />} label="Export" />
          </div>
        </header>

        {/* Main Content */}
        <main className="flex flex-1 overflow-hidden">
          {/* Left Sidebar */}
          <aside className="w-64 bg-white border-r border-slate-200 p-4 space-y-6 overflow-y-auto shrink-0">
            <Panel title="Existing Diagrams" icon={<GitBranch size={16} />}>
                <ul className="space-y-2">
                    {['Q3 Financials Flow', 'User Onboarding V2', 'API Architecture'].map(name => (
                        <li key={name} className="text-sm text-slate-600 hover:text-slate-900 hover:bg-slate-100 p-2 rounded-md cursor-pointer">{name}</li>
                    ))}
                </ul>
            </Panel>
            <Panel title="Recent Diagrams" icon={<MousePointer2 size={16} />}>
                <ul className="space-y-2">
                    {['Temporary Sketch', 'Mindmap Idea'].map(name => (
                        <li key={name} className="text-sm text-slate-600 hover:text-slate-900 hover:bg-slate-100 p-2 rounded-md cursor-pointer">{name}</li>
                    ))}
                </ul>
            </Panel>
          </aside>

          {/* Center Area */}
          <div className="flex flex-col flex-1">
            {/* Sub-Header */}
            <div className="flex items-center gap-4 p-3 bg-white/80 backdrop-blur-sm border-b border-slate-200">
              <input
                type="text"
                value={diagramName}
                onChange={(e) => setDiagramName(e.target.value)}
                className="px-3 py-1.5 text-sm font-medium border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                placeholder="Diagram Name"
              />
              <div className="w-px h-6 bg-slate-200"></div>
              <div className="relative">
                <select value={diagramType} onChange={(e) => setDiagramType(e.target.value)} className="appearance-none bg-white text-sm font-medium text-slate-700 pl-3 pr-8 py-1.5 border border-slate-300 rounded-md hover:border-slate-400 focus:ring-2 focus:ring-blue-500 outline-none">
                  {DIAGRAM_TYPES.map(type => <option key={type}>{type}</option>)}
                </select>
                <ChevronDown size={16} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
              <div className="relative">
                <select value={layoutStyle} onChange={(e) => setLayoutStyle(e.target.value)} className="appearance-none bg-white text-sm font-medium text-slate-700 pl-3 pr-8 py-1.5 border border-slate-300 rounded-md hover:border-slate-400 focus:ring-2 focus:ring-blue-500 outline-none">
                  {LAYOUT_STYLES.map(style => <option key={style}>{style}</option>)}
                </select>
                <ChevronDown size={16} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none" />
              </div>
              <button className="px-4 py-1.5 text-sm font-semibold text-white bg-slate-800 rounded-md hover:bg-slate-900 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-800 transition-colors">
                Apply Layout
              </button>
            </div>

            {/* Canvas */}
            <div className="flex-1 bg-slate-100 p-4 overflow-auto">
                <div
                    ref={canvasRef}
                    onDrop={onDrop}
                    onDragOver={onDragOver}
                    onClick={handleCanvasClick}
                    className="relative w-full h-full bg-white rounded-lg shadow-inner border-2 border-dashed border-slate-300 bg-[linear-gradient(90deg,rgba(203,213,225,0.4)_1px,transparent_1px),linear-gradient(rgba(203,213,225,0.4)_1px,transparent_1px)] bg-[size:20px_20px]"
                >
                    {nodes.map(node => (
                        <DiagramNode key={node.id} node={node} isSelected={selectedNodeId === node.id} onClick={setSelectedNodeId} />
                    ))}
                </div>
            </div>
          </div>

          {/* Right Sidebar */}
          <aside className="w-72 bg-white border-l border-slate-200 p-4 space-y-6 overflow-y-auto shrink-0">
            <Panel title="Search" icon={<Search size={16} />}>
              <input type="text" placeholder="Search for elements..." className="w-full px-3 py-2 text-sm border border-slate-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition" />
            </Panel>
            <Panel title="Node Types" icon={<Shapes size={16} />}>
              <div className="space-y-2">
                {NODE_PALETTE.map(nodeInfo => (
                  <NodePaletteItem key={nodeInfo.type} nodeInfo={nodeInfo} />
                ))}
              </div>
            </Panel>
             <Panel title="Suggested Nodes" icon={<LayoutGrid size={16} />}>
                <div className="grid grid-cols-2 gap-2">
                    <button className="flex flex-col items-center p-2 rounded-md hover:bg-slate-100 text-slate-600">
                        <RectangleHorizontal className="w-6 h-6 mb-1"/>
                        <span className="text-xs">Start Process</span>
                    </button>
                     <button className="flex flex-col items-center p-2 rounded-md hover:bg-slate-100 text-slate-600">
                        <Database className="w-6 h-6 mb-1"/>
                        <span className="text-xs">User DB</span>
                    </button>
                </div>
            </Panel>
          </aside>
        </main>
      </div>
    </>
  );
};

export default DiagramCraftStudio;


