  }, []);\n\n  // --- EVENT HANDLERS --- //\n  const handleAddTask = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (!title.trim() || !dueDate) return;\n\n    const newTask: Task = {\n      id: Date.now().toString(),\n      title: title.trim(),\n      description: description.trim(),\n      dueDate,\n      priority,\n      completed: false,\n    };\n\n    setTasks([...tasks, newTask]);\n    // Reset form\n    setTitle(\'\');\n    setDescription(\'\');\n    setDueDate(new Date());\n    setPriority(\'medium\');\n  };\n\n  const handleToggleComplete = (id: string) => {\n    setTasks(tasks.map(task => task.id === id ? { ...task, completed: !task.completed } : task));\n  };\n\n  const handleDeleteTask = (id: string) => {\n    setTasks(tasks.filter(task => task.id !== id));\n  };\n\n  // --- MEMOIZED DERIVED STATE --- //\n  const displayedTasks = useMemo(() => {\n    return tasks\n      .filter(task => {\n        if (filterStatus === \'all\') return true;\n        if (filterStatus === \'completed\') return task.completed;\n        if (filterStatus === \'pending\') return !task.completed;\n        return true;\n      })\n      .filter(task => \n        task.title.toLowerCase().includes(searchTerm.toLowerCase()) ||\n        task.description.toLowerCase().includes(searchTerm.toLowerCase())\n      )\n      .sort((a, b) => {\n        switch (sortOrder) {\n          case \'date-asc\': return a.dueDate.getTime() - b.dueDate.getTime();\n          case \'date-desc\': return b.dueDate.getTime() - a.dueDate.getTime();\n          case \'priority-high\': {\n            const priorityOrder = { high: 0, medium: 1, low: 2 };\n            return priorityOrder[a.priority] - priorityOrder[b.priority];\n          }\n          case \'priority-low\': {\n            const priorityOrder = { low: 0, medium: 1, high: 2 };\n            return priorityOrder[a.priority] - priorityOrder[b.priority];\n          }\n          default: return 0;\n        }\n      });\n  }, [tasks, filterStatus, searchTerm, sortOrder]);\n\n  // --- RENDER --- //\n  return (\n    <div className="min-h-screen w-full bg-gradient-to-br from-violet-100 via-purple-100 to-indigo-100 text-indigo-900 font-sans p-4 sm:p-6 lg:p-8">\n      <main className="max-w-7xl mx-auto space-y-8">\n        <header className="text-center">\n          <h1 className="text-4xl sm:text-5xl font-bold text-indigo-800 tracking-tight">Advanced To-Do Organizer</h1>\n          <p className="mt-2 text-lg text-indigo-600">Your personal productivity powerhouse</p>\n        </header>\n\n        {/* Task Creation Section */}\n        <Card className="p-6">\n          <form onSubmit={handleAddTask} className="space-y-6">\n            <h2 className="text-2xl font-semibold text-indigo-700 border-b border-indigo-200 pb-3">Create a New Task</h2>\n            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">\n              {/* Title Input */}\n              <div>\n                <label htmlFor="title" className="block text-sm font-medium text-indigo-700 mb-1">Title</label>\n                <input id="title" type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g., Design new dashboard" required className="w-full px-4 py-2 bg-white/80 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition" />\n              </div>\n\n              {/* Due Date & Priority */}\n              <div className="grid grid-cols-2 gap-4">\n                {/* Due Date Input */}\n                 <div className="relative" ref={datePickerRef}>\n                    <label htmlFor="due-date" className="block text-sm font-medium text-indigo-700 mb-1">Due Date</label>\n                    <button type="button" id="due-date" onClick={() => setDatePickerOpen(!isDatePickerOpen)} className="w-full flex justify-between items-center px-4 py-2 bg-white/80 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition">\n                      <span>{dueDate ? format(dueDate, \'PPP\') : \'Select a date\'}</span>\n                      <CalendarIcon className="h-5 w-5 text-indigo-400" />\n                    </button>\n                    {isDatePickerOpen && (\n                      <div className="absolute z-10 mt-2 bg-white rounded-lg shadow-lg border border-gray-200">\n                         <DayPicker\n                           mode="single"\n                           selected={dueDate}\n                           onSelect={(date) => { setDueDate(date); setDatePickerOpen(false); }}\n                           initialFocus\n                           styles={{ caption: { color: \'#4338ca\' } }}\n                           className="p-2"\n                         />\n                      </div>\n                    )}\n                 </div>\n\n                {/* Priority Dropdown */}\n                <div>\n                  <label htmlFor="priority" className="block text-sm font-medium text-indigo-700 mb-1">Priority</label>\n                  <div className="relative">\n                    <select id="priority" value={priority} onChange={(e) => setPriority(e.target.value as Priority)} className="w-full appearance-none px-4 py-2 bg-white/80 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition">\n                      {Object.entries(priorityConfig).map(([key, { label }]) => (\n                        <option key={key} value={key}>{label}</option>\n                      ))}\n                    </select>\n                    <ChevronDown className="h-5 w-5 text-indigo-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />\n                  </div>\n                </div>\n              </div>\n            </div>\n\n            {/* Description Textarea */}\n            <div>\n              <label htmlFor="description" className="block text-sm font-medium text-indigo-700 mb-1">Description (Optional)</label>\n              <textarea id="description" value={description} onChange={(e) => setDescription(e.target.value)} rows={3} placeholder="Add more details about the task..." className="w-full px-4 py-2 bg-white/80 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"></textarea>\n            </div>\n\n            <div className="flex justify-end">\n              <button type="submit" className="inline-flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white font-semibold rounded-lg shadow-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all duration-200 transform hover:scale-105">\n                <Plus className="h-5 w-5" />\n                Add Task\n              </button>\n            </div>\n          </form>\n        </Card>\n\n        {/* Filtering Section */}\n        <Card className="p-6">\n          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center">\n            {/* Search Input */}\n            <div className="relative md:col-span-1">\n              <Search className="h-5 w-5 text-indigo-400 absolute left-3 top-1/2 -translate-y-1/2" />\n              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Search tasks..." className="w-full pl-10 pr-4 py-2 bg-white/80 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition" />\n            </div>\n            \n            <div className="flex items-center justify-center md:justify-end md:col-span-2 gap-4">\n              {/* Sort Dropdown */}\n              <div className="relative">\n                  <select value={sortOrder} onChange={(e) => setSortOrder(e.target.value)} className="w-full appearance-none px-4 py-2 bg-white/80 border border-indigo-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition">\n                    <option value="date-asc">Sort by Date (Asc)</option>\n                    <option value="date-desc">Sort by Date (Desc)</option>\n                    <option value="priority-high">Sort by Priority (High-Low)</option>\n                    <option value="priority-low">Sort by Priority (Low-High)</option>\n                  </select>\n                  <ChevronDown className="h-5 w-5 text-indigo-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />\n              </div>\n\n              {/* Filter Buttons (Completed/Pending Checkboxes) */}\n              <div className="flex items-center bg-indigo-100 rounded-lg p-1">\n                {([\'all\', \'pending\', \'completed\'] as FilterStatus[]).map(status => (\n                    <button key={status} onClick={() => setFilterStatus(status)} className={`px-3 py-1 text-sm font-medium rounded-md transition-colors ${filterStatus === status ? \'bg-indigo-600 text-white shadow\' : \'text-indigo-600 hover:bg-indigo-200\'}`}>\n                      {status.charAt(0).toUpperCase() + status.slice(1)}\n                    </button>\n                ))}\n              </div>\n            </div>\n          </div>\n        </Card>\n\n        {/* Task List Section */}\n        <Card className="p-6">\n          <h2 className="text-2xl font-semibold text-indigo-700 border-b border-indigo-200 pb-3 mb-6">Your Tasks</h2>\n          {displayedTasks.length > 0 ? (\n            <ul className="space-y-4">\n              {displayedTasks.map(task => (\n                <li key={task.id} className={`p-4 rounded-lg border flex items-center gap-4 transition-all duration-300 ${task.completed ? \'bg-gray-50 border-gray-200 opacity-60\' : \'bg-white border-indigo-100\'}`}>\n                  <button onClick={() => handleToggleComplete(task.id)} className="flex-shrink-0">\n                    {task.completed ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <Circle className="h-6 w-6 text-gray-300" />}\n                  </button>\n                  <div className="flex-grow">\n                    <p className={`font-semibold ${task.completed ? \'line-through text-gray-500\' : \'text-indigo-800\'}`}>{task.title}</p>\n                    {task.description && <p className={`text-sm ${task.completed ? \'text-gray-400\' : \'text-indigo-500\'}`}>{task.description}</p>}\n                  </div>\n                  <div className="flex-shrink-0 flex items-center gap-4 text-sm">\n                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${priorityConfig[task.priority].color}`}>{priorityConfig[task.priority].label}</span>\n                    <div className="flex items-center gap-1 text-indigo-500">\n                      <CalendarIcon className="h-4 w-4" />\n                      <span>{format(task.dueDate, \'MMM d\')}</span>\n                    </div>\n                    <button onClick={() => handleDeleteTask(task.id)} className="text-gray-400 hover:text-red-500 transition-colors">\n                      <Trash2 className="h-5 w-5" />\n                    </button>\n                  </div>\n                </li>\n              ))}\n            </ul>\n          ) : (\n            /* Empty Task List Message */\n            <div className="text-center py-12 border-2 border-dashed border-indigo-200 rounded-lg">\n              <ClipboardList className="mx-auto h-12 w-12 text-indigo-300" />\n              <h3 className="mt-4 text-lg font-medium text-indigo-600">No tasks found</h3>\n              <p className="mt-1 text-sm text-indigo-500">Create a new task or adjust your filters.</p>\n            </div>\n          )}\n        </Card>\n      </main>\n    </div>\n  );\n};\n\nexport default AdvancedTodoPage;\n'}

