// --- HELPER COMPONENTS (within the same file) ---

interface IconWrapperProps {
    children: ReactNode;
    tooltip: string;
    onClick?: () => void;
    isActive?: boolean;
}

const TopBarButton: FC<IconWrapperProps> = ({ children, tooltip, onClick, isActive = false }) => (
    <button
        onClick={onClick}
        title={tooltip}
        className={`p-2 rounded-md transition-colors duration-200 ${isActive ? 'bg-emerald-100 dark:bg-emerald-800 text-emerald-600 dark:text-emerald-300' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'}`}>
        {children}
    </button>
);

interface FileItemProps {
    name: string;
    type: 'file' | 'image';
    isActive: boolean;
    onClick: () => void;
}

const FileItem: FC<FileItemProps> = ({ name, type, isActive, onClick }) => {
    const Icon = type === 'image' ? Image : FileCode;
    return (
        <button
            onClick={onClick}
            className={`w-full text-left flex items-center gap-2 px-3 py-1.5 text-sm rounded-md transition-colors ${isActive ? 'bg-emerald-100 dark:bg-emerald-900/50 text-emerald-700 dark:text-emerald-300' : 'hover:bg-slate-100 dark:hover:bg-slate-700/50'}`}>
            <Icon className="w-4 h-4 flex-shrink-0" />
            <span className="truncate">{name}</span>
        </button>
    );
};

