import { useState, useMemo, type FC, type FormEvent, type SVGProps } from 'react';
import type { NextPage } from 'next';

// --- DEPENDENCY: LUCIDE-REACT ICONS ---
// In a real project, you would `npm install lucide-react`
import { Home, Search, HandHeart, Apple, Warehouse, UserCircle, Plus, Trash2 } from 'lucide-react';

// --- TYPE DEFINITIONS ---
type NavItem = 'Home' | 'Donation' | 'Distribution' | 'Volunteer' | 'Account';

const FOOD_TYPES = ['Fresh Produce', 'Canned Goods', 'Dairy & Eggs', 'Bakery', 'Meats & Poultry', 'Dry Goods'] as const;
type FoodType = typeof FOOD_TYPES[number];

interface Donation {
  id: string;
  foodType: FoodType;
  quantity: number;
  donatedAt: Date;
  donor: string;
}

// --- UI COMPONENTS ---

const NavButton: FC<{ text: NavItem; icon: React.ReactNode; isActive: boolean; onClick: () => void; }> = ({ text, icon, isActive, onClick }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all duration-300 ${isActive
        ? 'bg-sky-600 text-white shadow-md'
        : 'text-slate-300 hover:bg-slate-700/50 hover:text-white'
      }`}
  >
    {icon}
    {text}
  </button>
);

const Card: FC<{ children: React.ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-slate-800/50 backdrop-blur-sm border border-slate-700 rounded-xl shadow-lg ${className}`}>
    {children}
  </div>
);

// --- PAGE SECTIONS / VIEWS ---

const HomeView: FC<{ onGetStarted: () => void }> = ({ onGetStarted }) => (
  <div className="text-center">
    <h1 className="text-5xl font-bold text-white tracking-tight mb-4">Welcome to the Food Distribution Hub</h1>
    <p className="text-slate-300 max-w-2xl mx-auto text-lg mb-8">
      Our platform connects generous donors with communities in need. Help us fight hunger by donating surplus food or find distribution points near you.
    </p>
    <button
      onClick={onGetStarted}
      className="bg-sky-600 text-white font-bold py-3 px-8 rounded-full text-lg hover:bg-sky-500 transition-transform duration-300 hover:scale-105 shadow-lg"
    >
      Get Started
    </button>
  </div>
);

const DonationView: FC = () => {
  const [donations, setDonations] = useState<Donation[]>([
    { id: '1', foodType: 'Fresh Produce', quantity: 50, donatedAt: new Date('2023-10-26T10:00:00Z'), donor: 'Green Farms' },
    { id: '2', foodType: 'Bakery', quantity: 200, donatedAt: new Date('2023-10-25T14:30:00Z'), donor: 'City Bakery' },
    { id: '3', foodType: 'Canned Goods', quantity: 500, donatedAt: new Date('2023-10-25T09:15:00Z'), donor: 'SuperMart' },
  ]);
  const [foodType, setFoodType] = useState<FoodType>(FOOD_TYPES[0]);
  const [quantity, setQuantity] = useState('');

  const handleAddDonation = (e: FormEvent) => {
    e.preventDefault();
    const numQuantity = parseInt(quantity, 10);
    if (!numQuantity || numQuantity <= 0) {
      alert('Please enter a valid quantity.');
      return;
    }

    const newDonation: Donation = {
      id: new Date().toISOString(),
      foodType,
      quantity: numQuantity,
      donatedAt: new Date(),
      donor: 'Yourself' // Placeholder for user system
    };

    setDonations([newDonation, ...donations]);
    setQuantity('');
  };

  const handleDeleteDonation = (id: string) => {
    setDonations(donations.filter(d => d.id !== id));
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <Card className="lg:col-span-1 p-6">
        <h2 className="text-2xl font-bold text-white mb-4">Add a New Donation</h2>
        <form onSubmit={handleAddDonation} className="space-y-4">
          <div>
            <label htmlFor="foodType" className="block text-sm font-medium text-slate-300 mb-1">Food Type</label>
            <select
              id="foodType"
              value={foodType}
              onChange={(e) => setFoodType(e.target.value as FoodType)}
              className="w-full bg-slate-700 border border-slate-600 text-white rounded-lg p-2.5 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none"
            >
              {FOOD_TYPES.map(type => <option key={type}>{type}</option>)}
            </select>
          </div>
          <div>
            <label htmlFor="quantity" className="block text-sm font-medium text-slate-300 mb-1">Quantity (in lbs/units)</label>
            <input
              type="number"
              id="quantity"
              value={quantity}
              onChange={(e) => setQuantity(e.target.value)}
              placeholder="e.g., 50"
              className="w-full bg-slate-700 border border-slate-600 text-white rounded-lg p-2.5 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none"
            />
          </div>
          <button type="submit" className="w-full flex items-center justify-center gap-2 bg-sky-600 text-white font-bold py-3 px-4 rounded-lg hover:bg-sky-500 transition-colors duration-300">
            <Plus size={20} />
            Add Donation
          </button>
        </form>
      </Card>

      <Card className="lg:col-span-2 p-6">
        <h2 className="text-2xl font-bold text-white mb-4">Recent Donations</h2>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="border-b border-slate-700">
                <th className="p-3 text-sm font-semibold text-slate-400">Food Type</th>
                <th className="p-3 text-sm font-semibold text-slate-400">Quantity</th>
                <th className="p-3 text-sm font-semibold text-slate-400">Donor</th>
                <th className="p-3 text-sm font-semibold text-slate-400">Date</th>
                <th className="p-3 text-sm font-semibold text-slate-400"></th>
              </tr>
            </thead>
            <tbody>
              {donations.map(d => (
                <tr key={d.id} className="border-b border-slate-800 hover:bg-slate-700/50">
                  <td className="p-3 text-white font-medium">{d.foodType}</td>
                  <td className="p-3 text-slate-300">{d.quantity}</td>
                  <td className="p-3 text-slate-300">{d.donor}</td>
                  <td className="p-3 text-slate-300 text-sm">{d.donatedAt.toLocaleDateString()}</td>
                  <td className="p-3 text-right">
                    <button onClick={() => handleDeleteDonation(d.id)} className="text-slate-400 hover:text-red-500 transition-colors">
                       <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
};

const PlaceholderView: FC<{ title: string }> = ({ title }) => (
  <Card className="p-12 text-center">
    <h2 className="text-3xl font-bold text-white mb-2">{title}</h2>
    <p className="text-slate-300">This section is currently under construction. Check back soon for updates!</p>
  </Card>
);


