        return <PlaceholderView title="Distribution Centers" />;
      case 'Volunteer':
        return <PlaceholderView title="Volunteer Opportunities" />;
      case 'Account':
        return <PlaceholderView title="Your Account" />;
      default:
        return <HomeView onGetStarted={() => setActiveView('Donation')} />;
    }
  };

  return (
    <div className="min-h-screen w-full bg-slate-900 bg-gradient-to-b from-blue-950 to-slate-900 text-slate-100 font-sans">
      <header className="p-4 sticky top-0 z-10 bg-slate-900/70 backdrop-blur-md border-b border-slate-800">
        <div className="container mx-auto flex justify-between items-center">
          <div className="text-2xl font-bold text-white tracking-wider">FoodHub</div>
          <nav className="hidden md:flex items-center gap-2 bg-slate-800/60 p-1 rounded-xl">
            {navItems.map(item => (
              <NavButton
                key={item.name}
                text={item.name}
                icon={item.icon}
                isActive={activeView === item.name}
                onClick={() => setActiveView(item.name)}
              />
            ))}
          </nav>
          <div className="relative">
            <input
              type="text"
              placeholder="Search..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="bg-slate-700 border border-slate-600 rounded-lg py-2 pl-10 pr-4 text-white placeholder-slate-400 focus:ring-2 focus:ring-sky-500 focus:border-sky-500 outline-none transition-all w-40 md:w-64"
            />
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          </div>
        </div>
      </header>

      <main className="container mx-auto p-4 sm:p-6 lg:p-8">
        <div className="mt-8">
          {renderContent()}
        </div>
      </main>

      {/* Mobile Navigation */}
      <footer className="md:hidden fixed bottom-0 left-0 right-0 bg-slate-900/80 backdrop-blur-sm border-t border-slate-800 p-2">
          <div className="flex justify-around">
