type Case = {
  id: string;
  title: string;
  description: string;
  status: CaseStatus;
  date: string;
  hoursLogged: number;
  expenses: number;
  notes: string[];
};

type NavItem = 'Cases' | 'Reports' | 'Work Hours' | 'Expenses' | 'Assignments';

