// --- HELPER COMPONENTS ---

const StatusBadge: FC<{ status: CaseStatus }> = ({ status }) => {
  const statusStyles: Record<CaseStatus, string> = {
    Open: 'bg-blue-200 text-blue-800',
    'In Progress': 'bg-yellow-200 text-yellow-800',
    Closed: 'bg-green-200 text-green-800',
  };
  return (
    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${statusStyles[status]}`}>
      {status}
    </span>
  );
};

const InfoPill: FC<{ icon: ReactNode; label: string; value: string | number }> = ({ icon, label, value }) => (
  <div className="flex items-center text-sm text-stone-500">
    {icon}
    <span className="ml-1.5 font-medium">{label}:</span>
    <span className="ml-1">{value}</span>
  </div>
);

const Modal: FC<{ isOpen: boolean; onClose: () => void; title: string; children: ReactNode }> = ({ isOpen, onClose, title, children }) => {
  useEffect(() => {
    const handleEsc = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [onClose]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-60 backdrop-blur-sm" onClick={onClose}>
      <div className="bg-stone-50 rounded-2xl shadow-2xl w-full max-w-lg m-4 text-stone-800 border border-stone-300" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between p-6 border-b border-stone-200">
          <h2 className="text-2xl font-bold text-stone-800">{title}</h2>
          <button onClick={onClose} className="p-2 rounded-full text-stone-500 hover:bg-stone-200 hover:text-stone-800 transition-colors">
            <X size={20} />
          </button>
        </div>
        <div className="p-6">
          {children}
        </div>
      </div>
    </div>
  );
};

