  };

  const handleLogHours = () => {
    if (!selectedCase || !hoursToAdd) return;
    const hours = parseFloat(hoursToAdd);
    if (isNaN(hours) || hours <= 0) return;
    updateCaseDetail(selectedCase.id, { hoursLogged: selectedCase.hoursLogged + hours });
    setHoursToAdd('');
