r="Search by name, region, or habitat..."\n                        value={searchTerm}\n                        onChange={(e) => { setSearchTerm(e.target.value); setCurrentPage(1); }}\n                        className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-rose-300 focus:border-rose-500 outline-none transition"\n                    />\n                </div>\n                <div className="flex items-center gap-2 justify-end">\n                    <button \n                        onClick={() => alert(\'Add new species functionality not implemented.\')}\n                        className="flex items-center gap-2 px-4 py-2 bg-rose-800 text-white rounded-lg hover:bg-rose-900 transition-colors shadow font-medium">\n                        <Plus className="w-4 h-4" />\n                        Add Species\n                    </button>\n                    <button \n                        onClick={() => setShowFilters(!showFilters)}\n                        className="flex items-center gap-2 px-4 py-2 bg-white text-rose-800 border border-rose-800 rounded-lg hover:bg-rose-50 transition-colors font-medium">\n                        <Filter className="w-4 h-4" />\n                        Filters\n                    </button>\n                </div>\n            </div>\n            {showFilters && (\n                <div className="mt-4 pt-4 border-t border-slate-200">\n                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">\n                        <div>\n                            <h4 className="font-semibold mb-2 text-slate-600">Conservation Status</h4>\n                            <div className="flex flex-wrap gap-2">\n                                {ALL_STATUSES.map(status => (\n                                    <button key={status} onClick={() => handleFilterChange(\'status\', status)} className={`px-3 py-1 text-sm rounded-full border transition-colors ${filters.status.includes(status) ? \'bg-rose-800 text-white border-rose-800\' : \'bg-white text-slate-700 hover:bg-rose-50 border-slate-300\'}`}>\n                                        {status}\n                                    </button>\n                                ))}\n                            </div>\n                        </div>\n                        <div>\n                            <h4 className="font-semibold mb-2 text-slate-600">Region</h4>\n                            <div className="flex flex-wrap gap-2">\n                                {ALL_REGIONS.map(region => (\n                                    <button key={region} onClick={() => handleFilterChange(\'region\', region)} className={`px-3 py-1 text-sm rounded-full border transition-colors ${filters.region.includes(region) ? \'bg-rose-800 text-white border-rose-800\' : \'bg-white text-slate-700 hover:bg-rose-50 border-slate-300\'}`}>\n                                        {region}\n                                    </button>\n                                ))}\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            )}\n        </div>\n\n        {/* Species Table / Cards */}\n        <div className="bg-white rounded-xl shadow-sm overflow-hidden border border-slate-200">\n          <div className="overflow-x-auto">\n            <table className="w-full text-sm text-left text-slate-600">\n              <thead className="text-xs text-slate-700 uppercase bg-slate-100 border-b border-slate-200">\n                <tr>\n                  <th scope="col" className="px-6 py-4 font-bold">Species</th>\n                  <th scope="col" className="px-6 py-4 font-bold">Status</th>\n                  <th scope="col" className="px-6 py-4 font-bold">Population Trend</th>\n                  <th scope="col" className="px-6 py-4 font-bold">Regions & Habitats</th>\n                  <th scope="col" className="px-6 py-4 font-bold text-right">Actions</th>\n                </tr>\n              </thead>\n              <tbody>\n                {paginatedSpecies.length > 0 ? paginatedSpecies.map(species => (\n                  <tr key={species.id} className="bg-white border-b last:border-b-0 border-slate-200 hover:bg-rose-50/50 transition-colors">\n                    <td className="px-6 py-4">\n                        <div className="flex items-center gap-4">\n                            <div className="bg-slate-200 border-2 border-dashed rounded-xl w-16 h-16 flex items-center justify-center">\n                                <PawPrint className="w-8 h-8 text-slate-400" />\n                            </div>\n                            <div>\n                                <div className="font-bold text-base text-slate-900">{species.commonName}</div>\n                                <div className="font-mono text-xs text-slate-500 italic">{species.scientificName}</div>\n                            </div>\n                        </div>\n                    </td>\n                    <td className="px-6 py-4">\n                      <StatusBadge status={species.conservationStatus} />\n                    </td>\n                    <td className="px-6 py-4">\n                      <TrendIndicator trend={species.populationTrend} />\n                    </td>\n                    <td className="px-6 py-4">\n                        <div className="flex items-start gap-2 text-slate-500">\n                            <Globe className="w-4 h-4 mt-0.5 shrink-0"/>\n                            <span>{species.regions.join(\', \')}</span>\n                        </div>\n                        <div className="flex items-start gap-2 text-slate-500 mt-1">\n                            <Trees className="w-4 h-4 mt-0.5 shrink-0"/>\n                            <span>{species.habitats.join(\', \')}</span>\n                        </div>\n                    </td>\n                    <td className="px-6 py-4 text-right">\n                      <div className="flex justify-end gap-2">\n                        <button onClick={() => alert(`Editing ${species.commonName}`)} className="p-2 text-slate-500 hover:text-rose-800 hover:bg-rose-100 rounded-md transition-colors"><Edit className="w-4 h-4" /></button>\n                        <button onClick={() => handleDelete(species.id)} className="p-2 text-slate-500 hover:text-rose-800 hover:bg-rose-100 rounded-md transition-colors"><Trash2 className="w-4 h-4" /></button>\n                      </div>\n                    </td>\n                  </tr>\n                )) : (\n                    <tr>\n                        <td colSpan={5} className="text-center py-16 px-6">\n                            <div className="flex flex-col items-center gap-2 text-slate-500">\n                                <Search className="w-12 h-12" />\n                                <h3 className="text-lg font-semibold">No Species Found</h3>\n                                <p>Your search and filter combination returned no results.</p>\n                            </div>\n                        </td>\n                    </tr>\n                )}\n              </tbody>\n            </table>\n          </div>\n          {totalPages > 1 && (\n            <div className="p-4 flex items-center justify-between border-t border-slate-200">\n              <p className="text-sm text-slate-600">Showing <span className="font-medium">{paginatedSpecies.length}</span> of <span className="font-medium">{filteredSpecies.length}</span> results</p>\n              <nav className="flex items-center gap-2">\n                <PageButton onClick={() => setCurrentPage(p => p - 1)} disabled={currentPage === 1}>\n                  <ChevronLeft className="w-4 h-4" />\n                </PageButton>\n                <span className="text-sm text-slate-600">Page {currentPage} of {totalPages}</span>\n                <PageButton onClick={() => setCurrentPage(p => p + 1)} disabled={currentPage === totalPages}>\n                  <ChevronRight className="w-4 h-4" />\n                </PageButton>\n              </nav>\n            </div>\n          )}\n        </div>\n      </main>\n    </div>\n  );\n};\n\nexport default SpeciesBioInfoManager;\n'}

