import { useState, FC, FormEvent, useEffect } from 'react';
import type { NextPage } from 'next';
import { Mail, Lock, User, AlertTriangle } from 'lucide-react';

// Type definition for the active form view
type View = 'login' | 'register';

// Helper component for form inputs to keep the main component cleaner
interface InputProps {
  id: string;
  type: string;
  placeholder: string;
  value: string;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  icon: React.ReactNode;
}

const FormInput: FC<InputProps> = ({ id, type, placeholder, value, onChange, icon }) => (
  <div className="relative mb-4">
    <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
      {icon}
    </div>
    <input
      id={id}
      name={id}
      type={type}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      className="w-full rounded-lg border border-gray-300 bg-gray-50 p-3 pl-10 text-gray-800 transition-colors focus:border-cadet-blue-500 focus:outline-none focus:ring-2 focus:ring-cadet-blue-200"
      required
    />
  </div>
);

const SocialConnectPage: NextPage = () => {
  // State management
  const [view, setView] = useState<View>('login');
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
