  useEffect(() => {
    setError(null);
    setUsername('');
    setEmail('');
    setPassword('');
    setConfirmPassword('');
  }, [view]);

  const handleLogin = (e: FormEvent) => {
    e.preventDefault();
    // Mock login logic
    if (username === 'testuser' && password === 'password123') {
      setError(null);
      alert('Login successful!');
      // Here you would typically redirect the user or update auth context
    } else {
      setError('Invalid username or password');
    }
  };

  const handleRegister = (e: FormEvent) => {
    e.preventDefault();
    // Mock registration logic
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    if (password.length < 8) {
        setError('Password must be at least 8 characters long');
        return;
    }
    setError(null);
    alert('Registration successful!');
    // Reset to login view after successful registration
    setView('login');
  };

  return (
    <div className="flex min-h-screen w-full items-center justify-center bg-gradient-to-br from-cyan-50 to-cyan-200 p-4 font-sans">
      {/* Social Connect Card */}
      <div className="w-full max-w-md transform rounded-2xl bg-white p-8 shadow-2xl transition-all md:p-10">
        <h1 className="mb-2 text-center text-3xl font-bold text-slate-700">
          Social Connect
        </h1>
        <p className="mb-8 text-center text-gray-500">Welcome! Please login or register.</p>

        {/* View Toggler (Login/Register Buttons) */}
        <div className="mb-8 flex justify-center rounded-lg bg-gray-100 p-1">
          <button
            onClick={() => setView('login')}
            className={`w-1/2 rounded-md py-2 text-sm font-semibold transition-colors duration-300 ${view === 'login' ? 'bg-white text-slate-700 shadow-sm' : 'text-gray-500 hover:bg-gray-200'}`}>
