            Register
          </button>
        </div>

        {/* Forms Container */}
        <div>
          {view === 'login' ? (
            <form onSubmit={handleLogin}>
              <FormInput
                id="username"
                type="text"
                placeholder="Username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                icon={<User className="h-5 w-5 text-gray-400" />}
              />
              <FormInput
                id="password"
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                icon={<Lock className="h-5 w-5 text-gray-400" />}
              />
              <button
                type="submit"
                className="w-full rounded-lg bg-slate-600 py-3 font-semibold text-white transition-transform hover:bg-slate-700 hover:scale-105 focus:outline-none focus:ring-2 focus:ring-slate-500 focus:ring-offset-2">
                Submit Login
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister}>
               <FormInput
                id="username"
                type="text"
                placeholder="Username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                icon={<User className="h-5 w-5 text-gray-400" />}
              />
              <FormInput
                id="email"
                type="email"
                placeholder="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                icon={<Mail className="h-5 w-5 text-gray-400" />}
              />
              <FormInput
                id="password"
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                icon={<Lock className="h-5 w-5 text-gray-400" />}
              />
              <FormInput
                id="confirmPassword"
                type="password"
                placeholder="Confirm Password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                icon={<Lock className="h-5 w-5 text-gray-400" />}
              />
              <button
                type="submit"
                className="w-full rounded-lg bg-slate-600 py-3 font-semibold text-white transition-transform hover:bg-slate-700 hover:scale-105 focus:outline-none focus:ring-2 focus:ring-slate-500 focus:ring-offset-2">
                Register
              </button>
            </form>
          )}
        </div>

        {/* Error Message Card */}
        {error && (
          <div className="mt-6 flex items-center justify-center rounded-lg bg-red-100 p-3 text-sm text-red-700">
            <AlertTriangle className="mr-2 h-5 w-5 flex-shrink-0" />
            <span>{error}</span>
          </div>
        )}
      </div>
    </div>
  );
};

export default SocialConnectPage;


