type View = 'signIn' | 'register';

const MatrimonyConnectPage: FC = () => {
  const [view, setView] = useState<View>('signIn');
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [gender, setGender] = useState('');
  const [aboutYourself, setAboutYourself] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const resetForm = () => {
    setFullName('');
    setEmail('');
    setPassword('');
    setConfirmPassword('');
    setGender('');
    setAboutYourself('');
    setError(null);
    setSuccess(null);
  };

  const handleViewChange = (newView: View) => {
    resetForm();
    setView(newView);
  };

  const handleSignIn = (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!email || !password) {
      setError('Please enter both email and password.');
      return;
    }
    console.log('Signing in with:', { email, password });
    setSuccess(`Welcome back! Successfully signed in as ${email}.`);
    // In a real app, you'd make an API call here.
  };

  const handleRegister = (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    if ([fullName, email, password, confirmPassword, gender, aboutYourself].some(field => field.trim() === '')) {
      setError('Please fill out all fields.');
      return;
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match.');
      return;
    }
    if (password.length < 8) {
        setError('Password must be at least 8 characters long.');
        return;
    }
    console.log('Registering with:', { fullName, email, gender, aboutYourself });
    setSuccess('Registration successful! Please sign in.');
    setTimeout(() => handleViewChange('signIn'), 2000);
  };

  const renderSignInForm = () => (
    <form onSubmit={handleSignIn} className="space-y-6">
      <div className="relative">
        <AtSignIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
        <input
          id="email-signin"
          type="email"
          placeholder="your@email.com"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300"
        />
      </div>
      <div className="relative">
        <LockIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
        <input
          id="password-signin"
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300"
        />
      </div>
      <button type="submit" className="w-full py-3 px-4 bg-yellow-400 hover:bg-yellow-500 text-stone-900 font-semibold rounded-lg shadow-lg transition duration-300 ease-in-out transform hover:scale-105">
        Sign In
      </button>
      <p className="text-center text-sm">
        <span className="text-stone-300">New to MatrimonyConnect? </span>
        <button type="button" onClick={() => handleViewChange('register')} className="font-medium text-yellow-300 hover:text-yellow-200 hover:underline">
          Create an account
        </button>
      </p>
    </form>
  );

  const renderRegisterForm = () => (
    <form onSubmit={handleRegister} className="space-y-4">
      <div className="relative">
        <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
        <input id="full-name" type="text" placeholder="Full Name" value={fullName} onChange={(e) => setFullName(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300" />
      </div>
      <div className="relative">
        <AtSignIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
        <input id="email-register" type="email" placeholder="Email Address" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300" />
      </div>
      {/* Gender Selection Card */}
      <div className="relative">
        <UsersIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
        <select id="gender" value={gender} onChange={(e) => setGender(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300 appearance-none">
            <option value="" disabled>Select your gender</option>
            <option value="male">Male</option>
            <option value="female">Female</option>
            <option value="other">Other</option>
            <option value="prefer_not_to_say">Prefer not to say</option>
        </select>
      </div>
      <div className="relative">
        <LockIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
        <input id="password-register" type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300" />
      </div>
      <div className="relative">
        <LockIcon className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-stone-400" />
        <input id="confirm-password" type="password" placeholder="Confirm Password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300" />
      </div>
       {/* About Yourself Textarea */}
      <div className="relative">
        <InfoIcon className="absolute left-3 top-4 h-5 w-5 text-stone-400" />
        <textarea id="about-yourself" placeholder="Tell us a little about yourself..." value={aboutYourself} onChange={(e) => setAboutYourself(e.target.value)} rows={3} className="w-full pl-10 pr-4 py-3 bg-stone-700 border border-stone-600 rounded-lg text-yellow-100 placeholder-stone-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 transition duration-300 resize-none" />
      </div>
      <button type="submit" className="w-full py-3 px-4 bg-yellow-400 hover:bg-yellow-500 text-stone-900 font-semibold rounded-lg shadow-lg transition duration-300 ease-in-out transform hover:scale-105">
        Register
      </button>
      <p className="text-center text-sm">
        <span className="text-stone-300">Already have an account? </span>
        <button type="button" onClick={() => handleViewChange('signIn')} className="font-medium text-yellow-300 hover:text-yellow-200 hover:underline">
          Sign In
        </button>
      </p>
    </form>
  );

  return (
    <main className="min-h-screen bg-yellow-100 flex flex-col items-center justify-center p-4 font-sans">
      {/* Profile Completion Card (The main container) */}
      <div className="w-full max-w-md bg-stone-800 rounded-2xl shadow-2xl p-8 space-y-6 transform transition-all duration-500">
        <div className="text-center space-y-2">
            <h1 className="text-4xl font-bold text-yellow-100 tracking-tight">MatrimonyConnect</h1>
            <p className="text-yellow-200">
                {view === 'signIn' ? 'Sign in to find your partner' : 'Create an account to get started'}
            </p>
        </div>

        {error && <div className="bg-red-900/50 border border-red-700 text-red-300 text-sm rounded-lg p-3 text-center">{error}</div>}
        {success && <div className="bg-green-900/50 border border-green-700 text-green-300 text-sm rounded-lg p-3 text-center">{success}</div>}

        {view === 'signIn' ? renderSignInForm() : renderRegisterForm()}
      </div>
      <footer className="mt-8 text-center text-sm text-stone-600">
        <p>&copy; {new Date().getFullYear()} MatrimonyConnect. All rights reserved.</p>
      </footer>
    </main>
  );
};

export default MatrimonyConnectPage;


