// --- HELPER FUNCTIONS ---
const calculateMatchPercentage = (userSkills: Skill[], otherSkills: Skill[]): number => {
  if (userSkills.length === 0) return 0;
  const userSkillNames = new Set(userSkills.map(s => s.name.toLowerCase()));
  const otherSkillNames = new Set(otherSkills.map(s => s.name.toLowerCase()));
  const commonSkills = [...userSkillNames].filter(skill => otherSkillNames.has(skill));
  return Math.round((commonSkills.length / userSkillNames.size) * 100);
};

