    <h3 className="text-xl font-bold text-slate-700">{title}</h3>
  </div>
);

const AddItemInput: FC<{ onAdd: (value: string) => void; placeholder: string }> = ({ onAdd, placeholder }) => {
  const [value, setValue] = useState('');
  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && value.trim()) {
      onAdd(value.trim());
      setValue('');
    }
  };
  return (
    <input
      type="text"
      value={value}
      onChange={(e) => setValue(e.target.value)}
      onKeyDown={handleKeyDown}
      placeholder={placeholder}
      className="w-full p-2 mt-2 text-sm border rounded-md bg-white border-slate-300 focus:ring-2 focus:ring-amber-600 focus:border-transparent transition"
    />
  );
};

