// MAIN PAGE COMPONENT
const ImaginationHubPage: NextPage = () => {
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [posts, setPosts] = useState<Post[]>(initialPosts);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme]);

  const toggleTheme = () => {
    setTheme(theme === 'dark' ? 'light' : 'dark');
  };

  const handleInteraction = (postId: number, type: 'like' | 'dislike') => {
    setPosts(posts.map(post => {
      if (post.id === postId) {
        const wasLiked = post.isLiked;
        const wasDisliked = post.isDisliked;
        let newLikes = post.likes;
        let newDislikes = post.dislikes;

        if (type === 'like') {
          const isLiked = !wasLiked;
          const isDisliked = false;
          newLikes = wasLiked ? newLikes - 1 : newLikes + 1;
          if (wasDisliked) newDislikes -= 1;
          return { ...post, isLiked, isDisliked, likes: newLikes, dislikes: newDislikes };
        } else { // type === 'dislike'
          const isDisliked = !wasDisliked;
          const isLiked = false;
          newDislikes = wasDisliked ? newDislikes - 1 : newDislikes + 1;
          if (wasLiked) newLikes -= 1;
          return { ...post, isLiked, isDisliked, likes: newLikes, dislikes: newDislikes };
        }
      }
      return post;
    }));
  };

  const filteredPosts = useMemo(() =>
    posts.filter(post =>
      post.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
      post.author.toLowerCase().includes(searchTerm.toLowerCase())
    ), [posts, searchTerm]);

  const colorPalette = {
    bg: 'bg-slate-100 dark:bg-slate-900',
