    border: 'border-slate-200 dark:border-slate-700',
    inputBg: 'bg-slate-200 dark:bg-slate-800',
    accent: 'text-azure-500',
  };

  return (
    <div className={`min-h-screen ${colorPalette.bg} ${colorPalette.textPrimary} font-sans transition-colors duration-300`}>
      <div className="max-w-screen-xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <header className={`flex items-center justify-between py-6 border-b ${colorPalette.border}`}>
          <h1 className="text-3xl md:text-4xl font-bold tracking-tight text-slate-900 dark:text-white">World of Imagination</h1>
          <div className="flex items-center space-x-2 md:space-x-4">
            <button onClick={toggleTheme} className={`p-2 rounded-full ${colorPalette.textSecondary} hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors`} aria-label="Toggle theme">
              {theme === 'dark' ? <SunIcon className="w-5 h-5" /> : <MoonIcon className="w-5 h-5" />}
            </button>
            <button className={`p-2 rounded-full ${colorPalette.textSecondary} hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors`} aria-label="Menu">
              <MenuIcon className="w-5 h-5" />
            </button>
          </div>
        </header>

        {/* Search Bar */}
        <div className="py-8">
          <div className="relative">
            <input
              type="text"
              placeholder="Search for inspiration..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className={`w-full pl-12 pr-4 py-3 rounded-full border ${colorPalette.border} ${colorPalette.cardBg} ${colorPalette.textPrimary} focus:ring-2 focus:ring-blue-500 focus:outline-none transition-shadow`}
            />
            <div className={`absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none ${colorPalette.textSecondary}`}>
              <SearchIcon className="w-5 h-5" />
            </div>
          </div>
        </div>

        {/* Main Content Grid */}
        <main className="pb-16">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredPosts.map(post => (
              <div key={post.id} className={`${colorPalette.cardBg} rounded-2xl shadow-md hover:shadow-xl transition-shadow duration-300 flex flex-col overflow-hidden border ${colorPalette.border}`}>
                <div className="p-6 flex-grow">
                  <div className="flex items-center mb-4">
                    <div className="bg-gray-200 border-2 border-dashed rounded-full w-10 h-10 dark:bg-slate-700 dark:border-slate-600" />
                    <div className="ml-3">
                      <p className="font-semibold text-sm text-slate-900 dark:text-white">{post.author}</p>
                      <p className={`text-xs ${colorPalette.textSecondary}`}>Posted 2 hours ago</p>
                    </div>
                  </div>
                  <p className={`${colorPalette.textSecondary} text-base`}>{post.content}</p>
                </div>
                <div className={`border-t ${colorPalette.border} px-6 py-3 flex justify-between items-center bg-slate-50 dark:bg-slate-800/50`}>
                  <div className="flex items-center space-x-5 text-sm">
                    <button 
                      onClick={() => handleInteraction(post.id, 'like')}
                      className={`flex items-center space-x-1.5 transition-colors ${post.isLiked ? 'text-pink-500' : `${colorPalette.textSecondary} hover:text-pink-500`}`}
                      aria-label='Like post'
                    >
                      <HeartIcon className={`w-5 h-5 ${post.isLiked ? 'fill-current' : ''}`} />
                      <span>{post.likes}</span>
                    </button>
                    <button 
                      onClick={() => handleInteraction(post.id, 'dislike')}
                      className={`flex items-center space-x-1.5 transition-colors ${post.isDisliked ? 'text-blue-500' : `${colorPalette.textSecondary} hover:text-blue-500`}`}
                      aria-label='Dislike post'
                    >
                      <ThumbsDownIcon className={`w-5 h-5 ${post.isDisliked ? 'fill-current' : ''}`} />
                      <span>{post.dislikes}</span>
                    </button>
                    <button className={`flex items-center space-x-1.5 ${colorPalette.textSecondary} hover:text-green-500 transition-colors`} aria-label='Comment on post'>
                      <MessageCircleIcon className="w-5 h-5" />
                      <span>{post.comments}</span>
                    </button>
                  </div>
                </div>
              </div>
            ))}
