        <footer className={`py-6 text-center border-t ${colorPalette.border} ${colorPalette.textSecondary} text-sm`}>
          <p>&copy; {new Date().getFullYear()} Imagination Hub. All rights reserved.</p>
        </footer>
      </div>
    </div>
  );
};

export default ImaginationHubPage;


