const WildAnimalDetectionHubPage: NextPage = () => {
  const [animals, setAnimals] = useState<Animal[]>(initialAnimals);
  const [detections, setDetections] = useState<Detection[]>(initialDetections);

  const handleToggleAlert = useCallback((id: number) => {
    setAnimals(prevAnimals =>
      prevAnimals.map(animal =>
        animal.id === id ? { ...animal, alertOn: !animal.alertOn } : animal
      )
    );
  }, []);

  const handleSimulateDetection = useCallback((animal: Animal) => {
    const newDetection: Detection = {
        id: Date.now(),
        animalName: animal.name,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        color: animal.color,
    };
    setDetections(prevDetections => [newDetection, ...prevDetections]);
  }, []);

  const handleClearDetections = useCallback(() => {
    setDetections([]);
  }, []);

  return (
    <main className="min-h-screen bg-rose-50 font-sans text-slate-800 p-4 sm:p-6 md:p-8">
      <div className="max-w-7xl mx-auto">
