        <header className="text-center mb-12">
          <h1 className="text-4xl md:text-5xl font-extrabold text-firebrick-800">Wild Animal Detection</h1>
          <p className="mt-2 text-lg text-firebrick-700">Real-time monitoring and SMS alert system for wildlife presence.</p>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
          {/* Detected Animals Section */}
          <div className="lg:col-span-1">
            <h2 className="text-2xl font-bold text-slate-800 mb-4">Detected Animals</h2>
            <Card className="p-6">
                {detections.length > 0 ? (
                    <div className="space-y-4">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-semibold text-slate-700">Recent Observations</h3>
                            <button 
                                onClick={handleClearDetections}
                                className="flex items-center px-3 py-1.5 text-sm font-medium text-white bg-firebrick-600 rounded-md hover:bg-firebrick-700 transition-colors"
                            >
                                <Trash2 size={14} className="mr-1.5" />
                                Clear
                            </button>
                        </div>
                        {detections.map(detection => (
                            <DetectedAnimalCard key={detection.id} detection={detection} />
                        ))}
                    </div>
                ) : (
                    <div className="text-center py-8">
                        <AlertTriangle className="mx-auto text-slate-400 mb-4" size={40} />
                        <h3 className="font-semibold text-slate-600">No detections yet.</h3>
                        <p className="text-sm text-slate-500">Monitoring wildlife...</p>
                    </div>
                )}
            </Card>
          </div>

          {/* Animal Gallery Section */}
          <div className="lg:col-span-2">
            <h2 className="text-2xl font-bold text-slate-800 mb-4">Animal Gallery & Alerts</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {animals.map(animal => (
                <AnimalCard 
                    key={animal.id} 
                    animal={animal} 
                    onToggleAlert={handleToggleAlert} 
                    onSimulateDetection={handleSimulateDetection} 
                />
              ))}
            </div>
          </div>
        </div>
      </div>
    </main>
  );
};

