// --- MAIN PAGE COMPONENT ---

const EuroTravelExplorerPage: NextPage = () => {
  const [activeView, setActiveView] = useState<'home' | 'bookings'>('home');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredDestinations = useMemo(() =>
    initialDestinations.filter(dest =>
      dest.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      dest.description.toLowerCase().includes(searchTerm.toLowerCase())
    ), [searchTerm]);

  return (
    <div className="min-h-screen bg-pink-50 font-sans">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-6">
        {/* Header & Navigation */}
        <header className="flex flex-col sm:flex-row justify-between items-center gap-4 py-4 mb-6">
          <div className="flex items-center gap-3 text-2xl font-bold text-pink-600">
            <Plane size={32} />
            <span>EuroTravel Explorer</span>
          </div>
          <nav className="flex items-center gap-2 p-1.5 bg-pink-100 rounded-full">
            <NavButton icon={<HomeIcon size={16} />} label="Home" isActive={activeView === 'home'} onClick={() => setActiveView('home')} />
            <NavButton icon={<Bookmark size={16} />} label="Bookings" isActive={activeView === 'bookings'} onClick={() => setActiveView('bookings')} />
          </nav>
        </header>

        {/* Search Bar - Only shows on Home view */}
        {activeView === 'home' && (
          <div className="w-full max-w-2xl mx-auto my-8">
            <div className="relative">
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Search for countries, cities, or campsites..."
                className="w-full pl-12 pr-28 py-4 text-base bg-white border-2 border-transparent rounded-full shadow-lg focus:outline-none focus:ring-2 focus:ring-pink-500 focus:border-transparent transition-shadow"
              />
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <button
                onClick={() => alert(`Searching for: ${searchTerm}`)}
                className="absolute right-2 top-1/2 -translate-y-1/2 bg-pink-600 text-white font-semibold px-6 py-2.5 rounded-full hover:bg-pink-700 transition-colors duration-200"
              >
                Search
              </button>
            </div>
          </div>
        )}

        {/* Main Content Area */}
        <main>
          {activeView === 'home' ? <HomePage destinations={filteredDestinations} /> : <BookingsPage />}
        </main>

        {/* Footer */}
        <footer className="text-center mt-16 py-6 border-t border-pink-200">
          <p className="text-slate-500 text-sm">&copy; {new Date().getFullYear()} EuroTravel Explorer. All rights reserved.</p>
        </footer>
      </div>
    </div>
  );
};

export default EuroTravelExplorerPage;


