// --- MAIN PAGE COMPONENT ---
const PremiumCarRentalPage: NextPage = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [location, setLocation] = useState('');
  const [passengers, setPassengers] = useState(1);

  const filteredCars = useMemo(() => {
    return CARS_DATA.filter(car => {
      const matchesQuery = 
        car.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        car.type.toLowerCase().includes(searchQuery.toLowerCase()) ||
        car.pricePerDay.toString().includes(searchQuery);
      const matchesPassengers = car.passengers >= passengers;
      return matchesQuery && matchesPassengers;
    });
  }, [searchQuery, passengers]);

  const handleDecrement = () => {
    setPassengers(prev => Math.max(1, prev - 1));
  };

  const handleIncrement = () => {
    setPassengers(prev => Math.min(10, prev + 1));
  };

  return (
    <div className="min-h-screen bg-slate-900 text-gray-300 font-sans">
      {/* Header */}
      <header className="bg-slate-900/80 backdrop-blur-sm sticky top-0 z-50 border-b border-slate-700">
