          </button>
        </nav>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-6 py-12">
        {/* Search & Filter Section */}
        <section className="mb-12">
            <h1 className="text-4xl md:text-5xl font-extrabold text-white text-center mb-4">Premium Car Rental Services</h1>
            <p className="text-lg text-gray-400 text-center mb-8 max-w-3xl mx-auto">Find the perfect vehicle for your next adventure with our exclusive fleet of premium cars.</p>

            <div className="bg-slate-800 p-6 rounded-2xl shadow-2xl flex flex-col lg:flex-row items-center gap-4">
                {/* Search Bar */}
                <div className="relative w-full lg:w-1/3">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                    <input 
                        type="text"
                        placeholder="Search by name, detail, or price..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-slate-700 text-white rounded-lg pl-12 pr-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                {/* Location Search Bar */}
                <div className="relative w-full lg:w-1/3">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                    <input 
                        type="text"
                        placeholder="Enter a location"
                        value={location}
                        onChange={(e) => setLocation(e.target.value)}
                        className="w-full bg-slate-700 text-white rounded-lg pl-12 pr-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
                    />
                </div>

                {/* Passenger Counter */}
                <div className="flex items-center justify-between w-full lg:w-auto bg-slate-700 rounded-lg px-4 py-3">
                    <Users className="text-gray-400 mr-4" size={20} />
                    <span className="text-white mr-4 whitespace-nowrap">Passengers</span>
                    <div className="flex items-center gap-2">
                        <button onClick={handleDecrement} className="bg-slate-600 rounded-full w-8 h-8 flex items-center justify-center text-white hover:bg-slate-500 transition-colors duration-200"> <Minus size={16} /> </button>
                        <span className="text-white font-bold w-4 text-center">{passengers}</span>
                        <button onClick={handleIncrement} className="bg-slate-600 rounded-full w-8 h-8 flex items-center justify-center text-white hover:bg-slate-500 transition-colors duration-200"> <Plus size={16} /> </button>
                    </div>
                </div>
            </div>
        </section>

        {/* Car Listings */}
        <section>
          {filteredCars.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
              {filteredCars.map(car => (
                <CarCard key={car.id} car={car} />
              ))}
            </div>
          ) : (
            <div className="text-center py-16 bg-slate-800 rounded-2xl">
                <h3 className="text-2xl font-bold text-white">No Cars Found</h3>
                <p className="text-gray-400 mt-2">Try adjusting your search criteria.</p>
            </div>
          )}
        </section>
      </main>

      {/* Footer */}
      <footer className="bg-slate-900 border-t border-slate-700 mt-16">
        <div className="container mx-auto px-6 py-6 text-center text-gray-500">
          <p>&copy; {new Date().getFullYear()} Premium Car Rental Hub. All rights reserved.</p>
