// --- UI HELPER COMPONENTS ---

const Card: FC<{ children: ReactNode; className?: string }> = ({ children, className = '' }) => (
  <div className={`bg-white dark:bg-slate-800 rounded-2xl shadow-lg overflow-hidden transition-all duration-300 ${className}`}>
    {children}
  </div>
);

const Section: FC<{ id: string; title: string; subtitle: string; children: ReactNode; className?: string }> = ({ id, title, subtitle, children, className = '' }) => (
  <section id={id} className={`py-16 sm:py-24 px-4 sm:px-6 lg:px-8 ${className}`}>
    <div className="max-w-7xl mx-auto">
      <div className="text-center mb-12">
        <h2 className="text-3xl sm:text-4xl font-bold tracking-tight text-slate-900 dark:text-white">{title}</h2>
        <p className="mt-4 text-lg text-slate-600 dark:text-slate-300 max-w-2xl mx-auto">{subtitle}</p>
      </div>
      {children}
    </div>
  </section>
);

const InputField: FC<{ id: string; label: string; type?: string; value: string; onChange: (e: React.ChangeEvent<HTMLInputElement>) => void; icon: ReactNode; placeholder: string }> = ({ id, label, type = 'text', value, onChange, icon, placeholder }) => (
  <div>
    <label htmlFor={id} className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">{label}</label>
    <div className="relative rounded-md shadow-sm">
      <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
        {icon}
      </div>
      <input type={type} id={id} value={value} onChange={onChange} className="block w-full rounded-lg border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-700 pl-10 py-2.5 text-slate-900 dark:text-white focus:border-cyan-500 focus:ring-cyan-500 sm:text-sm" placeholder={placeholder} />
    </div>
  </div>
);

const SelectField: FC<{ id: string; label: string; value: string; onChange: (e: React.ChangeEvent<HTMLSelectElement>) => void; icon: ReactNode; options: string[] }> = ({ id, label, value, onChange, icon, options }) => (
  <div>
    <label htmlFor={id} className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">{label}</label>
    <div className="relative">
      <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
        {icon}
      </div>
      <select id={id} value={value} onChange={onChange} className="block w-full appearance-none rounded-lg border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-700 pl-10 pr-10 py-2.5 text-slate-900 dark:text-white focus:border-cyan-500 focus:ring-cyan-500 sm:text-sm">
