: \'Mar\', expenses: 5000 },\n  { name: \'Apr\', expenses: 4500 },\n  { name: \'May\', expenses: 6000 },\n  { name: \'Jun\', expenses: 5500 },\n];\n\nconst expenseDistributionData = [\n  { name: \'Travel\', value: 400 },\n  { name: \'Accommodation\', value: 300 },\n  { name: \'Meals\', value: 200 },\n  { name: \'Other\', value: 100 },\n];\n\nconst COLORS = [\'#3b82f6\', \'#8b5cf6\', \'#10b981\', \'#f59e0b\'];\n\nconst recentActivityData = [\n  { icon: CheckCircle, color: \'text-emerald-500\', text: \'Reimbursement #R1234 approved.\', time: \'2 hours ago\' },\n  { icon: PlusCircle, color: \'text-sky-500\', text: \'New booking for SFO -> LAX added.\', time: \'1 day ago\' },\n  { icon: FileText, color: \'text-amber-500\', text: \'Settlement report for Q2 generated.\', time: \'3 days ago\' },\n  { icon: CheckCircle, color: \'text-emerald-500\', text: \'Reimbursement #R1230 approved.\', time: \'5 days ago\' },\n];\n\n// --- TYPES ---\ntype View = \'dashboard\' | \'bookTicket\';\ntype DropdownState = { bookings: boolean; reimbursement: boolean };\n\n// --- HELPER HOOK for closing dropdown on outside click ---\nconst useOutsideClick = (callback: () => void) => {\n  const ref = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    const handleClick = (event: MouseEvent) => {\n      if (ref.current && !ref.current.contains(event.target as Node)) {\n        callback();\n      }\n    };\n\n    document.addEventListener(\'mousedown\', handleClick);\n    return () => {\n      document.removeEventListener(\'mousedown\', handleClick);\n    };\n  }, [callback]);\n\n  return ref;\n};\n\n// --- UI COMPONENTS ---\n\nconst Header: FC<{ setView: (view: View) => void }> = ({ setView }) => {\n  const [dropdowns, setDropdowns] = useState<DropdownState>({ bookings: false, reimbursement: false });\n\n  const toggleDropdown = (key: keyof DropdownState) => {\n    setDropdowns(prev => ({ ...{ bookings: false, reimbursement: false }, [key]: !prev[key] }));\n  };\n\n  const closeDropdowns = () => setDropdowns({ bookings: false, reimbursement: false });\n\n  const dropdownRef = useOutsideClick(closeDropdowns);\n\n  return (\n    <header className="bg-gradient-to-r from-purple-600 to-indigo-700 text-white shadow-lg">\n      <div className="container mx-auto px-6 py-4 flex justify-between items-center">\n        <h1 className="text-2xl font-bold tracking-wider">Travel Expense Manager</h1>\n        <nav className="flex items-center space-x-4" ref={dropdownRef}>\n          <button onClick={() => setView(\'dashboard\')} className="hidden sm:flex items-center space-x-2 px-4 py-2 rounded-md hover:bg-white/10 transition-colors">\n            <span>Dashboard</span>\n          </button>\n          <div className="relative">\n            <button onClick={() => toggleDropdown(\'bookings\')} className="flex items-center space-x-2 px-4 py-2 rounded-md bg-white/10 hover:bg-white/20 transition-colors">\n              <span>Bookings</span>\n              <ChevronDown className={`w-4 h-4 transition-transform ${dropdowns.bookings ? \'rotate-180\' : \'\'}`} />\n            </button>\n            {dropdowns.bookings && (\n              <div className="absolute right-0 mt-2 w-48 bg-white rounded-md shadow-xl z-20 py-1 text-slate-800">\n                <a href="#" onClick={(e) => { e.preventDefault(); setView(\'bookTicket\'); closeDropdowns(); }} className="flex items-center px-4 py-2 text-sm hover:bg-slate-100">\n                  <Plane className="w-4 h-4 mr-3 text-slate-500" />\n                  Book Ticket\n                </a>\n                <a href="#" className="flex items-center px-4 py-2 text-sm hover:bg-slate-100">\n                  <Hotel className="w-4 h-4 mr-3 text-slate-500" />\n                  Book Hotel\n                </a>\n                <a href="#" className="flex items-center px-4 py-2 text-sm hover:bg-slate-100">\n                  <Train className="w-4 h-4 mr-3 text-slate-500" />\n                  Book Train\n                </a>\n              </div>\n            )}\n          </div>\n          <div className="relative">\n            <button onClick={() => toggleDropdown(\'reimbursement\')} className="flex items-center space-x-2 px-4 py-2 rounded-md bg-white/10 hover:bg-white/20 transition-colors">\n              <span>Reimbursement</span>\n              <ChevronDown className={`w-4 h-4 transition-transform ${dropdowns.reimbursement ? \'rotate-180\' : \'\'}`} />\n            </button>\n            {dropdowns.reimbursement && (\n              <div className="absolute right-0 mt-2 w-56 bg-white rounded-md shadow-xl z-20 py-1 text-slate-800">\n                <a href="#" className="block px-4 py-2 text-sm hover:bg-slate-100">Submit Application</a>\n                <a href="#" className="block px-4 py-2 text-sm hover:bg-slate-100">View Status</a>\n                <a href="#" className="block px-4 py-2 text-sm hover:bg-slate-100">Generate Settlement Report</a>\n              </div>\n            )}\n          </div>\n          <div className="w-10 h-10 rounded-full bg-purple-400 flex items-center justify-center border-2 border-white/50">\n            <User className="w-5 h-5" />\n          </div>\n        </nav>\n      </div>\n    </header>\n  );\n};\n\nconst MetricCard: FC<{ icon: React.ElementType, title: string, value: string, color: string }> = ({ icon: Icon, title, value, color }) => (\n  <div className={`bg-white p-6 rounded-xl shadow-md flex items-center space-x-4 border-l-4 ${color}`}>\n    <div className={`p-3 rounded-full ${color.replace(\'border-\', \'bg-\').replace(\'500\', \'100\')}`}>\n      <Icon className={`w-6 h-6 ${color.replace(\'border-\', \'text-\')}`} />\n    </div>\n    <div>\n      <p className="text-sm text-slate-500 font-medium">{title}</p>\n      <p className="text-2xl font-bold text-slate-800">{value}</p>\n    </div>\n  </div>\n);\n\nconst DashboardView = () => (\n  <div className="space-y-8">\n    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">\n      <MetricCard icon={DollarSign} title="Total Expenses (YTD)" value="$24,850" color="border-sky-500" />\n      <MetricCard icon={Wallet} title="Total Reimbursed" value="$21,300" color="border-emerald-500" />\n      <MetricCard icon={Clock} title="Pending Approval" value="$3,550" color="border-amber-500" />\n    </div>\n\n    <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">\n      <div className="lg:col-span-3 bg-white p-6 rounded-xl shadow-md">\n        <h3 className="text-lg font-semibold text-slate-800 mb-4">Monthly Expense Overview</h3>\n        <div className="h-72">\n          <ResponsiveContainer width="100%" height="100%">\n            <BarChart data={monthlyExpenseData} margin={{ top: 5, right: 20, left: -10, bottom: 5 }}>\n              <CartesianGrid strokeDasharray="3 3" vertical={false} />\n              <XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fill: \'#64748b\' }} />\n              <YAxis axisLine={false} tickLine={false} tick={{ fill: \'#64748b\' }} tickFormatter={(value) => `$${Number(value) / 1000}k`} />\n              <Tooltip cursor={{ fill: \'rgba(241, 245, 249, 0.5)\' }} contentStyle={{ background: \'white\', border: \'1px solid #e2e8f0\', borderRadius: \'0.5rem\' }} />\n              <Bar dataKey="expenses" fill="#4f46e5" radius={[4, 4, 0, 0]} />\n            </BarChart>\n          </ResponsiveContainer>\n        </div>\n      </div>\n\n      <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-md">\n        <h3 className="text-lg font-semibold text-slate-800 mb-4">Expense Distribution Card</h3>\n        <div className="h-72">\n          <ResponsiveContainer width="100%" height="100%">\n            <PieChart>\n              <Pie data={expenseDistributionData} cx="50%" cy="50%" labelLine={false} outerRadius={80} fill="#8884d8" dataKey="value">\n                {expenseDistributionData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}\n              </Pie>\n              <Tooltip contentStyle={{ background: \'white\', border: \'1px solid #e2e8f0\', borderRadius: \'0.5rem\' }} />\n              <PieLegend iconType="circle" iconSize={10} wrapperStyle={{ paddingTop: \'20px\' }} />\n            </PieChart>\n          </ResponsiveContainer>\n        </div>\n      </div>\n    </div>\n\n    <div className="bg-white p-6 rounded-xl shadow-md">\n      <h3 className="text-lg font-semibold text-slate-800 mb-4">Recent Activity</h3>\n      <ul className="space-y-4">\n        {recentActivityData.map((activity, index) => (\n          <li key={index} className="flex items-center space-x-4 pb-4 border-b border-slate-100 last:border-b-0">\n            <activity.icon className={`w-5 h-5 flex-shrink-0 ${activity.color}`} />\n            <div className="flex-grow">\n              <p className="text-sm text-slate-700">{activity.text}</p>\n            </div>\n            <p className="text-xs text-slate-400 font-medium whitespace-nowrap">{activity.time}</p>\n          </li>\n        ))}\n      </ul>\n    </div>\n  </div>\n);\n\nconst BookTicketView: FC<{ setView: (view: View) => void }> = ({ setView }) => {\n  return (\n    <div className="bg-white p-8 rounded-xl shadow-md max-w-2xl mx-auto">\n      <div className="flex items-center justify-between mb-6">\n        <h2 className="text-xl font-bold text-slate-800">Book a New Ticket</h2>\n        <button onClick={() => setView(\'dashboard\')} className="flex items-center space-x-2 text-sm font-medium text-slate-600 hover:text-slate-900 transition-colors">\n          <ArrowLeft className="w-4 h-4" />\n          <span>Back to Dashboard</span>\n        </button>\n      </div>\n      <form className="space-y-6">\n        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">\n          <div>\n            <label htmlFor="departure-city" className="block text-sm font-medium text-slate-600 mb-1">Departure City</label>\n            <div className="relative">\n              <MapPin className="w-5 h-5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />\n              <input type="text" id="departure-city" placeholder="e.g., New York" className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 transition" />\n            </div>\n          </div>\n          <div>\n            <label htmlFor="destination-city" className="block text-sm font-medium text-slate-600 mb-1">Destination City</label>\n            <div className="relative">\n              <MapPin className="w-5 h-5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />\n              <input type="text" id="destination-city" placeholder="e.g., London" className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 transition" />\n            </div>\n          </div>\n        </div>\n        <div>\n          <label htmlFor="travel-dates" className="block text-sm font-medium text-slate-600 mb-1">Travel Dates</label>\n          <div className="relative">\n            <Calendar className="w-5 h-5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />\n            <input type="text" id="travel-dates" placeholder="e.g., 2024-08-15 to 2024-08-22" className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 transition" />\n          </div>\n        </div>\n        <div>\n          <label htmlFor="purpose" className="block text-sm font-medium text-slate-600 mb-1">Purpose of Travel</label>\n          <div className="relative">\n            <Briefcase className="w-5 h-5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />\n            <input type="text" id="purpose" placeholder="e.g., Q3 Client Meeting" className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 transition" />\n          </div>\n        </div>\n        <div className="flex justify-end pt-4">\n          <button type="submit" className="px-6 py-2 bg-slate-800 text-white font-semibold rounded-md hover:bg-slate-900 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-800 transition-colors">Submit Booking</button>\n        </div>\n      </form>\n    </div>\n  );\n};\n\nconst Footer = () => (\n  <footer className="text-center py-8 text-slate-500 text-sm">\n    <div className="space-x-6">\n      <a href="#" className="hover:text-slate-800 transition-colors">Privacy Policy</a>\n      <a href="#" className="hover:text-slate-800 transition-colors">Terms of Service</a>\n      <a href="#" className="hover:text-slate-800 transition-colors">Contact Support</a>\n    </div>\n    <p className="mt-4">&copy; {new Date().getFullYear()} Travel Expense Manager. All rights reserved.</p>\n  </footer>\n);\n\nconst TravelExpenseManagerPage: NextPage = () => {\n  const [view, setView] = useState<View>(\'dashboard\');\n\n  return (\n    <div className="min-h-screen bg-slate-100 font-sans">\n      <Header setView={setView} />\n      <main className="container mx-auto px-6 py-8">\n        {view === \'dashboard\' ? <DashboardView /> : <BookTicketView setView={setView} />}\n      </main>\n      <Footer />\n    </div>\n  );\n};\n\nexport default TravelExpenseManagerPage;\n'}
